window.CURSOS_MARA = window.CURSOS_MARA || [];
window.CURSOS_MARA.push({"id":"c-inteligencia-emocional","nombre":"Inteligencia emocional y manejo del estrés","color":"#7C3AED","nivel":"Cursos libres de capacitación","familia":"Desarrollo humano","periodoTipo":null,"periodoNum":null,"desc":"Aprende a reconocer lo que sientes, calmarte antes de reaccionar, manejar el estrés del día a día y comunicarte mejor en el trabajo y en casa, con herramientas prácticas y basadas en evidencia. No es terapia: te enseña también cuándo y dónde buscar ayuda profesional.","horas":12,"precio":790,"publicado":true,"proximamente":false,"modulos":[{"id":"c-inteligencia-emocional-m1","titulo":"Módulo 1 — Emociones e inteligencia emocional","resumen":"Para qué sirven las emociones, qué es (y qué no es) la inteligencia emocional según los modelos serios, y cómo empezar a observarte. Tres lecciones y una evaluación.","lecciones":[{"id":"c-inteligencia-emocional-m1-l1","titulo":"Lección 1 — Para qué sirven las emociones","objetivo":"explicar qué es una emoción, para qué sirve y por qué ninguna emoción es «mala» en sí misma.","bloques":[{"tipo":"destacado","texto":"<b>Antes de empezar, con claridad.</b> Este es un <b>curso libre de capacitación</b>: al terminarlo recibes una <b>constancia de Instituto Mara</b>, que <b>no</b> es un documento oficial de la SEP ni una certificación de CONOCER. El curso <b>no es terapia ni diagnóstico</b> y <b>no sustituye la atención psicológica o médica</b>. Si en algún momento te sientes rebasado, en el módulo 3 encontrarás señales para buscar ayuda. Si tienes pensamientos de hacerte daño, llama ya a la <b>Línea de la Vida 800 911 2000</b> (24 horas, gratuita) o al <b>911</b> en una emergencia."},{"tipo":"texto","texto":"Una <b>emoción</b> es una reacción breve de todo tu cuerpo ante algo que te importa. Tiene tres partes que ocurren casi al mismo tiempo: lo que <b>sientes en el cuerpo</b> (corazón acelerado, nudo en la garganta), lo que <b>piensas</b> («esto es injusto») y lo que <b>te dan ganas de hacer</b> (gritar, huir, abrazar). Las emociones duran segundos o minutos; cuando un tono emocional se queda por horas o días le llamamos <b>estado de ánimo</b>."},{"tipo":"tabla","titulo":"Cada emoción trae un mensaje","encabezados":["Emoción","Qué suele avisarte","Hacia qué te empuja"],"filas":[["Miedo","Hay un peligro o algo incierto","Protegerte, prepararte, alejarte"],["Enojo","Algo es injusto o te bloquea un objetivo","Poner un límite, defenderte"],["Tristeza","Perdiste algo o a alguien importante","Detenerte, pedir apoyo, despedirte"],["Alegría","Algo va bien o lograste algo","Acercarte, compartir, repetir"],["Asco","Algo te parece dañino o inaceptable","Rechazar, apartarte"],["Sorpresa","Pasó algo inesperado","Poner atención, reorientarte"]],"nota":"No hay emociones buenas o malas: hay emociones <b>agradables o desagradables</b>, y formas de actuar que ayudan o que dañan."},{"tipo":"texto","texto":"Ejemplo: Laura, cajera en una tienda de autoservicio, siente enojo cuando un cliente le avienta el cambio. El enojo le avisa que la trataron sin respeto. El problema no es sentir enojo; el problema sería aventarle el cambio de regreso. Lo que haces con la emoción es lo que puedes aprender a manejar."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una emoción es…","ops":["Una reacción breve del cuerpo y la mente ante algo que te importa","Un defecto de carácter que hay que eliminar","Lo mismo que un estado de ánimo que dura semanas"],"correcta":0,"explica":"Las emociones son breves; los estados de ánimo duran más."},{"p":"Sentir enojo cuando te tratan mal…","ops":["Significa que eres una persona agresiva","Debe esconderse siempre","Es una señal útil: algo te parece injusto"],"correcta":2,"explica":"El enojo informa; lo que importa es cómo actúas."},{"p":"La tristeza suele empujarte a…","ops":["Celebrar","Detenerte y buscar apoyo","Atacar a otros"],"correcta":1,"explica":"Por eso tras una pérdida tenemos menos energía y buscamos compañía."}]},{"tipo":"relacionar","rotulo":"Relaciona la situación con la emoción más probable","pares":[["Te dicen que habrá recorte de personal y no sabes si te toca","Miedo"],["Un compañero presenta tu trabajo como suyo","Enojo"],["Tu mejor amiga se muda a otra ciudad","Tristeza"],["Te avisan que aprobaste tu examen de admisión","Alegría"],["Encuentras comida echada a perder en el refri de la oficina","Asco"]]},{"tipo":"reflexion","rotulo":"Tu semana emocional","pregunta":"Piensa en los últimos siete días. ¿Qué emoción sentiste más veces y en qué situación? ¿Qué te estaba avisando?","ayuda":"La emoción que más sentí fue… cuando… Creo que me avisaba que…"},{"tipo":"clave","items":["Una emoción es una reacción breve de cuerpo, pensamiento y ganas de actuar.","Todas las emociones informan algo; lo que se maneja es la conducta.","Este curso no es terapia: da constancia de Instituto Mara y te enseña cuándo pedir ayuda."]}]},{"id":"c-inteligencia-emocional-m1-l2","titulo":"Lección 2 — Qué es la inteligencia emocional (y qué no es)","objetivo":"describir el modelo de habilidades de Salovey y Mayer, ubicar el papel de Goleman y distinguir la inteligencia emocional de sus mitos.","bloques":[{"tipo":"texto","texto":"El término <b>inteligencia emocional</b> lo propusieron formalmente los psicólogos <b>Peter Salovey y John D. Mayer en 1990</b>. Para ellos es un conjunto de <b>habilidades</b>: percibir con precisión las emociones (propias y ajenas), usarlas para pensar mejor, comprenderlas y regularlas. En 1997 lo organizaron en cuatro ramas."},{"tipo":"tabla","titulo":"Modelo de cuatro ramas (Mayer y Salovey)","encabezados":["Habilidad","Qué significa","Ejemplo cotidiano"],"filas":[["Percibir emociones","Notar lo que sientes tú y lo que muestran otros en la cara, la voz y la postura","Darte cuenta de que tu hijo llegó callado y con los hombros caídos"],["Usar las emociones para pensar","Aprovechar el estado de ánimo para la tarea adecuada","Dejar la conciliación de facturas para cuando estés tranquilo"],["Comprender emociones","Saber de dónde vienen y cómo cambian","Entender que la irritación de tu jefe viene de la presión por el cierre de mes"],["Regular emociones","Manejar lo que sientes y ayudar a otros a hacerlo","Respirar antes de contestar un mensaje molesto del grupo de la familia"]]},{"tipo":"texto","texto":"El periodista y psicólogo <b>Daniel Goleman</b> popularizó el tema con su libro <i>Inteligencia emocional</i> (1995), que fue un éxito mundial. Su aporte fue <b>divulgar</b> la idea y llevarla a las empresas; sin embargo, algunas afirmaciones populares (por ejemplo, que la inteligencia emocional «importa más que el coeficiente intelectual» para todo) <b>no están respaldadas</b> de forma sólida por la investigación. En este curso nos quedamos con lo que sí tiene respaldo: son habilidades que se pueden practicar."},{"tipo":"comparar","titulo":"Mitos y realidad","malTitulo":"Lo que se dice por ahí","mal":"«Ser emocionalmente inteligente es estar siempre feliz.» «Es nunca enojarse.» «Se nace con ella o no.» «Es lo único que importa para triunfar.»","bienTitulo":"Lo que dice la evidencia","bien":"Es <b>sentir todas las emociones</b> y manejarlas bien. Enojarse a veces es sano si se expresa con respeto. Las habilidades <b>se pueden entrenar</b> con práctica. Ayuda en el trabajo y las relaciones, pero <b>no es la única</b> variable importante."},{"tipo":"relacionar","rotulo":"Relaciona el ejemplo con la rama del modelo","pares":[["Notas por el tono de voz que tu clienta está molesta","Percibir emociones"],["Aprovechas tu buen ánimo de la mañana para la junta creativa","Usar las emociones para pensar"],["Entiendes que tu frustración viene del cansancio, no de tu pareja","Comprender emociones"],["Caminas cinco minutos antes de responder un correo que te enojó","Regular emociones"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"¿Quiénes propusieron formalmente el concepto de inteligencia emocional en 1990?","ops":["Peter Salovey y John D. Mayer","Daniel Goleman y Howard Gardner","Sigmund Freud y Carl Jung"],"correcta":0,"explica":"Goleman lo popularizó en 1995."},{"p":"Una persona emocionalmente inteligente…","ops":["Nunca siente enojo","Siempre está de buen humor","Siente enojo o tristeza, pero los maneja sin dañar"],"correcta":2,"explica":"Regular no es suprimir."},{"p":"La inteligencia emocional…","ops":["Solo la tienen los líderes","Se puede desarrollar con práctica","Es fija desde el nacimiento"],"correcta":1,"explica":"Por eso tiene sentido tomar un curso."}]},{"tipo":"clave","items":["Salovey y Mayer (1990): la inteligencia emocional es un conjunto de habilidades.","Cuatro ramas: percibir, usar, comprender y regular emociones.","Goleman la popularizó; no es estar siempre feliz ni vale más que todo lo demás."]}]},{"id":"c-inteligencia-emocional-m1-l3","titulo":"Lección 3 — Emoción, pensamiento y conducta","objetivo":"identificar la cadena situación–pensamiento–emoción–conducta y registrar una situación propia.","bloques":[{"tipo":"texto","texto":"Casi nunca es la situación sola la que te hace sentir. Entre lo que pasa y lo que sientes hay una <b>interpretación</b>: lo que te dices sobre lo que pasó. Por eso dos personas ante el mismo hecho sienten cosas distintas. Si tu jefa no te saluda en la mañana, puedes pensar «está enojada conmigo» (y sentir angustia) o «viene preocupada por algo» (y sentir curiosidad o nada en especial)."},{"tipo":"pasos","rotulo":"La cadena emocional","pasos":["<b>Situación:</b> lo que pasó, descrito como lo grabaría una cámara. «Mi jefa pasó sin saludarme.»","<b>Pensamiento:</b> lo que te dijiste. «Seguro hice algo mal.»","<b>Emoción y cuerpo:</b> lo que sentiste y dónde. «Angustia, estómago apretado.»","<b>Conducta:</b> lo que hiciste. «Me pasé la mañana revisando mis correos buscando el error.»","<b>Consecuencia:</b> qué resultó. «Avancé poco y seguí preocupada; luego supe que ella tenía a su mamá en el hospital.»"]},{"tipo":"ordenar","rotulo":"Ordena la cadena","items":[{"frase":"Situación pensamiento emoción y después conducta","es":"El orden típico de la cadena"},{"frase":"Lo que te dices cambia lo que sientes","es":"La idea central de esta lección"}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Entre la situación y la emoción está la ___ que haces de lo que pasó.","resp":["interpretación","interpretacion"],"es":"Lo que te dices sobre el hecho"},{"frase":"Una emoción que se queda por días se llama estado de ___.","resp":["ánimo","animo"]},{"frase":"Lo que haces a partir de una emoción se llama ___.","resp":["conducta","comportamiento"]}]},{"tipo":"plantilla","rotulo":"Registro de una situación","texto":"Fecha:\nSituación (como la grabaría una cámara):\nLo que pensé:\nLo que sentí (emoción e intensidad del 0 al 10):\nDónde lo sentí en el cuerpo:\nLo que hice:\nQué resultó:\nOtra forma posible de verlo:","nota":"Llénalo al menos tres veces esta semana. Te servirá en el módulo 2."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Dos compañeros reciben la misma crítica y uno se enoja y el otro no. ¿Por qué?","ops":["Cada uno la interpreta de forma distinta","Uno de los dos no tiene emociones","La crítica cambió de un compañero a otro"],"correcta":0,"explica":"La interpretación explica gran parte de la diferencia."},{"p":"¿Cuál describe una situación «como la grabaría una cámara»?","ops":["El cliente me humilló a propósito","El cliente me odia","El cliente dijo «esto está mal hecho» en voz alta"],"correcta":2,"explica":"Las otras dos ya son interpretaciones."}]},{"tipo":"clave","items":["Situación → pensamiento → emoción → conducta → consecuencia.","La interpretación influye mucho en lo que sientes.","Registrar situaciones es el primer paso para manejarlas."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"Una emoción se distingue de un estado de ánimo porque…","ops":["Dura semanas","Solo ocurre en la mente","Nunca se nota en el cuerpo","Es más breve y responde a algo concreto"],"correcta":3},{"p":"¿Qué afirmación es correcta?","ops":["La tristeza es una enfermedad","La alegría es la única emoción sana","Todas las emociones dan información útil","El enojo siempre es malo"],"correcta":2},{"p":"El concepto de inteligencia emocional lo propusieron formalmente en 1990…","ops":["La Organización Mundial de la Salud","Peter Salovey y John D. Mayer","Daniel Goleman","Albert Ellis"],"correcta":1},{"p":"El papel principal de Daniel Goleman fue…","ops":["Popularizar el tema con su libro de 1995","Crear el concepto en 1970","Demostrar que vale más que el coeficiente intelectual en todo","Diseñar la NOM-035"],"correcta":0},{"p":"Las cuatro ramas del modelo de Mayer y Salovey son…","ops":["Pensar, sentir, actuar y dormir","Miedo, enojo, tristeza y alegría","Motivación, dinero, poder y éxito","Percibir, usar, comprender y regular emociones"],"correcta":3},{"p":"Ser emocionalmente inteligente significa…","ops":["Estar feliz todo el tiempo","Ocultar lo que sientes","Sentir todas las emociones y manejarlas sin dañar","No enojarse nunca"],"correcta":2},{"p":"En la cadena emocional, lo que está entre la situación y la emoción es…","ops":["El estado de ánimo","El pensamiento o interpretación","La consecuencia","La conducta"],"correcta":1},{"p":"La constancia de este curso…","ops":["Es de Instituto Mara y no sustituye atención psicológica","Es un título oficial de la SEP","Es una certificación de CONOCER","Habilita para dar terapia"],"correcta":0}]}},{"id":"c-inteligencia-emocional-m2","titulo":"Módulo 2 — Autoconciencia y regulación","resumen":"Nombrar con precisión lo que sientes, calmar el cuerpo con la respiración, revisar tus pensamientos y hacer una pausa antes de reaccionar. Tres lecciones y una evaluación.","lecciones":[{"id":"c-inteligencia-emocional-m2-l1","titulo":"Lección 1 — Ponerle nombre a lo que sientes","objetivo":"ampliar tu vocabulario emocional y medir la intensidad de lo que sientes.","bloques":[{"tipo":"texto","texto":"Mucha gente solo usa tres palabras para lo que siente: «bien», «mal» y «estresado». El problema es que «mal» puede ser cansancio, frustración, culpa, soledad o miedo, y cada una pide algo distinto. Ponerle un <b>nombre preciso</b> a la emoción te ayuda a entenderla y a decidir qué hacer; varios estudios sugieren que nombrarla también ayuda a bajar un poco su intensidad."},{"tipo":"tabla","titulo":"Amplía tu vocabulario","encabezados":["Familia","Intensidad baja","Intensidad media","Intensidad alta"],"filas":[["Enojo","Molestia, fastidio","Irritación, frustración","Rabia, furia"],["Miedo","Inquietud, nervios","Preocupación, ansiedad","Pánico, terror"],["Tristeza","Desánimo, nostalgia","Decepción, pena","Desesperanza, desolación"],["Alegría","Tranquilidad, gusto","Entusiasmo, orgullo","Euforia, júbilo"],["Vergüenza","Incomodidad","Pena, bochorno","Humillación"]],"nota":"Súmale la intensidad del 0 al 10: «frustración, 6» dice mucho más que «mal»."},{"tipo":"tarjetas","rotulo":"¿Cuál es la diferencia?","tarjetas":[{"frente":"Culpa","reverso":"«Hice algo malo.» Se enfoca en una acción y empuja a reparar."},{"frente":"Vergüenza","reverso":"«Soy malo.» Se enfoca en la persona entera y empuja a esconderse."},{"frente":"Frustración","reverso":"Algo bloquea lo que querías lograr."},{"frente":"Decepción","reverso":"Algo o alguien no cumplió lo que esperabas."},{"frente":"Ansiedad","reverso":"Preocupación por algo que podría pasar en el futuro."}]},{"tipo":"practica","rotulo":"Nombra con precisión","preguntas":[{"p":"Llevas tres semanas intentando que el SAT te dé una cita y el sistema no te deja. Lo más preciso es…","ops":["Asco","Frustración","Tristeza"],"correcta":1,"explica":"Algo bloquea tu objetivo."},{"p":"Tu hermano prometió llegar a tu cumpleaños y no llegó ni avisó. Lo más probable es…","ops":["Decepción","Pánico","Euforia"],"correcta":0,"explica":"Esperabas algo que no ocurrió."},{"p":"Mañana presentas los resultados ante el director y no dejas de pensar en qué saldrá mal. Es…","ops":["Nostalgia","Orgullo","Ansiedad"],"correcta":2,"explica":"Preocupación por lo que podría pasar."}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"La culpa dice «hice algo malo»; la ___ dice «soy malo».","resp":["vergüenza","verguenza"]},{"frase":"Además del nombre, conviene medir la ___ de la emoción del 0 al 10.","resp":["intensidad"]},{"frase":"La rabia es la forma de intensidad alta del ___.","resp":["enojo"]}]},{"tipo":"reflexion","rotulo":"Tu emoción de hoy","pregunta":"Escribe cómo te sientes en este momento usando una palabra precisa y un número del 0 al 10. ¿Dónde lo notas en el cuerpo?","ayuda":"Ahora siento… (…/10) y lo noto en…"},{"tipo":"clave","items":["«Bien», «mal» y «estresado» no alcanzan: busca la palabra precisa.","Nombre + intensidad (0 a 10) + lugar en el cuerpo.","Culpa y vergüenza no son lo mismo: la culpa empuja a reparar."]}]},{"id":"c-inteligencia-emocional-m2-l2","titulo":"Lección 2 — Calmar el cuerpo: la respiración","objetivo":"practicar la respiración diafragmática y otras técnicas breves para bajar la activación.","bloques":[{"tipo":"texto","texto":"Cuando te enojas o te asustas, tu cuerpo se prepara para pelear o huir: el corazón se acelera, la respiración se vuelve corta y rápida, los músculos se tensan. En ese estado es difícil pensar con claridad. La buena noticia es que la <b>respiración</b> es una de las pocas funciones automáticas que puedes controlar a voluntad, y respirar <b>lento y con el abdomen</b> ayuda a que el cuerpo baje la activación."},{"tipo":"pasos","rotulo":"Respiración diafragmática (3 a 5 minutos)","pasos":["Siéntate con la espalda recta o acuéstate. Pon una mano en el pecho y otra sobre el abdomen.","Inhala por la nariz contando hasta 4. La mano del abdomen sube; la del pecho casi no se mueve.","Exhala despacio por la boca contando hasta 6. Deja que el abdomen baje.","Repite de 6 a 10 veces. Lo importante es que la exhalación dure más que la inhalación.","Si te mareas, respira más suave y vuelve a tu ritmo normal. No se trata de forzar."]},{"tipo":"tabla","titulo":"Otras técnicas rápidas","encabezados":["Técnica","Cómo se hace","Cuándo usarla"],"filas":[["Exhalación larga","Tres respiraciones soltando el aire el doble de lento de lo que entra","En el baño de la oficina antes de una junta tensa"],["5-4-3-2-1","Nombra 5 cosas que ves, 4 que oyes, 3 que tocas, 2 que hueles y 1 que saboreas","Cuando la mente se acelera con preocupaciones"],["Relajación muscular","Aprieta un grupo de músculos 5 segundos y suéltalo 10; recorre el cuerpo","En la noche, si te cuesta dormir"],["Moverte","Caminar diez minutos o subir escaleras","Cuando traes mucho enojo acumulado"]]},{"tipo":"destacado","texto":"<b>Honestidad:</b> estas técnicas ayudan a bajar la tensión del momento; no curan la ansiedad ni la depresión. Si la angustia es muy frecuente, muy intensa o no te deja trabajar o dormir, consulta a un profesional de la salud."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En la respiración diafragmática, lo que más ayuda es…","ops":["Aguantar el aire un minuto","Exhalar más lento de lo que inhalas","Respirar lo más rápido posible"],"correcta":1,"explica":"La exhalación larga favorece la calma."},{"p":"La mano que debe subir al inhalar es la del…","ops":["Abdomen","Pecho","Cuello"],"correcta":0,"explica":"Por eso se llama diafragmática o abdominal."},{"p":"El ejercicio 5-4-3-2-1 sirve para…","ops":["Curar la ansiedad para siempre","Calcular tu estrés","Traer la atención al presente con los sentidos"],"correcta":2,"explica":"Te saca del ciclo de preocupaciones por un momento."}]},{"tipo":"ordenar","rotulo":"Ordena la instrucción","items":[{"frase":"Inhala contando cuatro y exhala contando seis","es":"El ritmo básico"},{"frase":"Si te mareas respira más suave","es":"Una precaución"}]},{"tipo":"clave","items":["El cuerpo se activa ante el peligro; la respiración lenta ayuda a bajarlo.","Diafragmática: mano en el abdomen, inhala 4, exhala 6.","Las técnicas alivian el momento; no sustituyen la atención profesional."]}]},{"id":"c-inteligencia-emocional-m2-l3","titulo":"Lección 3 — Revisar pensamientos y hacer una pausa","objetivo":"detectar pensamientos distorsionados, buscar alternativas más equilibradas y aplicar una pausa antes de reaccionar.","bloques":[{"tipo":"texto","texto":"Cuando una emoción es muy fuerte, la mente tiende a exagerar. Estos atajos se conocen como <b>distorsiones cognitivas</b> y fueron descritos por la terapia cognitiva (Aaron Beck y sus seguidores). La <b>reestructuración</b> consiste en revisar el pensamiento como lo haría un buen detective: ¿qué pruebas hay?, ¿hay otra explicación?, ¿qué le diría a un amigo en mi lugar? No se trata de «pensar positivo», sino de <b>pensar con más precisión</b>."},{"tipo":"tabla","titulo":"Distorsiones frecuentes","encabezados":["Distorsión","Ejemplo","Pensamiento más equilibrado"],"filas":[["Catastrofizar","«Si me equivoco en el reporte me van a correr.»","«Un error se corrige; nunca han corrido a nadie por uno.»"],["Leer la mente","«Seguro piensan que soy un inútil.»","«No sé lo que piensan; puedo preguntar cómo me fue.»"],["Todo o nada","«Si no me sale perfecto, no sirvo.»","«Me salió bien en un 80% y puedo mejorar lo demás.»"],["Generalizar","«Siempre me pasa lo mismo, nadie me respeta.»","«Esta vez no me respetaron; otras veces sí.»"],["Personalizar","«Mi hijo reprobó por mi culpa.»","«Influyo, pero hay otros factores; ¿cómo lo apoyo ahora?»"]]},{"tipo":"relacionar","rotulo":"Relaciona el pensamiento con la distorsión","pares":[["«El jefe no contestó mi mensaje: seguro me va a despedir.»","Catastrofizar"],["«Mi suegra no dijo nada del mole: seguro le pareció horrible.»","Leer la mente"],["«Nunca hago nada bien.»","Generalizar"],["«Si no vendo la meta completa, fui un fracaso.»","Todo o nada"],["«La junta salió mal porque yo estaba ahí.»","Personalizar"]]},{"tipo":"pasos","rotulo":"La pausa STOP antes de reaccionar","pasos":["<b>S — Suspende:</b> detente. No contestes, no envíes, no grites todavía.","<b>T — Toma aire:</b> haz tres respiraciones lentas.","<b>O — Observa:</b> ¿qué siento (nombre y 0 a 10)?, ¿qué me estoy diciendo?, ¿hay otra forma de verlo?","<b>P — Procede:</b> elige una respuesta que te acerque a lo que quieres, no solo la que te pide el impulso."]},{"tipo":"comparar","titulo":"Reaccionar o responder","malTitulo":"Sin pausa","mal":"El cliente escribe en mayúsculas quejándose del pedido. Contestas en caliente: «Pues si no le gusta, compre en otro lado.» Pierdes al cliente y te reportan.","bienTitulo":"Con pausa","bien":"Lees, respiras, notas «enojo, 7» y el pensamiento «me está atacando». Lo reformulas: «está molesto por el retraso». Contestas: «Entiendo su molestia por el retraso. Reviso su pedido y le confirmo hoy antes de las 5.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Reestructurar un pensamiento es…","ops":["Ignorar lo que pasó","Revisar las pruebas y buscar una versión más precisa","Obligarte a pensar solo cosas bonitas"],"correcta":1,"explica":"Precisión, no optimismo forzado."},{"p":"En STOP, la «O» significa…","ops":["Observar lo que sientes y piensas","Olvidar el problema","Obedecer al impulso"],"correcta":0,"explica":"Observar da espacio para elegir."}]},{"tipo":"clave","items":["Las emociones intensas producen distorsiones: catastrofizar, leer la mente, todo o nada.","Reestructurar es buscar pruebas y una versión más equilibrada.","STOP: suspende, toma aire, observa y procede."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"¿Por qué conviene nombrar con precisión una emoción?","ops":["Hace que desaparezca para siempre","Es solo para psicólogos","Sirve para culpar a otros","Ayuda a entenderla y decidir qué hacer"],"correcta":3},{"p":"«Hice algo malo y quiero repararlo» describe…","ops":["Euforia","Asco","Culpa","Vergüenza"],"correcta":2},{"p":"Llevas semanas intentando un trámite y algo siempre lo bloquea. La emoción más precisa es…","ops":["Sorpresa","Frustración","Nostalgia","Orgullo"],"correcta":1},{"p":"En la respiración diafragmática…","ops":["Sube la mano del abdomen y la exhalación es más larga","Sube solo el pecho","Se respira rápido por la boca","Se aguanta el aire lo más posible"],"correcta":0},{"p":"Las técnicas de respiración…","ops":["Curan la depresión","Solo sirven si se hacen una hora","Son peligrosas para todos","Alivian la tensión del momento, pero no sustituyen la atención profesional"],"correcta":3},{"p":"«Si me equivoco en la factura me van a correr» es un ejemplo de…","ops":["Pensamiento equilibrado","Empatía","Catastrofizar","Personalizar"],"correcta":2},{"p":"Reestructurar un pensamiento significa…","ops":["Discutir con quien te hizo enojar","Revisar pruebas y buscar una interpretación más precisa","Pensar positivo a la fuerza","Negar lo que sientes"],"correcta":1},{"p":"El orden de la pausa STOP es…","ops":["Suspende, toma aire, observa y procede","Grita, respira, olvida y sigue","Observa, contesta, respira y te vas","Toma aire, contesta, suspende y observa"],"correcta":0}]}},{"id":"c-inteligencia-emocional-m3","titulo":"Módulo 3 — Estrés, burnout y hábitos que protegen","resumen":"Qué es el estrés, la diferencia entre estrés agudo y crónico, el burnout según la OMS, los hábitos que te protegen y tu plan personal. Tres lecciones y una evaluación.","lecciones":[{"id":"c-inteligencia-emocional-m3-l1","titulo":"Lección 1 — Qué es el estrés","objetivo":"explicar qué es el estrés, distinguir el agudo del crónico y reconocer sus señales en el cuerpo, la mente y la conducta.","bloques":[{"tipo":"texto","texto":"El <b>estrés</b> es la respuesta de tu cuerpo y tu mente cuando sientes que lo que se te exige es más de lo que puedes manejar con tus recursos. No siempre es malo: un poco de estrés antes de una entrevista de trabajo te pone alerta y te ayuda a prepararte. El problema aparece cuando la presión es <b>demasiada</b> o <b>no se acaba nunca</b>."},{"tipo":"comparar","titulo":"Estrés agudo y estrés crónico","malTitulo":"Estrés agudo","mal":"Dura minutos, horas o pocos días. Tiene un motivo claro: el tráfico en Periférico, la entrega de mañana, una discusión. Cuando pasa, el cuerpo se recupera. En dosis moderadas puede ayudarte a rendir.","bienTitulo":"Estrés crónico","bien":"Dura semanas o meses sin pausa: deudas que no bajan, un trabajo con exigencias imposibles, cuidar solo a un familiar enfermo. El cuerpo no se recupera y con el tiempo aumenta el riesgo de problemas de sueño, digestivos, de presión arterial, ansiedad y depresión."},{"tipo":"tabla","titulo":"Señales de estrés","encabezados":["Área","Señales frecuentes"],"filas":[["Cuerpo","Dolor de cabeza o de espalda, tensión en cuello y mandíbula, gastritis, cansancio que no se quita, gripas frecuentes"],["Mente","Preocupación constante, olvidos, dificultad para concentrarte, pensar que no vas a poder"],["Emociones","Irritabilidad, llanto fácil, desánimo, sentirte abrumado"],["Conducta","Dormir mal, comer de más o de menos, fumar o beber más, aislarte, postergar"]],"nota":"Estas señales también pueden deberse a otras causas de salud. Si persisten, consulta a tu médico."},{"tipo":"relacionar","rotulo":"¿Agudo o crónico?","pares":[["Nervios la noche antes de tu examen de manejo","Estrés agudo (breve, motivo claro)"],["Ocho meses cubriendo dos puestos sin aumento ni descanso","Estrés crónico (sostenido sin recuperación)"],["Un susto al frenar de golpe en la carretera","Reacción de alarma de segundos"],["Un año cuidando sola a tu papá con demencia","Sobrecarga prolongada de cuidados"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El estrés aparece cuando…","ops":["Estás de vacaciones","Duermes bien","Sientes que las exigencias rebasan tus recursos"],"correcta":2,"explica":"Es una evaluación de demandas contra recursos."},{"p":"¿Qué hace más dañino al estrés?","ops":["Que dure unos minutos","Que dure mucho sin recuperación","Que tenga un motivo claro"],"correcta":1,"explica":"El problema principal es la falta de recuperación."},{"p":"Tener gastritis, insomnio e irritabilidad por meses…","ops":["Merece atención y consulta médica","Es normal y no hay que hacer nada","Se quita solo siempre"],"correcta":0,"explica":"Tus síntomas merecen atención."}]},{"tipo":"reflexion","rotulo":"Tu termómetro","pregunta":"¿Qué señales de estrés notas en ti ahora? Marca de 0 a 10 cuánto estrés sientes esta semana y escribe cuál es su fuente principal.","ayuda":"Mi estrés esta semana es de… Lo noto en… La fuente principal es…"},{"tipo":"clave","items":["Estrés = exigencias que sientes mayores que tus recursos.","El agudo es breve y se recupera; el crónico se sostiene sin pausa y daña.","Escucha las señales del cuerpo, la mente, las emociones y la conducta."]}]},{"id":"c-inteligencia-emocional-m3-l2","titulo":"Lección 2 — Burnout y cuándo buscar ayuda","objetivo":"describir el burnout según la clasificación de la OMS y reconocer las señales para buscar ayuda profesional.","bloques":[{"tipo":"texto","texto":"El <b>burnout</b> o <b>síndrome de desgaste ocupacional</b> aparece en la <b>Clasificación Internacional de Enfermedades (CIE-11)</b> de la Organización Mundial de la Salud, vigente desde 2022, dentro del capítulo de factores que influyen en el estado de salud. La OMS aclara que <b>no lo clasifica como una enfermedad</b>, sino como un <b>fenómeno ocupacional</b>: resulta del estrés crónico en el trabajo que no se ha manejado con éxito y se refiere solo al contexto laboral."},{"tipo":"tabla","titulo":"Las tres dimensiones del burnout según la OMS","encabezados":["Dimensión","Cómo se vive"],"filas":[["Agotamiento","Sentirte sin energía desde que te levantas; el fin de semana no alcanza para recuperarte"],["Distancia mental del trabajo","Cinismo o sentimientos negativos hacia el trabajo: «me da igual», «que se arreglen ellos»"],["Menor eficacia profesional","Sentir que ya no rindes ni logras nada, aunque le eches ganas"]],"nota":"Solo un profesional de la salud puede valorar tu caso. Este cuadro es para que reconozcas señales, no para que te diagnostiques."},{"tipo":"destacado","texto":"<b>Busca ayuda profesional si…</b><br>• la tristeza, la angustia o el agotamiento duran más de dos semanas y no mejoran;<br>• ya no puedes trabajar, estudiar o atender tu casa como antes;<br>• duermes muy poco o casi todo el día;<br>• estás usando alcohol, pastillas u otras sustancias para aguantar;<br>• tienes ataques de pánico o te sientes sin esperanza.<br><br>Puedes empezar con tu médico familiar (en el IMSS, ISSSTE o centro de salud) o con un psicólogo con cédula. <b>Si piensas en hacerte daño o quitarte la vida, llama ahora a la Línea de la Vida 800 911 2000</b> (24 horas, gratuita y confidencial) o al <b>911</b> en una emergencia."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Según la OMS, el burnout es…","ops":["Una enfermedad mental grave","Un pretexto para no trabajar","Un fenómeno ocupacional, no una enfermedad"],"correcta":2,"explica":"Así aparece en la CIE-11."},{"p":"El burnout se refiere a…","ops":["Solo a los deportistas","El contexto laboral","Cualquier problema de la vida"],"correcta":1,"explica":"La OMS lo limita al ámbito del trabajo."},{"p":"Tu compañera dice que ya no ve sentido a seguir viviendo. Lo primero es…","ops":["Tomarlo en serio, no dejarla sola y llamar a la Línea de la Vida o al 911","Cambiar de tema para no incomodarla","Decirle que es el estrés y que ya se le pasará"],"correcta":0,"explica":"Siempre se toma en serio."}]},{"tipo":"relacionar","rotulo":"Relaciona la frase con la dimensión del burnout","pares":[["«Llego el lunes igual de cansado que el viernes.»","Agotamiento"],["«Los clientes me dan igual, que se quejen con quien quieran.»","Distancia mental o cinismo"],["«Hago y hago y siento que nada me sale.»","Menor eficacia profesional"]]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"La OMS incluye el burnout en la CIE-___ como fenómeno ocupacional.","resp":["11","once"]},{"frase":"La Línea de la Vida atiende las ___ horas y es gratuita.","resp":["24","veinticuatro"]},{"frase":"El burnout resulta del estrés ___ en el trabajo que no se ha manejado con éxito.","resp":["crónico","cronico"]}]},{"tipo":"clave","items":["Burnout: fenómeno ocupacional en la CIE-11, no una enfermedad.","Tres dimensiones: agotamiento, distancia mental y menor eficacia.","Si hay señales de alarma, busca ayuda; en riesgo: 800 911 2000 o 911."]}]},{"id":"c-inteligencia-emocional-m3-l3","titulo":"Lección 3 — Hábitos que protegen y tu plan","objetivo":"revisar tus hábitos de sueño, movimiento y uso del celular y armar un plan personal contra el estrés.","bloques":[{"tipo":"texto","texto":"No hay una técnica mágica contra el estrés, pero sí hábitos con buen respaldo que te dan más «colchón» para aguantar la presión. Tres de los más importantes son el <b>sueño</b>, el <b>movimiento</b> y los <b>límites digitales</b>. Además, recuerda que muchas fuentes de estrés vienen del trabajo o de la situación económica: cuidarte ayuda, pero a veces también hay que <b>cambiar la situación</b> (hablar con tu jefe, pedir apoyo, reorganizar deudas)."},{"tipo":"tabla","titulo":"Tres hábitos base","encabezados":["Hábito","Recomendación de referencia","Idea práctica"],"filas":[["Sueño","Los adultos necesitan en general 7 horas o más por noche","Misma hora para dormir y despertar, también en fin de semana; sin pantalla 30 minutos antes"],["Movimiento","La OMS recomienda a los adultos de 150 a 300 minutos de actividad moderada a la semana","Caminar a paso rápido 30 minutos, 5 días; bajarte una parada antes del camión"],["Límites digitales","No hay una cifra oficial; la clave es que el celular no invada descanso y familia","Silenciar el grupo del trabajo después de tu horario; celular fuera de la recámara"]]},{"tipo":"excel","rotulo":"Tu registro de sueño","datos":[["Día","Horas dormidas"],["Lunes",6],["Martes",5],["Miércoles",7],["Jueves",6],["Viernes",5],["Sábado",8],["Domingo",5],["Promedio",""],["Noches con menos de 7 horas",""]],"retos":[{"celda":"B9","formula":"=PROMEDIO(B2:B8)","esperado":6,"requiere":"PROMEDIO(","texto":"<b>B9</b>: calcula el promedio de horas dormidas en la semana con PROMEDIO.","pista":"=PROMEDIO(B2:B8)","explica":"Seis horas en promedio: por debajo de las 7 recomendadas para adultos."},{"celda":"B10","formula":"=CONTAR.SI(B2:B8,\"<7\")","esperado":5,"requiere":"CONTAR.SI(","texto":"<b>B10</b>: cuenta cuántas noches durmió menos de 7 horas. Usa CONTAR.SI.","pista":"El criterio va entre comillas: \"<7\".","explica":"Cinco de siete noches con sueño corto: un buen punto para empezar el plan."}]},{"tipo":"plantilla","rotulo":"Mi plan personal contra el estrés","texto":"Mis principales fuentes de estrés:\n1.\n2.\n\nLo que sí puedo cambiar de la situación:\n\nMis señales de alerta (cuerpo, mente, conducta):\n\nHábito de sueño que voy a cuidar:\nMovimiento semanal (qué, cuándo, cuánto):\nLímite digital:\nTécnica de calma que usaré (respiración, STOP, 5-4-3-2-1):\nPersona con quien puedo hablar:\nSi mis señales empeoran, voy a buscar ayuda en:\nLínea de la Vida: 800 911 2000 (24 horas) / Emergencias: 911","nota":"Guárdalo en tu celular y revísalo cada domingo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La OMS recomienda a los adultos de actividad moderada a la semana…","ops":["10 minutos","Diez horas diarias","De 150 a 300 minutos"],"correcta":2,"explica":"Por ejemplo, 30 minutos cinco días."},{"p":"Un buen límite digital es…","ops":["Contestar correos a las 2 de la mañana","Silenciar los grupos del trabajo fuera de tu horario","Dormir con el celular bajo la almohada"],"correcta":1,"explica":"Protege tu descanso."},{"p":"Si tu estrés viene de una carga de trabajo imposible…","ops":["Cuidarte ayuda, y también conviene hablar para cambiar la situación","Solo tienes que respirar mejor","Es tu culpa por no aguantar"],"correcta":0,"explica":"Hábitos y cambios en la situación van juntos."}]},{"tipo":"clave","items":["Sueño (7 horas o más), movimiento (150–300 min/semana) y límites digitales.","Cuidarte no sustituye cambiar lo que sí se puede cambiar de la situación.","Tu plan incluye señales de alerta y a dónde acudir si empeoras."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"El estrés aparece cuando…","ops":["Tienes tiempo libre","Todo sale como esperabas","Duermes ocho horas","Sientes que las exigencias superan tus recursos"],"correcta":3},{"p":"Una diferencia clave entre estrés agudo y crónico es que el crónico…","ops":["Siempre es útil","No afecta al cuerpo","Se sostiene por semanas o meses sin recuperación","Dura unos minutos"],"correcta":2},{"p":"¿Cuál es una señal de estrés en la conducta?","ops":["Sentirse abrumado","Beber o fumar más para aguantar","Dolor de cabeza","Preocupación constante"],"correcta":1},{"p":"Según la OMS, en la CIE-11 el burnout es…","ops":["Un fenómeno ocupacional, no una enfermedad","Una enfermedad infecciosa","Un trastorno de personalidad","Un tipo de depresión"],"correcta":0},{"p":"Las tres dimensiones del burnout son…","ops":["Hambre, sed y sueño","Miedo, enojo y alegría","Ansiedad, pánico y fobia","Agotamiento, distancia mental del trabajo y menor eficacia"],"correcta":3},{"p":"Si alguien te dice que piensa en quitarse la vida, lo correcto es…","ops":["Decirle que exagera","Esperar a que se le pase","Tomarlo en serio, no dejarlo solo y llamar al 800 911 2000 o al 911","Ignorarlo"],"correcta":2},{"p":"La OMS recomienda a los adultos a la semana…","ops":["Solo caminar el domingo","De 150 a 300 minutos de actividad moderada","30 minutos en total","Ningún ejercicio si hay estrés"],"correcta":1},{"p":"Un plan personal contra el estrés debe incluir…","ops":["Fuentes de estrés, hábitos, señales de alerta y a dónde pedir ayuda","Solo una lista de pendientes","Únicamente frases motivacionales","Nada, el estrés se va solo"],"correcta":0}]}},{"id":"c-inteligencia-emocional-m4","titulo":"Módulo 4 — Emociones en las relaciones","resumen":"Empatía, comunicación asertiva, manejo de conflictos y conversaciones difíciles, y tu plan de 30 días para practicar lo aprendido. Tres lecciones y una evaluación.","lecciones":[{"id":"c-inteligencia-emocional-m4-l1","titulo":"Lección 1 — Empatía: entender sin tener que estar de acuerdo","objetivo":"practicar la escucha empática y responder a las emociones de otros sin juzgar ni resolver de inmediato.","bloques":[{"tipo":"texto","texto":"La <b>empatía</b> es la capacidad de <b>entender lo que siente otra persona</b> y hacérselo saber. Ojo: entender no es darle la razón en todo ni cargar con su problema. Puedes entender el enojo de un cliente por el retraso de su pedido sin aceptar que te insulte. La empatía abre la puerta para que la otra persona se calme y el problema se pueda resolver."},{"tipo":"lista","items":["<b>Escucha completa:</b> deja el celular, mira a la persona y no prepares tu respuesta mientras habla.","<b>Nombra la emoción:</b> «Te noto preocupada», «Suena a que te sentiste ignorado».","<b>Valida:</b> «Tiene sentido que te moleste, llevas dos semanas esperando.»","<b>Pregunta antes de aconsejar:</b> «¿Quieres que te ayude a buscar una solución o prefieres desahogarte?»"]},{"tipo":"comparar","titulo":"Respuestas que cierran y respuestas que abren","malTitulo":"Cierran la conversación","mal":"Tu hijo adolescente dice que se siente solo en la nueva escuela. «No exageres, allá hay muchos niños.» «Yo a tu edad ni me quejaba.» «Ya se te pasará.»","bienTitulo":"Abren la conversación","bien":"«Suena difícil llegar a un lugar donde no conoces a nadie. ¿Qué ha sido lo más pesado?» Escuchas, y solo después preguntas si quiere ideas para hacer amigos."},{"tipo":"practica","rotulo":"Elige la respuesta más empática","preguntas":[{"p":"Tu compañero dice: «Me regañaron frente a todos y me dio mucha pena.»","ops":["«Pues para la otra no te equivoques.»","«A mí me pasó algo peor la semana pasada.»","«Qué feo que te expongan así. ¿Cómo estás?»"],"correcta":2,"explica":"Nombra la emoción y abre espacio; las otras juzgan o cambian el foco."},{"p":"Una clienta llega molesta porque le cobraron dos veces.","ops":["«Cálmese, señora.»","«Entiendo que es molesto ver un doble cargo. Lo reviso ahora mismo.»","«No es mi culpa, es el sistema.»"],"correcta":1,"explica":"Valida y actúa; «cálmese» suele enojar más."},{"p":"Tu pareja llega agotada del trabajo y te cuenta su día.","ops":["Escuchar y preguntar si quiere consejos o solo desahogarse","Darle de inmediato cinco soluciones","Contarle que tu día fue peor"],"correcta":0,"explica":"Pregunta antes de aconsejar."}]},{"tipo":"tarjetas","rotulo":"Frases que validan","tarjetas":[{"frente":"«Tiene sentido que…»","reverso":"Reconoce que la emoción tiene razones, aunque no estés de acuerdo con todo."},{"frente":"«Me imagino que…»","reverso":"Muestra que intentas ponerte en su lugar sin afirmar que sabes lo que siente."},{"frente":"«¿Te entendí bien que…?»","reverso":"Confirma que escuchaste y corrige malentendidos."},{"frente":"«¿Qué necesitas ahora?»","reverso":"Deja que la persona decida qué tipo de apoyo quiere."}]},{"tipo":"reflexion","rotulo":"Alguien que te escuchó bien","pregunta":"Recuerda a una persona que te hizo sentir realmente escuchado. ¿Qué hizo o dijo? ¿Qué puedes copiar de ella esta semana?","ayuda":"Esa persona… Voy a intentar…"},{"tipo":"clave","items":["Empatía es entender y mostrar que entiendes, no darle la razón en todo.","Escucha, nombra la emoción, valida y pregunta antes de aconsejar.","Evita minimizar («no exageres») y competir («a mí me fue peor»)."]}]},{"id":"c-inteligencia-emocional-m4-l2","titulo":"Lección 2 — Comunicación asertiva","objetivo":"distinguir los estilos pasivo, agresivo y asertivo y formular peticiones y límites con la fórmula de cuatro pasos.","bloques":[{"tipo":"texto","texto":"Ser <b>asertivo</b> es expresar lo que piensas, sientes y necesitas de forma <b>clara, directa y respetuosa</b>, cuidando tus derechos y los de la otra persona. En México a veces se confunde el respeto con quedarse callado («ni modo, así es mi jefe») o la sinceridad con gritar. La asertividad está en medio."},{"tipo":"tabla","titulo":"Tres estilos","encabezados":["Estilo","Cómo suena","Qué suele pasar"],"filas":[["Pasivo","«No, no pasa nada», aunque sí pase. Decir «sí» a todo.","Acumulas enojo, te sobrecargas y un día explotas."],["Agresivo","Gritos, sarcasmo, amenazas, «siempre haces todo mal».","Consigues algo en el momento, pero dañas la relación."],["Asertivo","«Me preocupa que… Te pido que…»","Hay más probabilidad de resolver sin dañar la relación."]]},{"tipo":"pasos","rotulo":"Fórmula para decir las cosas (cuatro pasos)","pasos":["<b>Hecho:</b> describe lo que pasó sin juzgar. «Esta semana llegaron tres pedidos después de las 6.»","<b>Emoción:</b> di lo que sientes, en primera persona. «Me siento presionada…»","<b>Necesidad:</b> explica por qué te importa. «…porque tengo que cerrar el inventario a las 7.»","<b>Petición concreta:</b> pide algo específico y posible. «¿Podemos acordar que los pedidos lleguen antes de las 5?»"]},{"tipo":"relacionar","rotulo":"Relaciona la frase con su estilo","pares":[["«No te preocupes, yo me quedo otra vez hasta tarde.» (aunque no quiere)","Pasivo"],["«Eres un irresponsable, contigo no se puede.»","Agresivo"],["«Me preocupa el retraso. ¿Me entregas el reporte mañana a las 10?»","Asertivo"],["«Ay, qué bonito que siempre llegas a la hora que quieres…»","Pasivo-agresivo (sarcasmo)"]]},{"tipo":"completar","rotulo":"Completa la fórmula","items":[{"frase":"En la fórmula asertiva, primero describes el ___ sin juzgar.","resp":["hecho"]},{"frase":"Hablar de lo que sientes en primera ___ reduce la actitud defensiva.","resp":["persona"]},{"frase":"La petición debe ser ___ y posible.","resp":["concreta","específica","especifica","clara"]}]},{"tipo":"plantilla","rotulo":"Guion para poner un límite","texto":"Cuando (hecho concreto):\nMe siento (emoción):\nPorque necesito (necesidad):\nTe pido que (petición concreta):\nSi no es posible, podemos (alternativa):\n\nEjemplo: Cuando me escriben al WhatsApp después de las 9 de la noche, me siento agotado, porque necesito descansar para rendir al otro día. Les pido que lo urgente me lo marquen por teléfono y lo demás lo vemos a las 9 de la mañana.","nota":"Practícalo en voz alta antes de la conversación real."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Decir «sí» a todo aunque no puedas es un estilo…","ops":["Asertivo","Empático","Pasivo"],"correcta":2,"explica":"A la larga genera resentimiento y sobrecarga."},{"p":"¿Cuál es una petición concreta?","ops":["«Échale más ganas.»","«¿Me confirmas antes del jueves a las 12?»","«A ver si un día te acuerdas.»"],"correcta":1,"explica":"Dice qué y cuándo."}]},{"tipo":"clave","items":["Asertivo = claro, directo y respetuoso con ambos.","Pasivo acumula, agresivo daña; el sarcasmo también es agresión.","Fórmula: hecho, emoción, necesidad y petición concreta."]}]},{"id":"c-inteligencia-emocional-m4-l3","titulo":"Lección 3 — Conflictos, conversaciones difíciles y tu plan de 30 días","objetivo":"preparar una conversación difícil, manejar un conflicto sin escalarlo y armar un plan de práctica de 30 días.","bloques":[{"tipo":"texto","texto":"Los <b>conflictos</b> son normales en cualquier oficina, negocio o familia: hay intereses distintos. El objetivo no es evitarlos, sino atenderlos <b>a tiempo</b> y con respeto. Una regla útil: <b>ataca el problema, no a la persona</b>. Otra: si alguno de los dos está muy alterado (8 de 10 o más), pospón la conversación y fija una hora para retomarla."},{"tipo":"pasos","rotulo":"Cómo preparar una conversación difícil","pasos":["<b>Define tu objetivo:</b> ¿qué quieres lograr? (un acuerdo, reparar la relación, poner un límite).","<b>Elige momento y lugar:</b> en privado, sin prisas y no cuando alguien está enojado o cansado.","<b>Abre con respeto:</b> «Quiero platicar contigo sobre algo que me importa para que trabajemos mejor.»","<b>Escucha su versión primero</b> y resume lo que entendiste.","<b>Expón tu punto</b> con la fórmula asertiva.","<b>Busquen opciones juntos</b> y acuerden algo concreto: quién, qué y cuándo.","<b>Da seguimiento</b> en una fecha acordada."]},{"tipo":"comparar","titulo":"Conflicto en la tienda familiar","malTitulo":"Escalar","mal":"Dos hermanos que atienden la papelería discuten frente a los clientes sobre quién dejó la caja descuadrada: «¡Tú siempre te llevas dinero sin anotar!» «¡Y tú nunca cierras bien!»","bienTitulo":"Resolver","bien":"Esperan al cierre. Uno dice: «Me preocupa que la caja no cuadre; quiero que encontremos la forma de evitarlo.» Escuchan ambas versiones y acuerdan anotar cada retiro en una libreta y hacer corte juntos a las 8."},{"tipo":"ordenar","rotulo":"Ordena las reglas","items":[{"frase":"Ataca el problema no a la persona","es":"Regla básica del conflicto"},{"frase":"Si estás en ocho o más pospón la conversación","es":"Regla de la intensidad"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu compañero está gritando y fuera de sí. Lo mejor es…","ops":["Proponer retomar la plática más tarde a una hora concreta","Gritar más fuerte para que escuche","Resolverlo ahí mismo a como dé lugar"],"correcta":0,"explica":"Con intensidad muy alta nadie escucha."},{"p":"Un buen acuerdo incluye…","ops":["Solo la promesa de «echarle ganas»","Quién tuvo la culpa","Quién hace qué y para cuándo"],"correcta":2,"explica":"Lo concreto se puede cumplir y revisar."}]},{"tipo":"plantilla","rotulo":"Mi plan de 30 días","texto":"Semana 1 — Autoconciencia: cada noche anoto una emoción del día con nombre, intensidad (0 a 10) y situación.\nSemana 2 — Regulación: practico 5 minutos de respiración diafragmática diaria y uso STOP al menos una vez.\nSemana 3 — Hábitos: cuido mi hora de dormir, camino 30 minutos 5 días y pongo un límite digital.\nSemana 4 — Relaciones: practico una escucha empática al día y tengo una conversación pendiente usando la fórmula asertiva.\n\nMi conversación pendiente es con:\nMi recompensa al terminar:\nPersona que me va a acompañar en el plan:\nSi me siento peor en lugar de mejor, busco ayuda en:","nota":"Si una semana no sale, no empiezas de cero: retoma al día siguiente."},{"tipo":"clave","items":["Ataca el problema, no a la persona; pospón si la intensidad es muy alta.","Prepara: objetivo, momento, escuchar, exponer, acordar y dar seguimiento.","Tu plan de 30 días: autoconciencia, regulación, hábitos y relaciones."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"La empatía consiste en…","ops":["Darle la razón en todo","Resolverle todos sus problemas","Sentir exactamente lo mismo que él","Entender lo que siente el otro y hacérselo saber"],"correcta":3},{"p":"¿Cuál respuesta es empática?","ops":["«A mí me fue peor.»","«Ya se te pasará.»","«Suena muy pesado lo que te pasó. ¿Cómo estás?»","«No exageres.»"],"correcta":2},{"p":"Antes de dar consejos conviene…","ops":["Cambiar de tema","Preguntar si la persona los quiere o prefiere desahogarse","Darlos de inmediato","Contar tu propia historia"],"correcta":1},{"p":"Ser asertivo significa…","ops":["Expresarte de forma clara, directa y respetuosa","Decir que sí a todo","Gritar para que te hagan caso","Usar el sarcasmo"],"correcta":0},{"p":"Los cuatro pasos de la fórmula asertiva son…","ops":["Grito, amenaza, castigo y perdón","Queja, culpa, silencio y olvido","Saludo, chiste, regaño y despedida","Hecho, emoción, necesidad y petición concreta"],"correcta":3},{"p":"«Ay, qué bonito que siempre llegas tarde…» es un ejemplo de…","ops":["Empatía","Escucha activa","Sarcasmo o estilo pasivo-agresivo","Asertividad"],"correcta":2},{"p":"En un conflicto, la regla básica es…","ops":["Buscar al culpable","Atacar el problema, no a la persona","Ganar la discusión a toda costa","Evitar hablarlo para siempre"],"correcta":1},{"p":"Si la otra persona está muy alterada, lo recomendable es…","ops":["Posponer y fijar una hora para retomar la conversación","Discutir más fuerte","Resolver todo en ese momento","Ignorarla para siempre"],"correcta":0}]}}]});
window.CURSOS_MARA.push({"id":"c-finanzas-personales","nombre":"Finanzas personales y salir de deudas","color":"#15803D","nivel":"Cursos libres de capacitación","familia":"Negocios y finanzas","periodoTipo":null,"periodoNum":null,"desc":"Aprende a saber en qué se va tu dinero, armar un presupuesto quincenal que sí se cumpla, entender el costo real de tus deudas y salir de ellas con un plan, y proteger tu dinero de fraudes. Es un curso educativo con ejercicios en hoja de cálculo; no es asesoría financiera personalizada.","horas":16,"precio":890,"publicado":true,"proximamente":false,"modulos":[{"id":"c-finanzas-personales-m1","titulo":"Módulo 1 — Diagnóstico: en qué se va tu dinero","resumen":"Ingreso neto, gastos fijos y variables, gastos hormiga y patrimonio neto: la foto honesta de tu situación antes de hacer cualquier plan. Tres lecciones y una evaluación.","lecciones":[{"id":"c-finanzas-personales-m1-l1","titulo":"Lección 1 — Tu punto de partida","objetivo":"entender para qué sirve un diagnóstico financiero y distinguir tu ingreso neto de tu ingreso bruto.","bloques":[{"tipo":"texto","texto":"Muchas personas sienten que «el dinero no alcanza», pero no saben exactamente <b>cuánto</b> entra, <b>cuánto</b> sale ni <b>a dónde</b> se va. Sin ese dato, cualquier plan es adivinanza. Este curso empieza por lo más sencillo y lo más poderoso: ver tus números con honestidad, sin culpa y sin regaños."},{"tipo":"destacado","texto":"<b>Antes de empezar.</b> Este es un curso <b>educativo</b> de Instituto Mara. Te enseña conceptos y herramientas generales; <b>no es asesoría financiera, fiscal ni legal personalizada</b> y no recomienda productos ni instituciones concretas. Para decisiones importantes (reestructurar una deuda grande, invertir, contratar un seguro) compara opciones y, si lo necesitas, acude a un profesional o a la CONDUSEF. Al terminar recibes una <b>constancia de Instituto Mara</b>; no es un documento con validez oficial de la SEP ni un certificado de competencia del CONOCER."},{"tipo":"tabla","titulo":"Ingreso bruto vs. ingreso neto","encabezados":["Concepto","Qué es","Ejemplo"],"filas":[["Ingreso bruto","Lo que «ganas» en papel, antes de descuentos.","Tu contrato dice $16,000 al mes."],["Descuentos","Impuestos (ISR), cuotas de seguridad social, crédito de vivienda, préstamos de nómina, etc.","Te descuentan $2,000 entre ISR, IMSS y otros."],["Ingreso neto","Lo que de verdad llega a tu cuenta o a tu mano.","Te depositan $7,000 cada quincena: $14,000 al mes."]],"nota":"Tu presupuesto se hace siempre con el <b>ingreso neto</b>. Si tus ingresos varían (propinas, ventas, comisiones), usa el promedio de los últimos 3 meses o, mejor aún, el mes más bajo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para hacer tu presupuesto usas…","ops":["El ingreso neto: lo que realmente recibes","El ingreso bruto del contrato"],"correcta":0,"explica":"Los descuentos nunca llegan a tu bolsillo, así que no puedes gastarlos."},{"p":"Si vendes por tu cuenta y un mes ganas $9,000 y otro $15,000, lo más prudente es planear con…","ops":["El mes más alto, para motivarte","Una cifra conservadora, cercana al mes bajo"],"correcta":1,"explica":"Si planeas con el mes alto, los meses bajos te obligan a pedir prestado."},{"p":"Un diagnóstico financiero sirve para…","ops":["Ver con datos cuánto entra, cuánto sale y a dónde va","Sentirte culpable por lo que gastas"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Lo que llega a tu cuenta después de descuentos es tu ingreso ___.","resp":["neto"]},{"frase":"Si tus ingresos cambian cada mes, planea con un ___ de los últimos meses o con el mes más bajo.","resp":["promedio"]},{"frase":"Durante 30 días conviene ___ todos tus gastos, incluso los pequeños.","resp":["registrar","anotar","apuntar"]}]},{"tipo":"pasos","rotulo":"Tu registro de 30 días","pasos":["Elige <b>una</b> herramienta: una libreta, una nota en el celular o una hoja de cálculo. La mejor es la que sí vas a usar.","Anota <b>cada</b> gasto el mismo día: fecha, concepto, monto y cómo pagaste (efectivo, débito, crédito).","Incluye lo pequeño: el café, la recarga, el pasaje, la propina, la app de comida.","Revisa también tus estados de cuenta y los cargos automáticos (suscripciones, domiciliaciones).","Al final del mes, agrupa por categorías. Esa es la materia prima de las siguientes lecciones."]},{"tipo":"reflexion","rotulo":"Tu punto de partida","pregunta":"¿Cuál es tu ingreso neto mensual aproximado y qué sientes que pasa con tu dinero cada quincena? Escríbelo tal como es; nadie más lo verá.","ayuda":"Mi ingreso neto es… / Siento que el dinero se me va en…"},{"tipo":"clave","items":["Sin datos no hay plan: primero diagnóstico, luego presupuesto.","Planea siempre con tu ingreso neto; si varía, con una cifra conservadora.","Registra todos tus gastos durante 30 días, incluso los pequeños."]}]},{"id":"c-finanzas-personales-m1-l2","titulo":"Lección 2 — Gastos fijos, variables y hormiga","objetivo":"clasificar tus gastos y medir cuánto se llevan los gastos hormiga de tu ingreso.","bloques":[{"tipo":"texto","texto":"Cuando ya tienes tu registro, el siguiente paso es <b>clasificar</b>. No todos los gastos se atacan igual: unos casi no se pueden mover este mes, otros sí, y algunos son tan pequeños que no los ves… hasta que los sumas."},{"tipo":"tabla","titulo":"Tres tipos de gasto","encabezados":["Tipo","Qué es","Ejemplos"],"filas":[["Fijos","Se repiten cada mes con un monto parecido. Difíciles de cambiar a corto plazo.","Renta, pago de un crédito, colegiatura, plan de celular, internet."],["Variables","Cambian de un mes a otro según cómo los manejes.","Despensa, gasolina o pasajes, luz, gas, comida fuera, ropa."],["Hormiga","Gastos pequeños y frecuentes que casi no notas.","Café, refresco, botana, cigarros, propinas en apps, envíos, suscripciones que no usas."]],"nota":"Un gasto hormiga no es «malo». El problema es cuando no lo decides tú, sino la costumbre."},{"tipo":"relacionar","rotulo":"Clasifica cada gasto","pares":[["Renta del departamento","Fijo"],["Despensa del súper y el mercado","Variable"],["Refresco y papitas en la tiendita diario","Hormiga"],["Mensualidad de la moto","Fijo (crédito)"],["Recibo de luz bimestral","Variable (servicio)"]]},{"tipo":"excel","rotulo":"¿Cuánto se llevan tus gastos hormiga?","datos":[["Gasto","Por día","Días al mes","Al mes"],["Café de la tiendita",25,22,""],["Refresco y botana",30,22,""],["Envíos y propinas en apps",15,30,""],["Total hormiga","","",""],["Ingreso neto mensual",14000,"",""],["% del ingreso","","",""]],"retos":[{"celda":"D2","formula":"=B2*C2","esperado":550,"texto":"<b>D2</b>: cuánto se va al mes en café: gasto por día × días al mes.","pista":"Multiplica B2 por C2."},{"celda":"D3","formula":"=B3*C3","esperado":660,"texto":"<b>D3</b>: lo mismo para refresco y botana."},{"celda":"D4","formula":"=B4*C4","esperado":450,"texto":"<b>D4</b>: lo mismo para envíos y propinas en apps."},{"celda":"D5","formula":"=SUMA(D2:D4)","esperado":1660,"requiere":"SUMA(","texto":"<b>D5</b>: total de gastos hormiga al mes con SUMA.","pista":"=SUMA(D2:D4)"},{"celda":"B7","formula":"=REDONDEAR(D5/B6*100,1)","esperado":11.9,"requiere":"REDONDEAR(","texto":"<b>B7</b>: ¿qué porcentaje de tu ingreso neto son los gastos hormiga? Divide el total entre el ingreso, multiplica por 100 y redondea a 1 decimal.","pista":"=REDONDEAR(D5/B6*100,1)","explica":"Casi 12 de cada 100 pesos se van en gastos que «no se sienten». Al año son casi $20,000. No se trata de eliminarlos todos, sino de decidir cuáles valen la pena."}]},{"tipo":"comparar","titulo":"Dos formas de ver el mismo café","malTitulo":"Sin datos","mal":"«Es solo un cafecito de 25 pesos, no pasa nada.»","bienTitulo":"Con datos","bien":"«Son $550 al mes y $6,600 al año. Me gusta, así que me quedo con tres días a la semana y el resto lo llevo de casa: ahorro unos $250 al mes.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La colegiatura mensual de tu hijo es un gasto…","ops":["Hormiga","Fijo"],"correcta":1},{"p":"Un gasto hormiga se caracteriza por ser…","ops":["Pequeño, frecuente y poco consciente","Grande y ocasional"],"correcta":0},{"p":"Para calcular qué parte de tu ingreso es un gasto, haces…","ops":["Ingreso − gasto × 100","Gasto ÷ ingreso × 100"],"correcta":1,"explica":"La división te da la proporción; al multiplicar por 100 la ves como porcentaje."}]},{"tipo":"clave","items":["Clasifica: fijos, variables y hormiga.","Los gastos hormiga se ven al multiplicarlos por los días del mes.","Gasto ÷ ingreso × 100 = qué porcentaje de tu ingreso se lleva."]}]},{"id":"c-finanzas-personales-m1-l3","titulo":"Lección 3 — Tu patrimonio neto","objetivo":"calcular tu patrimonio neto (lo que tienes menos lo que debes) y usarlo como indicador de avance.","bloques":[{"tipo":"texto","texto":"Tu flujo mensual dice cómo te va <i>este mes</i>. Tu <b>patrimonio neto</b> dice cómo te va <i>en general</i>: es todo lo que tienes (activos) menos todo lo que debes (pasivos). Si lo calculas hoy y dentro de 90 días, sabrás si de verdad avanzas."},{"tipo":"tarjetas","rotulo":"Conceptos básicos","tarjetas":[{"frente":"Activo","reverso":"Lo que tienes y vale dinero: ahorros, efectivo, un vehículo, un terreno, dinero que te deben y que sí te pagarán."},{"frente":"Pasivo","reverso":"Lo que debes: saldo de tarjetas, préstamos personales o de nómina, crédito automotriz, deudas con familiares, tandas que aún debes."},{"frente":"Patrimonio neto","reverso":"Activos − pasivos. Puede ser negativo, y eso no es una sentencia: es tu punto de partida."},{"frente":"Valor realista","reverso":"Registra lo que obtendrías hoy si vendieras el bien, no lo que pagaste por él."}]},{"tipo":"excel","rotulo":"Calcula tu patrimonio neto","datos":[["Concepto","Tipo","Monto"],["Ahorro en cuenta","Activo",6500],["Moto (valor de venta hoy)","Activo",18000],["Préstamo que me debe mi primo","Activo",3000],["Tarjeta de crédito","Pasivo",12400],["Préstamo de nómina","Pasivo",9800],["Total activos","",""],["Total pasivos","",""],["Patrimonio neto","",""],["Diagnóstico","",""]],"retos":[{"celda":"C7","formula":"=SUMAR.SI(B2:B6,\"Activo\",C2:C6)","esperado":27500,"requiere":"SUMAR.SI(","texto":"<b>C7</b>: suma solo los activos con SUMAR.SI.","pista":"=SUMAR.SI(B2:B6,\"Activo\",C2:C6)"},{"celda":"C8","formula":"=SUMAR.SI(B2:B6,\"Pasivo\",C2:C6)","esperado":22200,"requiere":"SUMAR.SI(","texto":"<b>C8</b>: suma solo los pasivos."},{"celda":"C9","formula":"=C7-C8","esperado":5300,"texto":"<b>C9</b>: patrimonio neto = activos − pasivos."},{"celda":"C10","formula":"=SI(C9>=0,\"Positivo\",\"Negativo\")","esperado":"Positivo","requiere":"SI(","texto":"<b>C10</b>: con SI, escribe «Positivo» si el patrimonio es mayor o igual a cero y «Negativo» si no.","pista":"=SI(C9>=0,\"Positivo\",\"Negativo\")","explica":"Es positivo, pero ojo: casi todo el activo es la moto. Si hubiera que pagar las deudas hoy, el ahorro no alcanza. Por eso importa también la liquidez: cuánto tienes disponible en efectivo o en cuenta."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El saldo que debes en tu tarjeta es un…","ops":["Pasivo","Activo"],"correcta":0},{"p":"Tu celular lo compraste en $8,000 pero hoy lo venderías en $2,500. En tu patrimonio lo registras en…","ops":["$8,000","$2,500"],"correcta":1,"explica":"Siempre valor realista de hoy."},{"p":"Si tu patrimonio neto es negativo significa que…","ops":["Hoy debes más de lo que tienes","Nunca podrás salir de deudas"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Ordena la fórmula","items":[{"frase":"Patrimonio neto es activos menos pasivos","es":"La idea central de la lección"},{"frase":"Mide tu patrimonio hoy y en noventa días","es":"Así compruebas si avanzas"}]},{"tipo":"clave","items":["Activos: lo que tienes. Pasivos: lo que debes.","Patrimonio neto = activos − pasivos, con valores realistas.","Un patrimonio negativo es un punto de partida, no una condena."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"Para hacer tu presupuesto debes usar…","ops":["Tu ingreso bruto","Lo que esperas ganar el próximo año","El límite de tu tarjeta","Tu ingreso neto"],"correcta":3},{"p":"Si tus ingresos varían cada mes, lo más prudente es planear con…","ops":["El ingreso de otra persona","Lo que te presten","Una cifra conservadora, como el promedio o el mes más bajo","El mejor mes del año"],"correcta":2},{"p":"La renta mensual es un gasto…","ops":["Extraordinario","Fijo","Hormiga","Variable"],"correcta":1},{"p":"¿Cuál es un gasto hormiga típico?","ops":["Un refresco diario en la tiendita","La renta","La colegiatura","El seguro del auto anual"],"correcta":0},{"p":"Gastas $30 diarios en botanas durante 22 días. Al mes son…","ops":["$300","$220","$1,500","$660"],"correcta":3},{"p":"Tus gastos hormiga suman $1,400 y tu ingreso neto es $14,000. Representan…","ops":["1.4% de tu ingreso","20% de tu ingreso","10% de tu ingreso","14% de tu ingreso"],"correcta":2},{"p":"El patrimonio neto se calcula como…","ops":["Ahorro × 12","Activos − pasivos","Ingresos − gastos del mes","Activos + pasivos"],"correcta":1},{"p":"Tienes $20,000 en activos y debes $26,000. Tu patrimonio neto es…","ops":["−$6,000","$46,000","$6,000","$0"],"correcta":0}]}},{"id":"c-finanzas-personales-m2","titulo":"Módulo 2 — Un presupuesto que sí se cumple","resumen":"El método 50/30/20 como guía, los sobres, el presupuesto por quincena y el ajuste entre lo planeado y lo real. Tres lecciones y una evaluación.","lecciones":[{"id":"c-finanzas-personales-m2-l1","titulo":"Lección 1 — La regla 50/30/20 como guía","objetivo":"usar la regla 50/30/20 como punto de referencia y comparar tu gasto real contra ella.","bloques":[{"tipo":"texto","texto":"Un presupuesto es simplemente <b>decidir antes</b> a dónde va a ir tu dinero, en lugar de preguntarte después a dónde se fue. Una guía muy conocida para empezar es la regla <b>50/30/20</b>: de tu ingreso neto, alrededor del 50% para necesidades, 30% para deseos y 20% para ahorro y pago extra de deudas."},{"tipo":"tabla","titulo":"La regla 50/30/20","encabezados":["Bloque","Guía","Incluye"],"filas":[["Necesidades","50%","Vivienda, despensa básica, transporte al trabajo, servicios, pagos mínimos de deudas, salud."],["Deseos","30%","Comida fuera, salidas, ropa que no es indispensable, suscripciones, regalos, gustos."],["Ahorro y deudas","20%","Fondo de emergencia, metas, retiro y pagos <b>por encima del mínimo</b> para salir de deudas."]],"nota":"Es una <b>guía</b>, no una ley. Si pagas una renta alta en una ciudad cara, tus necesidades pueden pasar del 50%. Lo importante es que el ahorro no sea «lo que sobre», porque casi nunca sobra."},{"tipo":"excel","rotulo":"Tu presupuesto contra la guía 50/30/20","datos":[["Bloque","Guía %","Monto guía","Gasto real","% real","Revisión"],["Necesidades",0.5,"",8400,"",""],["Deseos",0.3,"",4100,"",""],["Ahorro y deudas",0.2,"",1500,"",""],["Ingreso neto",14000,"","","",""]],"retos":[{"celda":"C2","formula":"=B2*$B$5","esperado":7000,"texto":"<b>C2</b>: monto guía para necesidades: porcentaje × ingreso neto. Fija el ingreso con $B$5.","pista":"=B2*$B$5"},{"celda":"C3","formula":"=B3*$B$5","esperado":4200,"texto":"<b>C3</b>: monto guía para deseos."},{"celda":"C4","formula":"=B4*$B$5","esperado":2800,"texto":"<b>C4</b>: monto guía para ahorro y deudas."},{"celda":"E2","formula":"=D2/$B$5","esperado":0.6,"texto":"<b>E2</b>: qué proporción del ingreso se fue en necesidades: gasto real ÷ ingreso.","pista":"=D2/$B$5","explica":"0.6 es 60%. Diez puntos arriba de la guía."},{"celda":"E4","formula":"=REDONDEAR(D4/$B$5,2)","esperado":0.11,"requiere":"REDONDEAR(","texto":"<b>E4</b>: proporción destinada a ahorro y deudas, redondeada a 2 decimales."},{"celda":"F2","formula":"=SI(D2>C2,\"Excede\",\"OK\")","esperado":"Excede","requiere":"SI(","texto":"<b>F2</b>: con SI, escribe «Excede» si el gasto real de necesidades supera el monto guía y «OK» si no.","pista":"=SI(D2>C2,\"Excede\",\"OK\")"},{"celda":"F4","formula":"=SI(D4<C4,\"Falta\",\"OK\")","esperado":"Falta","requiere":"SI(","texto":"<b>F4</b>: en ahorro la lógica se invierte: escribe «Falta» si el real es menor que la guía y «OK» si no.","explica":"Necesidades se pasan por $1,400 y el ahorro se queda $1,300 corto. El siguiente paso no es culparte: es revisar qué necesidad se puede bajar (por ejemplo, despensa planeada) para mover ese dinero a ahorro."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El pago mínimo obligatorio de tu tarjeta va en…","ops":["Deseos","Necesidades"],"correcta":1,"explica":"Dejar de pagarlo tiene consecuencias; lo que pagues por encima del mínimo va en el bloque de ahorro y deudas."},{"p":"La regla 50/30/20 es…","ops":["Una guía para empezar, que ajustas a tu realidad","Una obligación legal"],"correcta":0},{"p":"Con ingreso neto de $10,000, el 20% para ahorro y deudas son…","ops":["$200","$2,000"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El bloque de 30% corresponde a los ___.","resp":["deseos","gustos"]},{"frase":"El ahorro no debe ser lo que ___, sino algo que apartas primero.","resp":["sobre","sobra"]}]},{"tipo":"clave","items":["Presupuestar es decidir antes a dónde va tu dinero.","50/30/20: necesidades, deseos, ahorro y deudas; es guía, no ley.","Compara tu real contra la guía: gasto ÷ ingreso."]}]},{"id":"c-finanzas-personales-m2-l2","titulo":"Lección 2 — Sobres y presupuesto quincenal","objetivo":"repartir tu presupuesto por quincena y usar el método de sobres para no pasarte.","bloques":[{"tipo":"texto","texto":"En México muchas personas cobran <b>por quincena</b>, pero sus gastos no llegan parejos: la renta cae el día 1, la luz a media quincena, la tarjeta el 20. Si presupuestas por mes pero cobras por quincena, es común que una quincena sobre y la otra falte. La solución: <b>asignar cada gasto a la quincena con la que lo vas a pagar</b>."},{"tipo":"tarjetas","rotulo":"El método de sobres","tarjetas":[{"frente":"Qué es","reverso":"Separar el dinero de cada categoría en «sobres»: físicos (efectivo) o digitales (apartados o subcuentas)."},{"frente":"Regla de oro","reverso":"Cuando un sobre se vacía, se acabó esa categoría hasta la siguiente quincena, o pasas dinero de otro sobre conscientemente."},{"frente":"Sobres típicos","reverso":"Despensa, transporte, comida fuera, gustos, imprevistos del mes."},{"frente":"Versión digital","reverso":"Muchas cuentas permiten apartados o «cajitas». Revisa comisiones y condiciones antes de usarlas."}]},{"tipo":"excel","rotulo":"Presupuesto por quincena","datos":[["Gasto","Monto","Quincena"],["Renta",4500,1],["Luz y agua",650,2],["Internet y celular",700,2],["Despensa",2600,1],["Despensa",2600,2],["Transporte",900,1],["Transporte",900,2],["Pago tarjeta",1150,2],["Ingreso por quincena",7000,""],["Gastos quincena 1","",""],["Gastos quincena 2","",""],["Sobra o falta Q1","",""],["Sobra o falta Q2","",""]],"retos":[{"celda":"B11","formula":"=SUMAR.SI(C2:C9,1,B2:B9)","esperado":8000,"requiere":"SUMAR.SI(","texto":"<b>B11</b>: suma los gastos de la quincena 1 con SUMAR.SI.","pista":"=SUMAR.SI(C2:C9,1,B2:B9): rango del criterio, criterio y rango a sumar."},{"celda":"B12","formula":"=SUMAR.SI(C2:C9,2,B2:B9)","esperado":6000,"requiere":"SUMAR.SI(","texto":"<b>B12</b>: suma los gastos de la quincena 2."},{"celda":"B13","formula":"=B10-B11","esperado":-1000,"texto":"<b>B13</b>: ¿sobra o falta en la quincena 1? Ingreso menos gastos."},{"celda":"B14","formula":"=B10-B12","esperado":1000,"texto":"<b>B14</b>: lo mismo para la quincena 2.","explica":"En el mes todo cuadra (14,000 de ingreso y 14,000 de gasto), pero la renta hace que la quincena 1 quede $1,000 abajo. Solución: en cada quincena 2, aparta $1,000 en un sobre «renta» para usarlo el día 1. Sin este ajuste, la quincena 1 se «resuelve» con tarjeta."}]},{"tipo":"pasos","rotulo":"Arma tu presupuesto quincenal","pasos":["Escribe tu ingreso neto de <b>cada</b> quincena.","Pon en una lista tus gastos fijos con su <b>fecha de pago</b> y asígnalos a la quincena en que vencen.","Divide los variables (despensa, transporte) entre las dos quincenas.","Aparta el ahorro <b>al cobrar</b>, no al final.","Si una quincena queda en negativo, mueve dinero desde la otra con un sobre de «adelanto».","Revisa el día de pago: ¿quedó algo en los sobres? Pásalo a ahorro o a deuda."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si la renta vence el día 1 y cobras el 15 y el 30, conviene…","ops":["Apartar parte de la renta desde la quincena anterior","Pagarla con tarjeta cada mes"],"correcta":0,"explica":"Pagar un gasto fijo con crédito de manera recurrente es una de las rutas más comunes al sobreendeudamiento."},{"p":"En el método de sobres, si el sobre de comida fuera se vacía el día 8…","ops":["Usas la tarjeta y lo pagas luego","Ya no hay comida fuera hasta la siguiente quincena, o mueves dinero de otro sobre a propósito"],"correcta":1},{"p":"Un presupuesto quincenal se basa en…","ops":["Asignar cada gasto a la quincena en que se paga","Gastar todo al inicio del mes"],"correcta":0}]},{"tipo":"clave","items":["Si cobras por quincena, presupuesta por quincena.","Asigna cada gasto a la quincena en que vence y aparta el ahorro al cobrar.","Sobres: cuando se vacía uno, esa categoría se detiene."]}]},{"id":"c-finanzas-personales-m2-l3","titulo":"Lección 3 — El ajuste real: presupuesto contra realidad","objetivo":"comparar lo planeado con lo real, detectar excesos y ajustar el presupuesto sin abandonarlo.","bloques":[{"tipo":"texto","texto":"Ningún presupuesto sale perfecto el primer mes. La diferencia entre quien lo logra y quien lo abandona es que el primero <b>revisa y ajusta</b>. Cada quincena o cada mes compara lo que planeaste con lo que en verdad pasó, y decide: ¿subo el presupuesto de esa categoría, bajo otra o cambio un hábito?"},{"tipo":"excel","rotulo":"Presupuesto contra real","datos":[["Categoría","Presupuesto","Real","Diferencia","Revisión"],["Despensa",5200,5750,"",""],["Transporte",1800,1650,"",""],["Comida fuera",1200,2100,"",""],["Entretenimiento",800,650,"",""],["Total","","","",""]],"retos":[{"celda":"D2","formula":"=C2-B2","esperado":550,"texto":"<b>D2</b>: diferencia en despensa: real − presupuesto. Un número positivo significa que te pasaste."},{"celda":"D4","formula":"=C4-B4","esperado":900,"texto":"<b>D4</b>: diferencia en comida fuera."},{"celda":"E2","formula":"=SI(C2>B2,\"Exceso\",\"OK\")","esperado":"Exceso","requiere":"SI(","texto":"<b>E2</b>: escribe «Exceso» si el real supera lo presupuestado y «OK» si no.","pista":"=SI(C2>B2,\"Exceso\",\"OK\")"},{"celda":"E3","formula":"=SI(C3>B3,\"Exceso\",\"OK\")","esperado":"OK","requiere":"SI(","texto":"<b>E3</b>: la misma revisión para transporte."},{"celda":"B6","formula":"=SUMA(B2:B5)","esperado":9000,"requiere":"SUMA(","texto":"<b>B6</b>: total presupuestado."},{"celda":"C6","formula":"=SUMA(C2:C5)","esperado":10150,"requiere":"SUMA(","texto":"<b>C6</b>: total real."},{"celda":"D6","formula":"=C6-B6","esperado":1150,"texto":"<b>D6</b>: diferencia total.","explica":"Te pasaste $1,150, y casi todo viene de comida fuera. Ajuste realista: subir un poco el sobre de despensa (el presupuesto era bajo) y fijar un número de comidas fuera por quincena."}]},{"tipo":"comparar","titulo":"Dos reacciones al mismo resultado","malTitulo":"Abandonar","mal":"«Me pasé otra vez. Esto del presupuesto no es para mí.»","bienTitulo":"Ajustar","bien":"«Me pasé $900 en comida fuera. Casi todo fue entre semana porque no llevo comida. Voy a cocinar doble dos noches por semana y dejo el sobre de comida fuera en $1,400.»"},{"tipo":"lista","items":["<b>Si la categoría siempre se pasa:</b> quizá el presupuesto era irreal. Súbelo y baja otra.","<b>Si se pasa por un evento raro</b> (un cumpleaños, una reparación): anótalo y crea un sobre de «imprevistos».","<b>Si sobra:</b> no lo gastes «porque sobró»; mándalo a ahorro o a deuda.","<b>Revisa en fechas fijas:</b> el día de pago es ideal."]},{"tipo":"ordenar","rotulo":"Ordena el hábito","items":[{"frase":"Revisa tu presupuesto cada día de pago","es":"Un hábito sencillo que sostiene todo el plan"},{"frase":"Ajusta la categoría sin abandonar el plan","es":"La actitud correcta ante un exceso"}]},{"tipo":"reflexion","rotulo":"Tu primer ajuste","pregunta":"¿Qué categoría crees que más se te va a pasar y qué cambio concreto harías para evitarlo?","ayuda":"La categoría que más se me pasa es… Voy a…"},{"tipo":"clave","items":["Compara presupuesto contra real cada quincena o cada mes.","Diferencia = real − presupuesto; marca los excesos con SI.","Un exceso se ajusta; no es razón para abandonar el presupuesto."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"En la regla 50/30/20, el 20% se destina a…","ops":["Deseos","Renta","Impuestos","Ahorro y pagos extra a deudas"],"correcta":3},{"p":"Con un ingreso neto de $12,000, el 50% para necesidades son…","ops":["$3,600","$2,400","$6,000","$5,000"],"correcta":2},{"p":"La regla 50/30/20 debe entenderse como…","ops":["Un producto bancario","Una guía que se ajusta a cada realidad","Una obligación legal","Una regla que nunca cambia"],"correcta":1},{"p":"Gastaste $8,400 en necesidades con un ingreso de $14,000. Eso es…","ops":["60% del ingreso","50% del ingreso","40% del ingreso","84% del ingreso"],"correcta":0},{"p":"En el método de sobres, si un sobre se vacía…","ops":["Usas la tarjeta de crédito","Pides prestado","Cancelas el presupuesto","Esa categoría se detiene o mueves dinero de otro sobre a propósito"],"correcta":3},{"p":"Si cobras por quincena y la renta vence el día 1, lo recomendable es…","ops":["Pedir adelanto de nómina cada mes","Dejar de pagarla","Apartar una parte de la renta en la quincena anterior","Pagarla siempre con tarjeta"],"correcta":2},{"p":"Presupuestaste $1,200 en comida fuera y gastaste $2,100. La diferencia (real − presupuesto) es…","ops":["$1,200","$900","−$900","$3,300"],"correcta":1},{"p":"Si en un mes te sobra dinero de una categoría, conviene…","ops":["Mandarlo a ahorro o a pago de deuda","Gastarlo porque sobró","Ignorarlo","Sacarlo en efectivo"],"correcta":0}]}},{"id":"c-finanzas-personales-m3","titulo":"Módulo 3 — Deudas: entenderlas y salir de ellas","resumen":"Tasa de interés y CAT, pago mínimo contra pago para no generar intereses, métodos bola de nieve y avalancha, negociación, historial crediticio, préstamos fraudulentos y dónde verificar a una institución. Tres lecciones y una evaluación.","lecciones":[{"id":"c-finanzas-personales-m3-l1","titulo":"Lección 1 — Tasa de interés y CAT","objetivo":"distinguir la tasa de interés del CAT y usar el CAT para comparar créditos.","bloques":[{"tipo":"texto","texto":"Cuando pides prestado pagas un precio por usar dinero ajeno: el <b>interés</b>. La <b>tasa de interés</b> dice qué porcentaje del saldo pagas por ese uso, normalmente expresado <b>por año</b>. Pero un crédito también puede traer comisiones, seguros obligatorios y otros cargos. Para verlo todo junto existe el <b>CAT</b>."},{"tipo":"tabla","titulo":"Tasa de interés vs. CAT","encabezados":["","Tasa de interés","CAT (Costo Anual Total)"],"filas":[["Qué mide","Solo el costo por usar el dinero prestado.","El costo total del crédito en un año: intereses, comisiones y otros cargos del crédito."],["Para qué sirve","Calcular cuánto interés generas sobre tu saldo.","<b>Comparar</b> créditos del mismo tipo entre instituciones."],["Detalle","Se expresa como porcentaje anual.","Se expresa como porcentaje anual, <b>sin IVA</b>, y es informativo: úsalo para comparar, no como el monto exacto que pagarás."]],"nota":"En la publicidad y en tu contrato de crédito deben informarte el CAT. Compara siempre créditos del mismo tipo, plazo y monto parecidos."},{"tipo":"tabla","titulo":"Interés simple: la idea básica","encabezados":["Fórmula","Ejemplo"],"filas":[["Interés = capital × tasa anual × (meses ÷ 12)","$10,000 al 36% anual durante 12 meses = $3,600 de interés."]],"nota":"Muchos créditos reales calculan intereses sobre el saldo que va quedando, así que el cálculo exacto cambia. El interés simple sirve para darte una idea rápida del orden de magnitud."},{"tipo":"excel","rotulo":"Compara tres créditos","datos":[["Crédito","Tasa anual","CAT","Monto","Meses","Interés simple"],["Crédito A",0.42,0.58,10000,12,""],["Crédito B",0.36,0.61,10000,12,""],["Crédito C",0.39,0.49,10000,12,""],["CAT más bajo","","","","",""],["Más barato por CAT","","","","",""]],"retos":[{"celda":"F2","formula":"=D2*B2*E2/12","esperado":4200,"texto":"<b>F2</b>: interés simple del Crédito A: monto × tasa × meses ÷ 12.","pista":"=D2*B2*E2/12"},{"celda":"F3","formula":"=D3*B3*E3/12","esperado":3600,"texto":"<b>F3</b>: interés simple del Crédito B."},{"celda":"F4","formula":"=D4*B4*E4/12","esperado":3900,"texto":"<b>F4</b>: interés simple del Crédito C."},{"celda":"C5","formula":"=MIN(C2:C4)","esperado":0.49,"requiere":"MIN(","texto":"<b>C5</b>: encuentra el CAT más bajo con MIN."},{"celda":"C6","formula":"=INDICE(A2:A4,COINCIDIR(C5,C2:C4,0))","esperado":"Crédito C","requiere":"COINCIDIR(","texto":"<b>C6</b>: ¿qué crédito tiene ese CAT? Usa INDICE con COINCIDIR.","pista":"=INDICE(A2:A4,COINCIDIR(C5,C2:C4,0)). También sirve BUSCARX(C5,C2:C4,A2:A4), pero aquí practica COINCIDIR.","explica":"El Crédito B tiene la tasa más baja, pero su CAT es el más alto: seguramente carga comisiones o seguros. Por eso se compara con el CAT, no solo con la tasa. (Las cifras son un ejemplo para practicar.)"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para comparar dos créditos personales parecidos, lo más útil es ver…","ops":["Solo el monto de la mensualidad","El CAT"],"correcta":1,"explica":"Una mensualidad baja puede esconder un plazo muy largo y un costo total alto."},{"p":"El CAT incluye…","ops":["Intereses, comisiones y otros cargos del crédito, sin IVA","Solo la tasa de interés"],"correcta":0},{"p":"$20,000 al 30% anual durante 6 meses con interés simple generan…","ops":["$6,000","$3,000"],"correcta":1,"explica":"20,000 × 0.30 × 6 ÷ 12 = 3,000."}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"CAT significa Costo Anual ___.","resp":["Total"]},{"frase":"El CAT se usa principalmente para ___ créditos.","resp":["comparar"]}]},{"tipo":"clave","items":["La tasa mide el costo del dinero; el CAT, el costo total del crédito (sin IVA).","Compara créditos del mismo tipo por su CAT, no por la mensualidad.","Interés simple ≈ capital × tasa × meses ÷ 12."]}]},{"id":"c-finanzas-personales-m3-l2","titulo":"Lección 2 — Tarjeta de crédito, pago mínimo y cómo salir","objetivo":"entender por qué el pago mínimo alarga la deuda y elegir entre los métodos bola de nieve y avalancha.","bloques":[{"tipo":"texto","texto":"Tu estado de cuenta de tarjeta muestra dos cifras clave. El <b>pago mínimo</b> es lo menos que puedes pagar para no caer en atraso; el <b>pago para no generar intereses</b> es lo que debes cubrir antes de la fecha límite para que no te cobren intereses ordinarios. Si solo pagas el mínimo, casi todo se va en intereses y la deuda baja muy despacio. Además, sobre los intereses de la tarjeta se cobra <b>IVA</b>."},{"tipo":"excel","rotulo":"Tres meses pagando poco","datos":[["Mes","Saldo inicial","Interés + IVA","Pago","Saldo final"],[1,20000,"",1000,""],[2,"","",1000,""],[3,"","",1000,""],["Tasa anual",0.48,"","",""],["Intereses pagados en 3 meses","","","",""],["Cuánto bajó la deuda","","","",""]],"retos":[{"celda":"C2","formula":"=REDONDEAR(B2*$B$5/12*1.16,2)","esperado":928,"requiere":"REDONDEAR(","texto":"<b>C2</b>: interés del mes 1 con IVA: saldo × tasa anual ÷ 12 × 1.16, redondeado a 2 decimales.","pista":"=REDONDEAR(B2*$B$5/12*1.16,2)"},{"celda":"E2","formula":"=B2+C2-D2","esperado":19928,"texto":"<b>E2</b>: saldo final = saldo inicial + interés − pago."},{"celda":"B3","formula":"=E2","esperado":19928,"texto":"<b>B3</b>: el saldo inicial del mes 2 es el saldo final del mes 1."},{"celda":"C3","formula":"=REDONDEAR(B3*$B$5/12*1.16,2)","esperado":924.66,"requiere":"REDONDEAR(","texto":"<b>C3</b>: interés del mes 2."},{"celda":"E3","formula":"=B3+C3-D3","esperado":19852.66,"texto":"<b>E3</b>: saldo final del mes 2."},{"celda":"B4","formula":"=E3","esperado":19852.66,"texto":"<b>B4</b>: saldo inicial del mes 3."},{"celda":"C4","formula":"=REDONDEAR(B4*$B$5/12*1.16,2)","esperado":921.16,"requiere":"REDONDEAR(","texto":"<b>C4</b>: interés del mes 3."},{"celda":"E4","formula":"=B4+C4-D4","esperado":19773.82,"texto":"<b>E4</b>: saldo final del mes 3."},{"celda":"B6","formula":"=SUMA(C2:C4)","esperado":2773.82,"requiere":"SUMA(","texto":"<b>B6</b>: total de intereses (con IVA) pagados en 3 meses."},{"celda":"B7","formula":"=B2-E4","esperado":226.18,"texto":"<b>B7</b>: cuánto bajó la deuda: saldo inicial del mes 1 − saldo final del mes 3.","explica":"Pagaste $3,000 y la deuda solo bajó $226.18: el resto fueron intereses e IVA. Con pagos así, salir tomaría muchísimos años. Cada peso extra que pagues arriba del mínimo va directo a bajar el saldo. (Tasa de ejemplo; revisa la tuya en tu estado de cuenta.)"}]},{"tipo":"comparar","titulo":"Dos métodos para pagar varias deudas","malTitulo":"Bola de nieve","mal":"Pagas el mínimo en todas y todo el dinero extra va a la deuda de <b>saldo más pequeño</b>. Al liquidarla, sumas ese pago a la siguiente. Ventaja: ves victorias rápidas y te motiva.","bienTitulo":"Avalancha","bien":"Pagas el mínimo en todas y todo el dinero extra va a la deuda con la <b>tasa más alta</b>. Al liquidarla, pasas a la siguiente tasa más alta. Ventaja: pagas menos intereses en total."},{"tipo":"tabla","titulo":"Ejemplo: tus deudas","encabezados":["Deuda","Saldo","Tasa anual (ejemplo)","Bola de nieve","Avalancha"],"filas":[["Préstamo con un familiar","$3,000","0%","1.º","4.º"],["Tienda departamental","$6,500","60%","2.º","1.º"],["Tarjeta de crédito","$18,000","48%","3.º","2.º"],["Préstamo de nómina","$25,000","30%","4.º","3.º"]],"nota":"Cualquiera de los dos funciona si eres constante. Si te cuesta mantener la motivación, empieza con bola de nieve; si eres disciplinado y quieres pagar menos, avalancha."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si pagas solo el mínimo de tu tarjeta…","ops":["La deuda baja muy lento porque casi todo se va en intereses","Nunca te cobran intereses"],"correcta":0},{"p":"Para no pagar intereses ordinarios en tu tarjeta, cubres…","ops":["El pago mínimo","El pago para no generar intereses antes de la fecha límite"],"correcta":1},{"p":"En el método avalancha, el dinero extra va primero a la deuda…","ops":["Con la tasa más alta","Con el saldo más pequeño"],"correcta":0},{"p":"Sobre los intereses de la tarjeta de crédito se cobra…","ops":["Nada adicional","IVA"],"correcta":1}]},{"tipo":"clave","items":["Pago mínimo = evitas atraso, pero la deuda casi no baja.","Pago para no generar intereses = no pagas intereses ordinarios.","Bola de nieve: saldo más chico primero. Avalancha: tasa más alta primero."]}]},{"id":"c-finanzas-personales-m3-l3","titulo":"Lección 3 — Negociar, tu historial y los préstamos peligrosos","objetivo":"negociar una deuda, consultar tu historial crediticio gratis y reconocer préstamos fraudulentos.","bloques":[{"tipo":"texto","texto":"Si ya no puedes pagar, <b>no desaparezcas</b>: habla con la institución antes de caer en atrasos largos. Pregunta por opciones como una <b>reestructura</b> (cambiar plazo o mensualidad), un <b>convenio de pago</b> o, en algunos casos, una <b>quita</b> (pagar menos del total). Ojo: una quita o un convenio pueden quedar anotados en tu historial crediticio, y todo acuerdo debe ser <b>por escrito</b>."},{"tipo":"plantilla","rotulo":"Guion para negociar","texto":"Hola, soy [nombre], titular del crédito [número o últimos 4 dígitos].\nQuiero seguir pagando, pero mi situación cambió: [motivo breve y real].\nHoy puedo pagar [monto] cada [quincena/mes].\n¿Qué opciones tienen: reestructura, ampliar plazo o convenio de pago?\n¿Cuál sería el CAT, el plazo y el total a pagar con esa opción?\n¿Cómo se reportará en mi historial crediticio?\nPor favor envíenme el acuerdo por escrito antes de hacer cualquier pago.","nota":"Paga solo a cuentas o canales oficiales de la institución, nunca a la cuenta personal de un «gestor»."},{"tipo":"tabla","titulo":"Tu historial crediticio","encabezados":["Dato","Qué necesitas saber"],"filas":[["Qué son","Las sociedades de información crediticia (en México, Buró de Crédito y Círculo de Crédito) guardan tu historial: qué créditos tienes y cómo los pagas. No deciden si te prestan; lo decide cada institución."],["Reporte gratuito","Tienes derecho a un <b>Reporte de Crédito Especial gratuito cada 12 meses</b> en cada una. Solicítalo solo en sus sitios oficiales."],["¿Me «borran»?","Nadie «te saca» del buró. Los registros de deudas se eliminan después de ciertos plazos que dependen del monto en UDIS (de 1 a 6 años), con excepciones como créditos en juicio o fraude."],["Errores","Si ves un crédito que no reconoces o un dato equivocado, puedes presentar una reclamación ante la sociedad de información crediticia."]],"nota":"La UDI es una unidad cuyo valor en pesos publica el Banco de México y cambia todos los días. Al momento de escribir, una UDI vale alrededor de 8.8 pesos, así que 25 UDIS son poco más de 200 pesos."},{"tipo":"comparar","titulo":"Préstamo legítimo vs. montadeudas","malTitulo":"Señales de alerta","mal":"Préstamo «sin buró, en 5 minutos», te piden acceso a tus contactos, fotos o galería, te depositan menos de lo prometido, el plazo es de días, cobran con amenazas o exhibiéndote ante tus contactos, o te piden un «depósito de garantía» antes de prestarte.","bienTitulo":"Lo que debes ver","bien":"La institución aparece en el <b>SIPRES</b> de la CONDUSEF con su razón social, informa CAT, plazo y total a pagar antes de firmar, te entrega contrato, y cobra por canales oficiales y sin amenazas."},{"tipo":"pasos","rotulo":"Si ya caíste en una app montadeudas","pasos":["No pagues más «para que te dejen en paz»: los cobros suelen seguir.","Guarda evidencia: capturas de pantalla, números, mensajes y comprobantes.","Quita los permisos de la app y desinstálala; cambia contraseñas.","Avisa a tus contactos que podrían recibir mensajes falsos.","Denuncia ante la policía cibernética o la fiscalía de tu estado y presenta tu caso ante la CONDUSEF."]},{"tipo":"relacionar","rotulo":"¿Dónde lo reviso?","pares":[["Si una financiera está registrada","SIPRES de la CONDUSEF"],["Mi historial crediticio gratis","Reporte de Crédito Especial"],["Comparar créditos parecidos","El CAT de cada uno"],["Una queja contra un banco","CONDUSEF"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una app te presta «sin requisitos» pero pide acceso a tus contactos y fotos. Lo más probable es…","ops":["Que sea una app montadeudas","Que sea un préstamo más seguro"],"correcta":0,"explica":"Una institución seria no necesita tu galería ni tus contactos para darte un crédito."},{"p":"Un «gestor» te ofrece «borrarte del buró» por $3,000. Eso es…","ops":["Un servicio oficial","Un fraude: nadie puede borrarte a cambio de dinero"],"correcta":1},{"p":"Tu Reporte de Crédito Especial es gratuito…","ops":["Una vez cada 12 meses","Nunca"],"correcta":0}]},{"tipo":"clave","items":["Si no puedes pagar, negocia a tiempo y todo por escrito.","Reporte de Crédito Especial gratis cada 12 meses; nadie te «borra» del buró por dinero.","Antes de pedir prestado, verifica a la institución en el SIPRES de la CONDUSEF."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"El CAT sirve principalmente para…","ops":["Saber tu saldo exacto","Calcular tu ingreso neto","Consultar tu historial crediticio","Comparar el costo total de créditos parecidos"],"correcta":3},{"p":"El CAT se expresa…","ops":["En UDIS","Como porcentaje diario con IVA","Como porcentaje anual y sin IVA","En pesos por mes"],"correcta":2},{"p":"$10,000 al 36% anual durante 12 meses, con interés simple, generan…","ops":["$1,200","$3,600","$360","$36,000"],"correcta":1},{"p":"Si pagas solo el mínimo de tu tarjeta…","ops":["La deuda baja muy lento porque casi todo son intereses","Liquidas la deuda en un mes","Te dejan de cobrar intereses","Mejora automáticamente tu historial"],"correcta":0},{"p":"El método de bola de nieve prioriza…","ops":["La deuda con la tasa más alta","La deuda más antigua","La deuda con el banco más grande","La deuda con el saldo más pequeño"],"correcta":3},{"p":"El método avalancha permite…","ops":["No pagar mínimos","Borrarte del buró","Pagar menos intereses en total","Ver victorias más rápido siempre"],"correcta":2},{"p":"¿Cada cuánto puedes obtener gratis tu Reporte de Crédito Especial?","ops":["Nunca es gratis","Una vez cada 12 meses","Cada mes","Cada 5 años"],"correcta":1},{"p":"Para verificar si una financiera está registrada, consultas…","ops":["El SIPRES de la CONDUSEF","Las reseñas de la app","Un grupo de redes sociales","Al gestor que te la recomendó"],"correcta":0}]}},{"id":"c-finanzas-personales-m4","titulo":"Módulo 4 — Ahorro, metas y retiro","resumen":"Fondo de emergencia, metas con fecha y monto, el efecto de la inflación y lo básico del ahorro para el retiro: Afore, aportaciones voluntarias y ahorro solidario. Tres lecciones y una evaluación.","lecciones":[{"id":"c-finanzas-personales-m4-l1","titulo":"Lección 1 — Tu fondo de emergencia","objetivo":"calcular la meta de tu fondo de emergencia y cuánto apartar cada mes y cada quincena para lograrla.","bloques":[{"tipo":"texto","texto":"Un <b>fondo de emergencia</b> es dinero apartado solo para imprevistos: quedarte sin trabajo, una enfermedad, una reparación urgente. Es lo que evita que cada susto termine en una tarjeta de crédito o en un préstamo caro. Por eso, incluso mientras pagas deudas, conviene empezar con un colchón pequeño y luego hacerlo crecer."},{"tipo":"tabla","titulo":"¿Cuánto juntar?","encabezados":["Etapa","Meta orientativa","Para qué"],"filas":[["Colchón inicial","Lo equivalente a unas 2 a 4 semanas de gastos esenciales","Cubrir imprevistos pequeños sin usar crédito mientras pagas deudas."],["Fondo básico","3 meses de gastos esenciales","Una emergencia mediana o unas semanas sin ingreso."],["Fondo sólido","6 meses o más","Si tu ingreso es variable, trabajas por tu cuenta o mantienes a otras personas."]],"nota":"Guárdalo separado de tu cuenta de gasto diario, en un lugar seguro y con disponibilidad inmediata o casi inmediata. No es dinero para invertir a largo plazo ni para gustos."},{"tipo":"excel","rotulo":"Calcula tu fondo de emergencia","datos":[["Concepto","Monto"],["Renta",4500],["Despensa",4200],["Transporte",1500],["Servicios",1100],["Pagos mínimos de deudas",1200],["Total esencial al mes",""],["Meses de colchón",3],["Meta del fondo",""],["Ya tengo ahorrado",5000],["Meses para lograrlo",12],["Ahorro mensual necesario",""],["Ahorro por quincena",""]],"retos":[{"celda":"B7","formula":"=SUMA(B2:B6)","esperado":12500,"requiere":"SUMA(","texto":"<b>B7</b>: suma tus gastos esenciales del mes."},{"celda":"B9","formula":"=B7*B8","esperado":37500,"texto":"<b>B9</b>: meta del fondo = gasto esencial × meses de colchón."},{"celda":"B12","formula":"=REDONDEAR((B9-B10)/B11,0)","esperado":2708,"requiere":"REDONDEAR(","texto":"<b>B12</b>: cuánto ahorrar al mes: (meta − lo que ya tienes) ÷ meses, redondeado a pesos completos.","pista":"=REDONDEAR((B9-B10)/B11,0). Los paréntesis hacen que primero se reste.","explica":"Te faltan $32,500; entre 12 meses son $2,708.33, que redondeamos a $2,708."},{"celda":"B13","formula":"=REDONDEAR(B12/2,0)","esperado":1354,"requiere":"REDONDEAR(","texto":"<b>B13</b>: ¿cuánto apartar cada quincena? Divide entre 2 y redondea.","explica":"Si $1,354 por quincena es imposible hoy, alarga el plazo o empieza con el colchón inicial. Una meta alcanzable vale más que una perfecta que abandonas."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu fondo de emergencia se usa para…","ops":["Las vacaciones de diciembre","Imprevistos reales: pérdida de ingreso, salud, reparaciones urgentes"],"correcta":1,"explica":"Los gastos que sabes que vienen (vacaciones, útiles, regalos) son metas, no emergencias."},{"p":"Si tu ingreso es variable, conviene un fondo…","ops":["Más grande, de 6 meses o más","Más pequeño"],"correcta":0},{"p":"El fondo de emergencia debe estar…","ops":["En tu cartera","Separado de tu dinero de gasto diario y disponible rápido"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Meta del fondo = gasto esencial mensual × ___ de colchón.","resp":["meses"]},{"frase":"Un fondo de emergencia evita que cada imprevisto termine en ___.","resp":["deuda","deudas","crédito"]}]},{"tipo":"clave","items":["El fondo de emergencia evita nuevas deudas ante imprevistos.","Meta = gasto esencial × meses; empieza con un colchón pequeño.","Ahorro mensual = (meta − lo que tienes) ÷ meses."]}]},{"id":"c-finanzas-personales-m4-l2","titulo":"Lección 2 — Metas de ahorro e inflación","objetivo":"plantear metas de ahorro con monto y fecha, y considerar la inflación al calcularlas.","bloques":[{"tipo":"texto","texto":"«Quiero ahorrar» es un deseo; «quiero juntar $13,000 para un refrigerador en 24 meses» es una <b>meta</b>. Una meta útil tiene <b>qué</b>, <b>cuánto</b> y <b>para cuándo</b>. Y si es a más de un año, hay que considerar la <b>inflación</b>: el aumento general de los precios, que hace que el mismo dinero compre menos con el tiempo."},{"tipo":"tarjetas","rotulo":"Conceptos clave","tarjetas":[{"frente":"Meta concreta","reverso":"Qué quieres, cuánto cuesta y para cuándo. Ejemplo: $13,000 para un refrigerador en 24 meses."},{"frente":"Inflación","reverso":"Aumento generalizado de precios. El Banco de México tiene como objetivo una inflación anual de 3% con un margen de ±1 punto."},{"frente":"Poder adquisitivo","reverso":"Lo que puedes comprar con tu dinero. Si guardas billetes en un cajón, pierden poder adquisitivo con la inflación."},{"frente":"Rendimiento real","reverso":"Lo que gana tu ahorro menos la inflación. Si tu ahorro gana menos que la inflación, en términos reales pierde."}]},{"tipo":"excel","rotulo":"Tu meta con inflación","datos":[["Concepto","Valor"],["Precio hoy del refrigerador",12000],["Inflación anual supuesta",0.04],["Años para comprarlo",2],["Precio estimado",""],["Meses de ahorro",""],["Ahorro mensual",""],["Poder de compra de $10,000 guardados en un cajón",""]],"retos":[{"celda":"B5","formula":"=REDONDEAR(B2*(1+B3)^B4,0)","esperado":12979,"requiere":"REDONDEAR(","texto":"<b>B5</b>: precio estimado dentro de 2 años: precio × (1 + inflación) elevado a los años, redondeado a pesos.","pista":"=REDONDEAR(B2*(1+B3)^B4,0). El símbolo ^ eleva a una potencia.","explica":"La inflación se acumula año con año: 12,000 × 1.04 × 1.04 = 12,979.20."},{"celda":"B6","formula":"=B4*12","esperado":24,"texto":"<b>B6</b>: ¿cuántos meses son 2 años?"},{"celda":"B7","formula":"=REDONDEAR(B5/B6,0)","esperado":541,"requiere":"REDONDEAR(","texto":"<b>B7</b>: ahorro mensual para llegar al precio estimado, redondeado.","explica":"Si hubieras usado el precio de hoy, apartarías $500 al mes y al final te faltarían casi $1,000."},{"celda":"B8","formula":"=REDONDEAR(10000/(1+B3)^B4,0)","esperado":9246,"requiere":"REDONDEAR(","texto":"<b>B8</b>: ¿cuánto «valen» en pesos de hoy $10,000 guardados 2 años sin rendimiento? Divide 10,000 entre (1 + inflación) elevado a los años.","explica":"Con 4% de inflación supuesta, después de 2 años esos $10,000 compran lo que hoy compran unos $9,246. La cifra de inflación es un supuesto para practicar; la real cambia cada mes."}]},{"tipo":"comparar","titulo":"Deseo vs. meta","malTitulo":"Deseo","mal":"«Este año sí voy a ahorrar para algo.»","bienTitulo":"Meta","bien":"«Voy a juntar $13,000 para un refrigerador en 24 meses: $541 al mes, $271 cada quincena, en un apartado que no toco.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La inflación hace que…","ops":["El mismo dinero compre menos con el tiempo","El dinero guardado crezca solo"],"correcta":0},{"p":"El objetivo de inflación del Banco de México es…","ops":["0% anual","3% anual, con un margen de ±1 punto"],"correcta":1,"explica":"Es un objetivo; la inflación real puede quedar por encima o por debajo."},{"p":"Si tu ahorro rinde 3% al año y la inflación es 4%, tu rendimiento real es…","ops":["Negativo, alrededor de −1%","Positivo de 7%"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Ordena la idea","items":[{"frase":"Una meta tiene qué, cuánto y cuándo","es":"La estructura mínima de una meta"},{"frase":"La inflación reduce el poder de compra","es":"Por qué se ajustan las metas largas"}]},{"tipo":"clave","items":["Una meta tiene monto y fecha; así se convierte en ahorro mensual.","Para metas de más de un año, ajusta el precio por inflación.","Rendimiento real = rendimiento − inflación."]}]},{"id":"c-finanzas-personales-m4-l3","titulo":"Lección 3 — Ahorro para el retiro","objetivo":"entender cómo funciona tu cuenta para el retiro y qué opciones existen para aumentarla.","bloques":[{"tipo":"texto","texto":"Si trabajas o trabajaste con seguridad social (IMSS o ISSSTE) desde las reformas a las pensiones, tienes una <b>cuenta individual</b> administrada por una <b>Afore</b>. Ahí llegan aportaciones tuyas, de tu patrón y del gobierno. Esa cuenta es tuya, aunque cambies de trabajo, y lo que acumules será la base de tu pensión."},{"tipo":"tabla","titulo":"Lo básico de tu cuenta para el retiro","encabezados":["Tema","Qué necesitas saber"],"filas":[["Afore","Administradora de Fondos para el Retiro. Invierte los recursos de tu cuenta individual. Las regula la CONSAR."],["Localizar tu Afore","Si no sabes en cuál estás, puedes consultarlo con tu CURP en los canales oficiales de la CONSAR o en la app oficial del sistema de ahorro para el retiro."],["Aportaciones voluntarias","Puedes depositar dinero extra a tu cuenta cuando quieras y desde montos pequeños. Hay subcuentas de corto y de largo plazo; cada una tiene reglas distintas para retirar."],["Beneficiarios","Registra o actualiza a tus beneficiarios y revisa que tus datos estén correctos."],["Si trabajas por tu cuenta","También puedes abrir una cuenta en una Afore y hacer aportaciones voluntarias aunque no cotices al IMSS."]],"nota":"Compara Afores con la información oficial de la CONSAR (rendimientos netos y comisiones). Este curso no recomienda ninguna en particular."},{"tipo":"destacado","texto":"<b>Ahorro solidario: solo para trabajadores del Estado.</b> Si cotizas al ISSSTE bajo el régimen de <b>cuentas individuales</b> (ingresaste a partir del 1 de abril de 2007 o elegiste ese régimen), puedes pedir que te descuenten el 1% o el 2% de tu sueldo básico y tu dependencia aporta <b>$3.25 por cada peso</b> que ahorres, con un tope de 6.5% del sueldo básico. Si trabajas en el sector privado (IMSS), esta figura no te aplica."},{"tipo":"relacionar","rotulo":"Relaciona","pares":[["Administra tu cuenta individual para el retiro","Afore"],["Regula y supervisa a las Afores","CONSAR"],["Dinero extra que tú decides depositar a tu cuenta","Aportación voluntaria"],["$3.25 por cada peso para trabajadores ISSSTE","Ahorro solidario"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El ahorro solidario está disponible para…","ops":["Cualquier trabajador del sector privado","Trabajadores al servicio del Estado en el régimen de cuentas individuales del ISSSTE"],"correcta":1,"explica":"Si cotizas al IMSS, tu opción para aumentar tu ahorro es hacer aportaciones voluntarias."},{"p":"Tu cuenta individual en la Afore…","ops":["Es tuya aunque cambies de trabajo","Se pierde si renuncias"],"correcta":0},{"p":"Si trabajas por tu cuenta y no cotizas…","ops":["No existe ninguna forma de ahorrar para el retiro","También puedes abrir una cuenta de Afore y hacer aportaciones voluntarias"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu cuenta para el retiro","pregunta":"¿Sabes en qué Afore estás y cuánto tienes? Escribe qué harás esta semana para averiguarlo o para actualizar a tus beneficiarios.","ayuda":"Esta semana voy a…"},{"tipo":"clave","items":["Tu cuenta individual en la Afore es tuya y te sigue de trabajo en trabajo.","Aportaciones voluntarias: dinero extra para tu retiro, desde montos pequeños.","Ahorro solidario solo aplica a trabajadores del ISSSTE en cuentas individuales."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"Un fondo de emergencia sirve para…","ops":["Comprar regalos de diciembre","Invertir en la bolsa","Pagar la renta cada mes","Imprevistos reales sin tener que endeudarte"],"correcta":3},{"p":"Tus gastos esenciales son $10,000 al mes y quieres 3 meses de colchón. Tu meta es…","ops":["$3,000","$10,000","$30,000","$13,000"],"correcta":2},{"p":"Te faltan $12,000 para tu meta y tienes 12 meses. Debes ahorrar al mes…","ops":["$1,200","$1,000","$12,000","$100"],"correcta":1},{"p":"La inflación es…","ops":["El aumento generalizado de los precios","El interés que paga tu cuenta","Un impuesto al ahorro","La comisión de la Afore"],"correcta":0},{"p":"Con 4% de inflación anual, algo que hoy cuesta $10,000 costará en un año aproximadamente…","ops":["$14,000","$10,040","$9,600","$10,400"],"correcta":3},{"p":"La Afore es…","ops":["Un tipo de seguro de auto","Una oficina del SAT","La administradora de tu cuenta individual para el retiro","Un banco que presta dinero"],"correcta":2},{"p":"El ahorro solidario (la dependencia aporta $3.25 por cada peso) aplica a…","ops":["Cualquier persona con tarjeta de crédito","Trabajadores del Estado en el régimen de cuentas individuales del ISSSTE","Todos los trabajadores del IMSS","Solo a trabajadores independientes"],"correcta":1},{"p":"Si trabajas por tu cuenta, para ahorrar para el retiro puedes…","ops":["Abrir una cuenta en una Afore y hacer aportaciones voluntarias","Nada, no hay opción","Solo comprar una tanda","Esperar a que el patrón aporte"],"correcta":0}]}},{"id":"c-finanzas-personales-m5","titulo":"Módulo 5 — Protege tu dinero y arma tu plan de 90 días","resumen":"Seguros básicos, fraudes financieros comunes, protección de tus datos bancarios y un plan de 90 días para poner en práctica todo el curso. Tres lecciones y una evaluación.","lecciones":[{"id":"c-finanzas-personales-m5-l1","titulo":"Lección 1 — Seguros básicos","objetivo":"entender para qué sirve un seguro y los conceptos que debes revisar antes de contratar uno.","bloques":[{"tipo":"texto","texto":"Un <b>seguro</b> es un contrato en el que pagas una cantidad (la <b>prima</b>) para que, si ocurre un evento cubierto, la aseguradora pague una parte o todo el daño. Sirve para lo que no podrías pagar tú solo sin arruinar tus finanzas: una hospitalización, un choque con daños a terceros, el fallecimiento de quien sostiene a la familia."},{"tipo":"tarjetas","rotulo":"Conceptos que debes entender","tarjetas":[{"frente":"Prima","reverso":"Lo que pagas por el seguro (mensual, semestral o anual)."},{"frente":"Suma asegurada","reverso":"El máximo que pagará la aseguradora por un evento cubierto."},{"frente":"Deducible","reverso":"La parte del daño que pagas tú antes de que el seguro empiece a pagar."},{"frente":"Coaseguro","reverso":"Un porcentaje del gasto que te toca pagar a ti, después del deducible (común en gastos médicos)."},{"frente":"Exclusiones","reverso":"Lo que el seguro no cubre. Léelas antes de firmar."},{"frente":"Beneficiarios","reverso":"Quién recibe el dinero en un seguro de vida. Mantenlos actualizados."}]},{"tipo":"tabla","titulo":"Seguros que conviene conocer","encabezados":["Seguro","Qué cubre","Para quién es útil"],"filas":[["Vida","Pago a tus beneficiarios si falleces.","Si alguien depende de tu ingreso."],["Gastos médicos","Hospitalización, cirugías y tratamientos según la póliza.","Si no tienes seguridad social o quieres cobertura adicional."],["Auto: responsabilidad civil","Daños que causes a otras personas o a sus bienes.","Si manejas. Revisa qué exige la ley de tu estado y para circular por carreteras federales."],["Hogar o daños","Incendio, robo o fenómenos naturales, según la póliza.","Si tienes bienes que no podrías reponer."]],"nota":"Revisa primero qué te cubre ya tu seguridad social o tu trabajo (por ejemplo, un seguro de vida de prestación). Compara al menos tres cotizaciones y lee condiciones generales y exclusiones."},{"tipo":"relacionar","rotulo":"Relaciona el concepto","pares":[["Lo que pagas por tener el seguro","Prima"],["Lo que pagas tú antes de que pague el seguro","Deducible"],["Porcentaje del gasto médico que te toca","Coaseguro"],["Lo que la póliza no cubre","Exclusiones"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu auto tiene un deducible de $8,000 y el daño cuesta $30,000. Si el siniestro está cubierto, la aseguradora paga aproximadamente…","ops":["$22,000","$30,000"],"correcta":0,"explica":"Tú cubres el deducible y la aseguradora el resto, hasta la suma asegurada."},{"p":"Un seguro de vida es más importante cuando…","ops":["Nadie depende de ti","Otras personas dependen de tu ingreso"],"correcta":1},{"p":"Antes de contratar un seguro debes leer…","ops":["Las condiciones generales y las exclusiones","Solo el precio de la prima"],"correcta":0}]},{"tipo":"clave","items":["Un seguro protege contra gastos que no podrías pagar solo.","Entiende prima, suma asegurada, deducible, coaseguro y exclusiones.","Revisa qué ya tienes cubierto y compara antes de contratar."]}]},{"id":"c-finanzas-personales-m5-l2","titulo":"Lección 2 — Fraudes comunes y tus datos bancarios","objetivo":"reconocer los fraudes financieros más comunes y proteger tus cuentas y datos personales.","bloques":[{"tipo":"texto","texto":"Muchos fraudes no «hackean» nada: te convencen a ti de entregar tus datos o de hacer una transferencia. Usan <b>urgencia</b> («tu cuenta será bloqueada»), <b>miedo</b> («detectamos un cargo») o <b>premios</b> («ganaste»). La regla más importante: <b>tu banco nunca te pedirá tu NIP, tu contraseña completa ni los códigos que te llegan por SMS o por la app</b>."},{"tipo":"tabla","titulo":"Fraudes frecuentes","encabezados":["Fraude","Cómo llega","Cómo protegerte"],"filas":[["Llamada falsa del banco (vishing)","Te llaman «del área de seguridad» y piden un código o que muevas tu dinero a una «cuenta segura».","Cuelga y llama tú al número que viene al reverso de tu tarjeta."],["Mensaje o correo con enlace (phishing)","SMS, WhatsApp o correo con un enlace a una página idéntica a la de tu banco.","No abras enlaces; entra solo desde la app oficial o escribiendo la dirección tú mismo."],["Ventas en línea falsas","Precios muy bajos en redes sociales; piden transferencia o depósito anticipado.","Desconfía de ofertas irreales y de vendedores sin historial."],["Premios y herencias","Ganaste un sorteo en el que nunca participaste, pero debes pagar un «trámite».","Nadie paga para cobrar un premio legítimo."],["Inversiones milagro","Rendimientos altos, rápidos y «garantizados»; ganas si invitas a más personas.","Si suena demasiado bueno, verifica a la empresa con la CONDUSEF y la CNBV."]]},{"tipo":"comparar","titulo":"La misma llamada, dos respuestas","malTitulo":"Lo que busca el defraudador","mal":"«Sí, te paso el código que me llegó para cancelar el cargo.»","bienTitulo":"Lo que te protege","bien":"«Voy a colgar y llamaré al número que viene en mi tarjeta.» Después revisas tus movimientos en la app oficial."},{"tipo":"lista","items":["<b>Activa notificaciones</b> de cada movimiento en tu app bancaria.","<b>Usa contraseñas distintas</b> y, si tu banco lo permite, tarjeta digital para compras en línea.","<b>No prestes tu cuenta</b> para recibir dinero de desconocidos: puede usarse para fraudes.","<b>Registra tu teléfono en el REUS</b> de la CONDUSEF para limitar la publicidad de instituciones financieras; así cualquier llamada «de promoción» te parecerá más sospechosa.","<b>Si te roban el celular</b>, reporta la línea y avisa a tu banco de inmediato."]},{"tipo":"pasos","rotulo":"Si fuiste víctima de un fraude","pasos":["Llama a tu banco por sus canales oficiales y pide bloquear tu tarjeta o cuenta.","Presenta la aclaración o reclamación por escrito y guarda tu número de folio.","Cambia contraseñas y revisa tus movimientos recientes.","Si el banco no resuelve, acude a la CONDUSEF.","Si hubo un delito, presenta tu denuncia ante la fiscalía o la policía cibernética."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Alguien «del banco» te pide el código que te acaba de llegar por SMS. Tú…","ops":["Lo das para cancelar el cargo","No lo das, cuelgas y llamas al número oficial"],"correcta":1,"explica":"Ese código autoriza operaciones: quien lo tiene puede mover tu dinero."},{"p":"Te ofrecen 20% de rendimiento mensual «garantizado». Es señal de…","ops":["Posible fraude","Una inversión segura"],"correcta":0},{"p":"Para dejar de recibir publicidad de instituciones financieras puedes registrarte en…","ops":["Tu Afore","El REUS de la CONDUSEF"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Ordena la regla de oro","items":[{"frase":"Tu banco nunca te pide tu NIP","es":"La regla que evita la mayoría de los fraudes"},{"frase":"Cuelga y llama tú al número oficial","es":"Qué hacer ante una llamada sospechosa"}]},{"tipo":"clave","items":["Urgencia, miedo o premio: las tres señales de un fraude.","Nunca compartas NIP, contraseñas ni códigos de verificación.","Si te pasa: bloquea, reclama por escrito, acude a la CONDUSEF y denuncia."]}]},{"id":"c-finanzas-personales-m5-l3","titulo":"Lección 3 — Tu plan de 90 días","objetivo":"armar y dar seguimiento a un plan de 90 días que integre diagnóstico, presupuesto, deudas, ahorro y protección.","bloques":[{"tipo":"texto","texto":"Ya tienes las herramientas. Ahora hay que convertirlas en acciones pequeñas, con fecha, durante los próximos <b>90 días</b>. No se trata de cambiarlo todo en una semana, sino de avanzar un paso a la vez y medir tu progreso con tu patrimonio neto y tu nivel de deuda."},{"tipo":"pasos","rotulo":"Tu ruta en tres etapas","pasos":["<b>Días 1 a 30 — Diagnóstico:</b> registra todos tus gastos, calcula tu ingreso neto, tus gastos hormiga y tu patrimonio neto. Pide tu Reporte de Crédito Especial.","<b>Días 31 a 60 — Orden:</b> arma tu presupuesto quincenal, usa sobres, lista tus deudas por saldo y tasa y elige bola de nieve o avalancha. Negocia la que ya no puedas pagar.","<b>Días 61 a 90 — Protección:</b> empieza tu colchón de emergencia, revisa tu Afore y beneficiarios, revisa tus seguros y activa las alertas de tu banco.","<b>Día 90:</b> vuelve a calcular tu patrimonio neto y compáralo con el del día 1."]},{"tipo":"excel","rotulo":"Da seguimiento a tu plan","datos":[["Acción","Semana meta","Estado"],["Registrar todos mis gastos",2,"Hecho"],["Hacer mi presupuesto quincenal",3,"Hecho"],["Pedir mi Reporte de Crédito Especial",4,"Pendiente"],["Listar deudas por tasa y saldo",4,"Hecho"],["Abrir un apartado para emergencias",6,"Pendiente"],["Negociar la deuda más cara",8,"Pendiente"],["Revisar seguros y beneficiarios",10,"Pendiente"],["Acciones hechas","",""],["Total de acciones","",""],["Avance %","",""],["Pendientes hasta la semana 6","",""]],"retos":[{"celda":"B9","formula":"=CONTAR.SI(C2:C8,\"Hecho\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>B9</b>: cuenta cuántas acciones están «Hecho»."},{"celda":"B10","formula":"=CONTARA(A2:A8)","esperado":7,"requiere":"CONTARA(","texto":"<b>B10</b>: cuenta cuántas acciones hay en total con CONTARA."},{"celda":"B11","formula":"=REDONDEAR(B9/B10*100,0)","esperado":43,"requiere":"REDONDEAR(","texto":"<b>B11</b>: porcentaje de avance, redondeado a entero."},{"celda":"B12","formula":"=CONTAR.SI.CONJUNTO(C2:C8,\"Pendiente\",B2:B8,\"<=6\")","esperado":2,"requiere":"CONTAR.SI.CONJUNTO(","texto":"<b>B12</b>: ¿cuántas acciones siguen pendientes y tenían meta en la semana 6 o antes? Usa CONTAR.SI.CONJUNTO con dos condiciones.","pista":"=CONTAR.SI.CONJUNTO(C2:C8,\"Pendiente\",B2:B8,\"<=6\")","explica":"Dos acciones urgentes: pedir tu reporte de crédito y abrir el apartado de emergencias. Esas van primero esta semana."}]},{"tipo":"plantilla","rotulo":"Mi plan de 90 días","texto":"Mi ingreso neto mensual: $____\nMi patrimonio neto hoy: $____\nMis gastos hormiga al mes: $____\nMétodo para mis deudas (bola de nieve o avalancha): ____\nDeuda que ataco primero: ____\nMeta de colchón de emergencia: $____ para el día ____\nAhorro por quincena: $____\nDía fijo de revisión de mi presupuesto: ____\nPersona con quien comparto mi plan: ____\nMi patrimonio neto en el día 90: $____","nota":"Cópiala en tu libreta o en tu celular y revísala cada día de pago."},{"tipo":"reflexion","rotulo":"Tu compromiso","pregunta":"¿Cuál es la primera acción de tu plan que harás en las próximas 48 horas? Escríbela con día y hora.","ayuda":"El ____ a las ____ voy a…"},{"tipo":"clave","items":["Convierte lo aprendido en acciones pequeñas con fecha.","Diagnóstico, orden y protección: una etapa por mes.","Mide tu avance con tu patrimonio neto del día 1 y del día 90."]}]}],"quiz":{"titulo":"Evaluación del módulo 5","preguntas":[{"p":"El deducible de un seguro es…","ops":["Lo que pagas cada mes por el seguro","El máximo que paga la aseguradora","Lo que no cubre la póliza","La parte del daño que pagas tú antes de que pague la aseguradora"],"correcta":3},{"p":"La prima de un seguro es…","ops":["Un descuento del banco","Un tipo de deducible","Lo que pagas por tener el seguro","El dinero que recibe el beneficiario"],"correcta":2},{"p":"Un seguro de vida es especialmente útil cuando…","ops":["Tienes un auto nuevo","Otras personas dependen de tu ingreso","Nadie depende de ti","Quieres ahorrar para vacaciones"],"correcta":1},{"p":"Tu banco te puede pedir por teléfono…","ops":["Nunca tu NIP, contraseñas ni códigos de verificación","Tu NIP para verificar tu identidad","El código que te llegó por SMS","Tu contraseña completa"],"correcta":0},{"p":"Una inversión que promete rendimientos altos y garantizados si invitas a más personas es…","ops":["Una inversión regulada","Un seguro de vida","Una Afore","Una señal de posible fraude"],"correcta":3},{"p":"Si fuiste víctima de un cargo no reconocido, lo primero es…","ops":["Publicarlo en redes","Pagar el cargo","Llamar a tu banco por canales oficiales y bloquear","Esperar al siguiente estado de cuenta"],"correcta":2},{"p":"El REUS de la CONDUSEF sirve para…","ops":["Elegir Afore","Limitar la publicidad de instituciones financieras","Consultar tu historial crediticio","Pedir préstamos"],"correcta":1},{"p":"Al final del plan de 90 días mides tu avance comparando…","ops":["Tu patrimonio neto del día 1 y del día 90","Cuántas compras hiciste","Tu límite de crédito","El número de tarjetas que tienes"],"correcta":0}]}}]});
window.CURSOS_MARA.push({"id":"d-marketing-digital","nombre":"Diplomado en Marketing Digital y Redes Sociales para Negocios","color":"#EA580C","nivel":"Diplomados","familia":"Negocios y finanzas","periodoTipo":null,"periodoNum":null,"desc":"Arma la estrategia digital de tu negocio paso a paso: cliente ideal, WhatsApp Business y perfil de Google, contenido para redes, anuncios pagados y medición en hoja de cálculo. Es práctico y con ejemplos mexicanos; no promete ventas garantizadas: te enseña a probar, medir y decidir con datos.","horas":32,"precio":1690,"publicado":true,"proximamente":false,"modulos":[{"id":"d-marketing-digital-m1","titulo":"Módulo 1 — Estrategia: a quién le vendes, qué ofreces y cuánto inviertes","resumen":"Cliente ideal, propuesta de valor, embudo de ventas, objetivos SMART y presupuesto de marketing con hoja de cálculo. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-marketing-digital-m1-l1","titulo":"Lección 1 — Marketing digital con los pies en la tierra","objetivo":"entender qué es el marketing digital para un negocio pequeño y describir a tu cliente ideal.","bloques":[{"tipo":"destacado","texto":"<b>Sobre este diplomado.</b> Es un <b>diplomado libre de capacitación</b>: al terminarlo recibes una <b>constancia emitida por Instituto Mara</b>. No es un título ni un estudio con reconocimiento de validez oficial de la SEP, ni una certificación de competencias del CONOCER. Lo que sí te llevas es un plan de marketing aplicado a tu propio negocio."},{"tipo":"texto","texto":"El marketing digital no es «subir cosas a Facebook». Es <b>conseguir y conservar clientes usando canales digitales</b>: tu perfil de Google, WhatsApp, redes sociales, anuncios y tu página. Para una taquería, una estética o un consultorio dental, el objetivo casi nunca es «tener muchos likes»; es que <b>más gente correcta te encuentre, te escriba y te compre</b>, y que regrese. Nadie puede garantizarte ventas: lo que sí puedes es probar, medir y mejorar con orden."},{"tipo":"comparar","titulo":"Dos formas de hacer marketing","malTitulo":"Publicar por publicar","mal":"«Hoy subo una foto porque hace mucho que no publico.» Sin saber a quién le hablas, sin medir, copiando lo que hace la competencia y metiendo dinero a «promocionar» cuando las ventas bajan.","bienTitulo":"Con estrategia","bien":"Sabes quién es tu cliente, qué problema le resuelves, en qué canal está, qué quieres lograr este mes y cuánto vas a invertir. Cada publicación y cada peso tienen un propósito que puedes medir."},{"tipo":"titulo","texto":"Tu cliente ideal"},{"tipo":"texto","texto":"El <b>cliente ideal</b> (también le dicen «buyer persona») es la descripción de la persona que <b>más te conviene</b> atender: la que valora lo que haces, puede pagarlo y regresa. No es «todo el mundo». Descríbelo con datos que realmente conozcas por tus ventas, no con suposiciones."},{"tipo":"plantilla","rotulo":"Ficha de cliente ideal","texto":"FICHA DE CLIENTE IDEAL\n\nNombre ficticio: (ej. «Mariana, la mamá que trabaja»)\nEdad aproximada y zona donde vive o trabaja:\nOcupación y horario:\n¿Qué problema o deseo la trae a mi negocio?:\n¿Qué le preocupa antes de comprar? (precio, confianza, tiempo, higiene):\n¿Dónde busca información? (Google Maps, Facebook, TikTok, grupos de WhatsApp, recomendación):\n¿Qué palabras usa para buscarme? (ej. «estética cerca de mí», «dentista que acepte pagos»):\n¿Cuánto gasta normalmente y cada cuánto compra?:\n¿Qué la haría recomendarme?:","nota":"Llena la ficha pensando en tus 5 mejores clientes reales. Si tienes dos tipos muy distintos, haz dos fichas."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para una estética de barrio, el cliente ideal es…","ops":["Una descripción concreta de quien más le conviene atender","Toda la gente de la ciudad"],"correcta":0,"explica":"Si le hablas a todos, tu mensaje no conecta con nadie."},{"p":"Un buen indicador del marketing de una taquería es…","ops":["Cuántos likes tuvo la última foto","Cuántos pedidos llegan por WhatsApp o Maps"],"correcta":1,"explica":"Los likes pueden ayudar, pero lo que paga la renta son los pedidos."},{"p":"La ficha de cliente ideal se llena mejor con…","ops":["Lo que sabes de tus clientes reales","Lo que te gustaría que fueran tus clientes"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu negocio en una frase","pregunta":"Escribe a qué se dedica tu negocio, quién es tu mejor cliente y por qué te compra a ti. Te servirá en todo el diplomado.","ayuda":"Mi negocio es… Mi mejor cliente es… Me compra porque…"},{"tipo":"clave","items":["Marketing digital = conseguir y conservar clientes por canales digitales, no juntar likes.","Tu cliente ideal es alguien concreto, descrito con datos reales.","Nadie garantiza ventas: se prueba, se mide y se mejora."]}]},{"id":"d-marketing-digital-m1-l2","titulo":"Lección 2 — Propuesta de valor: por qué a ti y no al de enfrente","objetivo":"redactar una propuesta de valor clara y creíble para tu negocio.","bloques":[{"tipo":"texto","texto":"La <b>propuesta de valor</b> es la razón por la que tu cliente ideal debería elegirte. Responde en una o dos frases: <b>qué ofreces, a quién, qué problema resuelves y qué te hace diferente</b>. «Calidad y buen servicio» no es propuesta de valor: todos lo dicen. Busca algo concreto y comprobable."},{"tipo":"comparar","titulo":"Propuestas de valor","malTitulo":"Genéricas","mal":"Ferretería: «La mejor atención y los mejores precios.»<br>Consultorio dental: «Tu sonrisa es nuestra prioridad.»<br>Perfumes: «Fragancias de calidad.»","bienTitulo":"Concretas","bien":"Ferretería: «Te decimos qué material necesitas para tu reparación y te lo mandamos el mismo día en la colonia.»<br>Consultorio: «Limpieza dental con cita en 48 horas, precio publicado y pagos a meses.»<br>Perfumes: «Perfumes artesanales hechos en lotes pequeños en Puebla; te mandamos muestras antes de comprar el frasco.»"},{"tipo":"plantilla","rotulo":"Fórmula de propuesta de valor","texto":"Ayudo a [cliente ideal] a [lograr algo / resolver un problema] con [tu producto o servicio], a diferencia de [la alternativa común], porque [prueba o diferencia concreta].\n\nEjemplo (estética):\nAyudo a mujeres que trabajan en el centro a verse arregladas sin perder la tarde, con cortes y peinados con cita puntual de 45 minutos, a diferencia de las estéticas donde esperas turno, porque manejamos agenda por WhatsApp y confirmamos un día antes."},{"tipo":"relacionar","rotulo":"Relaciona la frase con lo que le falta","pares":[["«Somos los mejores de la ciudad»","No es comprobable"],["«Vendemos de todo para todos»","No dice a quién le habla"],["«Tacos de suadero» sin nada más","No dice qué la hace diferente"],["«Entrega en 30 minutos o el refresco va por nuestra cuenta»","Está completa y es concreta"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una propuesta de valor debe ser…","ops":["Lo más general posible para que le sirva a todos","Concreta y fácil de comprobar"],"correcta":1,"explica":"Lo concreto se recuerda y se puede cumplir."},{"p":"«Precio publicado y cita en 48 horas» es fuerte porque…","ops":["Quita dos miedos del cliente: sorpresas en el costo y la espera","Suena elegante"],"correcta":0},{"p":"Si tu diferencia es el precio más bajo…","ops":["Siempre es la mejor estrategia","Asegúrate de que tus márgenes lo aguanten"],"correcta":1,"explica":"Competir solo por precio es riesgoso para un negocio pequeño."}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"La propuesta de valor responde por qué el cliente debería elegirte a ti y no a la ___.","resp":["competencia","competencia."]},{"frase":"«Calidad y buen servicio» es una frase ___: todos la dicen.","resp":["genérica","generica","general"]}]},{"tipo":"clave","items":["Propuesta de valor = qué, para quién, qué resuelve y qué te hace distinto.","Evita frases que dice cualquiera; usa diferencias comprobables.","Promete solo lo que sí puedes cumplir todos los días."]}]},{"id":"d-marketing-digital-m1-l3","titulo":"Lección 3 — El embudo y los objetivos SMART","objetivo":"dibujar el embudo de tu negocio, calcular tasas de paso y fijar objetivos SMART.","bloques":[{"tipo":"texto","texto":"Casi nadie compra la primera vez que te ve. El <b>embudo</b> describe el camino: mucha gente <b>te conoce</b>, menos <b>se interesa</b> y te escribe, menos <b>te compra</b>, y algunos <b>regresan y te recomiendan</b>. En cada paso se va gente; tu trabajo es entender en qué paso se te van más."},{"tipo":"tabla","titulo":"Etapas del embudo","encabezados":["Etapa","Qué pasa","Ejemplo en una estética"],"filas":[["Descubrimiento","La persona sabe que existes","Ve un reel de un corte o te encuentra en Google Maps"],["Consideración","Compara y pregunta","Te escribe por WhatsApp: «¿cuánto el tinte?»"],["Conversión","Compra o agenda","Agenda cita y asiste"],["Lealtad","Regresa y recomienda","Vuelve cada 6 semanas y deja una reseña"]]},{"tipo":"excel","rotulo":"Embudo de la Estética Lupita (un mes)","datos":[["Etapa","Personas","Tasa de paso"],["Vieron publicaciones (alcance)",12000,""],["Escribieron por WhatsApp",240,""],["Agendaron cita",96,""],["Asistieron y pagaron",72,""],["Conversión total (alcance a clienta)","",""],["Clientas si 50% de los mensajes agendan","",""]],"retos":[{"celda":"C3","formula":"=B3/B2","esperado":0.02,"texto":"<b>C3</b>: ¿qué parte de quienes vieron las publicaciones escribió? Divide los mensajes entre el alcance.","pista":"=B3/B2. Dale formato de porcentaje: 2%."},{"celda":"C4","formula":"=B4/B3","esperado":0.4,"texto":"<b>C4</b>: de quienes escribieron, ¿qué parte agendó?"},{"celda":"C5","formula":"=B5/B4","esperado":0.75,"texto":"<b>C5</b>: de quienes agendaron, ¿qué parte asistió y pagó?"},{"celda":"C6","formula":"=B5/B2","esperado":0.006,"texto":"<b>C6</b>: conversión total: clientas que pagaron entre el alcance.","explica":"0.6%: de cada 1,000 personas que vieron algo, 6 terminaron pagando. Es normal que el número sea pequeño."},{"celda":"B7","formula":"=B3*0.5*C5","esperado":90,"texto":"<b>B7</b>: si mejoras la atención por WhatsApp y agenda 50% de quienes escriben (en vez de 40%), ¿cuántas clientas tendrías? Mensajes × 0.5 × tasa de asistencia (C5).","explica":"De 72 a 90 clientas sin gastar un peso más en alcance: a veces la mejora más barata está en contestar mejor, no en conseguir más vistas."}]},{"tipo":"texto","texto":"Un <b>objetivo SMART</b> es: <b>eSpecífico</b> (qué exactamente), <b>Medible</b> (con número), <b>Alcanzable</b> (realista con tus recursos), <b>Relevante</b> (ayuda al negocio) y con <b>Tiempo</b> definido. «Crecer en redes» no es SMART; «pasar de 72 a 85 clientas atendidas al mes antes del 30 de noviembre, mejorando la respuesta por WhatsApp» sí lo es."},{"tipo":"relacionar","rotulo":"¿Qué letra de SMART le falta?","pares":[["«Vender más tacos»","Específico y medible"],["«Triplicar las ventas en una semana sin presupuesto»","Alcanzable"],["«Llegar a 10 mil seguidores» en un consultorio que ya tiene agenda llena","Relevante"],["«Conseguir 40 reseñas nuevas en Google»","Tiempo definido"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si mucha gente te escribe pero pocos agendan, el problema está en…","ops":["La consideración: cómo respondes y cierras","El descubrimiento: te falta alcance"],"correcta":0,"explica":"Más alcance no arregla una mala atención en WhatsApp."},{"p":"¿Cuál objetivo es SMART?","ops":["Tener más presencia digital","Recibir 60 pedidos por WhatsApp en octubre"],"correcta":1}]},{"tipo":"clave","items":["El embudo: descubrimiento, consideración, conversión y lealtad.","Mide la tasa de paso entre etapas para saber dónde se te va la gente.","Objetivo SMART: específico, medible, alcanzable, relevante y con fecha."]}]},{"id":"d-marketing-digital-m1-l4","titulo":"Lección 4 — Presupuesto de marketing con hoja de cálculo","objetivo":"armar un presupuesto mensual, repartirlo por día y fijar cuánto puedes pagar por conseguir un cliente.","bloques":[{"tipo":"texto","texto":"Un presupuesto de marketing no tiene que ser grande; tiene que ser <b>claro y sostenible</b>. Muchos negocios pequeños empiezan destinando un porcentaje pequeño de sus ventas (suele mencionarse entre 3% y 10%, según el giro y la etapa) y lo ajustan con resultados. Lo más importante: saber <b>cuánto puedes pagar como máximo por conseguir un cliente</b> sin perder dinero."},{"tipo":"lista","items":["<b>Anuncios</b>: lo que pagas a Meta, Google o TikTok.","<b>Herramientas</b>: diseño, programación de publicaciones, dominio de tu página.","<b>Contenido</b>: fotos, video, alguien que te ayude a editar.","<b>Tu tiempo</b>: aunque no lo pagues, cuenta. Anótalo en horas por semana."]},{"tipo":"excel","rotulo":"Presupuesto mensual de la Taquería El Güero","datos":[["Concepto","Monto","% del total"],["Anuncios en Meta",3000,""],["Anuncios en Google",1500,""],["Herramientas (diseño, dominio)",250,""],["Sesión de fotos de platillos",800,""],["Total","",""],["Ventas mensuales",150000,""],["% de las ventas","",""],["Presupuesto diario Meta (30 días)","",""],["¿Dentro del tope de 5%?","",""],["Ticket promedio",180,""],["Margen bruto",0.4,""],["Costo máximo por cliente (1 compra)","",""]],"retos":[{"celda":"B6","formula":"=SUMA(B2:B5)","esperado":5550,"requiere":"SUMA(","texto":"<b>B6</b>: suma el presupuesto total del mes."},{"celda":"C2","formula":"=B2/$B$6","esperado":0.5405405405,"texto":"<b>C2</b>: ¿qué parte del presupuesto se va a Meta? Divide entre el total fijo ($B$6).","pista":"Con $B$6 puedes copiar la fórmula hacia abajo sin que se mueva el total."},{"celda":"B8","formula":"=B6/B7","esperado":0.037,"texto":"<b>B8</b>: ¿qué porcentaje de las ventas representa el presupuesto?"},{"celda":"B9","formula":"=REDONDEAR(B2/30,0)","esperado":100,"requiere":"REDONDEAR(","texto":"<b>B9</b>: presupuesto diario para Meta: el mensual entre 30, redondeado a 0 decimales.","explica":"Las plataformas de anuncios suelen pedir un presupuesto diario o total de campaña; saber tu cifra diaria evita sorpresas en el estado de cuenta."},{"celda":"B10","formula":"=SI(B8<=0.05,\"Sí\",\"No\")","esperado":"Sí","requiere":"SI(","texto":"<b>B10</b>: con SI, escribe «Sí» si el porcentaje de B8 es menor o igual a 5% (0.05) y «No» si lo rebasa.","pista":"=SI(B8<=0.05,\"Sí\",\"No\")"},{"celda":"B13","formula":"=B11*B12","esperado":72,"texto":"<b>B13</b>: ¿cuánto te deja una orden promedio? Ticket × margen bruto. Ese es el máximo que podrías pagar por conseguir un cliente que compra una sola vez.","explica":"Si un anuncio te cuesta más de $72 por cliente nuevo y ese cliente no regresa, pierdes dinero. Si regresa 3 veces, puedes pagar más: por eso importa la lealtad."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu margen por orden es de $72 y un anuncio te consigue clientes a $110 cada uno que compran una sola vez. Entonces…","ops":["Pierdes dinero con cada cliente de ese anuncio","Ganas porque vendes más"],"correcta":0,"explica":"Vender más con pérdida solo hace más grande la pérdida."},{"p":"Conviene definir el presupuesto…","ops":["Cuando las ventas bajan, metiendo todo lo que se pueda","Antes de empezar y revisarlo cada mes con resultados"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu presupuesto inicial","pregunta":"¿Cuánto podrías invertir al mes en marketing sin poner en riesgo la operación? ¿Cuál es tu ticket promedio y tu margen aproximado? Calcula tu costo máximo por cliente.","ayuda":"Ventas mensuales… Presupuesto… Ticket… Margen… Costo máximo por cliente…"},{"tipo":"clave","items":["Presupuesto claro: anuncios, herramientas, contenido y tu tiempo.","Divide entre 30 para saber tu gasto diario de anuncios.","Costo máximo por cliente = ticket × margen (más si el cliente regresa)."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"El objetivo principal del marketing digital en un negocio pequeño es…","ops":["Tener muchos seguidores","Publicar todos los días","Copiar a la competencia","Conseguir y conservar clientes"],"correcta":3},{"p":"El cliente ideal se describe mejor con…","ops":["Toda la población de tu ciudad","La opinión de tus amigos","Datos de tus clientes reales","Lo que te gustaría que fueran"],"correcta":2},{"p":"¿Cuál es una propuesta de valor concreta?","ops":["Calidad y servicio","Limpieza dental con cita en 48 horas y precio publicado","Tu sonrisa es nuestra prioridad","Somos los mejores"],"correcta":1},{"p":"La etapa del embudo donde el cliente compara y pregunta precios es…","ops":["Consideración","Descubrimiento","Lealtad","Conversión"],"correcta":0},{"p":"240 personas escribieron y 96 agendaron. La tasa de paso es…","ops":["96%","24%","2.4%","40%"],"correcta":3},{"p":"«Conseguir 40 reseñas nuevas en Google» no es SMART porque le falta…","ops":["Relación con el negocio","Ser específico","Una fecha límite","Un número"],"correcta":2},{"p":"Con presupuesto mensual de $3,000 para anuncios, el diario aproximado es…","ops":["$1,000","$100","$300","$30"],"correcta":1},{"p":"Ticket promedio de $180 y margen de 40%: el costo máximo por cliente de una sola compra es…","ops":["$72","$180","$40","$108"],"correcta":0}]}},{"id":"d-marketing-digital-m2","titulo":"Módulo 2 — Presencia básica: que te encuentren y te puedan escribir","resumen":"Perfil de Google Business Profile, WhatsApp Business (catálogo, respuestas rápidas y etiquetas), una página sencilla y reseñas. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-marketing-digital-m2-l1","titulo":"Lección 1 — Tu perfil de negocio en Google","objetivo":"crear u optimizar tu perfil de Google Business Profile para aparecer en Google Maps y en búsquedas locales.","bloques":[{"tipo":"texto","texto":"Cuando alguien busca «taquería cerca de mí» o «dentista en Coyoacán», Google muestra un mapa con negocios. Esa ficha sale del <b>Perfil de Negocio de Google</b> (Google Business Profile), que al momento de escribir es <b>gratuito</b>. Para muchos negocios locales es el canal digital que más clientes trae, incluso antes que las redes sociales."},{"tipo":"pasos","rotulo":"Pasos generales para crear o reclamar tu perfil","pasos":["Busca tu negocio en Google Maps. Si ya aparece (a veces lo da de alta un cliente), elige la opción para <b>reclamarlo</b>; si no, créalo desde la página de Google Business Profile.","Escribe el <b>nombre real</b> del negocio, tal como aparece en tu letrero. Agregar palabras de relleno («Taquería El Güero mejores tacos CDMX») va contra las reglas de Google y puede provocar la suspensión.","Elige la <b>categoría principal</b> más precisa (ej. «Clínica dental» en vez de «Médico») y, si aplica, categorías secundarias.","Pon dirección o zona de servicio, <b>horario real</b> (incluye días festivos) y teléfono o WhatsApp.","<b>Verifica</b> el perfil con el método que te pida Google en ese momento (video, llamada, correo o código). Los métodos cambian con el tiempo.","Sube <b>fotos reales</b>: fachada (para que te encuentren), interior, productos, equipo trabajando.","Completa servicios o productos con precio aproximado y una descripción que incluya tu propuesta de valor."]},{"tipo":"comparar","titulo":"Dos perfiles de ferretería","malTitulo":"Descuidado","mal":"Sin fotos o con una foto borrosa, horario de hace dos años, teléfono que ya no existe, categoría «Tienda» y ninguna reseña respondida.","bienTitulo":"Cuidado","bien":"Foto de la fachada con el letrero visible, horario actualizado (incluido el 16 de septiembre), WhatsApp activo, categoría «Ferretería», lista de servicios (corte de llaves, igualación de pintura) y reseñas respondidas."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu perfil de Google debe llevar el nombre…","ops":["Tal como aparece en tu letrero","Con palabras clave para salir primero"],"correcta":0,"explica":"Rellenar el nombre con palabras clave puede provocar que Google suspenda la ficha."},{"p":"La foto más útil para que un cliente nuevo llegue es…","ops":["Un logotipo en fondo blanco","La fachada con el letrero"],"correcta":1},{"p":"Si cambias el horario en vacaciones…","ops":["Actualízalo en el perfil antes de que empiecen","No importa, la gente llama primero"],"correcta":0,"explica":"Un cliente que llega y encuentra cerrado difícilmente regresa."}]},{"tipo":"tarjetas","rotulo":"Lo que más pesa en tu ficha local (según las guías públicas de Google)","tarjetas":[{"frente":"Relevancia","reverso":"Qué tan bien coincide tu perfil con lo que la persona busca: categoría, servicios, descripción."},{"frente":"Distancia","reverso":"Qué tan cerca estás de quien busca o de la zona que menciona."},{"frente":"Prominencia","reverso":"Qué tan conocido eres: reseñas, calificación, menciones en otros sitios."}]},{"tipo":"reflexion","rotulo":"Revisa tu ficha hoy","pregunta":"Busca tu negocio en Google Maps desde el celular como si fueras cliente. ¿Qué dato está mal, falta o se ve feo? Anota tres cosas que vas a corregir esta semana.","ayuda":"1… 2… 3…"},{"tipo":"clave","items":["El perfil de Google es gratuito y suele ser el primer contacto de un cliente local.","Nombre real, categoría precisa, horario al día y fotos reales.","Relevancia, distancia y prominencia influyen en dónde apareces."]}]},{"id":"d-marketing-digital-m2-l2","titulo":"Lección 2 — WhatsApp Business: tu mostrador digital","objetivo":"configurar WhatsApp Business con perfil, catálogo, mensajes automáticos, respuestas rápidas y etiquetas.","bloques":[{"tipo":"texto","texto":"En México, buena parte de las ventas de negocios pequeños se cierran por WhatsApp. La aplicación <b>WhatsApp Business</b> es gratuita y, al momento de escribir, incluye herramientas que la versión personal no tiene. Los nombres de los menús cambian con las actualizaciones; busca estas funciones dentro de <b>Herramientas para la empresa</b> o una sección similar."},{"tipo":"tabla","titulo":"Herramientas de WhatsApp Business","encabezados":["Herramienta","Para qué sirve","Ejemplo"],"filas":[["Perfil de empresa","Dirección, horario, descripción, correo y sitio web","Estética: «Cortes, tinte y peinado. Cita por este medio.»"],["Catálogo","Mostrar productos o servicios con foto, precio y descripción","Perfumería: cada fragancia con foto, precio y tamaño"],["Mensaje de bienvenida","Se envía cuando alguien escribe por primera vez o después de un tiempo sin escribir","Saludo, qué ofreces y cómo pedir"],["Mensaje de ausencia","Responde fuera de horario","«Abrimos mañana a las 9; tu mensaje ya quedó registrado»"],["Respuestas rápidas","Atajos para textos que repites (se activan con /)","/precios, /ubicacion, /pago"],["Etiquetas","Clasificar chats por etapa","Nuevo cliente · Pedido pendiente · Pagado · Entregado"]],"nota":"Al momento de escribir estas funciones existen en la app; su nombre o ubicación puede cambiar."},{"tipo":"plantilla","rotulo":"Mensaje de bienvenida para WhatsApp Business","texto":"¡Hola! Gracias por escribir a Estética Lupita.\n\nPara ayudarte más rápido, dime:\n1. ¿Qué servicio te interesa? (corte, tinte, peinado, uñas)\n2. ¿Qué día y horario te acomoda?\n\nNuestros precios están en el catálogo. Atendemos de martes a sábado de 10:00 a 19:00.\nEn un momento te respondemos personalmente.","nota":"Corto, útil y con una pregunta para que la persona dé el siguiente paso. Cambia el nombre, los servicios y el horario por los tuyos."},{"tipo":"plantilla","rotulo":"Respuestas rápidas sugeridas","texto":"/ubicacion → Estamos en Av. Juárez 120, local 3, junto a la farmacia. Aquí el mapa: [liga de Google Maps]\n/pago → Aceptamos efectivo, tarjeta y transferencia. Para apartar tu cita pedimos un anticipo de $100.\n/confirmar → Hola, te recordamos tu cita de mañana a las [hora]. ¿Nos confirmas con un «sí»?\n/gracias → ¡Gracias por tu visita! Si te gustó el servicio, nos ayudaría mucho tu reseña aquí: [liga de reseñas]"},{"tipo":"relacionar","rotulo":"Relaciona la necesidad con la herramienta","pares":[["Te escriben a las 11 de la noche","Mensaje de ausencia"],["Siempre te preguntan dónde estás","Respuesta rápida"],["No sabes qué pedidos faltan de pagar","Etiquetas"],["Quieres que vean fotos y precios sin mandarlos uno por uno","Catálogo"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un buen mensaje de bienvenida…","ops":["Incluye toda la historia del negocio","Es breve y termina con una pregunta que guía al cliente"],"correcta":1,"explica":"Tu objetivo es que la persona dé el siguiente paso."},{"p":"Las etiquetas sirven sobre todo para…","ops":["Ordenar los chats por etapa de venta","Decorar el perfil"],"correcta":0},{"p":"Usar un número personal para el negocio…","ops":["Es lo más profesional","Mezcla clientes con familia y complica la atención"],"correcta":1}]},{"tipo":"clave","items":["WhatsApp Business es gratuito y trae catálogo, mensajes automáticos, respuestas rápidas y etiquetas.","Mensaje de bienvenida corto que guíe al siguiente paso.","Etiqueta los chats para no perder pedidos ni pagos."]}]},{"id":"d-marketing-digital-m2-l3","titulo":"Lección 3 — Una página sencilla que sí funciona","objetivo":"decidir qué tipo de página necesitas y qué debe contener para convertir visitas en mensajes.","bloques":[{"tipo":"texto","texto":"No necesitas una página cara para empezar. Lo que necesitas es un lugar propio, que no dependa de una sola red social, donde alguien entienda en 10 segundos <b>qué haces, dónde estás, cuánto cuesta aproximadamente y cómo contactarte</b>. Las redes pueden cerrar tu cuenta o cambiar las reglas; tu página y tu lista de clientes son tuyas."},{"tipo":"tabla","titulo":"Opciones de página, de menos a más","encabezados":["Opción","Cuándo conviene","Ojo con"],"filas":[["Enlace en la biografía (una página con botones)","Empiezas y solo necesitas reunir tus ligas","Depende del servicio que uses; guarda tus ligas en otro lado"],["Página de una sola sección (landing)","Tienes un servicio principal o una promoción","Que cargue rápido en el celular"],["Sitio con constructor sencillo","Varios servicios, galería, preguntas frecuentes","Costo mensual y renovación del dominio"],["Tienda en línea","Vendes productos con envío y cobro en línea","Comisiones, envíos, devoluciones y aviso de privacidad"]]},{"tipo":"pasos","rotulo":"Lo que debe tener tu página (en este orden)","pasos":["Encabezado con <b>qué haces y para quién</b> (tu propuesta de valor).","Botón visible de <b>WhatsApp</b>. Puedes armar la liga con el formato wa.me seguido de tu número con clave de país (52 para México), sin espacios ni signos.","Fotos reales de tu trabajo o producto.","Servicios o productos con <b>precio o rango de precio</b>.","Ubicación con mapa, horario y formas de pago.","Reseñas o testimonios <b>reales</b> (con permiso de quien los dio).","<b>Aviso de privacidad</b> si recabas datos personales (lo vemos en el módulo 5)."]},{"tipo":"comparar","titulo":"Encabezado de un consultorio dental","malTitulo":"Poco claro","mal":"«Bienvenidos a nuestro sitio web. Somos un equipo comprometido con la excelencia.»","bienTitulo":"Claro","bien":"«Consultorio dental en Zapopan. Limpieza, resinas y ortodoncia con precio publicado. Agenda por WhatsApp en menos de 5 minutos.» [Botón: Agenda por WhatsApp]"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Lo primero que debe entender un visitante es…","ops":["Qué haces y cómo contactarte","La historia de la fundación del negocio"],"correcta":0},{"p":"Tener página propia además de redes sirve para…","ops":["Dejar de responder mensajes","No depender de una sola plataforma"],"correcta":1},{"p":"La liga de WhatsApp para México lleva el número…","ops":["Con clave de país 52 y sin espacios","Con guiones y paréntesis"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Ordena la idea clave","items":[{"frase":"Tu página debe decir qué haces y cómo contactarte","es":"Todo lo demás es secundario"}]},{"tipo":"clave","items":["Empieza sencillo: una página propia que no dependa de una red.","Propuesta de valor arriba, botón de WhatsApp visible, precios, ubicación y reseñas.","Si recabas datos personales, necesitas aviso de privacidad."]}]},{"id":"d-marketing-digital-m2-l4","titulo":"Lección 4 — Reseñas: pedirlas, responderlas y cuidarlas","objetivo":"conseguir reseñas honestas y responder las positivas y las negativas de forma profesional.","bloques":[{"tipo":"texto","texto":"Las reseñas influyen en si alguien te elige y en tu posición en Google Maps. La forma más efectiva de conseguirlas es sencilla: <b>pedirlas en el momento correcto</b> (justo después de una buena experiencia) y <b>facilitar la liga</b>. Tu perfil de Google te da una liga para pedir reseñas; guárdala como respuesta rápida en WhatsApp."},{"tipo":"destacado","texto":"<b>Nada de reseñas falsas.</b> Inventar reseñas, pedirlas a familiares que nunca te compraron o comprarlas engaña al consumidor y va contra las políticas de las plataformas; Google, al momento de escribir, también prohíbe ofrecer descuentos o regalos a cambio de reseñas. El riesgo es que te eliminen reseñas o suspendan tu perfil, además del daño a tu reputación."},{"tipo":"pasos","rotulo":"Cómo responder una reseña negativa","pasos":["<b>Respira</b> y no contestes en caliente. Responde en menos de 48 horas si puedes.","<b>Agradece</b> y reconoce la experiencia sin discutir.","<b>Discúlpate</b> por lo que sí salió mal (sin inventar culpas ni echar la culpa al cliente).","Explica <b>qué vas a hacer</b> o qué cambiaste.","<b>Lleva la conversación a privado</b> con un medio de contacto.","Nunca publiques datos personales del cliente ni detalles de su consumo o tratamiento (especialmente en salud)."]},{"tipo":"plantilla","rotulo":"Respuesta a una reseña negativa","texto":"Hola, [nombre]. Gracias por tomarte el tiempo de contarnos tu experiencia. Lamentamos mucho que tu pedido haya llegado frío y con 40 minutos de retraso; no es lo que queremos para nuestros clientes. Ya ajustamos la forma en que empacamos y asignamos los repartos en horas pico. Nos gustaría compensarte: escríbenos al WhatsApp [número] y con gusto lo platicamos. — Beto, Taquería El Güero","nota":"Para un consultorio dental: no confirmes en público que la persona es paciente ni menciones su tratamiento; responde de forma general e invítala a comunicarse en privado."},{"tipo":"comparar","titulo":"Respuesta a una reseña de 1 estrella","malTitulo":"Así no","mal":"«Eso es mentira, usted llegó tarde a su cita y encima quería descuento. No vuelva.»","bienTitulo":"Así sí","bien":"«Gracias por tu comentario. Sentimos que tu experiencia no fuera buena. Revisamos lo que pasó con tu cita y nos gustaría aclararlo contigo; escríbenos al WhatsApp del consultorio.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El mejor momento para pedir una reseña es…","ops":["Un mes después, por correo","Justo después de una buena experiencia"],"correcta":1,"explica":"La emoción está fresca y la liga a la mano."},{"p":"Ofrecer 10% de descuento a cambio de una reseña de 5 estrellas…","ops":["Va contra las políticas de Google y engaña a otros clientes","Es una buena práctica de marketing"],"correcta":0},{"p":"Al responder la reseña negativa de un paciente dental…","ops":["Explicas su diagnóstico para defenderte","No mencionas su tratamiento ni datos personales"],"correcta":1,"explica":"Los datos de salud son datos personales sensibles."}]},{"tipo":"clave","items":["Pide reseñas en el mejor momento y facilita la liga.","Cero reseñas falsas o compradas.","Ante una crítica: agradece, discúlpate, di qué cambiaste y lleva la plática a privado."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"El perfil de negocio en Google sirve principalmente para…","ops":["Publicar reels","Enviar correos masivos","Cobrar con tarjeta","Aparecer en Google Maps y búsquedas locales"],"correcta":3},{"p":"Agregar palabras clave al nombre del negocio en Google…","ops":["Es obligatorio","No tiene ningún efecto","Puede causar la suspensión del perfil","Siempre te sube al primer lugar"],"correcta":2},{"p":"En WhatsApp Business, para no escribir la dirección cada vez usas…","ops":["Llamadas","Respuestas rápidas","Etiquetas","Estados"],"correcta":1},{"p":"El mensaje de ausencia se envía…","ops":["Fuera de tu horario de atención","Cuando alguien paga","Solo a clientes frecuentes","Cada hora"],"correcta":0},{"p":"Para ordenar chats en «pedido pendiente», «pagado» y «entregado» usas…","ops":["Catálogo","Mensaje de bienvenida","Listas de difusión","Etiquetas"],"correcta":3},{"p":"Lo primero que debe mostrar tu página es…","ops":["Un video de 5 minutos","Tu organigrama","Qué haces, para quién y cómo contactarte","La misión y visión"],"correcta":2},{"p":"Ante una reseña negativa conviene…","ops":["Ignorarla siempre","Agradecer, disculparte y llevar la conversación a privado","Discutir en público","Borrarla"],"correcta":1},{"p":"Pedir a familiares que nunca te compraron que dejen reseñas…","ops":["Es una práctica engañosa que puede costarte el perfil","Es la forma recomendada de empezar","Es obligatorio","Mejora la confianza sin riesgo"],"correcta":0}]}},{"id":"d-marketing-digital-m3","titulo":"Módulo 3 — Contenido que tu cliente sí quiere ver","resumen":"Pilares de contenido, calendario, formatos (reels, TikTok, carruseles e historias), textos con AIDA, fotografía con celular, Canva y uso responsable de la inteligencia artificial. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-marketing-digital-m3-l1","titulo":"Lección 1 — Pilares de contenido y calendario","objetivo":"definir de 3 a 5 temas fijos para tus publicaciones y organizarlos en un calendario semanal realista.","bloques":[{"tipo":"texto","texto":"La pregunta «¿qué publico hoy?» se acaba cuando tienes <b>pilares de contenido</b>: 3 a 5 temas fijos que le interesan a tu cliente ideal y que conectan con lo que vendes. Así no improvisas cada día y tu cuenta se ve coherente."},{"tipo":"tabla","titulo":"Pilares para una tienda de perfumes artesanales","encabezados":["Pilar","Qué publicas","Ejemplo"],"filas":[["Enseñar","Consejos útiles relacionados con tu producto","«Dónde aplicarte el perfume para que dure más»"],["Detrás de cámaras","Cómo se hace, quién lo hace","Video mezclando esencias en el taller"],["Producto","Qué vendes, precio, cómo pedir","Carrusel con las 3 fragancias de temporada"],["Prueba social","Clientes contentos (con permiso)","Captura de una reseña o clienta mostrando su frasco"],["Comunidad","Tu ciudad, fechas, valores","Aromas inspirados en el Día de Muertos"]],"nota":"Una regla práctica: la mayoría de tus publicaciones deben aportar (enseñar, entretener, inspirar) y una parte menor vender directo."},{"tipo":"relacionar","rotulo":"Relaciona la publicación con su pilar (consultorio dental)","pares":[["«3 errores al cepillarte que dañan tus encías»","Enseñar"],["Video de cómo esterilizamos el instrumental","Detrás de cámaras"],["«Limpieza dental con precio publicado, agenda aquí»","Producto"],["Testimonio de un paciente que dio su permiso por escrito","Prueba social"]]},{"tipo":"plantilla","rotulo":"Calendario semanal de contenido","texto":"CALENDARIO SEMANAL — [Nombre del negocio] — Semana del [fecha]\n\nLunes | Pilar: Enseñar | Formato: Carrusel | Tema: | Llamado a la acción: Guarda esta publicación\nMiércoles | Pilar: Detrás de cámaras | Formato: Reel o TikTok | Tema: | Llamado a la acción: Síguenos para ver más\nViernes | Pilar: Producto | Formato: Foto o carrusel + historia | Tema: | Llamado a la acción: Pide por WhatsApp\nDiario | Historias: pregunta, encuesta, pedido del día o reseña\n\nDía para grabar todo: [ej. domingo 10:00 a 12:00]\nQuién publica y responde comentarios:\nMétrica a revisar el siguiente lunes:","nota":"Mejor 3 publicaciones constantes que 7 una semana y ninguna las dos siguientes."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Los pilares de contenido sirven para…","ops":["Tener temas fijos y dejar de improvisar","Publicar solo promociones"],"correcta":0,"explica":"Organizan tu contenido alrededor de lo que le interesa a tu cliente."},{"p":"¿Qué es más sostenible para un negocio de dos personas?","ops":["2 publicaciones diarias durante una semana y luego nada","3 publicaciones por semana, todas las semanas"],"correcta":1},{"p":"Un video mezclando esencias en el taller pertenece al pilar…","ops":["Detrás de cámaras","Prueba social"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tus pilares","pregunta":"Escribe 3 a 5 pilares para tu negocio y un ejemplo de publicación para cada uno.","ayuda":"Pilar 1… ejemplo… / Pilar 2… ejemplo…"},{"tipo":"clave","items":["Pilares = 3 a 5 temas fijos que conectan a tu cliente con lo que vendes.","Aporta más de lo que vendes directo.","Constancia realista mejor que ráfagas."]}]},{"id":"d-marketing-digital-m3-l2","titulo":"Lección 2 — Formatos: reels y TikTok, carruseles e historias","objetivo":"elegir el formato adecuado para cada objetivo y guionar un video corto.","bloques":[{"tipo":"texto","texto":"Cada formato cumple una función. Al momento de escribir, los <b>videos verticales cortos</b> (reels de Instagram y Facebook, TikTok, YouTube Shorts) suelen ser los que más alcance dan a cuentas pequeñas; los <b>carruseles</b> sirven para enseñar paso a paso y que te guarden; las <b>historias</b> duran poco y sirven para conversar con quienes ya te siguen. Los algoritmos cambian: prueba y mide en tu propia cuenta."},{"tipo":"tabla","titulo":"¿Qué formato para qué?","encabezados":["Formato","Fuerte en","Ejemplo"],"filas":[["Reel o TikTok (video vertical corto)","Descubrimiento: que te vea gente nueva","Antes y después de un peinado en 15 segundos"],["Carrusel (varias imágenes)","Enseñar y que te guarden o compartan","«5 herramientas que toda casa necesita» en la ferretería"],["Historias","Conversar con tus seguidores: encuestas, preguntas, ofertas del día","«¿Suadero o pastor? Vota»"],["Foto única","Producto, anuncio puntual","Nueva fragancia con precio"],["En vivo","Resolver dudas en tiempo real","Dentista respondiendo preguntas frecuentes"]]},{"tipo":"titulo","texto":"Anatomía de un video corto"},{"tipo":"lista","items":["<b>Gancho (0 a 3 segundos):</b> una imagen o frase que detenga el dedo. «Así se ve un suadero bien hecho.»","<b>Desarrollo:</b> muestra, no solo digas. Tomas cortas, cambia de ángulo cada pocos segundos.","<b>Cierre con llamado a la acción:</b> qué hacer ahora. «Pide por WhatsApp, liga en el perfil.»","<b>Subtítulos:</b> mucha gente ve videos sin sonido."]},{"tipo":"plantilla","rotulo":"Guion de reel de 20 segundos","texto":"GUION DE REEL — Taquería El Güero\n\nObjetivo: que gente de la colonia conozca el suadero y pida por WhatsApp.\n\n0-3 s | Toma: acercamiento al suadero en el comal chisporroteando | Texto en pantalla: «¿Así te sirven el suadero?»\n3-8 s | Toma: el taquero pica la carne y arma el taco | Voz: «Lo cocemos 4 horas en su propia grasa.»\n8-14 s | Toma: salsa verde, cebolla, cilantro, limón | Texto: «Salsa hecha diario»\n14-18 s | Toma: cliente mordiendo el taco (con su permiso) | Sonido ambiente\n18-20 s | Toma: fachada y letrero | Texto: «Pide por WhatsApp · Av. Hidalgo 45 · Abrimos 7 pm»\n\nAudio: música de la biblioteca de la plataforma o sonido original.\nSubtítulos: sí.\nDescripción: 2 líneas + llamado a la acción + ubicación.","nota":"Usa solo música disponible dentro de la plataforma para uso comercial o con licencia; lo vemos en el módulo 5."},{"tipo":"relacionar","rotulo":"Relaciona el objetivo con el formato","pares":[["Que gente nueva te conozca","Reel o TikTok"],["Enseñar un paso a paso que la gente guarde","Carrusel"],["Preguntar a tus seguidores qué sabor quieren","Historia con encuesta"],["Resolver dudas en tiempo real","Transmisión en vivo"]]},{"tipo":"ordenar","rotulo":"Ordena la estructura de un video corto","items":[{"frase":"Gancho desarrollo y llamado a la acción","es":"Los primeros 3 segundos deciden si se quedan"}]},{"tipo":"clave","items":["Video corto para descubrimiento, carrusel para enseñar, historias para conversar.","Gancho en 3 segundos, muestra en lugar de explicar y cierra con llamado a la acción.","Los algoritmos cambian: prueba formatos y mide en tu cuenta."]}]},{"id":"d-marketing-digital-m3-l3","titulo":"Lección 3 — Textos que venden (AIDA) y fotos con el celular","objetivo":"escribir textos con la fórmula AIDA y tomar mejores fotos de producto con tu celular.","bloques":[{"tipo":"texto","texto":"<b>AIDA</b> es una fórmula clásica de copywriting (redacción para vender): <b>Atención</b> (detén al lector), <b>Interés</b> (dale una razón para seguir leyendo), <b>Deseo</b> (muestra el beneficio para él) y <b>Acción</b> (dile qué hacer). Sirve para publicaciones, anuncios y hasta mensajes de WhatsApp."},{"tipo":"tabla","titulo":"AIDA en una estética","encabezados":["Paso","Texto"],"filas":[["Atención","¿Tu tinte se deslava a las dos semanas?"],["Interés","Casi siempre es por lavarlo con agua muy caliente y un champú que no es para cabello teñido."],["Deseo","En tu cita te decimos qué usar en casa para que el color te dure hasta la siguiente visita."],["Acción","Agenda tu tinte por WhatsApp; tenemos lugares el jueves y el viernes."]]},{"tipo":"comparar","titulo":"Beneficio en lugar de característica","malTitulo":"Característica","mal":"«Taladro de 600 W con percusión.»","bienTitulo":"Beneficio","bien":"«Perfora concreto para colgar tus repisas sin llamar a nadie. 600 W con percusión.»"},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"En AIDA, la última letra te recuerda decirle al cliente qué hacer: la ___.","resp":["acción","accion"]},{"frase":"La primera letra de AIDA es captar la ___.","resp":["atención","atencion"]},{"frase":"Hablar de lo que el cliente gana, y no solo de la ficha técnica, es hablar de ___.","resp":["beneficios","beneficio"]}]},{"tipo":"titulo","texto":"Fotos de producto con el celular"},{"tipo":"pasos","rotulo":"Checklist para una buena foto","pasos":["<b>Limpia la lente</b> del celular (en serio: es el error más común).","Usa <b>luz natural</b> de ventana, de lado; evita el flash y la luz amarilla del techo.","<b>Fondo sencillo</b> que no compita: una mesa de madera, una cartulina, una pared lisa.","Toca la pantalla para <b>enfocar</b> el producto y baja un poco la exposición si se ve «lavado».","Toma varias fotos desde distintos ángulos: de frente, desde arriba, detalle.","Fotografía el producto <b>en uso</b>: el taco en la mano, el perfume en el tocador, el cliente sonriendo (con su permiso).","Edita poco: recorta, endereza y ajusta brillo. Que la foto sea fiel: no engañes sobre el tamaño o el color real."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para una foto de perfume, la mejor luz suele ser…","ops":["El flash del celular de frente","Luz natural de ventana, de lado"],"correcta":1},{"p":"«¿Te duele la espalda después de un día en el mostrador?» corresponde a…","ops":["Atención","Acción"],"correcta":0,"explica":"Es la pregunta que detiene a quien tiene ese problema."},{"p":"Editar una foto para que el producto se vea más grande de lo que es…","ops":["Es una técnica normal de marketing","Puede ser publicidad engañosa"],"correcta":1}]},{"tipo":"clave","items":["AIDA: atención, interés, deseo y acción.","Vende beneficios, respáldalos con características.","Lente limpia, luz de ventana, fondo sencillo y fotos fieles al producto."]}]},{"id":"d-marketing-digital-m3-l4","titulo":"Lección 4 — Canva e inteligencia artificial, con criterio","objetivo":"diseñar piezas coherentes con Canva y usar la inteligencia artificial para generar ideas y borradores de forma responsable.","bloques":[{"tipo":"texto","texto":"<b>Canva</b> es una herramienta de diseño en línea con versión gratuita y plantillas para publicaciones, historias, menús y volantes. Al momento de escribir, la versión gratuita permite hacer casi todo lo que necesita un negocio pequeño; algunas funciones (como el kit de marca completo o ciertos elementos) son de pago. Lo importante no es la herramienta, sino ser <b>consistente</b>."},{"tipo":"lista","items":["<b>Kit de marca mínimo:</b> 2 o 3 colores, 1 o 2 tipografías y tu logotipo. Anótalos y úsalos siempre.","<b>Plantillas propias:</b> adapta una plantilla a tu marca y reutilízala; no empieces de cero cada vez.","<b>Legibilidad en celular:</b> letras grandes, poco texto, buen contraste.","<b>Licencias:</b> revisa los términos de uso de los elementos que uses, en especial para logotipos o productos que vas a vender."]},{"tipo":"titulo","texto":"Inteligencia artificial: ayudante, no piloto automático"},{"tipo":"texto","texto":"Herramientas de IA como los asistentes de chat pueden ayudarte a generar <b>ideas de publicaciones, borradores de texto, variaciones de un anuncio o respuestas modelo</b>. Pero pueden inventar datos, sonar genéricos o copiar ideas comunes. Tú decides, revisas y respondes por lo que publicas."},{"tipo":"comparar","titulo":"Uso de IA","malTitulo":"Irresponsable","mal":"Publicar tal cual el texto que te dio la IA con «los mejores precios de México» y «resultados garantizados»; pegarle datos de clientes (nombres, teléfonos, historial dental) para que redacte; generar una foto «de tu producto» que no se parece al real.","bienTitulo":"Responsable","bien":"Pedir 10 ideas de publicaciones para tus pilares, elegir 3 y reescribirlas con tu voz; verificar cada dato, precio o afirmación; no compartir datos personales de clientes; avisar cuando una imagen es ilustrativa y mostrar fotos reales del producto que vendes."},{"tipo":"plantilla","rotulo":"Instrucción (prompt) para pedir ideas a una IA","texto":"Actúa como asesor de marketing para un negocio pequeño en México.\nNegocio: [ferretería de barrio en Monterrey].\nCliente ideal: [personas que hacen reparaciones en casa y maestros de obra de la zona].\nPilares de contenido: [enseñar, producto, detrás de cámaras].\nDame 10 ideas de reels de menos de 30 segundos con gancho, desarrollo y llamado a la acción para pedir por WhatsApp.\nUsa español de México, tono cercano, sin prometer resultados ni inventar precios o datos.","nota":"Nunca incluyas datos personales de clientes en una instrucción. Revisa y adapta todo antes de publicar."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La IA te da un texto que dice «el mejor dentista de Guadalajara». Tú…","ops":["Lo quitas: no lo puedes comprobar","Lo publicas, la IA sabe"],"correcta":0,"explica":"Afirmaciones que no puedes probar pueden ser publicidad engañosa."},{"p":"¿Qué NO debes pegar en una herramienta de IA?","ops":["Una descripción general de tu negocio","Nombres y teléfonos de tus clientes"],"correcta":1},{"p":"Lo más importante de tu diseño en Canva es…","ops":["Ser consistente con colores, letras y logo","Usar una plantilla distinta cada día"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu kit de marca","pregunta":"Anota tus colores (si puedes, su código), tus tipografías y dónde está tu logotipo en buena calidad. Si no los tienes, elige hoy y escríbelos.","ayuda":"Colores… Tipografías… Logo…"},{"tipo":"clave","items":["Canva: kit de marca mínimo y plantillas propias reutilizables.","La IA ayuda con ideas y borradores; tú verificas y respondes por lo que publicas.","Nunca compartas datos personales de clientes con herramientas de IA."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"Los pilares de contenido son…","ops":["Las publicaciones con más likes","Los días en que publicas","Los anuncios pagados","De 3 a 5 temas fijos que conectan a tu cliente con lo que vendes"],"correcta":3},{"p":"Para que te descubra gente nueva, al momento de escribir suele funcionar mejor…","ops":["Un texto largo sin imagen","Una historia de 24 horas","El video vertical corto","Una foto del logotipo"],"correcta":2},{"p":"Un carrusel es especialmente útil para…","ops":["Cobrar","Enseñar paso a paso y que te guarden","Transmitir en vivo","Responder mensajes"],"correcta":1},{"p":"En un video corto, los primeros 3 segundos deben tener…","ops":["Un gancho","Los créditos","El logotipo fijo","El precio en letra pequeña"],"correcta":0},{"p":"AIDA significa…","ops":["Anuncio, imagen, diseño y alcance","Audiencia, interacción, datos y análisis","Alcance, impresiones, destino y audiencia","Atención, interés, deseo y acción"],"correcta":3},{"p":"Para una foto de producto con celular conviene…","ops":["Zoom digital al máximo","Luz amarilla del techo","Luz natural de lado y fondo sencillo","Flash directo y fondo lleno de objetos"],"correcta":2},{"p":"Usar la IA de forma responsable implica…","ops":["Prometer resultados garantizados","Revisar datos y adaptar el texto con tu voz","Publicar sin leer","Compartir datos de clientes"],"correcta":1},{"p":"Un kit de marca mínimo incluye…","ops":["Colores, tipografías y logotipo","Solo el nombre","Todas las plantillas de Canva","La contraseña de tus redes"],"correcta":0}]}},{"id":"d-marketing-digital-m4","titulo":"Módulo 4 — Publicidad pagada sin tirar el dinero","resumen":"Anuncios en Meta (Facebook e Instagram): objetivo, público, presupuesto diario y pruebas A/B; conceptos básicos de Google Ads y una lista de revisión para no desperdiciar presupuesto. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-marketing-digital-m4-l1","titulo":"Lección 1 — Antes de pagar: ¿estás listo para anunciarte?","objetivo":"decidir si tu negocio está listo para invertir en anuncios y elegir el objetivo correcto de campaña.","bloques":[{"tipo":"texto","texto":"Un anuncio lleva gente a tu negocio más rápido, pero <b>no arregla lo que está roto</b>. Si tu WhatsApp tarda un día en contestar, tu perfil no tiene precios o tu producto no convence, el anuncio solo hará que más gente vea el problema. Antes de pagar, revisa que tu «mostrador digital» funcione. Y recuerda: ninguna plataforma ni agencia puede garantizarte ventas."},{"tipo":"pasos","rotulo":"Lista previa a tu primer anuncio","pasos":["Tienes claro <b>a quién</b> le hablas y <b>qué</b> le ofreces (módulo 1).","Tu WhatsApp Business o tu página están listos para <b>recibir y contestar rápido</b> (módulo 2).","Ya publicaste contenido y sabes qué publicaciones <b>funcionan mejor sin pagar</b>: son buenas candidatas para anuncio.","Conoces tu <b>costo máximo por cliente</b> (ticket × margen).","Tienes un <b>presupuesto de prueba</b> que puedes perder sin afectar la operación.","Sabes <b>cómo vas a medir</b> (mensajes, llamadas, ventas) antes de empezar."]},{"tipo":"tabla","titulo":"Objetivos de campaña en Meta (al momento de escribir)","encabezados":["Objetivo","Para qué sirve","Ejemplo"],"filas":[["Reconocimiento","Que mucha gente de una zona vea tu marca","Apertura de una nueva sucursal de la estética"],["Tráfico","Llevar gente a tu página, perfil o WhatsApp","Visitas a la página de la tienda de perfumes"],["Interacción","Mensajes, reacciones, reproducciones de video","«Envía mensaje por WhatsApp» para la taquería"],["Clientes potenciales","Reunir datos de contacto de interesados","Formulario para valoración de ortodoncia"],["Ventas","Compras en línea o conversiones medidas","Tienda en línea con el píxel o la API de conversiones instalados"]],"nota":"Los nombres, la cantidad de objetivos y las opciones dentro de cada uno cambian con frecuencia; revisa lo que muestre tu Administrador de anuncios."},{"tipo":"comparar","titulo":"«Promocionar» vs. Administrador de anuncios","malTitulo":"«Promocionar publicación» desde la app","mal":"Rápido y sencillo, pero con menos control de objetivo, público y medición. Útil para una prueba pequeña.","bienTitulo":"Administrador de anuncios","bien":"Más control: eliges objetivo, público, ubicaciones, presupuesto y puedes hacer pruebas A/B. Vale la pena aprenderlo cuando ya inviertes cada mes."},{"tipo":"relacionar","rotulo":"Relaciona la meta del negocio con el objetivo","pares":[["Que la taquería reciba más pedidos por WhatsApp","Interacción (mensajes)"],["Que la colonia sepa que abriste","Reconocimiento"],["Reunir teléfonos de interesados en ortodoncia","Clientes potenciales"],["Vender perfumes en tu tienda en línea","Ventas"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu WhatsApp tarda 24 horas en responder. Antes de anunciarte…","ops":["Sube el presupuesto para compensar","Arregla la atención: el anuncio solo traería más mensajes sin contestar"],"correcta":1},{"p":"Una buena candidata para convertirse en anuncio es…","ops":["Una publicación que ya funcionó sin pagar","La publicación con menos interacción"],"correcta":0,"explica":"Si ya conectó con tu audiencia orgánica, tiene más probabilidades de funcionar pagada."},{"p":"El objetivo de campaña se elige según…","ops":["El color de tu logotipo","Lo que quieres que haga la persona"],"correcta":1}]},{"tipo":"clave","items":["El anuncio acelera lo que ya funciona; no arregla lo que está roto.","Elige el objetivo según la acción que quieres: mensaje, visita, registro o compra.","Presupuesto de prueba que puedas perder y forma de medir definida antes de empezar."]}]},{"id":"d-marketing-digital-m4-l2","titulo":"Lección 2 — Público, ubicación y presupuesto diario","objetivo":"definir un público local, fijar un presupuesto diario y entender cuánto tiempo dejar correr un anuncio.","bloques":[{"tipo":"texto","texto":"En Meta defines <b>a quién</b> se muestra tu anuncio: zona geográfica, edad, y a veces intereses o públicos similares a tus clientes. Al momento de escribir, Meta empuja cada vez más las opciones automáticas (como los públicos «Advantage+»), donde su sistema busca a quién mostrar el anuncio a partir de tus indicaciones. Para un negocio local, lo más importante casi siempre es <b>la ubicación</b>."},{"tipo":"tabla","titulo":"Público según el negocio","encabezados":["Negocio","Ubicación","Otros criterios"],"filas":[["Taquería con entrega a domicilio","Radio de 2 a 3 km alrededor del local","Mayores de 18; horario de anuncios en la tarde-noche si la herramienta lo permite"],["Estética","Radio de 3 a 5 km","Ajusta edad según tus clientas reales"],["Consultorio dental","Colonias o municipio donde viven o trabajan tus pacientes","Evita segmentar por condiciones de salud: las plataformas lo restringen y es un dato sensible"],["Perfumes con envío nacional","Todo México o ciudades donde vendes más","Intereses relacionados con perfumería o regalos"]]},{"tipo":"destacado","texto":"<b>Público muy pequeño o muy grande.</b> Si el público es diminuto, el anuncio se repite a las mismas personas y se encarece. Si es enorme para un negocio de barrio, pagas por gente que nunca llegará. Empieza con la zona realista a la que atiendes."},{"tipo":"titulo","texto":"Presupuesto diario y tiempo de prueba"},{"tipo":"texto","texto":"Una forma sencilla de arrancar: un <b>presupuesto diario pequeño</b> (lo que puedas sostener, por ejemplo entre $70 y $150 en un negocio local) durante <b>7 días sin tocar el anuncio</b>. Cambiar todo cada día impide que el sistema aprenda y que tú sepas qué funcionó. Después comparas contra tu costo máximo por cliente."},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Si inviertes $100 diarios durante 7 días, gastas en total $___.","resp":["700","700.00","$700"]},{"frase":"Para un negocio de barrio, el criterio más importante del público suele ser la ___.","resp":["ubicación","ubicacion","zona"]},{"frase":"Conviene dejar correr un anuncio unos ___ días antes de juzgarlo.","resp":["7","siete"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Segmentar anuncios de un consultorio por «personas con enfermedad de encías»…","ops":["No es posible o está restringido y toca datos sensibles","Es la mejor práctica"],"correcta":0},{"p":"Cambias público, imagen y texto cada día. El problema es que…","ops":["Gastas menos","No sabes qué cambio funcionó y el sistema no aprende"],"correcta":1,"explica":"Cambia una cosa a la vez y dale tiempo."}]},{"tipo":"clave","items":["Para negocio local, la ubicación manda.","Presupuesto diario sostenible y al menos una semana sin mover el anuncio.","Nada de segmentar por salud u otros datos sensibles."]}]},{"id":"d-marketing-digital-m4-l3","titulo":"Lección 3 — Creatividades y pruebas A/B","objetivo":"diseñar anuncios con gancho y comparar dos versiones cambiando una sola variable.","bloques":[{"tipo":"texto","texto":"La <b>creatividad</b> es la imagen o video y el texto del anuncio. Hoy es de lo que más influye en el resultado. Una <b>prueba A/B</b> compara dos versiones que son <b>iguales en todo menos en una cosa</b> (la imagen, el gancho o la oferta) para saber cuál funciona mejor. Al momento de escribir, el Administrador de anuncios de Meta tiene una función para pruebas A/B; también puedes hacerla a mano con dos anuncios en el mismo conjunto."},{"tipo":"tabla","titulo":"Qué probar (una cosa a la vez)","encabezados":["Variable","Versión A","Versión B"],"filas":[["Formato","Foto del platillo","Video de 10 segundos del taquero"],["Gancho","«Tacos de suadero en la Narvarte»","«¿Ya probaste el suadero de 4 horas?»"],["Oferta","Envío gratis","Orden de 5 tacos + refresco $95"],["Llamado a la acción","«Pide por WhatsApp»","«Ver menú»"]]},{"tipo":"excel","rotulo":"Prueba A/B de la tienda de perfumes (7 días, mismo presupuesto)","datos":[["Versión","Impresiones","Clics","Mensajes","CTR","Mensajes por clic"],["A: foto de frasco",9000,90,9,"",""],["B: video aplicando perfume",8500,170,12,"",""],["Ganadora por mensajes","","","","",""]],"retos":[{"celda":"E2","formula":"=C2/B2","esperado":0.01,"texto":"<b>E2</b>: CTR (tasa de clics) de A: clics entre impresiones.","pista":"=C2/B2 → 1%."},{"celda":"E3","formula":"=C3/B3","esperado":0.02,"texto":"<b>E3</b>: CTR de B."},{"celda":"F2","formula":"=D2/C2","esperado":0.1,"texto":"<b>F2</b>: de los clics de A, ¿qué parte terminó en mensaje?"},{"celda":"F3","formula":"=REDONDEAR(D3/C3,3)","esperado":0.071,"requiere":"REDONDEAR(","texto":"<b>F3</b>: lo mismo para B, redondeado a 3 decimales."},{"celda":"B4","formula":"=SI(D2>D3,\"A\",\"B\")","esperado":"B","requiere":"SI(","texto":"<b>B4</b>: con SI, escribe «A» si A generó más mensajes que B; si no, «B».","explica":"B atrae el doble de clics y más mensajes, aunque convierte un menor porcentaje de sus clics. Decide por el resultado que te importa (mensajes o ventas), no solo por el CTR. Con números tan pequeños, repite la prueba antes de sacar conclusiones definitivas."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En una prueba A/B bien hecha…","ops":["Solo cambia una variable entre versiones","Cambias imagen, texto y público a la vez"],"correcta":0},{"p":"Un anuncio tiene mejor CTR pero trae menos mensajes. ¿Cuál gana si tu objetivo son mensajes?","ops":["El de mejor CTR","El que trae más mensajes"],"correcta":1,"explica":"El CTR es una señal intermedia; el resultado es lo que pagas por conseguir."}]},{"tipo":"clave","items":["La creatividad (imagen, video, texto) es de lo que más pesa.","Prueba A/B: iguales en todo menos una variable.","Decide por el resultado que importa, no por métricas intermedias."]}]},{"id":"d-marketing-digital-m4-l4","titulo":"Lección 4 — Google Ads básico y cómo no tirar el dinero","objetivo":"entender la lógica de los anuncios de búsqueda en Google y aplicar una lista de revisión para cuidar tu presupuesto.","bloques":[{"tipo":"texto","texto":"En redes sociales interrumpes a la gente mientras se entretiene. En <b>Google</b>, la persona <b>ya está buscando</b> algo: «ferretería abierta domingo», «limpieza dental precio». Por eso los anuncios de búsqueda pueden traer clientes con mucha intención de compra. Al momento de escribir, Google Ads también ofrece campañas automatizadas (como Performance Max) que reparten tu anuncio en varios espacios; para empezar, las campañas de búsqueda son más fáciles de entender y controlar."},{"tipo":"tabla","titulo":"Conceptos básicos de Google Ads","encabezados":["Concepto","Qué es","Ejemplo"],"filas":[["Palabra clave","Lo que la gente escribe y para lo que quieres aparecer","«dentista en zapopan»"],["Concordancia","Qué tan parecido debe ser lo buscado a tu palabra clave (amplia, de frase, exacta)","Exacta: solo búsquedas con el mismo significado"],["Palabra clave negativa","Búsquedas en las que NO quieres aparecer","«gratis», «empleo», «curso»"],["Pago por clic","Normalmente pagas cuando alguien da clic, no cuando ve el anuncio","CPC de $8"],["Extensiones o recursos","Datos extra: llamada, ubicación, enlaces","Botón de llamar al consultorio"]],"nota":"Los nombres de las opciones cambian; revisa la ayuda oficial de Google Ads antes de configurar."},{"tipo":"relacionar","rotulo":"¿Palabra clave o palabra negativa? (ferretería)","pares":[["«ferretería cerca de mí»","Palabra clave: quiere comprar"],["«empleo en ferretería»","Negativa: busca trabajo"],["«cómo hacer una ferretería en minecraft»","Negativa: no es cliente"],["«impermeabilizante precio monterrey»","Palabra clave: intención de compra"]]},{"tipo":"pasos","rotulo":"Lista para no tirar el dinero","pasos":["Define <b>qué es un resultado</b> (mensaje, llamada, cita, venta) y mídelo desde el día uno.","Fija un <b>tope diario</b> y revisa el cobro en tu estado de cuenta cada semana.","Compara el <b>costo por resultado</b> contra tu costo máximo por cliente.","Agrega <b>palabras negativas</b> en Google y excluye zonas donde no das servicio.","Cambia <b>una sola cosa</b> a la vez y deja correr al menos una semana.","<b>Pausa</b> lo que no funciona y mueve el dinero a lo que sí (lo practicas en el módulo 5).","Desconfía de quien te <b>garantice</b> ventas o «primer lugar en Google»: nadie controla eso."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La ventaja principal de un anuncio de búsqueda en Google es que…","ops":["Siempre sale primero","La persona ya está buscando lo que vendes","Es gratis"],"correcta":1},{"p":"Tu anuncio de dentista aparece cuando buscan «dentista gratis». Conviene…","ops":["Subir el presupuesto","Agregar «gratis» como palabra negativa"],"correcta":1},{"p":"Una agencia te garantiza el primer lugar en Google y 100 clientes al mes…","ops":["Desconfía: nadie puede garantizar eso","Es una oferta segura"],"correcta":0}]},{"tipo":"clave","items":["En Google la gente ya está buscando: la intención es alta.","Palabras clave con intención de compra y palabras negativas para filtrar.","Tope diario, una variable a la vez y comparar contra tu costo máximo por cliente."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"Antes de anunciarte conviene…","ops":["Gastar lo más posible desde el primer día","Borrar tus publicaciones","Cambiar de nombre","Asegurarte de poder atender y contestar rápido"],"correcta":3},{"p":"Para recibir más pedidos por WhatsApp, el objetivo de Meta más adecuado suele ser…","ops":["Promoción de la app","Alcance máximo sin mensajes","Interacción (mensajes)","Reconocimiento"],"correcta":2},{"p":"Para una taquería con entrega a domicilio, el criterio de público más importante es…","ops":["La edad exacta","La ubicación cercana al local","Los intereses en viajes","Todo el país"],"correcta":1},{"p":"En una prueba A/B…","ops":["Solo cambia una variable","Todo cambia a la vez","Se usa un solo anuncio","No se mide nada"],"correcta":0},{"p":"El CTR se calcula como…","ops":["Gasto entre clics","Ventas entre gasto","Impresiones entre clics","Clics entre impresiones"],"correcta":3},{"p":"En Google Ads, una palabra clave negativa sirve para…","ops":["Pagar menos impuestos","Aparecer en más búsquedas","Evitar aparecer en búsquedas que no te convienen","Hablar mal de la competencia"],"correcta":2},{"p":"Normalmente, en los anuncios de búsqueda de Google pagas…","ops":["Solo si vendes","Por clic","Por cada persona que pasa por tu calle","Una cuota fija anual"],"correcta":1},{"p":"Una agencia te garantiza ventas seguras con anuncios. Lo correcto es…","ops":["Desconfiar: nadie puede garantizarlo","Firmar de inmediato","Pagar por adelantado un año","Cancelar tu perfil de Google"],"correcta":0}]}},{"id":"d-marketing-digital-m5","titulo":"Módulo 5 — Medir, decidir y cuidar lo legal","resumen":"Métricas que sí importan (alcance, interacción, CTR, CPC, costo por cliente, conversión y ROAS), un tablero en hoja de cálculo, tu plan de 90 días y los aspectos legales básicos: datos personales, publicidad veraz y derechos de autor. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-marketing-digital-m5-l1","titulo":"Lección 1 — Las métricas que sí importan","objetivo":"distinguir métricas de vanidad de métricas de negocio y calcular CTR, CPC, costo por cliente y tasa de conversión.","bloques":[{"tipo":"texto","texto":"Las plataformas te dan decenas de números. Muchos son <b>métricas de vanidad</b>: se ven bonitas pero no pagan la renta (seguidores, likes). Las <b>métricas de negocio</b> te dicen cuánto te cuesta conseguir un cliente y cuánto te deja. Aprende a calcularlas tú mismo en una hoja de cálculo: así no dependes de cómo cada plataforma las nombra o las presenta."},{"tipo":"tabla","titulo":"Glosario de métricas","encabezados":["Métrica","Qué mide","Fórmula"],"filas":[["Alcance","Personas distintas que vieron tu contenido","Lo reporta la plataforma"],["Impresiones","Veces que se mostró (una persona puede verlo varias veces)","Lo reporta la plataforma"],["Interacción","Reacciones, comentarios, compartidos, guardados","Interacciones ÷ alcance"],["CTR","Qué parte de quienes vieron el anuncio dio clic","Clics ÷ impresiones"],["CPC","Cuánto pagas por cada clic","Gasto ÷ clics"],["CPA o costo por cliente","Cuánto pagas por cada venta, cita o cliente","Gasto ÷ resultados"],["Tasa de conversión","Qué parte de los clics termina en venta","Ventas ÷ clics"],["ROAS","Pesos vendidos por cada peso de anuncio","Ventas en $ ÷ gasto"]]},{"tipo":"excel","rotulo":"Anuncios de la tienda de perfumes artesanales (un mes)","datos":[["Anuncio","Impresiones","Clics","Gasto","Ventas","CTR","CPC","CPA","Conversión"],["Video aroma vainilla",18000,270,900,9,"","","",""],["Carrusel 3 fragancias",15000,150,750,6,"","","",""],["Foto de estudio",20000,120,800,2,"","","",""],["Reseña de clienta",12000,240,600,8,"","","",""],["CPA más bajo","","","","","","","",""]],"retos":[{"celda":"F2","formula":"=C2/B2","esperado":0.015,"texto":"<b>F2</b>: CTR del video: clics entre impresiones.","pista":"=C2/B2 → 1.5%."},{"celda":"G2","formula":"=REDONDEAR(D2/C2,2)","esperado":3.33,"requiere":"REDONDEAR(","texto":"<b>G2</b>: CPC del video (gasto entre clics), redondeado a 2 decimales."},{"celda":"H2","formula":"=D2/E2","esperado":100,"texto":"<b>H2</b>: CPA, costo por venta del video: gasto entre ventas."},{"celda":"I2","formula":"=E2/C2","esperado":0.0333333333,"texto":"<b>I2</b>: tasa de conversión del video: ventas entre clics."},{"celda":"H3","formula":"=D3/E3","esperado":125,"texto":"<b>H3</b>: CPA del carrusel."},{"celda":"F4","formula":"=C4/B4","esperado":0.006,"texto":"<b>F4</b>: CTR de la foto de estudio."},{"celda":"H4","formula":"=D4/E4","esperado":400,"texto":"<b>H4</b>: CPA de la foto de estudio.","explica":"$400 por venta. Si el perfume deja, digamos, $180 de margen, cada venta de este anuncio cuesta más de lo que deja."},{"celda":"H5","formula":"=D5/E5","esperado":75,"texto":"<b>H5</b>: CPA de la reseña de clienta."},{"celda":"B6","formula":"=MIN(H2:H5)","esperado":75,"requiere":"MIN(","texto":"<b>B6</b>: ¿cuál es el CPA más bajo? Usa MIN sobre la columna H.","explica":"La reseña de una clienta real es el anuncio más barato por venta: la prueba social funciona. Con pocos datos, confírmalo repitiendo la prueba."}]},{"tipo":"relacionar","rotulo":"¿Vanidad o negocio?","pares":[["Número de seguidores","Vanidad: no dice si vendes"],["Costo por cliente nuevo","Negocio: cuánto pagas por vender"],["Mensajes que terminan en cita","Negocio: conversión real"],["Likes de una publicación","Vanidad: interés sin compromiso"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Gastaste $600 y conseguiste 8 ventas. Tu CPA es…","ops":["$4,800","$75"],"correcta":1,"explica":"Gasto ÷ resultados = 600 ÷ 8."},{"p":"Un anuncio con CTR alto pero sin ventas…","ops":["Atrae clics pero algo falla después: página, precio o atención","Es el mejor anuncio"],"correcta":0,"explica":"Revisa qué pasa después del clic."}]},{"tipo":"clave","items":["Mide lo que paga la renta: costo por cliente, conversión y ventas.","CTR = clics ÷ impresiones; CPC = gasto ÷ clics; CPA = gasto ÷ resultados.","Calcula tú las métricas en una hoja: no dependas de cómo las presenta cada plataforma."]}]},{"id":"d-marketing-digital-m5-l2","titulo":"Lección 2 — ROAS y la decisión de pausar","objetivo":"calcular el ROAS, compararlo con tu ROAS de equilibrio y decidir con SI qué anuncio mantener o pausar.","bloques":[{"tipo":"texto","texto":"El <b>ROAS</b> (retorno sobre la inversión publicitaria) dice cuántos pesos vendiste por cada peso de anuncio. Un ROAS de 4 significa que por cada $1 vendiste $4. Pero <b>vender no es ganar</b>: si tu margen es de 30%, de esos $4 solo te quedan $1.20 para pagar el anuncio. Tu <b>ROAS de equilibrio</b> es 1 ÷ margen: por debajo de ese número, el anuncio te hace perder dinero."},{"tipo":"excel","rotulo":"Anuncios de la Ferretería La Tuerca (un mes)","datos":[["Anuncio","Gasto","Ventas atribuidas","ROAS","Utilidad tras anuncio","Decisión","","Margen bruto",0.3],["Promo pintura",1200,6000,"","","","","ROAS de equilibrio",""],["Herramienta eléctrica",1500,2400,"","",""],["Kit de plomería",800,3200,"","",""],["Impermeabilizante temporada de lluvias",2000,11000,"","",""]],"retos":[{"celda":"I2","formula":"=REDONDEAR(1/I1,2)","esperado":3.33,"requiere":"REDONDEAR(","texto":"<b>I2</b>: ROAS de equilibrio: 1 entre el margen (I1), redondeado a 2 decimales.","explica":"Con 30% de margen necesitas vender al menos $3.33 por cada $1 de anuncio para no perder."},{"celda":"D2","formula":"=C2/B2","esperado":5,"texto":"<b>D2</b>: ROAS de la promo de pintura: ventas entre gasto."},{"celda":"D3","formula":"=C3/B3","esperado":1.6,"texto":"<b>D3</b>: ROAS de la herramienta eléctrica."},{"celda":"E3","formula":"=C3*$I$1-B3","esperado":-780,"texto":"<b>E3</b>: utilidad tras el anuncio: ventas × margen (fijo en $I$1) menos el gasto.","pista":"=C3*$I$1-B3"},{"celda":"F3","formula":"=SI(D3<$I$2,\"Pausar\",\"Mantener\")","esperado":"Pausar","requiere":"SI(","texto":"<b>F3</b>: con SI, escribe «Pausar» si el ROAS es menor que el de equilibrio ($I$2) y «Mantener» si no."},{"celda":"D4","formula":"=C4/B4","esperado":4,"texto":"<b>D4</b>: ROAS del kit de plomería."},{"celda":"F4","formula":"=SI(D4<$I$2,\"Pausar\",\"Mantener\")","esperado":"Mantener","requiere":"SI(","texto":"<b>F4</b>: aplica la misma regla al kit de plomería."},{"celda":"D5","formula":"=C5/B5","esperado":5.5,"texto":"<b>D5</b>: ROAS del impermeabilizante."},{"celda":"E5","formula":"=C5*$I$1-B5","esperado":1300,"texto":"<b>E5</b>: utilidad tras el anuncio del impermeabilizante."},{"celda":"F5","formula":"=SI(Y(D5>=$I$2,E5>0),\"Mantener\",\"Pausar\")","esperado":"Mantener","requiere":"Y(","texto":"<b>F5</b>: regla más estricta: «Mantener» solo si el ROAS es mayor o igual al de equilibrio <b>y</b> la utilidad es positiva. Usa SI con Y.","pista":"=SI(Y(condición1,condición2),\"Mantener\",\"Pausar\")"}]},{"tipo":"destacado","texto":"<b>Antes de pausar, piensa.</b> Algunos productos atraen clientes que después compran otras cosas o regresan. Si la herramienta eléctrica trae maestros de obra que luego compran cada semana, un ROAS bajo podría valer la pena. La hoja te da la regla; tú aportas el conocimiento de tu negocio. Y recuerda que las «ventas atribuidas» que reportan las plataformas son estimaciones: compáralas con tus ventas reales."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu margen es de 25%. Tu ROAS de equilibrio es…","ops":["25","4"],"correcta":1,"explica":"1 ÷ 0.25 = 4."},{"p":"Un anuncio tiene ROAS de 2 y tu equilibrio es 3.33. Si no hay otra razón de peso…","ops":["Lo pausas o lo mejoras","Le subes el presupuesto"],"correcta":0},{"p":"Un ROAS alto siempre significa ganancia…","ops":["Verdadero","Falso: depende del margen"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"ROAS = ventas en pesos ÷ ___ en anuncios.","resp":["gasto","inversión","inversion"]}]},{"tipo":"clave","items":["ROAS = ventas ÷ gasto; ROAS de equilibrio = 1 ÷ margen.","Con SI (y Y) conviertes la regla en una decisión automática.","Revisa el contexto: clientes que regresan y ventas reales vs. atribuidas."]}]},{"id":"d-marketing-digital-m5-l3","titulo":"Lección 3 — Tu tablero y tu plan de 90 días","objetivo":"armar un tablero por canal con SUMAR.SI y BUSCARV y convertir lo aprendido en un plan de 90 días.","bloques":[{"tipo":"texto","texto":"Un <b>tablero</b> es una hoja donde, cada semana, anotas lo que gastaste y los clientes que llegaron por cada canal. Con dos o tres fórmulas sabes qué canal te cuesta menos por cliente. Pregunta siempre a cada cliente nuevo «¿cómo nos conociste?» y anótalo: sin ese dato, el tablero no sirve."},{"tipo":"excel","rotulo":"Tablero del consultorio dental (3 semanas)","datos":[["Semana","Canal","Gasto","Clientes nuevos","","Canal","Gasto total","Clientes","Costo por cliente"],[1,"Meta",1200,6,"","Meta","","",""],[1,"Google Ads",900,5,"","Google Ads","","",""],[1,"Maps (gratis)",0,4,"","Maps (gratis)","","",""],[2,"Meta",1100,4,"","Total","","",""],[2,"Google Ads",1000,6,"","","","",""],[2,"Maps (gratis)",0,5,"","Consulta:","Google Ads","",""],[3,"Meta",1300,7,"","","","",""],[3,"Google Ads",800,3,"","","","",""],[3,"Maps (gratis)",0,3,"","","","",""]],"retos":[{"celda":"G2","formula":"=SUMAR.SI($B$2:$B$10,F2,$C$2:$C$10)","esperado":3600,"requiere":"SUMAR.SI(","texto":"<b>G2</b>: gasto total de Meta con SUMAR.SI: busca en la columna de canal el valor de F2 y suma la columna de gasto.","pista":"=SUMAR.SI(rango de canales, F2, rango de gasto). Fija los rangos con $."},{"celda":"H2","formula":"=SUMAR.SI($B$2:$B$10,F2,$D$2:$D$10)","esperado":17,"requiere":"SUMAR.SI(","texto":"<b>H2</b>: clientes nuevos que llegaron por Meta."},{"celda":"I2","formula":"=REDONDEAR(G2/H2,2)","esperado":211.76,"requiere":"REDONDEAR(","texto":"<b>I2</b>: costo por cliente de Meta, redondeado a 2 decimales."},{"celda":"G3","formula":"=SUMAR.SI($B$2:$B$10,F3,$C$2:$C$10)","esperado":2700,"requiere":"SUMAR.SI(","texto":"<b>G3</b>: gasto total de Google Ads."},{"celda":"H3","formula":"=SUMAR.SI($B$2:$B$10,F3,$D$2:$D$10)","esperado":14,"requiere":"SUMAR.SI(","texto":"<b>H3</b>: clientes de Google Ads."},{"celda":"I3","formula":"=REDONDEAR(G3/H3,2)","esperado":192.86,"requiere":"REDONDEAR(","texto":"<b>I3</b>: costo por cliente de Google Ads."},{"celda":"H4","formula":"=SUMAR.SI($B$2:$B$10,F4,$D$2:$D$10)","esperado":12,"requiere":"SUMAR.SI(","texto":"<b>H4</b>: clientes que llegaron por el perfil gratuito en Maps.","explica":"12 de 43 pacientes nuevos llegaron sin pagar anuncios: cuidar tu perfil y tus reseñas rinde."},{"celda":"H5","formula":"=SUMA(H2:H4)","esperado":43,"requiere":"SUMA(","texto":"<b>H5</b>: total de clientes nuevos."},{"celda":"H7","formula":"=BUSCARV(G7,$F$2:$I$4,4,FALSO)","esperado":192.86,"requiere":"BUSCARV(","texto":"<b>H7</b>: con BUSCARV, trae el costo por cliente del canal escrito en G7 (columna 4 de la tabla F2:I4, coincidencia exacta).","pista":"=BUSCARV(G7,$F$2:$I$4,4,FALSO)","explica":"Cambia G7 por «Meta» y la fórmula te da su costo sin buscar a mano. Así funciona un tablero."}]},{"tipo":"titulo","texto":"Plan de 90 días"},{"tipo":"plantilla","rotulo":"Plan de 90 días de marketing","texto":"PLAN DE 90 DÍAS — [Negocio] — del [fecha] al [fecha]\n\nObjetivo SMART: [ej. pasar de 30 a 45 pacientes nuevos al mes a más tardar el 31 de diciembre]\nCliente ideal: [resumen]\nPropuesta de valor: [una frase]\nPresupuesto mensual: $[ ] (anuncios $[ ], herramientas $[ ], contenido $[ ])\nCosto máximo por cliente: $[ ]\n\nDÍAS 1-30 | Bases\n- Perfil de Google completo y verificado; pedir reseñas a cada cliente satisfecho.\n- WhatsApp Business con catálogo, bienvenida, ausencia, respuestas rápidas y etiquetas.\n- Pilares de contenido y calendario: 3 publicaciones por semana.\n- Aviso de privacidad publicado.\n\nDÍAS 31-60 | Probar\n- Primer anuncio con presupuesto de prueba, 7 días sin tocarlo.\n- Prueba A/B de una variable.\n- Tablero semanal por canal (preguntar a cada cliente cómo nos conoció).\n\nDÍAS 61-90 | Ajustar\n- Pausar lo que esté por debajo del equilibrio; subir poco a poco lo que funciona.\n- Repetir los contenidos que más mensajes trajeron.\n- Revisión final: ¿se cumplió el objetivo? ¿qué sigue?\n\nRevisión semanal: [día y hora]   Responsable: [nombre]"},{"tipo":"ordenar","rotulo":"Ordena las tres etapas del plan","items":[{"frase":"Bases luego probar y al final ajustar","es":"Primero que todo funcione y después invertir"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para sumar el gasto de un solo canal usas…","ops":["SUMAR.SI","CONTARA"],"correcta":0,"explica":"Suma solo las filas que cumplen el criterio."},{"p":"Sin preguntar «¿cómo nos conociste?», el tablero…","ops":["Funciona igual","No puede atribuir clientes a cada canal"],"correcta":1}]},{"tipo":"clave","items":["SUMAR.SI por canal + costo por cliente = qué canal rinde más.","BUSCARV convierte la tabla en un tablero consultable.","Plan de 90 días: bases, probar y ajustar, con revisión semanal."]}]},{"id":"d-marketing-digital-m5-l4","titulo":"Lección 4 — Lo legal: datos personales, publicidad veraz y derechos de autor","objetivo":"identificar las obligaciones básicas de un negocio que hace marketing digital en México.","bloques":[{"tipo":"texto","texto":"Hacer marketing también implica reglas. Esta lección es <b>orientativa</b>: resume principios generales y <b>no sustituye la asesoría de un abogado</b> ni la lectura de las leyes vigentes, que cambian. Tres temas que todo negocio debe cuidar: <b>datos personales</b>, <b>publicidad veraz</b> y <b>derechos de autor e imagen</b>."},{"tipo":"tabla","titulo":"Tres marcos que debes conocer","encabezados":["Tema","Ley o autoridad","Lo básico"],"filas":[["Datos personales","Ley Federal de Protección de Datos Personales en Posesión de los Particulares (LFPDPPP). En marzo de 2025 se publicó una nueva ley que sustituyó a la de 2010; verifica qué autoridad la vigila hoy","Si recabas nombres, teléfonos, correos o datos de salud, debes informar con un aviso de privacidad para qué los usas y cómo ejercer los derechos ARCO"],["Publicidad veraz","Ley Federal de Protección al Consumidor; la vigila la PROFECO","La información y la publicidad deben ser veraces y comprobables, sin engañar sobre precio, características o condiciones de las promociones"],["Derechos de autor e imagen","Ley Federal del Derecho de Autor; INDAUTOR","Fotos, música, videos y textos tienen dueño. Usa material propio, con licencia o con permiso; pide permiso para usar la imagen de clientes"]],"nota":"Al momento de escribir. Consulta los textos vigentes en el sitio de la Cámara de Diputados o en el DOF."},{"tipo":"lista","items":["<b>Aviso de privacidad:</b> quién eres y tu domicilio, qué datos recabas, para qué los usas, con quién los compartes, cómo ejercer los derechos de Acceso, Rectificación, Cancelación y Oposición (ARCO) y cómo avisarás de cambios. Ponlo en tu página y ten una versión corta para WhatsApp o formularios.","<b>Datos sensibles</b> (salud, por ejemplo en un consultorio dental): requieren consentimiento expreso y cuidado especial. Nunca los publiques ni los pegues en herramientas externas.","<b>Mensajes de WhatsApp masivos</b>: envía promociones solo a quienes aceptaron recibirlas y respeta a quien pide que ya no le escribas."]},{"tipo":"comparar","titulo":"Publicidad","malTitulo":"Engañosa","mal":"«Blanqueamiento dental desde $99»* (*solo la valoración, el tratamiento cuesta $3,500). «Perfume 100% natural» cuando lleva fijadores sintéticos. «¡Último día de promoción!» todas las semanas. Foto de un platillo que no es el que sirves.","bienTitulo":"Veraz","bien":"Precio total visible con impuestos y qué incluye. Características que puedes comprobar. Promociones con vigencia y condiciones claras. Fotos reales del producto o aviso claro cuando la imagen es ilustrativa."},{"tipo":"relacionar","rotulo":"Relaciona la situación con el tema legal","pares":[["Usas una canción comercial famosa en un reel de tu negocio sin licencia","Derechos de autor"],["Tu formulario pide nombre y teléfono pero no tienes aviso de privacidad","Datos personales"],["Anuncias «envío gratis» y cobras el envío al final","Publicidad veraz"],["Publicas la foto de una clienta sin preguntarle","Derecho a la propia imagen"]]},{"tipo":"plantilla","rotulo":"Aviso de privacidad simplificado (borrador de ejemplo)","texto":"AVISO DE PRIVACIDAD SIMPLIFICADO\n\n[Nombre del negocio o persona responsable], con domicilio en [domicilio], es responsable del uso de tus datos personales.\n\n¿Para qué usamos tus datos? Para agendar tus citas, enviarte confirmaciones y atender tus pedidos. De forma adicional, y solo si lo aceptas, para enviarte promociones. Si no quieres recibirlas, escríbenos a [medio de contacto].\n\n¿Con quién los compartimos? [Con nadie / con la paquetería para entregar tu pedido].\n\nPuedes consultar el aviso de privacidad integral y cómo ejercer tus derechos de acceso, rectificación, cancelación y oposición en [liga o lugar].","nota":"Borrador didáctico. El contenido exacto del aviso depende de la ley vigente y de los datos que recabes; valídalo con un especialista, en especial si manejas datos de salud."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tomar una foto de Google Imágenes para tu publicidad…","ops":["Puede violar derechos de autor: usa fotos propias o con licencia","Está permitido porque está en internet"],"correcta":0},{"p":"Un consultorio dental que guarda historiales clínicos maneja…","ops":["Solo datos públicos","Datos personales sensibles"],"correcta":1,"explica":"Requieren consentimiento expreso y cuidado especial."},{"p":"Anunciar un precio que no incluye cargos obligatorios…","ops":["Puede ser publicidad engañosa","Es una práctica normal sin riesgo"],"correcta":0}]},{"tipo":"clave","items":["Si recabas datos personales, necesitas aviso de privacidad; los de salud son sensibles.","Publicidad veraz: precio total, características comprobables y promociones con condiciones claras.","Fotos, música e imagen de personas: propias, con licencia o con permiso."]}]}],"quiz":{"titulo":"Evaluación del módulo 5","preguntas":[{"p":"El CPA o costo por cliente se calcula como…","ops":["Clics ÷ impresiones","Ventas ÷ gasto","Gasto ÷ clics","Gasto ÷ resultados"],"correcta":3},{"p":"Una métrica de vanidad es…","ops":["La tasa de conversión","El ROAS","El número de seguidores","El costo por cliente"],"correcta":2},{"p":"Vendiste $6,000 con $1,200 de anuncios. Tu ROAS es…","ops":["4,800","5","0.2","7,200"],"correcta":1},{"p":"Con un margen de 30%, el ROAS de equilibrio es aproximadamente…","ops":["3.33","0.30","30","1.3"],"correcta":0},{"p":"Para sumar el gasto solo del canal «Meta» usas…","ops":["CONTAR","MAX","LARGO","SUMAR.SI"],"correcta":3},{"p":"=SI(D3<$I$2,\"Pausar\",\"Mantener\") sirve para…","ops":["Contar clics","Redondear el gasto","Pausar anuncios con ROAS debajo del equilibrio","Sumar ventas"],"correcta":2},{"p":"Si tu negocio recaba nombres y teléfonos de clientes, necesitas…","ops":["Una patente","Un aviso de privacidad","Nada, son datos públicos","Un registro ante el SAT"],"correcta":1},{"p":"Usar una canción comercial sin licencia en tus anuncios…","ops":["Puede violar derechos de autor","Es legal si el video dura menos de 30 segundos","Está permitido a negocios pequeños","Es obligatorio"],"correcta":0}]}}]});
window.CURSOS_MARA.push({"id":"d-contabilidad-resico","nombre":"Diplomado en Contabilidad Básica, RESICO y Facturación CFDI 4.0","color":"#1D4ED8","nivel":"Diplomados","familia":"Negocios y finanzas","periodoTipo":null,"periodoNum":null,"desc":"Aprende a llevar las cuentas de tu negocio, leer tus números en hoja de cálculo, calcular tu ISR en el RESICO y tu IVA, y facturar bien en CFDI 4.0. Es práctico y para personas físicas con negocios pequeños; no sustituye la asesoría de un contador público.","horas":32,"precio":1890,"publicado":true,"proximamente":false,"modulos":[{"id":"d-contabilidad-resico-m1","titulo":"Módulo 1 — Contabilidad básica para tu negocio","resumen":"Qué tienes, qué debes y qué es tuyo; ingresos, costos y gastos; la partida doble explicada sin enredos; catálogo de cuentas y flujo de efectivo. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-contabilidad-resico-m1-l1","titulo":"Lección 1 — Para qué sirve la contabilidad (y la ecuación que lo ordena todo)","objetivo":"entender qué es la contabilidad, para qué le sirve a un negocio pequeño y cómo se relacionan activo, pasivo y capital.","bloques":[{"tipo":"destacado","texto":"<b>Antes de empezar.</b> Este es un <b>diplomado libre</b> con constancia de Instituto Mara: no tiene validez oficial de la SEP ni es una certificación de CONOCER. Te enseña a entender y ordenar tus números y tus obligaciones, pero <b>no sustituye la asesoría de un contador público</b>. Las reglas fiscales cambian cada año (sobre todo con la <b>Resolución Miscelánea Fiscal</b>), así que antes de pagar o presentar algo, confirma el dato vigente en sat.gob.mx o con tu contador."},{"tipo":"texto","texto":"La <b>contabilidad</b> es anotar, ordenar y resumir todo lo que entra y sale de tu negocio para saber <b>cómo vas</b>. No es solo «cosa del SAT»: te dice si ganas o pierdes, cuánto puedes retirar para tu casa, cuánto le debes al proveedor y si te alcanza para surtir la próxima semana.<br><br>Piensa en doña Lupe, que tiene una tiendita de abarrotes. Si no anota nada, solo sabe cuánto hay en el cajón hoy. Si anota, sabe cuánto vendió en el mes, cuánto le costó la mercancía y cuánto le quedó de verdad."},{"tipo":"tabla","titulo":"Las tres palabras base","encabezados":["Concepto","Qué es","Ejemplo en la tiendita"],"filas":[["<b>Activo</b>","Lo que el negocio <b>tiene</b> o le deben","Efectivo en caja, dinero en el banco, mercancía en anaqueles, refrigerador, lo que te deben clientes de confianza (fiado)"],["<b>Pasivo</b>","Lo que el negocio <b>debe</b> a otros","Mercancía que te dio a crédito el proveedor, préstamo de la caja popular, impuestos por pagar"],["<b>Capital</b>","Lo que <b>es tuyo</b> de verdad: lo que pusiste más lo que has ganado y dejado en el negocio","Los $30,000 con que empezaste más las ganancias que no has retirado"]],"nota":"La ecuación contable: <b>Activo = Pasivo + Capital</b>. O dicho al revés: Capital = Activo − Pasivo."},{"tipo":"texto","texto":"¿Por qué siempre cuadra? Porque todo lo que tiene tu negocio salió de algún lado: o te lo prestaron (pasivo) o lo pusiste tú y lo fuiste ganando (capital). Si doña Lupe tiene $80,000 en activos y debe $25,000, su capital es <b>$55,000</b>."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El refrigerador de la tienda es…","ops":["Activo","Pasivo","Capital"],"correcta":0,"explica":"Es algo que el negocio tiene y usa para trabajar."},{"p":"La mercancía que el proveedor te dejó a pagar en 15 días genera un…","ops":["Activo","Ingreso","Pasivo"],"correcta":2},{"p":"Si tienes activos por $120,000 y deudas por $40,000, tu capital es…","ops":["$40,000","$80,000","$160,000"],"correcta":1,"explica":"Capital = Activo − Pasivo = 120,000 − 40,000."}]},{"tipo":"relacionar","rotulo":"Clasifica cada cosa","pares":[["$8,500 en la cuenta del banco del negocio","Activo"],["Préstamo de la caja popular por pagar","Pasivo"],["Dinero que pusiste para abrir el negocio","Capital"]]},{"tipo":"reflexion","rotulo":"Tu negocio en tres líneas","pregunta":"Escribe, aunque sea aproximado, qué tiene tu negocio (activo), qué debe (pasivo) y cuánto crees que es tuyo (capital). No importa si no es exacto: al final del módulo lo harás mejor.","ayuda":"Tengo… / Debo… / Lo mío es…"},{"tipo":"clave","items":["La contabilidad te dice cómo va tu negocio, no solo sirve para el SAT.","Activo = Pasivo + Capital: lo que tienes salió de lo que debes o de lo que es tuyo.","Este diplomado no sustituye a un contador y las reglas fiscales cambian cada año."]}]},{"id":"d-contabilidad-resico-m1-l2","titulo":"Lección 2 — Ingresos, costos y gastos: no es lo mismo","objetivo":"distinguir ingresos, costos y gastos y sumarlos por tipo en una hoja de cálculo.","bloques":[{"tipo":"texto","texto":"Para saber si ganas, necesitas separar tres cosas:<br><b>Ingresos</b>: lo que cobras por vender o por tu servicio.<br><b>Costos</b>: lo que pagas por lo que <b>vendes</b> (la mercancía para revender, la materia prima de lo que produces).<br><b>Gastos</b>: lo que pagas para <b>operar</b>, vendas mucho o poco (renta, luz, internet, sueldos, publicidad)."},{"tipo":"tabla","titulo":"Ejemplos por giro","encabezados":["Giro","Costo (lo que vendes)","Gasto (para operar)"],"filas":[["Papelería","Cuadernos, plumas y copias que revendes","Renta del local, luz, internet"],["Taquería","Carne, tortillas, verdura, gas de la plancha","Renta, sueldo del ayudante, bolsas de publicidad"],["Estética","Tinte y productos que aplicas al cliente","Renta, agua, publicidad en redes"],["Contadora independiente","Casi no hay costo de mercancía","Computadora, software, internet, transporte"]],"nota":"En servicios, a veces casi todo es gasto. Lo importante es que siempre separes lo del negocio de lo de tu casa."},{"tipo":"comparar","titulo":"Un error muy común","malTitulo":"Así no","mal":"Pagar el súper de la casa con el dinero de la caja y anotarlo como «gasto del negocio».","bienTitulo":"Así sí","bien":"Si sacas dinero para tu casa, anótalo como <b>retiro del dueño</b>. No es gasto del negocio: es parte de tu ganancia que te llevas."},{"tipo":"excel","rotulo":"Suma por tipo: Papelería La Estrella","datos":[["Concepto","Tipo","Monto","","Resumen","Total"],["Ventas de mostrador semana 1","Ingreso",18500,"","Ingreso",""],["Compra de cuadernos para reventa","Costo",9200,"","Costo",""],["Renta del local","Gasto",6000,"","Gasto",""],["Ventas de mostrador semana 2","Ingreso",21300,"","Utilidad",""],["Luz CFE","Gasto",850],["Compra de plumas y colores para reventa","Costo",5400],["Internet","Gasto",499]],"retos":[{"celda":"F2","formula":"=SUMAR.SI($B$2:$B$8,E2,$C$2:$C$8)","esperado":39800,"requiere":"SUMAR.SI(","texto":"<b>F2</b>: suma todos los montos cuyo tipo sea «Ingreso». Usa SUMAR.SI con el rango de tipos, el criterio (E2) y el rango de montos.","pista":"=SUMAR.SI(rango donde buscas, criterio, rango que sumas). Fija los rangos con $."},{"celda":"F3","formula":"=SUMAR.SI($B$2:$B$8,E3,$C$2:$C$8)","esperado":14600,"requiere":"SUMAR.SI(","texto":"<b>F3</b>: ahora suma los costos."},{"celda":"F4","formula":"=SUMAR.SI($B$2:$B$8,E4,$C$2:$C$8)","esperado":7349,"requiere":"SUMAR.SI(","texto":"<b>F4</b>: suma los gastos."},{"celda":"F5","formula":"=F2-F3-F4","esperado":17851,"texto":"<b>F5</b>: calcula la utilidad: ingresos menos costos menos gastos.","explica":"Vendió $39,800 pero le quedaron $17,851. Por eso «vender mucho» no es lo mismo que «ganar mucho»."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La harina que compra una panadería para hacer pan es…","ops":["Costo","Gasto","Ingreso"],"correcta":0,"explica":"Es parte directa de lo que vende."},{"p":"El recibo de luz del local es…","ops":["Costo","Pasivo","Gasto"],"correcta":2},{"p":"Sacar $2,000 de la caja para la colegiatura de tu hijo es…","ops":["Costo de ventas","Retiro del dueño","Gasto del negocio"],"correcta":1}]},{"tipo":"clave","items":["Ingreso: lo que cobras. Costo: lo que pagas por lo que vendes. Gasto: lo que pagas para operar.","Utilidad = Ingresos − Costos − Gastos.","Lo que sacas para tu casa es retiro del dueño, no gasto del negocio."]}]},{"id":"d-contabilidad-resico-m1-l3","titulo":"Lección 3 — La partida doble y el catálogo de cuentas, sin enredos","objetivo":"entender que cada movimiento afecta al menos dos cuentas y organizar tus cuentas en un catálogo sencillo.","bloques":[{"tipo":"texto","texto":"La <b>partida doble</b> suena complicada, pero la idea es simple: <b>cada movimiento tiene dos lados</b>. Si algo entra a una cuenta, sale de otra (o nace una deuda). Por eso la ecuación Activo = Pasivo + Capital nunca se descuadra.<br><br>Ejemplo: compras un refrigerador de $12,000 en efectivo. Tu cuenta <b>Equipo</b> sube $12,000 y tu cuenta <b>Caja</b> baja $12,000. Tu negocio no es más rico ni más pobre: cambió dinero por equipo."},{"tipo":"tabla","titulo":"Cuatro movimientos, dos lados cada uno","encabezados":["Movimiento","Lado 1 (lo que recibe)","Lado 2 (de dónde sale)"],"filas":[["Vendes $3,000 en efectivo","Caja +3,000","Ventas (ingreso) +3,000"],["Compras mercancía a crédito por $5,000","Inventario +5,000","Proveedores (pasivo) +5,000"],["Pagas al proveedor $5,000 por transferencia","Proveedores −5,000","Bancos −5,000"],["Pagas la renta de $6,000","Renta (gasto) +6,000","Bancos −6,000"]],"nota":"En contabilidad formal, al lado izquierdo se le llama <b>cargo</b> (o debe) y al derecho <b>abono</b> (o haber). La suma de cargos siempre es igual a la suma de abonos."},{"tipo":"texto","texto":"El <b>catálogo de cuentas</b> es la lista de «cajones» donde clasificas cada movimiento. Un negocio pequeño no necesita cientos de cuentas: con 15 a 25 bien pensadas basta. Se numeran por grupos para no perderse."},{"tipo":"tabla","titulo":"Catálogo mínimo para un negocio pequeño","encabezados":["Número","Cuenta","Grupo"],"filas":[["101 · 102 · 103","Caja · Bancos · Clientes","Activo"],["104 · 150","Inventario de mercancía · Mobiliario y equipo","Activo"],["201 · 202 · 203","Proveedores · Préstamos · Impuestos por pagar","Pasivo"],["301 · 302","Capital del dueño · Retiros del dueño","Capital"],["401","Ventas","Ingresos"],["501","Costo de lo vendido","Costos"],["601 · 602 · 603 · 604","Renta · Luz y agua · Sueldos · Publicidad","Gastos"]]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"En la partida doble, cada movimiento afecta al menos ___ cuentas.","resp":["dos","2"]},{"frase":"Al lado izquierdo de un registro se le llama ___ y al derecho, abono.","resp":["cargo","debe"]},{"frase":"La lista ordenada de cuentas de un negocio se llama catálogo de ___.","resp":["cuentas"]}]},{"tipo":"tarjetas","rotulo":"Repasa con tarjetas","tarjetas":[{"frente":"Compro equipo en efectivo","reverso":"Sube Equipo, baja Caja. El capital no cambia."},{"frente":"Compro mercancía a crédito","reverso":"Sube Inventario, sube Proveedores (lo que debes)."},{"frente":"Pago una deuda","reverso":"Baja Bancos, baja Proveedores."},{"frente":"Vendo al contado","reverso":"Sube Caja, sube Ventas (y con eso, tu utilidad)."}]},{"tipo":"ordenar","rotulo":"Ordena la regla de oro","items":[{"frase":"La suma de cargos siempre es igual a la de abonos","es":"Así se sabe que un registro cuadra"}]},{"tipo":"clave","items":["Partida doble: cada movimiento tiene dos lados y siempre cuadra.","Cargo es el lado izquierdo, abono el derecho; sus sumas son iguales.","Un catálogo de 15 a 25 cuentas numeradas por grupo basta para empezar."]}]},{"id":"d-contabilidad-resico-m1-l4","titulo":"Lección 4 — Flujo de efectivo: ganar no es lo mismo que tener dinero","objetivo":"proyectar entradas y salidas de dinero semana a semana y detectar a tiempo cuándo te faltará efectivo.","bloques":[{"tipo":"texto","texto":"Un negocio puede tener <b>utilidad</b> y aun así quedarse sin dinero. ¿Cómo? Si vendes a crédito, si compraste mucho inventario o si pagaste de golpe algo grande. La utilidad dice si ganas; el <b>flujo de efectivo</b> dice si <b>te alcanza hoy</b> para pagar."},{"tipo":"comparar","titulo":"Utilidad contra flujo","malTitulo":"Solo miro la utilidad","mal":"Don Beto, herrero, cerró un portón de $40,000 y «ganó» $15,000. Pero el cliente paga en 30 días y el viernes no tuvo para la raya del ayudante.","bienTitulo":"Miro también el flujo","bien":"Don Beto pidió 50% de anticipo, compró la lámina con ese dinero y dejó apartado el sueldo del ayudante antes de aceptar más trabajos."},{"tipo":"excel","rotulo":"Flujo semanal de la herrería","datos":[["Semana","Saldo inicial","Entradas","Salidas","Saldo final","Alerta"],[1,5000,12000,14500,"","OK"],[2,"",9000,13800,"",""]],"retos":[{"celda":"E2","formula":"=B2+C2-D2","esperado":2500,"texto":"<b>E2</b>: el saldo final es saldo inicial más entradas menos salidas."},{"celda":"B3","formula":"=E2","esperado":2500,"texto":"<b>B3</b>: el saldo inicial de la semana 2 es el saldo final de la semana 1."},{"celda":"E3","formula":"=B3+C3-D3","esperado":-2300,"texto":"<b>E3</b>: calcula el saldo final de la semana 2.","explica":"Sale negativo: en la semana 2 faltarán $2,300. Saberlo con anticipación te deja cobrar antes, negociar con el proveedor o posponer una compra."},{"celda":"F3","formula":"=SI(E3<0,\"Falta dinero\",\"OK\")","esperado":"Falta dinero","requiere":"SI(","texto":"<b>F3</b>: pon una alerta: SI el saldo final es menor que 0, «Falta dinero»; si no, «OK».","pista":"=SI(E3<0,\"Falta dinero\",\"OK\")"}]},{"tipo":"lista","items":["<b>Pide anticipo</b> en trabajos por encargo.","<b>Cobra a tiempo</b>: anota quién te debe y cuándo prometió pagar.","<b>No compres inventario de más</b>: el dinero parado en anaqueles no paga la renta.","<b>Separa el dinero de impuestos</b> desde que cobras (lo verás en el módulo 3)."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Vendiste $50,000 a crédito a 60 días. Este mes tu utilidad sube, pero tu efectivo…","ops":["No sube hasta que te paguen","Sube lo mismo","Baja $50,000"],"correcta":0},{"p":"El saldo inicial de una semana es…","ops":["Lo que vendiste esa semana","Siempre cero","El saldo final de la semana anterior"],"correcta":2}]},{"tipo":"reflexion","rotulo":"Tu semana más apretada","pregunta":"¿En qué semana del mes sueles quedarte corto de dinero (renta, raya, proveedor)? ¿Qué entrada o salida podrías mover para que no te falte?","ayuda":"Mi semana difícil es… porque… Podría…"},{"tipo":"clave","items":["La utilidad dice si ganas; el flujo dice si te alcanza para pagar hoy.","Saldo final = saldo inicial + entradas − salidas; se encadena semana a semana.","Anticipos, cobranza puntual y poco inventario parado protegen tu flujo."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"La ecuación contable es…","ops":["Activo = Ingresos − Gastos","Pasivo = Activo + Capital","Capital = Ingresos + Pasivo","Activo = Pasivo + Capital"],"correcta":3},{"p":"Un préstamo que debes pagar a la caja popular es…","ops":["Capital","Ingreso","Pasivo","Activo"],"correcta":2},{"p":"La mercancía que compras para revender, al venderse, se registra como…","ops":["Pasivo","Costo de lo vendido","Gasto de publicidad","Capital"],"correcta":1},{"p":"Si tu negocio tiene activos por $90,000 y pasivos por $35,000, el capital es…","ops":["$55,000","$125,000","$35,000","$90,000"],"correcta":0},{"p":"Sacar dinero de la caja para gastos de tu casa es…","ops":["Un gasto deducible del negocio","Un costo de ventas","Un ingreso","Un retiro del dueño"],"correcta":3},{"p":"En la partida doble…","ops":["Cada cuenta se anota dos veces al mes","Los abonos siempre son mayores","Cada movimiento afecta al menos dos cuentas y cargos = abonos","Solo se anotan las ventas"],"correcta":2},{"p":"Tu negocio tiene utilidad pero no te alcanza para la renta. Lo más probable es que…","ops":["Tus costos son cero","Tienes el dinero atorado en clientes o inventario","Tu contabilidad está mal por fuerza","Debes cerrar el negocio"],"correcta":1},{"p":"Semana con saldo inicial $4,000, entradas $10,000 y salidas $11,500. El saldo final es…","ops":["$2,500","$5,500","$25,500","−$2,500"],"correcta":0}]}},{"id":"d-contabilidad-resico-m2","titulo":"Módulo 2 — Tus números en hoja de cálculo: estados financieros, margen y punto de equilibrio","resumen":"Arma un estado de resultados y un balance sencillos, calcula el margen de tus productos y cuánto necesitas vender para no perder. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-contabilidad-resico-m2-l1","titulo":"Lección 1 — El estado de resultados","objetivo":"armar un estado de resultados mensual y leer qué te dice la utilidad bruta y la utilidad de operación.","bloques":[{"tipo":"texto","texto":"El <b>estado de resultados</b> (también le dicen «estado de pérdidas y ganancias») resume un periodo, normalmente un mes o un año. Responde una pregunta: <b>¿gané o perdí?</b> Se lee de arriba hacia abajo, como una escalera que va restando."},{"tipo":"tabla","titulo":"La escalera del estado de resultados","encabezados":["Renglón","Cómo se calcula","Qué te dice"],"filas":[["Ventas","Todo lo que vendiste en el periodo (sin IVA)","Qué tan grande es tu operación"],["− Costo de lo vendido","Lo que te costó la mercancía o materia prima de lo que vendiste","Cuánto se va en el producto"],["= Utilidad bruta","Ventas − Costo","Si tu precio cubre bien tu producto"],["− Gastos de operación","Renta, sueldos, luz, publicidad…","Cuánto cuesta mantener abierto el negocio"],["= Utilidad de operación","Utilidad bruta − Gastos","Lo que de verdad dejó el negocio antes de impuestos"]],"nota":"Usa las ventas <b>sin IVA</b>: el IVA que cobras no es tuyo, es del SAT (lo verás en el módulo 3)."},{"tipo":"excel","rotulo":"Estado de resultados: Taquería El Güero (septiembre)","datos":[["Concepto","Monto"],["Ventas",185000],["Costo de lo vendido",74000],["Utilidad bruta",""],["Renta",15000],["Sueldos",38000],["Gas y luz",9500],["Publicidad",3000],["Total de gastos de operación",""],["Utilidad de operación",""]],"retos":[{"celda":"B4","formula":"=B2-B3","esperado":111000,"texto":"<b>B4</b>: calcula la utilidad bruta (ventas menos costo de lo vendido)."},{"celda":"B9","formula":"=SUMA(B5:B8)","esperado":65500,"requiere":"SUMA(","texto":"<b>B9</b>: suma los gastos de operación con SUMA.","pista":"=SUMA(B5:B8)"},{"celda":"B10","formula":"=B4-B9","esperado":45500,"texto":"<b>B10</b>: calcula la utilidad de operación.","explica":"De $185,000 vendidos, al Güero le quedaron $45,500 antes de impuestos y antes de sus retiros personales."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si tu utilidad bruta es baja, lo primero que revisas es…","ops":["Cuántos seguidores tienes","Tu precio y el costo de tu producto","El recibo de luz"],"correcta":1,"explica":"La utilidad bruta solo depende de ventas y costo del producto."},{"p":"Las ventas del estado de resultados se anotan…","ops":["Sin IVA","Con IVA","Solo las de contado"],"correcta":0},{"p":"El estado de resultados cubre…","ops":["Un solo día fijo","Solo lo que hay en el banco","Un periodo (mes o año)"],"correcta":2}]},{"tipo":"ordenar","rotulo":"Ordena la escalera","items":[{"frase":"Ventas menos costo es igual a utilidad bruta","es":"Primer escalón"},{"frase":"Utilidad bruta menos gastos es utilidad de operación","es":"Segundo escalón"}]},{"tipo":"reflexion","rotulo":"Tu primer estado de resultados","pregunta":"Con los datos de tu último mes (aunque sean aproximados), escribe tus ventas, tu costo y tus tres gastos más grandes. ¿Cuál renglón te sorprendió?","ayuda":"Ventas… Costo… Gastos… Me sorprendió…"},{"tipo":"clave","items":["El estado de resultados responde «¿gané o perdí?» en un periodo.","Ventas − Costo = Utilidad bruta; Utilidad bruta − Gastos = Utilidad de operación.","Siempre trabaja con ventas sin IVA."]}]},{"id":"d-contabilidad-resico-m2-l2","titulo":"Lección 2 — El balance general: la foto de tu negocio","objetivo":"armar un balance sencillo con activo, pasivo y capital, y leerlo junto al estado de resultados.","bloques":[{"tipo":"texto","texto":"Si el estado de resultados es la «película» de un mes, el <b>balance general</b> (o estado de situación financiera) es la <b>foto</b> de un día: qué tiene tu negocio, qué debe y qué es tuyo en una fecha, por ejemplo, al 30 de septiembre."},{"tipo":"tabla","titulo":"Cómo se acomoda","encabezados":["Lado","Qué incluye","Ejemplos"],"filas":[["Activo","Lo que tienes","Caja, bancos, clientes, inventario, equipo"],["Pasivo","Lo que debes","Proveedores, préstamos, impuestos por pagar"],["Capital","Lo que es tuyo","Lo que aportaste + utilidades acumuladas − retiros"]],"nota":"Siempre se cumple: Total activo = Total pasivo + Capital."},{"tipo":"excel","rotulo":"Balance de la Estética Bella al 30 de septiembre","datos":[["Cuenta","Monto","Grupo"],["Caja",4500,"Activo"],["Bancos",38000,"Activo"],["Inventario de productos",62000,"Activo"],["Mobiliario y equipo",85000,"Activo"],["Proveedores",27000,"Pasivo"],["Préstamo bancario",40000,"Pasivo"],["","",""],["Total activo","",""],["Total pasivo","",""],["Capital","",""]],"retos":[{"celda":"B9","formula":"=SUMAR.SI(C2:C7,\"Activo\",B2:B7)","esperado":189500,"requiere":"SUMAR.SI(","texto":"<b>B9</b>: suma solo las cuentas del grupo «Activo» con SUMAR.SI.","pista":"=SUMAR.SI(C2:C7,\"Activo\",B2:B7)"},{"celda":"B10","formula":"=SUMAR.SI(C2:C7,\"Pasivo\",B2:B7)","esperado":67000,"requiere":"SUMAR.SI(","texto":"<b>B10</b>: ahora suma el pasivo."},{"celda":"B11","formula":"=B9-B10","esperado":122500,"texto":"<b>B11</b>: el capital es activo menos pasivo.","explica":"La dueña tiene $122,500 «suyos» dentro del negocio, aunque en efectivo solo haya $42,500 entre caja y bancos."}]},{"tipo":"texto","texto":"¿Qué buscar en tu balance?<br>• <b>¿Te alcanza para tus deudas de corto plazo?</b> Compara caja + bancos + clientes contra proveedores y lo que debes pagar pronto.<br>• <b>¿Tienes demasiado inventario?</b> Si es mucho más de lo que vendes en un mes, hay dinero parado.<br>• <b>¿Crece tu capital?</b> Si mes con mes baja, estás retirando más de lo que ganas o estás perdiendo."},{"tipo":"relacionar","rotulo":"Relaciona el estado con lo que responde","pares":[["¿Gané o perdí este mes?","Estado de resultados"],["¿Qué tengo y qué debo hoy?","Balance general"],["¿Me alcanza el dinero la próxima semana?","Flujo de efectivo"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El balance general muestra…","ops":["Solo las ventas","La situación en una fecha","Lo que pasó en todo el año"],"correcta":1},{"p":"Tu capital baja cada mes aunque vendes bien. Una causa probable es…","ops":["Retiras más de lo que ganas","Tienes mucho equipo","Pagas a tiempo al proveedor"],"correcta":0}]},{"tipo":"clave","items":["El balance es la foto de un día: activo, pasivo y capital.","Total activo = Total pasivo + Capital, siempre.","Revisa liquidez, inventario parado y si tu capital crece."]}]},{"id":"d-contabilidad-resico-m2-l3","titulo":"Lección 3 — Margen: cuánto te deja cada producto","objetivo":"calcular el margen en pesos y en porcentaje, y fijar un precio a partir del margen que quieres.","bloques":[{"tipo":"texto","texto":"El <b>margen</b> es lo que te queda de cada venta después de pagar el costo del producto.<br><b>Margen en pesos</b> = Precio − Costo.<br><b>Margen en %</b> = Margen en pesos ÷ Precio.<br><br>Conocer el margen de cada producto te dice cuáles te conviene empujar y cuáles solo te hacen trabajar."},{"tipo":"excel","rotulo":"Margen en la Panadería San José","datos":[["Producto","Precio","Costo","Margen $","Margen %","Margen deseado"],["Concha",12,4.5,"",""],["Pastel mediano",380,210,"",""],["Bolillo",3,1.9,"",""],["Gelatina","",9,"","",0.4]],"retos":[{"celda":"D2","formula":"=B2-C2","esperado":7.5,"texto":"<b>D2</b>: margen en pesos de la concha (precio menos costo)."},{"celda":"E2","formula":"=D2/B2","esperado":0.625,"texto":"<b>E2</b>: margen en porcentaje: margen en pesos entre precio. (0.625 = 62.5%)."},{"celda":"D3","formula":"=B3-C3","esperado":170,"texto":"<b>D3</b>: margen en pesos del pastel."},{"celda":"E3","formula":"=REDONDEAR(D3/B3,3)","esperado":0.447,"requiere":"REDONDEAR(","texto":"<b>E3</b>: margen % del pastel, redondeado a 3 decimales con REDONDEAR.","pista":"=REDONDEAR(D3/B3,3)","explica":"El pastel tiene menor margen % (44.7%) que la concha, pero deja $170 por pieza. Ambos datos importan."},{"celda":"B5","formula":"=C5/(1-F5)","esperado":15,"texto":"<b>B5</b>: fija el precio de la gelatina para tener 40% de margen: costo ÷ (1 − margen deseado).","explica":"Si solo le sumas 40% al costo (9 × 1.4 = $12.60), tu margen real sería de 28.6%, no de 40%."}]},{"tipo":"comparar","titulo":"Margen contra «le subo un tanto»","malTitulo":"Confusión común","mal":"«Le subo 40% al costo y ya gano 40%.» Con costo de $9, cobras $12.60 y te quedan $3.60: solo 28.6% del precio.","bienTitulo":"Cálculo correcto","bien":"Precio = costo ÷ (1 − 0.40) = $15. Te quedan $6, que sí son 40% del precio."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un producto cuesta $50 y lo vendes en $80. Su margen en % es…","ops":["60%","30%","37.5%"],"correcta":2,"explica":"30 ÷ 80 = 0.375."},{"p":"Para tener 50% de margen con un costo de $20, el precio debe ser…","ops":["$25","$40","$30"],"correcta":1,"explica":"20 ÷ (1 − 0.5) = 40."},{"p":"El bolillo tiene margen bajo. Tiene sentido venderlo si…","ops":["Atrae clientes que compran otros productos","Nunca tiene sentido","Solo si lo vendes a crédito"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Margen en % = margen en pesos entre el ___.","resp":["precio","precio de venta"]},{"frase":"Precio con margen deseado = costo entre (1 menos el ___ deseado).","resp":["margen"]}]},{"tipo":"clave","items":["Margen $ = Precio − Costo; Margen % = Margen $ ÷ Precio.","Precio con margen deseado = Costo ÷ (1 − margen).","Sumar un porcentaje al costo no te da ese mismo porcentaje de margen."]}]},{"id":"d-contabilidad-resico-m2-l4","titulo":"Lección 4 — Punto de equilibrio: cuánto necesitas vender para no perder","objetivo":"calcular el punto de equilibrio en unidades y en pesos y usarlo para fijar metas diarias.","bloques":[{"tipo":"texto","texto":"El <b>punto de equilibrio</b> es la cantidad que necesitas vender para que tus ventas cubran todos tus costos: ni ganas ni pierdes. Para calcularlo separa:<br>• <b>Costos fijos</b>: los pagas aunque no vendas (renta, sueldo base, internet).<br>• <b>Costo variable por unidad</b>: sube con cada venta (ingredientes, empaque, comisión de la terminal).<br><br><b>Contribución por unidad</b> = Precio − Costo variable.<br><b>Punto de equilibrio (unidades)</b> = Costos fijos ÷ Contribución por unidad."},{"tipo":"excel","rotulo":"Punto de equilibrio: Tacos Doña Mary","datos":[["Dato","Valor"],["Costos fijos del mes",24000],["Precio por orden",60],["Costo variable por orden",28],["Contribución por orden",""],["Punto de equilibrio (órdenes al mes)",""],["Órdenes por día (26 días)",""],["Ventas en pesos para equilibrio",""],["Utilidad si vende 900 órdenes",""]],"retos":[{"celda":"B5","formula":"=B3-B4","esperado":32,"texto":"<b>B5</b>: contribución por orden: precio menos costo variable."},{"celda":"B6","formula":"=B2/B5","esperado":750,"texto":"<b>B6</b>: punto de equilibrio en órdenes: costos fijos entre contribución."},{"celda":"B7","formula":"=REDONDEAR(B6/26,0)","esperado":29,"requiere":"REDONDEAR(","texto":"<b>B7</b>: meta diaria: divide entre 26 días de trabajo y redondea a entero.","explica":"Da 28.85; en metas de venta siempre conviene redondear hacia arriba: 29 órdenes diarias."},{"celda":"B8","formula":"=B6*B3","esperado":45000,"texto":"<b>B8</b>: ventas en pesos para llegar al equilibrio (órdenes × precio)."},{"celda":"B9","formula":"=900*B5-B2","esperado":4800,"texto":"<b>B9</b>: utilidad si vende 900 órdenes: 900 × contribución − costos fijos.","explica":"Cada orden arriba del punto de equilibrio aporta $32 de utilidad."}]},{"tipo":"tabla","titulo":"Qué mueve tu punto de equilibrio","encabezados":["Si…","El punto de equilibrio…"],"filas":[["Subes el precio","Baja (necesitas vender menos)"],["Sube el costo de la carne o la tortilla","Sube"],["Cambias a un local con renta más alta","Sube"],["Negocias mejor con el proveedor","Baja"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Costos fijos de $30,000, precio $100 y costo variable $40. El punto de equilibrio es…","ops":["300 unidades","750 unidades","500 unidades"],"correcta":2,"explica":"30,000 ÷ (100 − 40) = 500."},{"p":"La renta del local es un costo…","ops":["Fijo","Variable"],"correcta":0},{"p":"La comisión que cobra la terminal por cada venta con tarjeta es un costo…","ops":["Fijo","Variable"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu meta diaria","pregunta":"Calcula tu punto de equilibrio con tus números aproximados. ¿Cuántas unidades o servicios diarios necesitas? ¿Es realista con tus clientes de hoy?","ayuda":"Costos fijos… Contribución… Necesito vender… al día."},{"tipo":"clave","items":["Punto de equilibrio = Costos fijos ÷ (Precio − Costo variable).","Divídelo entre tus días de trabajo para tener una meta diaria.","Subir precio o bajar costos lo reduce; subir renta o insumos lo aumenta."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"Ventas $100,000, costo de lo vendido $45,000 y gastos $30,000. La utilidad de operación es…","ops":["$55,000","$70,000","$15,000","$25,000"],"correcta":3},{"p":"La utilidad bruta es…","ops":["Lo que hay en el banco","Activo menos pasivo","Ventas menos costo de lo vendido","Ventas menos todos los gastos"],"correcta":2},{"p":"El balance general muestra…","ops":["El flujo de la semana","Lo que tienes, lo que debes y lo que es tuyo en una fecha","Solo las ventas del mes","Solo los impuestos"],"correcta":1},{"p":"Un producto de $200 con costo de $120 tiene un margen de…","ops":["40%","60%","80%","66.7%"],"correcta":0},{"p":"Para tener 25% de margen con un costo de $75, el precio es…","ops":["$93.75","$95","$125","$100"],"correcta":3},{"p":"Costos fijos $18,000, precio $45 y costo variable $15. El punto de equilibrio es…","ops":["1,200 unidades","300 unidades","600 unidades","400 unidades"],"correcta":2},{"p":"Si sube el costo de tus insumos, tu punto de equilibrio…","ops":["Desaparece","Sube","Baja","No cambia"],"correcta":1},{"p":"En los estados financieros las ventas se anotan sin IVA porque…","ops":["El IVA que cobras no es ingreso tuyo, se entera al SAT","El IVA es opcional","El IVA es un gasto","Así lo pide el banco"],"correcta":0}]}},{"id":"d-contabilidad-resico-m3","titulo":"Módulo 3 — Obligaciones fiscales, RESICO e IVA para personas físicas","resumen":"RFC, e.firma, contraseña y constancia de situación fiscal; cómo funciona el Régimen Simplificado de Confianza; cálculo del ISR mensual con la tabla de tasas; IVA y retenciones. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-contabilidad-resico-m3-l1","titulo":"Lección 1 — Tus llaves ante el SAT: RFC, e.firma, contraseña y constancia","objetivo":"reconocer para qué sirve cada identificación fiscal y en qué régimen está tu actividad.","bloques":[{"tipo":"texto","texto":"Para trabajar en regla con el SAT necesitas cuatro «llaves». Cada una sirve para algo distinto y conviene tenerlas vigentes y guardadas en un lugar seguro (nunca se las mandes por WhatsApp a cualquiera)."},{"tipo":"tabla","titulo":"Las cuatro llaves","encabezados":["Llave","Qué es","Para qué la usas"],"filas":[["<b>RFC</b>","Tu clave del Registro Federal de Contribuyentes. En personas físicas tiene <b>13 caracteres</b>; en personas morales, 12.","Identificarte en facturas, declaraciones y trámites"],["<b>Contraseña</b> (antes CIEC)","Clave de acceso al portal del SAT","Entrar al portal, facturar con el servicio gratuito del SAT, presentar declaraciones sencillas, descargar tu constancia"],["<b>e.firma</b>","Archivos .cer y .key más la contraseña de la clave privada. Equivale a tu firma autógrafa. Tiene vigencia de <b>4 años</b>.","Trámites importantes, generar o cambiar la contraseña, requisito del RESICO, firmar ante el SAT"],["<b>Constancia de situación fiscal</b>","Documento que dice tu RFC, nombre, código postal del domicilio fiscal, régimen y obligaciones","Dársela a quien te va a facturar o pagar, abrir cuentas, darte de alta con clientes"]],"nota":"La primera e.firma se tramita con cita en una oficina del SAT. La renovación, en varios casos, puede hacerse en línea: verifica los requisitos vigentes en sat.gob.mx."},{"tipo":"tabla","titulo":"Regímenes comunes de personas físicas","encabezados":["Clave","Régimen","Ejemplo"],"filas":[["605","Sueldos y salarios","Trabajas en nómina para una empresa"],["606","Arrendamiento","Rentas un local o un departamento"],["612","Actividades empresariales y profesionales","Negocio o profesión con ingresos mayores al límite del RESICO o que eligió este régimen"],["625","Actividades empresariales con ingresos a través de plataformas tecnológicas","Vendes por apps o manejas para plataformas de transporte o reparto"],["626","Régimen Simplificado de Confianza (RESICO)","Tiendita, estética, taller, diseñador o profesionista independiente con ingresos de hasta $3.5 millones al año"]],"nota":"Una persona puede estar en más de un régimen a la vez (por ejemplo, 605 por su empleo y 626 por su negocio). Tu régimen exacto aparece en tu constancia."},{"tipo":"relacionar","rotulo":"¿Qué llave necesitas?","pares":[["Tu cliente te pide tus datos para darte de alta como proveedor","Constancia de situación fiscal"],["Olvidaste tu contraseña y quieres generarla en línea","e.firma"],["Vas a entrar al portal a descargar tus facturas","Contraseña"],["Te preguntan tu clave de 13 caracteres","RFC"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La e.firma tiene una vigencia de…","ops":["1 año","Es permanente","4 años"],"correcta":2,"explica":"Anota la fecha de vencimiento en tu calendario: sin e.firma vigente se complican muchos trámites."},{"p":"El RFC de una persona física tiene…","ops":["10 caracteres","13 caracteres","12 caracteres"],"correcta":1},{"p":"Tu régimen fiscal exacto lo confirmas en…","ops":["Tu constancia de situación fiscal","Tu credencial del INE","Tu estado de cuenta bancario"],"correcta":0}]},{"tipo":"lista","items":["Guarda los archivos de tu e.firma en <b>dos lugares</b> (por ejemplo, una USB y una nube personal).","Descarga una <b>constancia reciente</b> cada vez que te la pidan: si cambiaste de domicilio, los datos viejos harán fallar las facturas.","Si un gestor te «ayuda», no le entregues tu e.firma sin saber para qué la usará: con ella se puede firmar en tu nombre."]},{"tipo":"clave","items":["RFC, contraseña, e.firma y constancia: cuatro llaves con usos distintos.","La e.firma dura 4 años y equivale a tu firma; cuídala.","Tu régimen (605, 606, 612, 625, 626…) aparece en tu constancia de situación fiscal."]}]},{"id":"d-contabilidad-resico-m3-l2","titulo":"Lección 2 — El RESICO para personas físicas: quién entra y qué exige","objetivo":"identificar si puedes tributar en el Régimen Simplificado de Confianza y cuáles son sus obligaciones.","bloques":[{"tipo":"texto","texto":"El <b>Régimen Simplificado de Confianza (RESICO)</b> está en la Ley del ISR, artículos <b>113-E a 113-J</b>. Su idea es sencilla: pagas ISR con una <b>tasa baja (de 1% a 2.5%)</b> sobre lo que <b>cobraste</b>, sin restar gastos. A cambio, el SAT te pide estar al día con facturas, e.firma, buzón y pagos."},{"tipo":"tabla","titulo":"¿Quién puede tributar en el RESICO?","encabezados":["Requisito","Detalle"],"filas":[["Tipo de ingresos","Actividades empresariales, servicios profesionales (honorarios) o arrendamiento"],["Límite de ingresos","Que tus ingresos del año anterior no pasaran de <b>$3,500,000</b>; si empiezas actividades, que estimes no pasarlos"],["Otros ingresos permitidos","Puedes además tener sueldos y algunos otros ingresos, siempre que el total no pase del límite"],["Si rebasas el límite","Si en el año tus ingresos pasan de $3,500,000, dejas de tributar en el RESICO y pasas al régimen general que te corresponda"]]},{"tipo":"tabla","titulo":"Quiénes NO pueden tributar en el RESICO","encabezados":["Supuesto","Ejemplo"],"filas":[["Socios, accionistas o integrantes de personas morales, o partes relacionadas","Eres socio de una S.A. de C.V. (la Resolución Miscelánea prevé algunas excepciones; verifícalas en el SAT)"],["Residentes en el extranjero con establecimiento permanente en México","Extranjero que opera un negocio fijo aquí"],["Quienes tienen ingresos sujetos a regímenes fiscales preferentes","Ingresos de paraísos fiscales"],["Quienes reciben ciertos ingresos asimilados a salarios que señala la ley","Algunos casos de consejeros o asimilados; revísalo con tu contador"]]},{"tipo":"pasos","rotulo":"Obligaciones principales en el RESICO","pasos":["Estar inscrito en el RFC y mantener tu situación actualizada.","Tener <b>e.firma activa</b> y <b>buzón tributario</b> habilitado.","Expedir <b>CFDI</b> (facturas) por todos tus ingresos cobrados.","Pedir y conservar las facturas de tus compras y gastos.","Si tienes trabajadores, retener y pagar el ISR de sus sueldos.","Presentar tu <b>pago mensual a más tardar el día 17 del mes siguiente</b>.","Presentar tu <b>declaración anual en abril</b> del año siguiente."]},{"tipo":"destacado","texto":"<b>Cuidado:</b> si dejas de presentar <b>tres o más pagos mensuales</b> en un año, o no presentas tu declaración anual, sales del RESICO y pasas al régimen general, donde normalmente pagarás más y con más trámites."},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El límite de ingresos anuales para el RESICO de personas físicas es de 3.5 ___ de pesos.","resp":["millones"]},{"frase":"El pago mensual se presenta a más tardar el día ___ del mes siguiente.","resp":["17","diecisiete"]},{"frase":"La declaración anual de personas físicas se presenta en el mes de ___.","resp":["abril"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Rosa es socia de una S.A. de C.V. y además tiene una tienda de ropa. En principio…","ops":["Puede tributar sin problema","Debe cerrar la tienda","No puede tributar en el RESICO por la tienda"],"correcta":2,"explica":"Ser socio de una persona moral es una de las exclusiones, salvo excepciones que marca la Resolución Miscelánea."},{"p":"Omitir tres pagos mensuales en el año provoca…","ops":["Nada, si pagas la anual","Salir del RESICO","Una tasa más baja"],"correcta":1},{"p":"En el RESICO, el ISR se calcula sobre…","ops":["Los ingresos cobrados, sin restar gastos","La utilidad (ingresos menos gastos)","Solo lo depositado en el banco"],"correcta":0}]},{"tipo":"clave","items":["RESICO (LISR 113-E a 113-J): ISR de 1% a 2.5% sobre ingresos cobrados, sin deducciones.","Límite: $3,500,000 al año; socios de personas morales, en general, no pueden entrar.","Pago mensual a más tardar el día 17 y anual en abril; tres pagos omitidos te sacan del régimen."]}]},{"id":"d-contabilidad-resico-m3-l3","titulo":"Lección 3 — Calcula tu ISR mensual en el RESICO","objetivo":"aplicar la tabla de tasas mensuales del RESICO con BUSCARV aproximado y restar las retenciones.","bloques":[{"tipo":"texto","texto":"Cada mes sumas lo que <b>efectivamente cobraste</b> (sin IVA), buscas en la tabla la tasa que le toca a ese total y la multiplicas. Ojo: la tasa se aplica al <b>total</b> del mes; no es escalonada como la tabla del ISR de sueldos."},{"tipo":"tabla","titulo":"Tabla mensual del RESICO (LISR art. 113-E)","encabezados":["Ingresos cobrados en el mes, hasta…","Tasa"],"filas":[["$25,000.00","1.00%"],["$50,000.00","1.10%"],["$83,333.33","1.50%"],["$208,333.33","2.00%"],["$3,500,000.00","2.50%"]],"nota":"Fuente: artículo 113-E de la Ley del ISR. En la declaración anual (art. 113-F) se usa una tabla equivalente anual (hasta $300,000 al 1% … hasta $3,500,000 al 2.5%) y se restan los pagos mensuales. Confirma cada año que no haya cambiado."},{"tipo":"excel","rotulo":"ISR RESICO de Diseño Gráfico Ana","datos":[["Mes","Ingresos cobrados sin IVA","Tasa","ISR del mes","","Desde","Tasa"],["Enero",22000,"","","",0,0.01],["Febrero",38500,"","","",25000.01,0.011],["Marzo",61200,"","","",50000.01,0.015],["Abril",96000,"","","",83333.34,0.02],["","","","","",208333.34,0.025],["","","",""],["Abril: ISR que le retuvieron sus clientes (personas morales)",1200],["Abril: ISR a pagar",""]],"retos":[{"celda":"C2","formula":"=BUSCARV(B2,$F$2:$G$6,2,VERDADERO)","esperado":0.01,"requiere":"BUSCARV(","texto":"<b>C2</b>: busca la tasa de enero con BUSCARV <b>aproximado</b> (VERDADERO) sobre la tabla F2:G6. La columna F tiene el límite inferior de cada renglón.","pista":"=BUSCARV(B2,$F$2:$G$6,2,VERDADERO). Con VERDADERO, BUSCARV toma el renglón más grande que no pase del valor buscado."},{"celda":"D2","formula":"=REDONDEAR(B2*C2,2)","esperado":220,"requiere":"REDONDEAR(","texto":"<b>D2</b>: ISR de enero: ingresos por tasa, redondeado a 2 decimales."},{"celda":"C3","formula":"=BUSCARV(B3,$F$2:$G$6,2,VERDADERO)","esperado":0.011,"requiere":"BUSCARV(","texto":"<b>C3</b>: tasa de febrero."},{"celda":"D3","formula":"=REDONDEAR(B3*C3,2)","esperado":423.5,"requiere":"REDONDEAR(","texto":"<b>D3</b>: ISR de febrero.","explica":"38,500 × 1.1% = $423.50. La tasa de 1.1% se aplica a todo el ingreso del mes, no solo a lo que pasa de $25,000."},{"celda":"C5","formula":"=BUSCARV(B5,$F$2:$G$6,2,VERDADERO)","esperado":0.02,"requiere":"BUSCARV(","texto":"<b>C5</b>: tasa de abril."},{"celda":"D5","formula":"=REDONDEAR(B5*C5,2)","esperado":1920,"requiere":"REDONDEAR(","texto":"<b>D5</b>: ISR de abril."},{"celda":"B9","formula":"=D5-B8","esperado":720,"texto":"<b>B9</b>: resta al ISR de abril lo que le retuvieron sus clientes personas morales.","explica":"Las retenciones de 1.25% que te hacen las personas morales se acreditan contra tu pago mensual. Pide siempre que te las comprueben con su CFDI."}]},{"tipo":"comparar","titulo":"Dos formas de ver el mes","malTitulo":"Error frecuente","mal":"«Marzo tuve $61,200: pago 1% de los primeros 25 mil, 1.1% de los siguientes…»","bienTitulo":"Correcto","bien":"«Marzo tuve $61,200: cae en el renglón de hasta $83,333.33, así que pago 1.5% sobre los $61,200: $918.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Con ingresos cobrados de $45,000 en el mes, la tasa del RESICO es…","ops":["1.00%","1.50%","1.10%"],"correcta":2,"explica":"Está entre $25,000.01 y $50,000."},{"p":"Si cobraste $30,000 más IVA ($34,800), el ISR se calcula sobre…","ops":["$4,800","$30,000","$34,800"],"correcta":1},{"p":"Si facturaste en marzo pero te pagaron en abril, el ingreso cuenta en…","ops":["Abril, cuando lo cobraste","Marzo, cuando facturaste","Ninguno de los dos"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu tasa aproximada","pregunta":"Con tu promedio de ingresos cobrados al mes (sin IVA), ¿en qué renglón de la tabla caes y cuánto ISR pagarías? ¿Cuánto conviene que apartes cada semana para no batallar el día 17?","ayuda":"Cobro en promedio… mi tasa es… apartaría… a la semana."},{"tipo":"clave","items":["ISR RESICO mensual = ingresos cobrados sin IVA × la tasa del renglón que les toca.","La tasa se aplica al total del mes; usa BUSCARV aproximado con límites inferiores.","Resta las retenciones de 1.25% que te hicieron personas morales."]}]},{"id":"d-contabilidad-resico-m3-l4","titulo":"Lección 4 — IVA básico y retenciones","objetivo":"calcular el IVA trasladado, el acreditable y el IVA a pagar, y entender las retenciones cuando facturas a personas morales.","bloques":[{"tipo":"texto","texto":"El <b>IVA</b> no es un gasto ni un ingreso tuyo: tú lo <b>cobras</b> a tus clientes por cuenta del SAT (IVA <b>trasladado</b>) y lo <b>pagas</b> a tus proveedores (IVA <b>acreditable</b>, si tienes su factura). Cada mes, a más tardar el día 17, pagas la diferencia.<br><br><b>IVA a pagar = IVA trasladado − IVA acreditable − IVA que te retuvieron</b>."},{"tipo":"tabla","titulo":"Tasas y exenciones (ejemplos)","encabezados":["Tratamiento","Ejemplos","¿Puedes acreditar el IVA de tus compras?"],"filas":[["<b>16%</b> (tasa general)","Ropa, papelería, servicios de estética, diseño, reparaciones, comida preparada","Sí"],["<b>0%</b>","Muchos alimentos no preparados (tortilla, huevo, frijol), medicinas de patente, algunos productos agrícolas","Sí"],["<b>Exento</b>","Renta de casa habitación, consultas médicas de profesionistas, colegiaturas de escuelas con validez oficial, venta de casa habitación","No"],["<b>8%</b> (estímulo en región fronteriza)","Ciertos negocios en zonas fronterizas que se inscriben al estímulo","Verifica requisitos en el SAT"]],"nota":"Clasificar mal un producto es de los errores más caros. Si vendes cosas mixtas (por ejemplo, abarrotes con refrescos y botanas), revisa con tu contador qué va a 0% y qué a 16%."},{"tipo":"excel","rotulo":"IVA de septiembre: Abarrotes Doña Lupe","datos":[["Concepto","Base","IVA"],["Ventas gravadas al 16% (refrescos, botanas, limpieza)",85000,""],["Ventas a tasa 0% (tortilla, huevo, frijol)",42000,0],["Compras y gastos con factura al 16%",47500,""],["IVA a cargo del mes","",""],["IVA que le retuvieron clientes","",0],["IVA a pagar","",""],["Resultado","",""]],"retos":[{"celda":"C2","formula":"=B2*0.16","esperado":13600,"texto":"<b>C2</b>: IVA trasladado: ventas gravadas por 0.16."},{"celda":"C4","formula":"=B4*0.16","esperado":7600,"texto":"<b>C4</b>: IVA acreditable de sus compras y gastos con factura."},{"celda":"C5","formula":"=C2+C3-C4","esperado":6000,"texto":"<b>C5</b>: IVA trasladado total (16% + 0%) menos acreditable."},{"celda":"C7","formula":"=C5-C6","esperado":6000,"texto":"<b>C7</b>: resta el IVA retenido (en su caso, cero)."},{"celda":"C8","formula":"=SI(C7<0,\"Saldo a favor\",\"A pagar\")","esperado":"A pagar","requiere":"SI(","texto":"<b>C8</b>: SI el IVA a pagar es negativo, «Saldo a favor»; si no, «A pagar».","explica":"Las ventas al 0% no generan IVA, pero sí le permiten acreditar el IVA de sus compras. Por eso muchos negocios de alimentos básicos tienen saldos a favor."}]},{"tipo":"tabla","titulo":"Retenciones cuando facturas a una persona moral (empresa)","encabezados":["Retención","Cuándo aplica","Cuánto"],"filas":[["ISR RESICO","Siempre que una persona moral te paga como contribuyente del RESICO (LISR art. 113-J)","<b>1.25%</b> del importe sin IVA"],["IVA","Solo en ciertos casos: servicios profesionales (honorarios), arrendamiento, comisiones, autotransporte de carga y otros que marca la Ley del IVA. No aplica a la simple venta de mercancía.","<b>Dos terceras partes</b> del IVA (10.6667% del importe)"]],"nota":"La persona moral te entrega el CFDI de la retención; tú la restas de tu pago mensual. Guarda ese comprobante."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Vendiste $20,000 más IVA y compraste con factura $12,000 más IVA. Tu IVA a pagar es…","ops":["$3,200","$1,920","$1,280"],"correcta":2,"explica":"3,200 − 1,920 = 1,280."},{"p":"El IVA de una compra sin factura…","ops":["Se acredita a la mitad","No lo puedes acreditar","Se acredita igual"],"correcta":1},{"p":"Si vendes un tostador (mercancía) a una empresa estando en el RESICO, en general te retienen…","ops":["1.25% de ISR, sin retención de IVA","Dos terceras partes de IVA y nada de ISR","Nada"],"correcta":0}]},{"tipo":"clave","items":["IVA a pagar = trasladado − acreditable − retenido; se paga a más tardar el día 17.","16%, 0% y exento no son lo mismo: con 0% sí acreditas; con exento, no.","Personas morales te retienen 1.25% de ISR y, en servicios o rentas, dos terceras partes del IVA."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"El RESICO de personas físicas está regulado en…","ops":["El artículo 1 de la Ley del IVA","La Ley Federal del Trabajo","El Anexo 20 únicamente","Los artículos 113-E a 113-J de la Ley del ISR"],"correcta":3},{"p":"El límite de ingresos anuales para tributar en el RESICO como persona física es…","ops":["$5,000,000","$300,000","$3,500,000","$2,000,000"],"correcta":2},{"p":"Con ingresos cobrados de $70,000 en el mes, el ISR RESICO es…","ops":["$1,400","$1,050","$770","$700"],"correcta":1},{"p":"El pago mensual del RESICO vence…","ops":["El día 17 del mes siguiente","El último día del mismo mes","El día 5 del mes siguiente","Solo en abril"],"correcta":0},{"p":"Una causa para salir del RESICO es…","ops":["Tener un solo cliente","Facturar a personas físicas","Vender por internet","Omitir tres o más pagos mensuales en el año"],"correcta":3},{"p":"Un contribuyente del RESICO que factura a una persona moral sufre una retención de ISR de…","ops":["2.5%","16%","1.25%","10%"],"correcta":2},{"p":"Vendes $50,000 más IVA y tus compras con factura suman $30,000 más IVA. El IVA a pagar es…","ops":["$12,800","$3,200","$8,000","$4,800"],"correcta":1},{"p":"¿Cuál documento muestra tu régimen fiscal y el código postal de tu domicilio fiscal?","ops":["La constancia de situación fiscal","La e.firma","El acuse de la declaración anual","El estado de cuenta"],"correcta":0}]}},{"id":"d-contabilidad-resico-m4","titulo":"Módulo 4 — Facturación CFDI 4.0 sin errores","resumen":"Los datos del receptor, el uso del CFDI, la forma y el método de pago (PUE o PPD), el complemento de pago, la cancelación, la factura global y los errores que más rechazos provocan. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-contabilidad-resico-m4-l1","titulo":"Lección 1 — Los datos del receptor y el uso del CFDI","objetivo":"capturar correctamente nombre, RFC, código postal, régimen fiscal y uso del CFDI de tu cliente.","bloques":[{"tipo":"texto","texto":"La factura electrónica se llama <b>CFDI</b> (Comprobante Fiscal Digital por Internet) y la versión vigente es la <b>4.0</b>. Su gran cambio fue que ahora los datos de tu cliente (el <b>receptor</b>) deben coincidir <b>exactamente</b> con los que tiene registrados en el SAT. Si uno no cuadra, el sistema de facturación rechaza la factura y no se puede timbrar.<br><br>Por eso, antes de facturar a alguien por primera vez, pídele su <b>constancia de situación fiscal</b> reciente: ahí vienen todos los datos."},{"tipo":"tabla","titulo":"Los cinco datos del receptor","encabezados":["Dato","Cómo va","Error típico"],"filas":[["<b>Nombre o razón social</b>","Tal cual aparece en la constancia, en personas morales <b>sin</b> el régimen societario (sin «S.A. de C.V.»)","Poner el nombre comercial («Ferretería El Clavo») en vez de la razón social"],["<b>RFC</b>","13 caracteres si es persona física, 12 si es persona moral","Una letra o dígito cambiado"],["<b>Código postal</b>","El del <b>domicilio fiscal</b> del cliente, no el de su sucursal ni el tuyo","Usar un CP viejo porque el cliente se mudó"],["<b>Régimen fiscal</b>","La clave de su régimen (601, 605, 612, 626…)","Poner tu régimen en vez del de tu cliente"],["<b>Uso del CFDI</b>","Para qué usará tu cliente la factura; debe ser compatible con su régimen","Poner «Gastos en general» a un asalariado que quiere deducir una consulta médica"]],"nota":"El nombre se captura como aparece en la constancia; muchos sistemas lo piden en mayúsculas."},{"tipo":"tabla","titulo":"Usos del CFDI más comunes","encabezados":["Clave","Uso","Ejemplo"],"filas":[["G01","Adquisición de mercancías","Una tienda te compra producto para revender"],["G03","Gastos en general","Una empresa te paga un servicio de diseño o de mantenimiento"],["I04","Equipo de cómputo y accesorios","Tu cliente compra una computadora para su negocio"],["D01","Honorarios médicos, dentales y gastos hospitalarios","Deducción personal en la anual de un paciente"],["S01","Sin efectos fiscales","Público en general o clientes que no deducirán la factura"],["CP01","Pagos","Solo en el complemento de pago (lección 2)"]],"nota":"El catálogo completo está en el SAT (catálogo c_UsoCFDI del Anexo 20). Si dudas, pregúntale al cliente qué uso le indicó su contador."},{"tipo":"excel","rotulo":"Revisa los datos antes de timbrar","datos":[["Cliente","RFC","Largo RFC","Tipo de persona","Nombre capturado","Nombre en mayúsculas"],["Ferreteros del Bajío","FBA150312KT7","","","ferreteros del bajío",""],["Lucía Hernández Ruiz","HERL850621MN4","","","lucía hernández ruiz",""]],"retos":[{"celda":"C2","formula":"=LARGO(B2)","esperado":12,"requiere":"LARGO(","texto":"<b>C2</b>: cuenta los caracteres del RFC con LARGO."},{"celda":"D2","formula":"=SI(C2=12,\"Moral\",SI(C2=13,\"Física\",\"Revisar\"))","esperado":"Moral","requiere":"SI(","texto":"<b>D2</b>: SI tiene 12 caracteres es «Moral»; SI tiene 13, «Física»; si no, «Revisar».","pista":"=SI(C2=12,\"Moral\",SI(C2=13,\"Física\",\"Revisar\"))"},{"celda":"C3","formula":"=LARGO(B3)","esperado":13,"requiere":"LARGO(","texto":"<b>C3</b>: largo del RFC de Lucía."},{"celda":"D3","formula":"=SI(C3=12,\"Moral\",SI(C3=13,\"Física\",\"Revisar\"))","esperado":"Física","requiere":"SI(","texto":"<b>D3</b>: tipo de persona de Lucía."},{"celda":"F2","formula":"=MAYUSC(E2)","esperado":"FERRETEROS DEL BAJÍO","requiere":"MAYUSC(","texto":"<b>F2</b>: convierte el nombre capturado a mayúsculas con MAYUSC.","explica":"Saber si el cliente es persona física o moral te dice qué retenciones podría hacerte: las personas morales retienen 1.25% de ISR a quien está en el RESICO."}]},{"tipo":"relacionar","rotulo":"¿Qué dato está mal?","pares":[["Pusiste «Abarrotes La Güera» y su constancia dice «María Guadalupe Soto Ruiz»","Nombre"],["El cliente se cambió de colonia y usaste la dirección anterior","Código postal"],["Escribiste 626 porque es tu régimen, pero el cliente es asalariado","Régimen fiscal"],["La empresa quería G01 para mercancía y pusiste S01","Uso del CFDI"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El código postal del receptor debe ser…","ops":["El de tu local","El de la sucursal donde compró","El de su domicilio fiscal registrado en el SAT"],"correcta":2,"explica":"Lo tomas de su constancia de situación fiscal."},{"p":"A «Muebles Finos del Norte, S.A. de C.V.» la facturas como…","ops":["Mueblería La Fina","MUEBLES FINOS DEL NORTE","MUEBLES FINOS DEL NORTE SA DE CV"],"correcta":1,"explica":"En CFDI 4.0 el régimen societario (S.A. de C.V.) no se escribe."},{"p":"La mejor forma de tener datos correctos del cliente es…","ops":["Pedirle su constancia de situación fiscal reciente","Copiarlos de una factura de hace dos años","Preguntarle su RFC por teléfono y adivinar lo demás"],"correcta":0}]},{"tipo":"clave","items":["En CFDI 4.0 nombre, RFC, código postal y régimen del receptor deben coincidir con el SAT.","Pide la constancia de situación fiscal reciente antes de facturar por primera vez.","El uso del CFDI lo decide tu cliente y debe ser compatible con su régimen."]}]},{"id":"d-contabilidad-resico-m4-l2","titulo":"Lección 2 — Forma de pago, método PUE o PPD y el complemento de pago","objetivo":"elegir correctamente entre PUE y PPD, llenar la forma de pago y saber cuándo emitir un complemento de pago.","bloques":[{"tipo":"texto","texto":"Dos campos se confunden mucho:<br>• <b>Método de pago</b>: <b>cuándo</b> te pagan. <b>PUE</b> (Pago en una sola exhibición) si ya te pagaron todo; <b>PPD</b> (Pago en parcialidades o diferido) si te pagarán después o en partes.<br>• <b>Forma de pago</b>: <b>cómo</b> te pagaron: 01 efectivo, 02 cheque nominativo, 03 transferencia, 04 tarjeta de crédito, 28 tarjeta de débito… Si usas PPD, la forma de pago va como <b>99 · Por definir</b>."},{"tipo":"comparar","titulo":"El caso de don Beto","malTitulo":"Así no","mal":"Factura el portón de $40,000 como PUE con forma 03 (transferencia) aunque el cliente le pagará en 30 días.","bienTitulo":"Así sí","bien":"Como aún no le pagan, factura con <b>PPD</b> y forma <b>99</b>. Cuando reciba cada pago, emite un <b>complemento de pago</b>."},{"tipo":"pasos","rotulo":"Cómo funciona el complemento de pago","pasos":["Emites la factura con método <b>PPD</b> y forma de pago <b>99</b>.","Tu cliente te paga (todo o una parte).","Emites un <b>CFDI de pago</b> (complemento, tipo «P»), con uso <b>CP01</b>, que dice cuánto, cuándo y cómo te pagaron y a qué factura corresponde.","Lo emites <b>a más tardar el día 5 (natural) del mes siguiente</b> al que recibiste el pago.","Si te pagan en partes, emites un complemento por cada pago y la factura queda con saldo pendiente hasta liquidarse."]},{"tipo":"destacado","texto":"<b>Importante para el RESICO:</b> pagas ISR sobre lo que <b>cobras</b>. Una factura PPD no cuenta como ingreso hasta que te pagan; el complemento es lo que demuestra cuándo cobraste. Si facturas PUE algo que no te han pagado, el SAT puede considerar que ya lo cobraste. Hay reglas de la Resolución Miscelánea que permiten PUE en algunos casos cuando el pago llega dentro del mismo mes: <b>verifica en el SAT o con tu contador</b> antes de usarlas."},{"tipo":"excel","rotulo":"Control de facturas y complementos","datos":[["Factura","Cliente","Importe","¿Pagada al emitir?","Método","Pagada después","¿Complemento?"],["A-101","Constructora Río","40000","No","","Sí",""],["A-102","Salón Glamour","3500","Sí","","",""],["A-103","Hotel Plaza","18000","No","","No",""],["","","","","Complementos pendientes","",""]],"retos":[{"celda":"E2","formula":"=SI(D2=\"Sí\",\"PUE\",\"PPD\")","esperado":"PPD","requiere":"SI(","texto":"<b>E2</b>: SI la factura se pagó al emitirse («Sí») el método es «PUE»; si no, «PPD».","pista":"=SI(D2=\"Sí\",\"PUE\",\"PPD\")"},{"celda":"E3","formula":"=SI(D3=\"Sí\",\"PUE\",\"PPD\")","esperado":"PUE","requiere":"SI(","texto":"<b>E3</b>: método de la factura A-102."},{"celda":"E4","formula":"=SI(D4=\"Sí\",\"PUE\",\"PPD\")","esperado":"PPD","requiere":"SI(","texto":"<b>E4</b>: método de la factura A-103."},{"celda":"G2","formula":"=SI(Y(E2=\"PPD\",F2=\"Sí\"),\"Emitir\",\"No\")","esperado":"Emitir","requiere":"Y(","texto":"<b>G2</b>: SI el método es PPD <b>y</b> ya se pagó después, «Emitir»; si no, «No». Usa SI con Y.","pista":"=SI(Y(E2=\"PPD\",F2=\"Sí\"),\"Emitir\",\"No\")"},{"celda":"G5","formula":"=CONTAR.SI(E2:E4,\"PPD\")","esperado":2,"requiere":"CONTAR.SI(","texto":"<b>G5</b>: cuenta cuántas facturas son PPD (a cada una le tocará al menos un complemento cuando pague).","explica":"La A-101 ya necesita su complemento; la A-103 lo necesitará cuando el hotel pague. Lleva esta lista cada semana para no olvidar ninguno."}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"Si te pagarán después o en partes, el método de pago es ___.","resp":["PPD"]},{"frase":"Con método PPD, la forma de pago se anota como 99, por ___.","resp":["definir"]},{"frase":"El complemento de pago lleva el uso de CFDI ___.","resp":["CP01"]}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Te pagan con tarjeta de débito en el momento de la venta. Usas…","ops":["PPD y forma 99","PUE y forma 99","PUE y forma 28"],"correcta":2},{"p":"Tu cliente te paga el 20 de octubre una factura PPD. El complemento debe emitirse…","ops":["En abril, con la anual","A más tardar el 5 de noviembre","A más tardar el 20 de octubre"],"correcta":1},{"p":"Método de pago responde a…","ops":["Cuándo te pagan","Cómo te pagan","Para qué usará la factura el cliente"],"correcta":0}]},{"tipo":"clave","items":["PUE si ya te pagaron todo; PPD (con forma 99) si te pagarán después o en partes.","Por cada pago de una factura PPD emite un complemento a más tardar el día 5 del mes siguiente.","En el RESICO el complemento prueba cuándo cobraste, y eso define cuándo pagas ISR."]}]},{"id":"d-contabilidad-resico-m4-l3","titulo":"Lección 3 — Cancelación de facturas y factura global","objetivo":"cancelar una factura con el motivo correcto y emitir la factura global de tus ventas al público en general.","bloques":[{"tipo":"texto","texto":"Si una factura salió mal, no la «borras»: la <b>cancelas</b> en el portal del SAT o en tu sistema de facturación, eligiendo un <b>motivo</b>. Y si vendes a gente que no pide factura, esas ventas también deben quedar amparadas: para eso existe la <b>factura global</b>."},{"tipo":"tabla","titulo":"Motivos de cancelación","encabezados":["Clave","Motivo","Cuándo se usa"],"filas":[["01","Comprobante emitido con errores con relación","Hay un error y primero emites la factura correcta; al cancelar la mala indicas cuál la sustituye"],["02","Comprobante emitido con errores sin relación","Hay un error y no vas a emitir otra que la sustituya"],["03","No se llevó a cabo la operación","La venta se cayó"],["04","Operación nominativa relacionada en una factura global","Una venta que incluiste en la global ahora se factura a nombre del cliente"]],"nota":"Plazo: en general puedes cancelar a más tardar en el mes en que debes presentar la declaración anual del año en que emitiste la factura (para personas físicas, abril del año siguiente). Verifica el plazo vigente en el SAT."},{"tipo":"lista","items":["En muchos casos el cliente debe <b>aceptar</b> la cancelación; tiene <b>3 días hábiles</b> para responder y, si no contesta, se considera aceptada.","Hay excepciones en las que no se necesita aceptación (por ejemplo, facturas de montos bajos o canceladas muy poco después de emitirlas); los supuestos exactos están en la Resolución Miscelánea: verifícalos en el SAT.","Antes de cancelar una factura PPD, revisa que no tenga complementos de pago relacionados."]},{"tipo":"tabla","titulo":"Datos de la factura global","encabezados":["Campo","Qué se pone"],"filas":[["RFC del receptor","<b>XAXX010101000</b> (público en general)"],["Nombre","PUBLICO EN GENERAL"],["Régimen fiscal del receptor","616 · Sin obligaciones fiscales"],["Uso del CFDI","S01 · Sin efectos fiscales"],["Código postal del receptor","El mismo de tu lugar de expedición"],["Periodicidad","Diaria, semanal, quincenal o mensual (la bimestral es solo para casos que vienen del antiguo RIF)"],["Plazo","Dentro de las 24 horas siguientes al cierre del periodo elegido"]],"nota":"En cada concepto van tus notas o tickets del periodo, con su IVA desglosado. No incluyas ventas por las que ya emitiste factura a nombre del cliente."},{"tipo":"excel","rotulo":"Factura global semanal: Abarrotes Doña Lupe","datos":[["Ticket","Día","Cliente","Total con IVA (16%)","","Resumen","Monto"],["T-201","Lunes","Público en general",580,"","Total público en general",""],["T-202","Lunes","Taller Mecánico Ruiz",1160,"","Base sin IVA",""],["T-203","Martes","Público en general",348,"","IVA 16%",""],["T-204","Jueves","Público en general",870,"","Tickets en la global",""],["T-205","Sábado","Público en general",464]],"retos":[{"celda":"G2","formula":"=SUMAR.SI(C2:C6,\"Público en general\",D2:D6)","esperado":2262,"requiere":"SUMAR.SI(","texto":"<b>G2</b>: suma solo los tickets de «Público en general» (el taller ya pidió su factura).","pista":"=SUMAR.SI(C2:C6,\"Público en general\",D2:D6)"},{"celda":"G3","formula":"=REDONDEAR(G2/1.16,2)","esperado":1950,"requiere":"REDONDEAR(","texto":"<b>G3</b>: saca la base sin IVA: el total entre 1.16, redondeado a 2 decimales."},{"celda":"G4","formula":"=G2-G3","esperado":312,"texto":"<b>G4</b>: el IVA es el total menos la base."},{"celda":"G5","formula":"=CONTAR.SI(C2:C6,\"Público en general\")","esperado":4,"requiere":"CONTAR.SI(","texto":"<b>G5</b>: cuenta cuántos tickets van en la global.","explica":"Ojo: aquí todos los productos son al 16%. Si vendes productos al 0% (tortilla, huevo), sepáralos, porque en la factura cada concepto lleva su propia tasa."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Facturaste a un cliente con el RFC equivocado y ya emitiste la factura correcta. Cancelas con motivo…","ops":["03","04","01, relacionándola con la nueva"],"correcta":2},{"p":"El RFC genérico de la factura global es…","ops":["Tu propio RFC","XAXX010101000","XEXX010101000"],"correcta":1},{"p":"Si eliges periodicidad semanal, la factura global se emite…","ops":["Dentro de las 24 horas siguientes al cierre de la semana","Una vez al año","Cuando te acuerdes"],"correcta":0}]},{"tipo":"clave","items":["Cancela con el motivo correcto: 01 con relación, 02 sin relación, 03 operación no realizada, 04 global.","Muchas cancelaciones requieren que el cliente las acepte en 3 días hábiles.","La factura global (XAXX010101000, 616, S01) ampara tus ventas sin factura del periodo."]}]},{"id":"d-contabilidad-resico-m4-l4","titulo":"Lección 4 — Los errores de facturación más comunes y cómo evitarlos","objetivo":"reconocer los errores de facturación más frecuentes y armar una rutina para evitarlos.","bloques":[{"tipo":"texto","texto":"La mayoría de los problemas con facturas no son de mala fe: son prisas. El cliente espera, el sistema rechaza y se captura «lo que sea» para salir del paso. Luego viene la cancelación, el enojo del cliente o un ingreso declarado en el mes equivocado."},{"tipo":"tarjetas","rotulo":"Errores frecuentes (voltea para ver la solución)","tarjetas":[{"frente":"«El RFC no coincide con el nombre»","reverso":"Captura el nombre exactamente como la constancia, sin «S.A. de C.V.» y sin nombre comercial."},{"frente":"«El código postal no corresponde»","reverso":"El cliente cambió de domicilio. Pídele una constancia reciente."},{"frente":"El uso del CFDI no es compatible con el régimen","reverso":"Pregunta al cliente qué uso necesita; para público en general o sin obligaciones, S01 con régimen 616."},{"frente":"Facturaste PUE algo que te pagarán en 30 días","reverso":"Usa PPD con forma 99 y después emite el complemento."},{"frente":"Aplicaste 16% a la tortilla y al huevo","reverso":"Revisa la tasa de cada producto: muchos alimentos básicos van al 0%."},{"frente":"Olvidaste complementos de pago","reverso":"Revisa cada semana tu lista de facturas PPD cobradas."}]},{"tipo":"relacionar","rotulo":"Relaciona el problema con la prevención","pares":[["Datos del cliente equivocados","Pedir constancia de situación fiscal reciente"],["Ingreso declarado en el mes equivocado","Usar PPD y complemento cuando cobras después"],["Ventas sin factura que no quedan amparadas","Emitir la factura global a tiempo"],["Factura con monto equivocado","Revisar la vista previa antes de timbrar"]]},{"tipo":"plantilla","rotulo":"Checklist para pegar junto a la caja","texto":"1. ¿Tengo la constancia reciente del cliente?\n2. Nombre, RFC, código postal y régimen, tal cual la constancia.\n3. Uso del CFDI: el que me pidió el cliente.\n4. ¿Ya me pagó todo? Sí → PUE y forma real. No → PPD y forma 99.\n5. Tasa de IVA correcta en cada producto (16%, 0% o exento).\n6. Revisar la vista previa antes de timbrar.\n7. Enviar PDF y XML al cliente y guardar una copia.","nota":"Imprímelo o guárdalo como nota en tu celular."},{"tipo":"ordenar","rotulo":"Ordena la regla práctica","items":[{"frase":"Primero revisa la vista previa y después timbra","es":"Timbrar es cuando la factura queda registrada ante el SAT"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El archivo que tiene validez fiscal es…","ops":["El PDF","La captura de pantalla","El XML"],"correcta":2,"explica":"El PDF es una representación impresa; lo que vale ante el SAT es el XML timbrado."},{"p":"Tu sistema rechaza la factura por el régimen del receptor. Lo primero es…","ops":["Cambiar el RFC por el genérico","Revisar el régimen en la constancia del cliente","Poner el tuyo"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu error más frecuente","pregunta":"¿Cuál de estos errores te ha pasado (o le ha pasado a quien factura en tu negocio)? ¿Qué paso del checklist lo habría evitado?","ayuda":"Me ha pasado… Lo evito con…"},{"tipo":"clave","items":["La mayoría de los errores vienen de datos del cliente viejos o capturados de memoria.","PPD más complemento cuando cobras después; tasa de IVA correcta en cada producto.","Revisa la vista previa, timbra, envía PDF y XML y guarda tu copia."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"En CFDI 4.0, ¿qué datos del receptor deben coincidir con el SAT?","ops":["Solo el RFC","Solo el nombre comercial","El correo y el teléfono","Nombre, RFC, código postal y régimen fiscal"],"correcta":3},{"p":"A una persona moral se le factura con el nombre…","ops":["Con «S.A. de C.V.» siempre","Con el nombre del dueño","Como aparece en la constancia, sin el régimen societario","Con su nombre comercial"],"correcta":2},{"p":"Vas a cobrar una factura en dos pagos. El método de pago es…","ops":["CP01","PPD","PUE","S01"],"correcta":1},{"p":"El complemento de pago se emite…","ops":["A más tardar el día 5 del mes siguiente al pago","El mismo día de la factura","Solo si el cliente lo pide","Al final del año"],"correcta":0},{"p":"El uso del CFDI de la factura global es…","ops":["G03 · Gastos en general","G01 · Adquisición de mercancías","CP01 · Pagos","S01 · Sin efectos fiscales"],"correcta":3},{"p":"Una venta que no se realizó se cancela con el motivo…","ops":["02","04","03","01"],"correcta":2},{"p":"Tickets con IVA por $1,160 en total tienen una base sin IVA de…","ops":["$185.60","$1,000","$974.40","$1,160"],"correcta":1},{"p":"¿Cuál archivo tiene validez fiscal?","ops":["El XML timbrado","El PDF","La nota de venta a mano","El correo de envío"],"correcta":0}]}},{"id":"d-contabilidad-resico-m5","titulo":"Módulo 5 — Control y cumplimiento mes con mes","resumen":"Un registro de ingresos y gastos que sí vas a usar, la conciliación bancaria sencilla, el buzón tributario, tu calendario fiscal y cuándo conviene contratar a un contador. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-contabilidad-resico-m5-l1","titulo":"Lección 1 — Tu registro de ingresos y gastos","objetivo":"llevar un registro mensual de ingresos y gastos por categoría y detectar los gastos que no tienen factura.","bloques":[{"tipo":"texto","texto":"Todo lo que viste en este diplomado depende de una cosa: <b>anotar</b>. No necesitas un programa caro; una hoja de cálculo con seis columnas basta: <b>fecha, concepto, tipo</b> (ingreso o gasto), <b>categoría, monto</b> y <b>¿tiene CFDI?</b><br><br>La última columna es clave: en el RESICO tu ISR se calcula sobre ingresos sin restar gastos, pero las facturas de tus compras sí te sirven para <b>acreditar el IVA</b> y para demostrar de dónde salió tu mercancía."},{"tipo":"lista","items":["Anota <b>el mismo día</b>, o al menos cada noche: al final del mes ya no te acuerdas.","Usa <b>pocas categorías</b> (10 a 15) y siempre las mismas: Ventas, Insumos, Renta, Luz, Sueldos, Transporte, Publicidad…","Guarda el <b>XML</b> de cada factura de compra en una carpeta por mes.","Anota aparte tus <b>retiros personales</b>: no son gasto del negocio."]},{"tipo":"excel","rotulo":"Registro de octubre: Estética Bella","datos":[["Concepto","Tipo","Categoría","Monto","¿CFDI?","","Resumen","Valor"],["Servicios de la semana 1 y 2","Ingreso","Ventas",12400,"Sí","","Ingresos del mes",""],["Compra de tintes","Gasto","Insumos",3200,"Sí","","Insumos",""],["Renta del local","Gasto","Renta",7000,"Sí","","Gastos sin CFDI (número)",""],["Servicios a domicilio","Ingreso","Ventas",2600,"Sí","","Gastos sin CFDI (monto)",""],["Gasolina","Gasto","Transporte",900,"No","","ISR RESICO estimado (tasa 1%)",""],["Shampoo y tratamientos","Gasto","Insumos",1850,"No"],["Publicidad en redes","Gasto","Publicidad",600,"Sí"]],"retos":[{"celda":"H2","formula":"=SUMAR.SI(B2:B8,\"Ingreso\",D2:D8)","esperado":15000,"requiere":"SUMAR.SI(","texto":"<b>H2</b>: suma los ingresos del mes con SUMAR.SI."},{"celda":"H3","formula":"=SUMAR.SI(C2:C8,G3,D2:D8)","esperado":5050,"requiere":"SUMAR.SI(","texto":"<b>H3</b>: suma lo gastado en la categoría «Insumos» (está escrita en G3).","pista":"=SUMAR.SI(C2:C8,G3,D2:D8)"},{"celda":"H4","formula":"=CONTAR.SI.CONJUNTO(B2:B8,\"Gasto\",E2:E8,\"No\")","esperado":2,"requiere":"CONTAR.SI.CONJUNTO(","texto":"<b>H4</b>: cuenta los gastos que <b>no</b> tienen CFDI. Usa CONTAR.SI.CONJUNTO con dos condiciones: tipo «Gasto» y CFDI «No».","pista":"=CONTAR.SI.CONJUNTO(B2:B8,\"Gasto\",E2:E8,\"No\")"},{"celda":"H5","formula":"=SUMAR.SI.CONJUNTO(D2:D8,B2:B8,\"Gasto\",E2:E8,\"No\")","esperado":2750,"requiere":"SUMAR.SI.CONJUNTO(","texto":"<b>H5</b>: suma el monto de esos gastos sin CFDI con SUMAR.SI.CONJUNTO (primero va el rango que sumas).","explica":"Son $2,750 de compras cuyo IVA no podrá acreditar. Pedir factura en la gasolinera y con el proveedor de shampoo le ahorra dinero."},{"celda":"H6","formula":"=H2*0.01","esperado":150,"texto":"<b>H6</b>: con $15,000 cobrados (renglón de hasta $25,000), el ISR RESICO estimado es 1% de los ingresos."}]},{"tipo":"comparar","titulo":"Dos formas de llevar las cuentas","malTitulo":"La libreta que nadie suma","mal":"Anota en una libreta cuando se acuerda, mezcla gastos de la casa y del negocio, y a fin de mes no sabe cuánto facturó.","bienTitulo":"La hoja de 6 columnas","bien":"Anota cada noche, usa las mismas categorías, separa retiros y en 5 minutos sabe cuánto cobró, cuánto gastó y cuánto apartar para impuestos."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La columna «¿tiene CFDI?» te sirve para…","ops":["Saber qué compras te permiten acreditar IVA","Calcular tu margen","Saber cuántos clientes tienes"],"correcta":0},{"p":"Pagar la luz de tu casa con dinero del negocio se anota como…","ops":["Gasto de luz del negocio","Insumo","Retiro personal"],"correcta":2},{"p":"Para sumar con dos condiciones (tipo y CFDI) usas…","ops":["PROMEDIO","SUMAR.SI.CONJUNTO","SUMA"],"correcta":1}]},{"tipo":"clave","items":["Seis columnas bastan: fecha, concepto, tipo, categoría, monto y ¿tiene CFDI?","SUMAR.SI por categoría y SUMAR.SI.CONJUNTO con dos condiciones te dan el resumen del mes.","Pide factura de tus compras: sin CFDI no acreditas el IVA."]}]},{"id":"d-contabilidad-resico-m5-l2","titulo":"Lección 2 — Conciliación bancaria sencilla","objetivo":"comparar tu registro con el estado de cuenta del banco y explicar las diferencias.","bloques":[{"tipo":"texto","texto":"Casi nunca coinciden el saldo de tu registro y el del estado de cuenta. No siempre es un error: hay movimientos que tú ya anotaste y el banco todavía no refleja, y cargos del banco que tú no has anotado. <b>Conciliar</b> es explicar cada diferencia hasta que los dos saldos cuadren."},{"tipo":"tabla","titulo":"Las diferencias típicas","encabezados":["Partida","Qué es","Qué haces"],"filas":[["<b>Depósito en tránsito</b>","Lo anotaste, pero el banco aún no lo refleja (por ejemplo, depositaste el último día)","Se suma al saldo del banco"],["<b>Pago o cheque pendiente de cobro</b>","Lo anotaste, pero aún no sale del banco","Se resta al saldo del banco"],["<b>Comisiones del banco</b>","El banco las cobró y tú no las anotaste","Se restan a tu registro (y las anotas)"],["<b>Depósitos no identificados</b>","Te depositaron y no sabes quién ni por qué","Investiga: puede ser un cobro que debes facturar"]]},{"tipo":"excel","rotulo":"Conciliación de octubre: Papelería La Estrella","datos":[["Concepto","Monto"],["Saldo según estado de cuenta",48250],["Más: depósito en tránsito del 31 de octubre",2000],["Menos: pago al proveedor aún no cobrado",3800],["Saldo del banco ajustado",""],["Saldo según mi registro",46600],["Menos: comisiones del banco no anotadas",150],["Saldo de mi registro ajustado",""],["Diferencia",""],["Estado",""]],"retos":[{"celda":"B5","formula":"=B2+B3-B4","esperado":46450,"texto":"<b>B5</b>: saldo del banco ajustado: saldo del estado de cuenta más depósito en tránsito menos pago pendiente."},{"celda":"B8","formula":"=B6-B7","esperado":46450,"texto":"<b>B8</b>: saldo de tu registro ajustado: tu saldo menos las comisiones que no habías anotado."},{"celda":"B9","formula":"=B5-B8","esperado":0,"texto":"<b>B9</b>: calcula la diferencia entre los dos saldos ajustados."},{"celda":"B10","formula":"=SI(ABS(B9)<1,\"Conciliado\",\"Revisar\")","esperado":"Conciliado","requiere":"ABS(","texto":"<b>B10</b>: SI el valor absoluto de la diferencia es menor que 1, «Conciliado»; si no, «Revisar». Usa SI con ABS.","pista":"=SI(ABS(B9)<1,\"Conciliado\",\"Revisar\")","explica":"Con ABS da igual si la diferencia es positiva o negativa: lo que importa es que sea casi cero."}]},{"tipo":"pasos","rotulo":"Rutina mensual de conciliación","pasos":["Descarga el estado de cuenta del mes.","Marca en tu registro cada movimiento que sí aparece en el banco.","Lo que quedó sin marcar en tu registro son partidas en tránsito o pendientes.","Lo que quedó sin marcar en el banco (comisiones, depósitos no identificados) anótalo o investígalo.","Arma la conciliación y confirma que la diferencia sea cero."]},{"tipo":"destacado","texto":"<b>Ojo con los depósitos:</b> el SAT recibe información de tus cuentas bancarias. Si te depositan por ventas y no las facturas ni las declaras, tus depósitos no van a cuadrar con tus ingresos declarados. Separar una cuenta solo para el negocio te facilita todo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Depositaste $5,000 el 31 y el banco lo refleja el día 1. En la conciliación es…","ops":["Un depósito en tránsito","Una comisión","Un error del banco"],"correcta":0},{"p":"La comisión por manejo de cuenta que no anotaste se…","ops":["Suma al saldo del banco","Ignora","Resta a tu registro y la anotas"],"correcta":2}]},{"tipo":"clave","items":["Conciliar es explicar cada diferencia entre tu registro y el banco.","Depósitos en tránsito se suman al banco; pagos pendientes se restan; comisiones se restan a tu registro.","Usa una cuenta solo para el negocio e investiga los depósitos no identificados."]}]},{"id":"d-contabilidad-resico-m5-l3","titulo":"Lección 3 — Buzón tributario y calendario fiscal","objetivo":"mantener activo tu buzón tributario y organizar tus fechas fiscales del mes y del año.","bloques":[{"tipo":"texto","texto":"El <b>buzón tributario</b> es tu «correo oficial» con el SAT, dentro del portal. Por ahí te avisa de requerimientos, invitaciones, multas y resoluciones. En el RESICO tenerlo habilitado es obligatorio.<br><br>Lo importante: si el SAT te deja una notificación y no la abres, <b>en pocos días se te tiene por notificado de todas formas</b> (así lo prevé el Código Fiscal de la Federación). Ignorar el buzón no detiene los plazos."},{"tipo":"pasos","rotulo":"Cómo tener el buzón en orden","pasos":["Entra al portal del SAT con tu RFC y contraseña o e.firma.","Busca la opción de <b>buzón tributario</b> y registra tus <b>medios de contacto</b>: correo electrónico y número de celular.","Confirma el correo con el código que te llega.","Pon un recordatorio para revisar el buzón <b>cada semana</b>, aunque no te llegue aviso."]},{"tipo":"tabla","titulo":"Tu calendario fiscal (persona física en el RESICO)","encabezados":["Cuándo","Qué"],"filas":[["Dentro de las 24 horas siguientes al cierre del periodo","Factura global de ventas al público en general"],["A más tardar el día 5 de cada mes","Complementos de pago de lo cobrado el mes anterior"],["A más tardar el día 17 de cada mes","Pago mensual de ISR RESICO e IVA del mes anterior (y retenciones de ISR de tus trabajadores, si tienes)"],["Cada semana","Revisar buzón tributario y facturas PPD cobradas"],["Abril","Declaración anual de personas físicas"],["Antes de que venza (cada 4 años)","Renovar tu e.firma"]],"nota":"Pueden existir otras obligaciones según tu caso (declaraciones informativas, cuotas del IMSS si tienes trabajadores, impuestos locales como el impuesto sobre nómina). Verifica en el SAT y con tu contador cuáles te aplican."},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El pago mensual del RESICO se presenta a más tardar el día ___ del mes siguiente.","resp":["17","diecisiete"]},{"frase":"Tu medio oficial de comunicación con el SAT se llama buzón ___.","resp":["tributario"]},{"frase":"La e.firma debe renovarse cada ___ años.","resp":["4","cuatro"]}]},{"tipo":"ordenar","rotulo":"Ordena tu rutina del mes","items":[{"frase":"Día 5 complementos y día 17 impuestos","es":"Dos fechas fijas cada mes"}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si no abres una notificación del buzón tributario…","ops":["El SAT te la manda por correo postal","Igual se te tiene por notificado en pocos días","El plazo nunca empieza"],"correcta":1},{"p":"En el RESICO el buzón tributario es…","ops":["Obligatorio","Opcional","Solo para personas morales"],"correcta":0}]},{"tipo":"clave","items":["El buzón tributario es obligatorio en el RESICO; ignorarlo no detiene los plazos.","Fechas fijas: día 5 complementos, día 17 impuestos, abril la anual.","Revisa el buzón cada semana y renueva tu e.firma antes de que venza."]}]},{"id":"d-contabilidad-resico-m5-l4","titulo":"Lección 4 — Cuándo contratar a un contador (y cómo aprovecharlo)","objetivo":"decidir en qué momento conviene contratar a un contador y qué información entregarle para que te rinda.","bloques":[{"tipo":"texto","texto":"Con lo que aprendiste puedes entender tus números, llevar tu registro, facturar bien y revisar tus pagos. Pero hay situaciones en las que <b>un contador público no es un lujo sino un ahorro</b>: un error fiscal puede costar recargos, multas o salir del RESICO."},{"tipo":"lista","items":["Tus ingresos se acercan al límite de <b>$3.5 millones</b> anuales o piensas cambiar de régimen.","Vas a <b>contratar trabajadores</b> (nómina, IMSS, retenciones).","Vendes productos con <b>tasas mixtas</b> de IVA o exportas.","Recibiste un <b>requerimiento, carta invitación o multa</b> del SAT.","Te vas a asociar o vas a formar una <b>sociedad</b>.","Tienes <b>saldos a favor</b> de IVA que quieres recuperar.","Simplemente no tienes tiempo y prefieres dedicarte a vender."]},{"tipo":"comparar","titulo":"Cómo trabajar con tu contador","malTitulo":"Así no","mal":"Le mandas por WhatsApp fotos de tickets el día 16, no sabes qué declaró y nunca ves los acuses.","bienTitulo":"Así sí","bien":"Cada día 5 le envías tu registro del mes, tus XML y tu estado de cuenta; él te manda la línea de captura y el acuse, y tú los guardas."},{"tipo":"plantilla","rotulo":"Paquete mensual para tu contador","texto":"Mes: ____\n1. Registro de ingresos y gastos (hoja de cálculo).\n2. XML de facturas emitidas y recibidas.\n3. Complementos de pago emitidos.\n4. Estado de cuenta bancario y conciliación.\n5. CFDI de retenciones que te hicieron personas morales.\n6. Dudas o cambios del mes (nuevo cliente grande, contratación, compra de equipo).","nota":"Pídele siempre: acuse de la declaración, línea de captura y comprobante de pago."},{"tipo":"relacionar","rotulo":"¿Qué te toca a ti y qué al contador?","pares":[["Anotar cada día ingresos y gastos","Tú"],["Presentar la declaración con tu autorización","El contador"],["Guardar acuses y comprobantes de pago","Ambos"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Recibiste una carta invitación del SAT por diferencias en tus depósitos. Lo más sensato es…","ops":["Ignorarla","Cerrar tu cuenta bancaria","Revisarla pronto con un contador"],"correcta":2},{"p":"Aunque tengas contador, conviene que tú…","ops":["Dejes de anotar tus ventas","Veas los acuses y entiendas qué se declaró","Le des tu e.firma sin preguntar"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu plan de cumplimiento","pregunta":"Escribe tres acciones concretas que harás este mes para tener tus números y tus impuestos en orden (por ejemplo: abrir cuenta solo del negocio, pedir constancias a mis clientes frecuentes, buscar contador).","ayuda":"1… 2… 3…"},{"tipo":"clave","items":["Un contador conviene cuando creces, contratas, tienes IVA complejo o recibes algo del SAT.","Entrégale un paquete mensual ordenado y pide siempre acuses y líneas de captura.","Aunque delegues, la responsabilidad fiscal sigue siendo tuya: entiende qué se declara."]}]}],"quiz":{"titulo":"Evaluación del módulo 5","preguntas":[{"p":"Para sumar los gastos de una categoría en tu registro usas…","ops":["CONTAR","LARGO","MAYUSC","SUMAR.SI"],"correcta":3},{"p":"La columna «¿tiene CFDI?» te ayuda sobre todo a…","ops":["Conciliar el banco","Fijar precios","Saber qué IVA de compras puedes acreditar","Calcular el ISR RESICO"],"correcta":2},{"p":"Un depósito que anotaste pero el banco aún no refleja es…","ops":["Un depósito no identificado","Un depósito en tránsito","Una comisión","Un pago pendiente"],"correcta":1},{"p":"Saldo del banco $30,000, depósito en tránsito $1,500 y pago pendiente $2,500. El saldo del banco ajustado es…","ops":["$29,000","$34,000","$31,500","$27,500"],"correcta":0},{"p":"El buzón tributario…","ops":["Es opcional","Solo recibe felicitaciones","Se revisa una vez al año","Es obligatorio en el RESICO y no abrirlo no detiene los plazos"],"correcta":3},{"p":"El pago mensual de ISR RESICO e IVA vence…","ops":["El último día hábil del mes","En abril","El día 17 del mes siguiente","El día 5 del mes siguiente"],"correcta":2},{"p":"¿Cuál situación es una señal clara para contratar contador?","ops":["Compraste papelería","Vas a contratar a tu primer trabajador","Vendiste más que ayer","Cambiaste el logo"],"correcta":1},{"p":"Aunque tengas contador, la responsabilidad de tus obligaciones fiscales es…","ops":["Tuya","Solo del contador","Del banco","Del SAT"],"correcta":0}]}}]});
window.CURSOS_MARA.push({"id":"c-atencion-ventas","nombre":"Atención al cliente y ventas","color":"#0891B2","nivel":"Cursos libres de capacitación","familia":"Negocios y finanzas","periodoTipo":null,"periodoNum":null,"desc":"Aprende a atender en mostrador, por teléfono y por WhatsApp, a resolver quejas con calma, a vender preguntando en lugar de presionar y a medir tus resultados con indicadores sencillos. Incluye guiones y plantillas listas para usar en tu trabajo.","horas":12,"precio":790,"publicado":true,"proximamente":false,"modulos":[{"id":"c-atencion-ventas-m1","titulo":"Módulo 1 — El servicio que el cliente recuerda","resumen":"Momentos de verdad, expectativas del cliente, lenguaje positivo y cómo atender bien en mostrador, por teléfono y por WhatsApp. Tres lecciones y una evaluación.","lecciones":[{"id":"c-atencion-ventas-m1-l1","titulo":"Lección 1 — Momentos de verdad y expectativas","objetivo":"explicar qué es un momento de verdad, de dónde salen las expectativas del cliente y por qué la experiencia se juzga completa, no por partes.","bloques":[{"tipo":"destacado","texto":"<b>Antes de empezar, con claridad.</b> Este es un <b>curso libre de capacitación</b>. Al terminarlo recibes una <b>constancia de Instituto Mara</b>, que <b>no</b> es un documento oficial de la SEP ni una certificación de CONOCER. Su valor está en lo que vas a poder hacer mejor en tu trabajo desde mañana: atender, resolver quejas y vender sin presionar."},{"tipo":"texto","texto":"Jan Carlzon, director de la aerolínea escandinava SAS en los años ochenta, popularizó la idea de los <b>momentos de verdad</b>: cada instante en que un cliente tiene contacto con tu negocio y se forma una opinión. No solo cuando lo atiendes tú: también cuando ve tu anuncio, busca estacionamiento, espera en la fila, lee tu respuesta en WhatsApp o revisa su ticket. En una farmacia, por ejemplo, pueden ser diez o doce momentos en una visita de cinco minutos."},{"tipo":"tabla","titulo":"Los momentos de verdad en un taller mecánico","encabezados":["Momento","Lo que el cliente nota"],"filas":[["Antes de llegar","Si le contestaron el teléfono, si el taller tiene reseñas y ubicación clara en el mapa."],["La recepción del auto","Si lo saludan, si revisan el auto con él y le dan un folio o nota de recepción."],["El diagnóstico","Si le explican con palabras sencillas y le dan un presupuesto por escrito antes de trabajar."],["La espera","Si le avisan avances o tiene que llamar él cada día para preguntar."],["La entrega","Si el auto está limpio, le muestran las piezas cambiadas y el cobro coincide con lo acordado."],["Después","Si le escriben a la semana para saber cómo sigue el auto."]],"nota":"Basta un momento malo para arruinar varios buenos: el cliente recuerda el conjunto como una sola experiencia."},{"tipo":"texto","texto":"Las <b>expectativas</b> son lo que el cliente espera antes de llegar. Salen de su experiencia pasada, de lo que le contaron, de tu publicidad y de lo que le prometes tú. La satisfacción depende de la distancia entre lo que esperaba y lo que recibió. Por eso <b>prometer de más es peligroso</b>: «te lo entregamos mañana» y entregar pasado mañana se siente peor que decir «pasado mañana» y cumplir."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un momento de verdad es…","ops":["Cualquier contacto del cliente con tu negocio en el que se forma una opinión","Solo el momento en que paga","Una promoción de temporada"],"correcta":0,"explica":"Incluye anuncios, filas, mensajes, llamadas y hasta el estacionamiento."},{"p":"Si prometes entrega en 2 días y entregas en 3, el cliente…","ops":["No nota nada","Queda más contento","Se siente decepcionado aunque 3 días sea razonable"],"correcta":2,"explica":"La satisfacción se mide contra lo que esperaba, y la expectativa la pusiste tú."},{"p":"Las expectativas del cliente se forman con…","ops":["Lo que decida el gerente","Experiencias pasadas, recomendaciones, publicidad y tus promesas","Solo el precio"],"correcta":1,"explica":"Por eso tu publicidad y tus palabras deben ser realistas."}]},{"tipo":"relacionar","rotulo":"Relaciona el momento con el negocio","pares":[["El cliente espera su turno viendo si la fila avanza","Caja de un banco"],["Recibe el presupuesto por escrito antes de la reparación","Taller mecánico"],["Le explican cada cuánto tomar el medicamento","Farmacia"],["Le preguntan si todo estuvo bien antes de traer la cuenta","Restaurante"],["Recibe foto del producto y precio total por mensaje","Venta por WhatsApp"]]},{"tipo":"reflexion","rotulo":"Tu mapa de momentos de verdad","pregunta":"Piensa en tu trabajo. Enumera los momentos de verdad que vive tu cliente desde que te busca hasta después de comprar. ¿Cuál crees que hoy es el más débil?","ayuda":"Mis momentos de verdad son… El más débil es… porque…"},{"tipo":"clave","items":["Un momento de verdad es cada contacto en que el cliente se forma una opinión.","La satisfacción es la distancia entre lo esperado y lo recibido: promete lo que puedes cumplir.","La constancia del curso es de Instituto Mara (no SEP ni CONOCER)."]}]},{"id":"c-atencion-ventas-m1-l2","titulo":"Lección 2 — Primera impresión y lenguaje positivo","objetivo":"aplicar un saludo efectivo y cambiar frases negativas o frías por lenguaje positivo sin mentirle al cliente.","bloques":[{"tipo":"texto","texto":"La primera impresión se forma en segundos: tu mirada, tu postura, si dejas el celular, si saludas primero. No necesitas un guion robótico; necesitas <b>cuatro cosas</b>: reconocer al cliente en cuanto llega (aunque estés ocupado), saludar con amabilidad, presentarte o identificarte y ofrecer ayuda con una pregunta abierta."},{"tipo":"plantilla","rotulo":"Saludo en mostrador o piso de venta","texto":"Buenas tardes, bienvenido(a) a [nombre del negocio]. Soy [tu nombre]. ¿En qué te puedo ayudar hoy?\n\nSi estás atendiendo a otra persona:\nBuenas tardes, en un momento estoy contigo. Gracias por esperar.","nota":"Ajusta el «tú» o «usted» a tu negocio y a la persona. Con clientes mayores o en bancos, «usted» suele ser lo más seguro."},{"tipo":"texto","texto":"El <b>lenguaje positivo</b> no es decir que todo se puede. Es decir <b>lo que sí puedes hacer</b> en lugar de solo lo que no. La información es la misma; cambia cómo se siente el cliente y qué hace después."},{"tipo":"comparar","titulo":"Frases que cierran y frases que abren","malTitulo":"Lenguaje negativo o frío","mal":"«No hay.»<br>«No se puede, son políticas.»<br>«Eso no me toca a mí.»<br>«Tiene que llenar este formato.»<br>«No sé.»","bienTitulo":"Lenguaje positivo","bien":"«Ese modelo se agotó; lo esperamos el jueves. ¿Te lo aparto o te muestro uno parecido?»<br>«Lo que sí puedo hacer es…»<br>«Te llevo con la persona que lo resuelve.»<br>«Para avanzar, solo necesito que llenes este formato; te ayudo.»<br>«Déjame averiguarlo y te confirmo en diez minutos.»"},{"tipo":"completar","rotulo":"Completa con lenguaje positivo","items":[{"frase":"En vez de «no sé», di: «Déjame ___ y te confirmo».","resp":["averiguarlo","investigarlo","revisarlo","checarlo"],"es":"Y cumple con confirmar."},{"frase":"En vez de «no se puede», empieza con: «Lo que sí puedo ___ es…».","resp":["hacer","ofrecerte"]},{"frase":"Reconoce al cliente en cuanto llega, aunque estés ___ con otra persona.","resp":["ocupado","ocupada","atendiendo"]}]},{"tipo":"practica","rotulo":"¿Cuál suena mejor?","preguntas":[{"p":"Un cliente pide una talla que no hay.","ops":["«No hay, ya se acabó.»","«Esa talla se acabó; puedo pedirla a otra sucursal y te llega en dos días. ¿Te parece?»"],"correcta":1,"explica":"Das la misma mala noticia, pero con una salida."},{"p":"Te preguntan algo que no sabes.","ops":["«Buena pregunta; lo confirmo con mi gerente y te digo en cinco minutos.»","«Ni idea, pregúntele a otro.»"],"correcta":0},{"p":"El sistema está caído y no puedes cobrar con tarjeta.","ops":["«El sistema no sirve, ni modo.»","«En este momento solo podemos recibir efectivo o transferencia; si prefieres tarjeta, te aparto la compra mientras se restablece.»"],"correcta":1,"explica":"Lenguaje positivo es honesto: explicas lo que pasa y ofreces opciones reales."}]},{"tipo":"clave","items":["Reconoce al cliente en cuanto llega, saluda, identifícate y pregunta en qué ayudar.","Lenguaje positivo: di lo que sí puedes hacer, sin mentir.","«Déjame averiguarlo» solo funciona si de verdad regresas con la respuesta."]}]},{"id":"c-atencion-ventas-m1-l3","titulo":"Lección 3 — Atención presencial, por teléfono y por WhatsApp","objetivo":"adaptar la atención a cada canal con guiones y reglas prácticas para mostrador, llamada y mensaje.","bloques":[{"tipo":"texto","texto":"Lo que el cliente espera cambia según el canal. En persona ve tu cara y tu lenguaje corporal; por teléfono solo escucha tu <b>voz</b>; por WhatsApp solo lee tus <b>palabras</b> y cuánto tardas en contestar. Un «ok» seco que en persona acompañarías con una sonrisa, por mensaje puede leerse como molestia."},{"tipo":"tabla","titulo":"Reglas básicas por canal","encabezados":["Canal","Haz","Evita"],"filas":[["Presencial","Contacto visual, deja el celular, acompaña al cliente al producto en vez de solo señalar.","Platicar con compañeros mientras el cliente espera; atender viendo la pantalla."],["Teléfono","Contesta antes del tercer timbre, identifícate, sonríe al hablar (se nota), pide permiso antes de dejar en espera.","Dejar en espera más de un minuto sin volver; transferir sin explicar a dónde."],["WhatsApp","Responde rápido aunque sea para avisar que revisas; mensajes cortos; precio total y datos claros; confirma por escrito lo acordado.","Audios largos sin preguntar; solo «ok» o «sí»; dejar en visto; mandar diez mensajes seguidos."]]},{"tipo":"plantilla","rotulo":"Guion telefónico básico","texto":"Contestar:\n[Nombre del negocio], buenos días, le atiende [tu nombre]. ¿En qué le puedo ayudar?\n\nSi necesitas dejarlo en espera:\n¿Me permite un minuto en la línea mientras reviso el sistema?\n(Al volver) Gracias por esperar, ya tengo la información.\n\nSi debes transferir:\nLe voy a comunicar con [nombre o área], que es quien le puede resolver. Si se corta la llamada, el número directo es [número].\n\nCerrar:\n¿Hay algo más en lo que le pueda ayudar? Gracias por llamar a [nombre del negocio], que tenga buen día."},{"tipo":"plantilla","rotulo":"Primera respuesta por WhatsApp","texto":"¡Hola, [nombre]! Gracias por escribir a [nombre del negocio]. Soy [tu nombre].\nCon gusto te ayudo. Para darte el precio exacto, ¿me confirmas el modelo (o la medida) que buscas?\n\nSi vas a tardar:\nEstoy revisando existencias en bodega; en máximo 15 minutos te confirmo.","nota":"Si el negocio usa respuesta automática fuera de horario, di cuándo contestará una persona: «Te respondemos mañana a partir de las 9:00»."},{"tipo":"ordenar","rotulo":"Ordena la regla de oro de WhatsApp","items":[{"frase":"Contesta rápido aunque sea para decir que revisas","es":"El silencio se lee como desinterés"},{"frase":"Confirma por escrito precio total y fecha de entrega","es":"Evita malentendidos después"}]},{"tipo":"practica","rotulo":"¿Qué harías?","preguntas":[{"p":"Un cliente escribe por WhatsApp a las 11:00 y tú estás con otro cliente en mostrador.","ops":["Le mandas un mensaje breve: «Hola, en 10 minutos te atiendo» y cumples","Lo dejas en visto hasta la tarde"],"correcta":0,"explica":"Un mensaje de acuse baja la ansiedad del cliente y evita que le escriba a la competencia."},{"p":"Por teléfono necesitas revisar algo que tomará tres minutos.","ops":["Lo dejas en espera sin avisar","Ofreces devolver la llamada en cinco minutos a un número que confirmas"],"correcta":1,"explica":"Más de un minuto en espera se siente eterno; mejor devolver la llamada."},{"p":"Un cliente de la tienda departamental pregunta dónde están las toallas.","ops":["Lo acompañas o lo llevas hasta el pasillo","Le señalas vagamente al fondo"],"correcta":0}]},{"tipo":"clave","items":["Cada canal tiene sus reglas: en persona cuenta el cuerpo, por teléfono la voz, por WhatsApp las palabras y la rapidez.","Pide permiso antes de dejar en espera y no pases de un minuto.","Por mensaje, confirma por escrito precio total, fecha y lo acordado."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"Un «momento de verdad» es…","ops":["El momento en que se cierra la venta","Una auditoría interna","El día de la inauguración","Cualquier contacto en que el cliente se forma una opinión de tu negocio"],"correcta":3},{"p":"La satisfacción del cliente depende principalmente de…","ops":["Solo de la decoración del local","Cuántos empleados hay","La diferencia entre lo que esperaba y lo que recibió","Solo del precio"],"correcta":2},{"p":"¿Qué es más recomendable?","ops":["Prometer lo que pida el cliente","Prometer lo que puedes cumplir y, si se puede, superarlo","Prometer de más para asegurar la venta","No prometer nada nunca"],"correcta":1},{"p":"Un ejemplo de lenguaje positivo es…","ops":["«Se agotó; llega el jueves. ¿Te lo aparto?»","«No hay.»","«Son políticas.»","«Eso no me toca.»"],"correcta":0},{"p":"Si estás atendiendo a alguien y llega otro cliente, lo mejor es…","ops":["Ignorarlo hasta terminar","Dejar al primero para atender al segundo","Pedirle que regrese otro día","Reconocerlo con un saludo y decirle que en un momento lo atiendes"],"correcta":3},{"p":"Antes de dejar a alguien en espera por teléfono debes…","ops":["Colgar y esperar que vuelva a llamar","Transferir a cualquier extensión","Pedir permiso y volver en menos de un minuto o devolver la llamada","Poner la llamada en espera sin decir nada"],"correcta":2},{"p":"Por WhatsApp, una buena práctica es…","ops":["Contestar al día siguiente siempre","Confirmar por escrito el precio total y la fecha de entrega","Mandar audios de cinco minutos","Responder solo «ok»"],"correcta":1},{"p":"La constancia de este curso es emitida por…","ops":["Instituto Mara, como curso libre de capacitación","La SEP, con validez oficial","CONOCER, como certificación de competencias","PROFECO"],"correcta":0}]}},{"id":"c-atencion-ventas-m2","titulo":"Módulo 2 — Clientes molestos y quejas","resumen":"Escucha activa y empatía, un método de cuatro pasos para atender quejas, qué frases evitar, cuándo escalar y los derechos básicos del consumidor ante PROFECO. Tres lecciones y una evaluación.","lecciones":[{"id":"c-atencion-ventas-m2-l1","titulo":"Lección 1 — Escucha activa y empatía","objetivo":"usar la escucha activa y frases de empatía para bajar la tensión de un cliente molesto antes de buscar la solución.","bloques":[{"tipo":"texto","texto":"Un cliente molesto casi nunca está enojado contigo como persona: está enojado con la situación (el cobro doble, el auto que sigue fallando, la medicina que no llegó). Si lo tomas personal, te defiendes; si te defiendes, él sube el tono. La primera tarea no es resolver: es que <b>se sienta escuchado</b>. Mientras una persona siente que no la escuchan, no puede oír ninguna solución."},{"tipo":"lista","items":["<b>Deja que termine.</b> No interrumpas aunque ya sepas qué va a decir.","<b>Muestra que escuchas:</b> asiente, mira a los ojos, di «ajá», «entiendo», toma notas.","<b>Parafrasea:</b> repite con tus palabras lo que entendiste: «Entonces te cobraron dos veces la misma compra, ¿es correcto?».","<b>Nombra la emoción sin juzgarla:</b> «Entiendo que estés molesto; yo también lo estaría».","<b>Pregunta para completar:</b> fecha, número de ticket, qué esperaba que pasara."]},{"tipo":"destacado","texto":"<b>Empatía no es darle la razón en todo.</b> Es reconocer cómo se siente. Puedes decir «entiendo tu molestia» aunque después le expliques que el producto no tiene garantía por mal uso. Lo que baja la tensión es sentirse comprendido, no que le digas que sí a todo."},{"tipo":"comparar","titulo":"La misma queja, dos respuestas","malTitulo":"Respuesta que enciende","mal":"Cliente: «¡Es la tercera vez que vengo por lo mismo!»<br>Empleado: «Pues yo no lo atendí las otras veces. Además, cálmese, así no le puedo ayudar.»","bienTitulo":"Respuesta que calma","bien":"Cliente: «¡Es la tercera vez que vengo por lo mismo!»<br>Empleado: «Tiene toda la razón en estar molesto: tres vueltas es demasiado. Cuénteme qué pasó cada vez y hoy me encargo yo personalmente de darle seguimiento.»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Parafrasear significa…","ops":["Repetir con tus palabras lo que entendiste para confirmarlo","Contestar con una frase hecha","Cambiar de tema"],"correcta":0,"explica":"Además de confirmar datos, demuestra que sí pusiste atención."},{"p":"Decir «cálmese» a alguien muy molesto suele…","ops":["Tranquilizarlo de inmediato","Ser la mejor forma de empezar","Enojarlo más, porque se siente juzgado"],"correcta":2,"explica":"Mejor nombra la emoción: «Entiendo que estés molesto»."},{"p":"Mostrar empatía significa…","ops":["Contarle tus propios problemas","Reconocer cómo se siente el cliente","Darle la razón en todo y regalarle algo"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa la frase de escucha activa","items":[{"frase":"«Entonces, si entendí bien, te cobraron dos ___ la misma compra, ¿es correcto?»","resp":["veces"],"es":"Parafrasear confirma los datos."},{"frase":"«Entiendo que estés ___; yo también lo estaría.»","resp":["molesto","molesta","enojado","enojada"]}]},{"tipo":"clave","items":["Primero que se sienta escuchado; después la solución.","Escucha activa: dejar terminar, mostrar atención, parafrasear, nombrar la emoción y preguntar.","Empatía es reconocer lo que siente, no darle la razón en todo."]}]},{"id":"c-atencion-ventas-m2-l2","titulo":"Lección 2 — Un método para atender quejas","objetivo":"aplicar un método de cuatro pasos (escuchar, disculparse, solucionar y agradecer) y saber qué frases evitar y cuándo escalar.","bloques":[{"tipo":"texto","texto":"Muchas empresas usan métodos con siglas en inglés, como <b>LAST</b> (<i>Listen, Apologize, Solve, Thank</i>) o <b>HEARD</b> (<i>Hear, Empathize, Apologize, Resolve, Diagnose</i>). Todos dicen lo mismo con distintas palabras. Aquí lo usamos en cuatro pasos fáciles de recordar: <b>Escuchar, Disculparse, Solucionar y Agradecer</b>. Después del agradecimiento, <b>anota la causa</b> para que no se repita."},{"tipo":"pasos","rotulo":"Los cuatro pasos ante una queja","pasos":["<b>Escuchar:</b> deja que cuente todo, parafrasea y confirma los datos (ticket, fecha, producto).","<b>Disculparse:</b> una disculpa sincera por la molestia, sin culpar a otros: «Lamento mucho que hayas tenido que regresar». Disculparte por cómo se siente no es aceptar culpa legal.","<b>Solucionar:</b> ofrece lo que sí puedes hacer, con opciones si es posible, y di cuándo quedará resuelto. Si no está en tus manos, escala y di a quién y cuándo.","<b>Agradecer:</b> «Gracias por decírnoslo; nos ayuda a mejorar». Quien se queja te da la oportunidad de corregir; la mayoría de los inconformes simplemente se va.","<b>Anotar y corregir la causa:</b> registra la queja y avisa a quien pueda evitar que vuelva a pasar."]},{"tipo":"plantilla","rotulo":"Respuesta a una queja por WhatsApp","texto":"Hola, [nombre]. Gracias por escribirnos y lamento mucho que tu pedido llegara incompleto; entiendo la molestia, sobre todo si lo necesitabas hoy.\n\nYa revisé tu pedido [número]: faltaron [producto]. Te propongo dos opciones:\n1) Te lo enviamos sin costo mañana antes de las 14:00.\n2) Te reembolsamos [monto] a tu mismo método de pago.\n\n¿Cuál prefieres? En cuanto me confirmes, te mando el número de guía o el comprobante.\nGracias por avisarnos; ya lo reportamos para que no vuelva a pasar.","nota":"Evita copiar y pegar la misma respuesta a todos: usa el nombre del cliente y los datos reales de su caso."},{"tipo":"tabla","titulo":"Frases que conviene evitar","encabezados":["Evita","Mejor di"],"filas":[["«Cálmese.»","«Entiendo que esté molesto; vamos a resolverlo.»"],["«Son políticas de la empresa.»","«Lo que sí puedo ofrecerte es…» y explica el motivo."],["«Eso no es mi área.»","«Te comunico con quien lo resuelve y me aseguro de que te atienda.»"],["«Es que el sistema…» o «es que mi compañero…»","Una disculpa sin culpar y la solución."],["«Nadie más se ha quejado.»","«Gracias por avisarnos; lo vamos a revisar.»"]]},{"tipo":"destacado","texto":"<b>¿Cuándo escalar?</b> Pasa el caso a tu supervisor cuando la solución que pide el cliente está fuera de tu autorización (un reembolso mayor, una excepción), cuando ya hubo dos intentos fallidos, cuando el cliente lo pide expresamente o cuando hay insultos o amenazas. Escalar no es rendirse: preséntale el caso a tu supervisor para que el cliente no tenga que repetir todo."},{"tipo":"ordenar","rotulo":"Ordena los pasos del método","items":[{"frase":"Escuchar disculparse solucionar y agradecer","es":"Y al final, anotar la causa"}]},{"tipo":"practica","rotulo":"¿Qué paso falta?","preguntas":[{"p":"El empleado escuchó, se disculpó y resolvió, pero el cliente se fue sin que le dijeran nada más.","ops":["Agradecer","Escuchar","Escalar"],"correcta":0,"explica":"Agradecer cierra bien y convierte la queja en algo positivo."},{"p":"El cliente sigue gritando y el empleado ya le está explicando la solución.","ops":["Dar más opciones","Escuchar y calmar primero"],"correcta":1,"explica":"Si no se siente escuchado, no oirá la solución."},{"p":"El cliente pide un reembolso mayor al que el cajero está autorizado a dar.","ops":["Escalar al supervisor explicándole el caso","Decirle que no se puede y despedirse"],"correcta":0,"explica":"Escala sin que el cliente tenga que repetir su historia."},{"p":"Un cliente amenaza con golpear al empleado.","ops":["Seguir con el método como si nada","Pedir apoyo de inmediato al supervisor o a seguridad"],"correcta":1,"explica":"Tu seguridad va primero."}]},{"tipo":"clave","items":["Escuchar, Disculparse, Solucionar, Agradecer… y anotar la causa.","Evita «cálmese», «son políticas» y «no es mi área».","Escala cuando la solución no está en tus manos, sin que el cliente repita todo."]}]},{"id":"c-atencion-ventas-m2-l3","titulo":"Lección 3 — Derechos básicos del consumidor","objetivo":"conocer los derechos básicos que protege la Ley Federal de Protección al Consumidor y cómo orientar a un cliente que quiere acudir a PROFECO.","bloques":[{"tipo":"texto","texto":"En México, la <b>Ley Federal de Protección al Consumidor</b> (LFPC) protege a quienes compran productos o contratan servicios, y la <b>Procuraduría Federal del Consumidor (PROFECO)</b> es la autoridad que la vigila. Conocer lo básico te ayuda a no prometer lo que no puedes, a no negar lo que el cliente sí tiene derecho a recibir y a evitar problemas para tu negocio."},{"tipo":"tabla","titulo":"Lo básico que conviene saber","encabezados":["Tema","Qué dice en términos generales"],"filas":[["Información y precio","El cliente tiene derecho a información veraz y clara. El precio exhibido debe ser el <b>precio total</b> (con impuestos), y los precios, promociones y condiciones anunciados deben respetarse."],["Garantía","Cuando un bien o servicio se ofrece con garantía, esta <b>no puede ser menor a 90 días</b> desde la entrega, y debe decir cómo se hace válida."],["Producto defectuoso o servicio mal hecho","El consumidor puede pedir, según el caso, reparación, reposición, rebaja o devolución del dinero, además de una bonificación en los casos que marca la ley."],["Trato digno","No se puede negar el servicio ni discriminar por sexo, edad, origen, discapacidad, religión u otra condición."],["Quejas","El consumidor puede acudir a PROFECO. El plazo general para presentar una queja es de un año."]],"nota":"Resumen didáctico, no asesoría legal. Ante un caso concreto, consulta el texto vigente de la ley o a PROFECO."},{"tipo":"destacado","texto":"<b>¿Cómo orientar al cliente?</b> Si no logras resolver y el cliente quiere quejarse formalmente, no lo tomes a mal: es su derecho. PROFECO atiende en el <b>Teléfono del Consumidor: 55 5568 8722</b> (Ciudad de México y zona metropolitana) y <b>800 468 8722</b> (resto del país), en línea por <b>Concilianet</b> y en sus oficinas. Hacer bien las cosas desde el mostrador evita casi todas estas quejas."},{"tipo":"relacionar","rotulo":"Relaciona la situación con el derecho","pares":[["El anaquel dice 199 pesos pero en caja cobran 229","Respetar el precio exhibido"],["La licuadora falla a los 40 días de comprada con garantía","Garantía mínima de 90 días"],["El letrero dice «precio más IVA»","El precio debe ser total con impuestos"],["Le niegan la entrada a una persona por su apariencia","Trato digno sin discriminación"],["No se resolvió en tienda y el cliente quiere quejarse","Acudir a PROFECO"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un producto ofrecido con garantía debe tener, como mínimo…","ops":["15 días de garantía","Lo que decida la tienda","90 días de garantía"],"correcta":2,"explica":"Lo establece el artículo 77 de la LFPC."},{"p":"Si en el anaquel hay un precio y en caja sale otro más alto…","ops":["Se cobra el del sistema porque es el oficial","Se debe respetar el precio exhibido"],"correcta":1,"explica":"El precio anunciado obliga al proveedor."},{"p":"Un cliente te dice que irá a PROFECO. Lo profesional es…","ops":["Intentar una última solución y, si no, darle la información sin molestarte","Decirle que PROFECO no sirve para nada"],"correcta":0,"explica":"Acudir a PROFECO es su derecho."}]},{"tipo":"clave","items":["La LFPC protege al consumidor; PROFECO vigila que se cumpla.","Precio total exhibido y respetado; garantía mínima de 90 días cuando se ofrece; trato sin discriminación.","Teléfono del Consumidor: 55 5568 8722 y 800 468 8722; en línea, Concilianet."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"Ante un cliente muy molesto, lo primero es…","ops":["Explicarle de inmediato la política","Decirle «cálmese»","Llamar a seguridad","Escucharlo hasta que termine y demostrarle que lo entiendes"],"correcta":3},{"p":"Parafrasear sirve para…","ops":["Cambiar de tema","Corregir la gramática del cliente","Confirmar que entendiste y demostrar que escuchaste","Ganar tiempo"],"correcta":2},{"p":"Los cuatro pasos del método visto en el curso son…","ops":["Preguntar, cotizar, cerrar y facturar","Escuchar, disculparse, solucionar y agradecer","Negar, justificar, esperar y cerrar","Vender, cobrar, empacar y despedir"],"correcta":1},{"p":"¿Cuál frase conviene evitar?","ops":["«Son políticas de la empresa.»","«Lo que sí puedo hacer es…»","«Gracias por avisarnos.»","«Me encargo personalmente.»"],"correcta":0},{"p":"Conviene escalar un caso cuando…","ops":["El cliente hace una pregunta sencilla","Tienes prisa","Siempre, en todos los casos","La solución está fuera de tu autorización o ya hubo intentos fallidos"],"correcta":3},{"p":"Cuando un producto se ofrece con garantía, esta no puede ser menor a…","ops":["7 días","Un año","90 días","30 días"],"correcta":2},{"p":"El precio que se exhibe al consumidor debe ser…","ops":["Solo el de contado","El precio total, con impuestos incluidos","El precio sin IVA","Cualquiera, mientras en caja se aclare"],"correcta":1},{"p":"La autoridad que atiende quejas de consumidores en México es…","ops":["PROFECO","CONDUSEF para todo tipo de compras","La STPS","El SAT"],"correcta":0}]}},{"id":"c-atencion-ventas-m3","titulo":"Módulo 3 — Vender ayudando, no presionando","resumen":"Preguntas para entender la necesidad, beneficios en lugar de características, manejo de objeciones, cierre, venta cruzada sin presión y seguimiento. Tres lecciones y una evaluación.","lecciones":[{"id":"c-atencion-ventas-m3-l1","titulo":"Lección 1 — Preguntar antes de ofrecer","objetivo":"hacer preguntas abiertas y usar una versión sencilla de la secuencia SPIN para descubrir lo que el cliente necesita.","bloques":[{"tipo":"texto","texto":"La <b>venta consultiva</b> parte de una idea sencilla: primero entiendes el problema del cliente y después le ofreces lo que lo resuelve. El vendedor que suelta el catálogo completo en cuanto el cliente entra vende menos que el que pregunta dos o tres cosas bien pensadas. Las <b>preguntas abiertas</b> (qué, para qué, cómo, cuál) invitan a platicar; las cerradas (¿sí o no?) sirven para confirmar."},{"tipo":"comparar","titulo":"Preguntas que cierran y preguntas que abren","malTitulo":"Preguntas cerradas al inicio","mal":"«¿Busca una lavadora?» «¿La quiere de 18 kilos?» «¿Algo más?»","bienTitulo":"Preguntas abiertas","bien":"«¿Para cuántas personas es la lavadora?» «¿Qué no le gustaba de la que tenía?» «¿Qué es lo más importante para usted: capacidad, consumo de agua o precio?»"},{"tipo":"texto","texto":"El investigador Neil Rackham estudió miles de visitas de venta y propuso el modelo <b>SPIN</b>, que ordena las preguntas en cuatro tipos. Aquí va en versión simplificada con un ejemplo de <b>banco</b>: un cliente pregunta por una tarjeta de crédito."},{"tipo":"tabla","titulo":"SPIN simplificado","encabezados":["Tipo de pregunta","Para qué sirve","Ejemplo (banco)"],"filas":[["Situación","Conocer el contexto","«¿Para qué gastos piensa usar la tarjeta?»"],["Problema","Descubrir qué le molesta o le falta","«¿Qué le ha complicado de su tarjeta actual?»"],["Implicación","Que dimensione lo que le cuesta ese problema","«Si paga anualidad cada año, ¿cuánto le cuesta al final?»"],["Necesidad-beneficio","Que él mismo diga qué ganaría","«¿Qué tanto le ayudaría una tarjeta sin anualidad?»"]],"nota":"No es un interrogatorio: con dos o tres preguntas bien hechas suele bastar. Escucha la respuesta antes de hacer la siguiente."},{"tipo":"relacionar","rotulo":"Relaciona la pregunta con su tipo","pares":[["¿Cuántos kilómetros maneja al día?","Situación"],["¿Ha notado que el auto jala hacia un lado al frenar?","Problema"],["Si esas balatas fallan en carretera, ¿qué podría pasar?","Implicación"],["¿Le daría tranquilidad salir de viaje con los frenos revisados?","Necesidad-beneficio"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una pregunta abierta es…","ops":["«¿Lo quiere negro?»","«¿Algo más?»","«¿Qué uso le va a dar al celular?»"],"correcta":2,"explica":"Las abiertas empiezan con qué, cómo, para qué, cuál."},{"p":"El objetivo de preguntar antes de ofrecer es…","ops":["Saber cuánto dinero trae","Entender la necesidad para recomendar lo que sí le sirve","Retrasar la venta"],"correcta":1,"explica":"Una recomendación a la medida vende más y genera confianza."},{"p":"En la venta consultiva, quien más debe hablar al inicio es…","ops":["El cliente","El vendedor","El gerente"],"correcta":0}]},{"tipo":"clave","items":["Primero entiende el problema; después ofrece.","Preguntas abiertas para descubrir, cerradas para confirmar.","SPIN: situación, problema, implicación y necesidad-beneficio."]}]},{"id":"c-atencion-ventas-m3-l2","titulo":"Lección 2 — Beneficios y objeciones","objetivo":"traducir características en beneficios y responder objeciones de precio, tiempo y confianza sin discutir.","bloques":[{"tipo":"texto","texto":"Una <b>característica</b> es lo que el producto tiene («batería de 5,000 mAh»). Un <b>beneficio</b> es lo que eso significa para <b>este</b> cliente («te dura todo el día aunque uses el GPS para repartir»). El puente es la frase <b>«lo que significa para ti es que…»</b>. Usa la información que obtuviste al preguntar."},{"tipo":"relacionar","rotulo":"Relaciona la característica con su beneficio","pares":[["Refrigerador con tecnología inverter","Gastas menos luz cada bimestre"],["Medicamento genérico con la misma sustancia","Mismo tratamiento a menor precio"],["Llantas con garantía de 50 mil kilómetros","Años sin volver a pensar en llantas"],["Seguro con asistencia vial incluida","Si te quedas tirado, alguien llega por ti"],["Colchón con 30 noches de prueba","Si no descansas bien, lo devuelves"]]},{"tipo":"texto","texto":"Una <b>objeción</b> es una duda o un freno, no un «no» definitivo. Las tres más comunes son <b>precio</b> («está caro»), <b>tiempo</b> («lo voy a pensar») y <b>confianza</b> («¿y si no sirve?»). La regla: <b>no discutas</b>. Primero reconoce, luego pregunta qué hay detrás y al final responde con información."},{"tipo":"tabla","titulo":"Cómo responder las objeciones más comunes","encabezados":["Objeción","Pregunta para entenderla","Posible respuesta"],"filas":[["«Está muy caro.»","«¿Caro comparado con qué?» o «¿Qué presupuesto tenías en mente?»","Muestra el costo por uso o por mes, ofrece una opción más económica o formas de pago reales, sin bajar la calidad de tu explicación."],["«Lo voy a pensar.»","«Claro. ¿Qué es lo que te gustaría pensar: el precio, el modelo o algo más?»","Resuelve esa duda concreta; si aún quiere pensarlo, ofrece enviar la cotización por WhatsApp y acuerda cuándo le escribes."],["«No sé si me va a servir.»","«¿Qué te preocupa que pase?»","Garantía, política de cambios, testimonios o una prueba; nunca prometas lo que no está por escrito."]]},{"tipo":"comparar","titulo":"La objeción de precio en una tienda de colchones","malTitulo":"Discutir","mal":"Cliente: «Está carísimo.»<br>Vendedor: «No, fíjese que no está caro, es de muy buena calidad, en otras tiendas está más caro.»","bienTitulo":"Reconocer, preguntar y responder","bien":"Cliente: «Está carísimo.»<br>Vendedor: «Entiendo, es una inversión. ¿Lo estás comparando con otro modelo?… Este cuesta 8,400 y dura unos 8 años: son menos de 3 pesos por noche de buen descanso. Si prefieres, te muestro uno de 5,900 con menos soporte para la espalda.»"},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El puente entre característica y beneficio es: «Lo que ___ para ti es que…».","resp":["significa"]},{"frase":"Ante una objeción, primero la reconoces y luego ___ qué hay detrás.","resp":["preguntas","averiguas","descubres"]}]},{"tipo":"practica","rotulo":"¿Qué es?","preguntas":[{"p":"«Tiene pantalla de 6.7 pulgadas.»","ops":["Característica","Beneficio"],"correcta":0,"explica":"Beneficio sería: «ves tus videos y la letra más grande sin forzar la vista»."},{"p":"«Lo voy a pensar.»","ops":["Un «no» definitivo","Objeción de tiempo que merece una pregunta amable"],"correcta":1,"explica":"Pregunta qué quiere pensar; muchas veces hay una duda concreta."},{"p":"Ante «está caro», la peor respuesta suele ser…","ops":["Discutir que no está caro","Preguntar con qué lo compara","Mostrar el costo por uso"],"correcta":0}]},{"tipo":"clave","items":["Característica es lo que tiene; beneficio es lo que significa para este cliente.","Objeción no es rechazo: reconoce, pregunta y responde.","Nunca prometas lo que no está por escrito."]}]},{"id":"c-atencion-ventas-m3-l3","titulo":"Lección 3 — Cierre, venta cruzada y seguimiento","objetivo":"cerrar la venta con naturalidad, ofrecer complementos útiles sin presionar y dar seguimiento por WhatsApp de forma respetuosa.","bloques":[{"tipo":"texto","texto":"Si hiciste bien las preguntas y resolviste las dudas, el <b>cierre</b> es solo el paso natural: invitar a decidir. Muchas ventas se pierden porque el vendedor nunca lo pregunta. Hay formas sencillas de cerrar sin presionar: la <b>pregunta directa</b> («¿Te lo llevas?»), la de <b>alternativa</b> («¿Lo prefieres en gris o en azul?») y el <b>resumen</b> («Buscabas algo ligero, que aguante el agua y de menos de 1,500; este cumple las tres. ¿Te lo preparo?»)."},{"tipo":"destacado","texto":"<b>Lo que no es cierre, es presión:</b> inventar que «es el último» si no lo es, decir que la promoción «se acaba hoy» cuando no es cierto o insistir después de un «no» claro. Además de ser una mala práctica, la información falsa sobre precios o promociones puede meter en problemas a tu negocio con PROFECO."},{"tipo":"texto","texto":"La <b>venta cruzada</b> es ofrecer un complemento que de verdad le sirve al cliente: el protector para el celular nuevo, el suero oral junto con el medicamento para la diarrea, la alineación con las llantas, la mica o el cargador. Funciona cuando es <b>una sola sugerencia, relacionada y explicada</b>. Deja de funcionar cuando parece lista de pendientes para llegar a la meta."},{"tipo":"comparar","titulo":"Venta cruzada en farmacia","malTitulo":"Presionar","mal":"«¿No quiere también vitaminas, un gel antibacterial, estas pastillas para la garganta y la promoción de pañales?»","bienTitulo":"Ayudar","bien":"«Con este medicamento el doctor suele recomendar tomar mucho líquido; si quieres, te muestro el suero oral, cuesta 28 pesos.»"},{"tipo":"plantilla","rotulo":"Mensaje de seguimiento por WhatsApp","texto":"Hola, [nombre], soy [tu nombre] de [negocio]. Te escribo por la cotización de [producto] que te mandé el [día].\n¿Pudiste revisarla o te surgió alguna duda?\n\nTe comento que el precio de [monto] con [forma de pago] sigue vigente hasta el [fecha real].\nSi prefieres que no te escriba más sobre esto, dime sin problema. ¡Gracias!","nota":"Un seguimiento, máximo dos, con días de por medio. Pedir permiso para seguir escribiendo genera confianza; insistir a diario la destruye."},{"tipo":"ordenar","rotulo":"Ordena la regla de la venta cruzada","items":[{"frase":"Una sugerencia relacionada y explicada vale más que diez","es":"Cruzar la venta sin presionar"},{"frase":"Después de un no claro se agradece y se respeta","es":"Límite de la persuasión"}]},{"tipo":"practica","rotulo":"¿Qué harías?","preguntas":[{"p":"Un cliente compró llantas en el taller.","ops":["Le ofreces cambio de aceite, lavado, aromatizante y tapetes","No le dices nada nunca","Le sugieres la alineación explicando por qué alarga la vida de las llantas"],"correcta":2,"explica":"Una sugerencia relacionada y útil."},{"p":"Mandaste una cotización hace tres días y el cliente no ha contestado.","ops":["Das por perdida la venta sin escribir","Envías un mensaje amable preguntando si tiene dudas","Le mandas cinco mensajes el mismo día"],"correcta":1,"explica":"Uno o dos seguimientos respetuosos, con fecha real de vigencia."},{"p":"El cliente ya dijo que sí le gusta y resolviste sus dudas.","ops":["Lo invitas a decidir: «¿Te lo preparo?»","Sigues mostrando más productos","Esperas a que él diga «me lo llevo»"],"correcta":0,"explica":"Si no preguntas, muchas ventas se quedan en el aire."}]},{"tipo":"clave","items":["El cierre es invitar a decidir: directo, alternativa o resumen.","Venta cruzada: una sugerencia relacionada, útil y explicada.","Seguimiento amable con datos reales; respeta el «no»."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"En la venta consultiva, primero…","ops":["Muestras todo el catálogo","Das el precio más bajo","Hablas de la marca","Entiendes la necesidad del cliente con preguntas"],"correcta":3},{"p":"¿Cuál es una pregunta abierta?","ops":["«¿Pagas con tarjeta?»","«¿Es todo?»","«¿Para qué vas a usar la laptop?»","«¿La quieres gris?»"],"correcta":2},{"p":"En SPIN, «¿Qué le ha complicado de su tarjeta actual?» es una pregunta de…","ops":["Cierre","Problema","Situación","Implicación"],"correcta":1},{"p":"«Te dura todo el día aunque uses el GPS» es…","ops":["Un beneficio","Una característica","Una objeción","Un cierre"],"correcta":0},{"p":"Ante «lo voy a pensar», lo más útil es…","ops":["Insistir hasta que compre","Decir que la promoción termina hoy aunque no sea cierto","Despedirlo sin más","Preguntar con amabilidad qué le gustaría pensar"],"correcta":3},{"p":"Un cierre de alternativa es…","ops":["«¿Algo más?»","«Luego me dices»","«¿Lo prefieres en gris o en azul?»","«Cómpralo ya, es el último»"],"correcta":2},{"p":"Una buena venta cruzada es…","ops":["Insistir tres veces","Una sugerencia relacionada, útil y explicada","Ofrecer todo lo que hay en promoción","Agregar productos sin preguntar"],"correcta":1},{"p":"Un seguimiento por WhatsApp respetuoso…","ops":["Pregunta si hay dudas, da fecha real de vigencia y respeta si no quiere más mensajes","Se manda todos los días hasta que compre","Usa urgencias falsas","Se hace con audios largos"],"correcta":0}]}},{"id":"c-atencion-ventas-m4","titulo":"Módulo 4 — Medir para mejorar","resumen":"NPS, satisfacción, tiempo de respuesta, tasa de conversión y ticket promedio calculados en una hoja de cálculo, y tu plan personal de mejora. Tres lecciones y una evaluación.","lecciones":[{"id":"c-atencion-ventas-m4-l1","titulo":"Lección 1 — NPS y satisfacción del cliente","objetivo":"calcular el Net Promoter Score (NPS) y distinguirlo de la satisfacción promedio.","bloques":[{"tipo":"texto","texto":"Lo que no se mide se queda en opinión. Dos indicadores muy usados para saber cómo te ve el cliente son la <b>satisfacción</b> (por ejemplo, «Del 1 al 5, ¿qué tan satisfecho quedaste?») y el <b>NPS</b> o <i>Net Promoter Score</i>, propuesto por Fred Reichheld en 2003. El NPS se basa en una sola pregunta: <b>«Del 0 al 10, ¿qué tan probable es que nos recomiendes con un familiar o amigo?»</b>"},{"tipo":"tabla","titulo":"Cómo se clasifica cada respuesta del NPS","encabezados":["Calificación","Grupo","Qué suele significar"],"filas":[["9 y 10","Promotores","Te recomiendan y vuelven."],["7 y 8","Pasivos","Quedaron bien, pero se van con otro sin pensarlo mucho."],["0 a 6","Detractores","Quedaron inconformes y pueden hablar mal de ti."]],"nota":"<b>NPS = % de promotores − % de detractores.</b> Los pasivos no suman ni restan, pero sí cuentan en el total. El resultado va de −100 a +100; no es un porcentaje."},{"tipo":"excel","rotulo":"Calcula el NPS de la semana (restaurante)","datos":[["Cliente","Calificación (0 a 10)","","Indicador","Valor"],["C01",10,"","Promotores (9 y 10)",""],["C02",9,"","Detractores (0 a 6)",""],["C03",8,"","Total de respuestas",""],["C04",6,"","NPS",""],["C05",10,"","",""],["C06",7,"","",""],["C07",9,"","",""],["C08",3,"","",""],["C09",10,"","",""],["C10",8,"","",""],["C11",5,"","",""],["C12",9,"","",""]],"retos":[{"celda":"E2","formula":"=CONTAR.SI(B2:B13,\">=9\")","esperado":6,"requiere":"CONTAR.SI(","texto":"<b>E2</b>: cuenta a los promotores (calificación de 9 o más).","pista":"=CONTAR.SI(rango,\">=9\"). El criterio va entre comillas."},{"celda":"E3","formula":"=CONTAR.SI(B2:B13,\"<=6\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>E3</b>: cuenta a los detractores (6 o menos)."},{"celda":"E4","formula":"=CONTAR(B2:B13)","esperado":12,"requiere":"CONTAR(","texto":"<b>E4</b>: cuenta cuántas respuestas hay en total con CONTAR."},{"celda":"E5","formula":"=REDONDEAR((E2-E3)/E4*100,0)","esperado":25,"requiere":"REDONDEAR(","texto":"<b>E5</b>: calcula el NPS: (promotores − detractores) entre el total, por 100, redondeado a 0 decimales.","pista":"=REDONDEAR((E2-E3)/E4*100,0)","explica":"50% de promotores − 25% de detractores = NPS de 25. Los 3 pasivos cuentan en el total aunque no sumen ni resten."}]},{"tipo":"destacado","texto":"<b>El número es el inicio, no el final.</b> Después de la calificación, pregunta «¿Qué fue lo principal para darnos esa calificación?». Los comentarios de los detractores te dicen qué corregir; los de los promotores, qué no debes perder. Y compárate contigo mismo mes a mes, no contra cifras de otras industrias."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un cliente califica con 8. Es…","ops":["Promotor","Detractor","Pasivo"],"correcta":2,"explica":"Los pasivos (7 y 8) cuentan en el total, pero no suman ni restan."},{"p":"Si tienes 40% de promotores y 40% de detractores, tu NPS es…","ops":["80","0","40"],"correcta":1,"explica":"40 − 40 = 0."},{"p":"El NPS se mide en una escala de…","ops":["−100 a +100","0 a 10","0% a 100%"],"correcta":0}]},{"tipo":"clave","items":["NPS: «¿qué tan probable es que nos recomiendes?» del 0 al 10.","Promotores 9–10, pasivos 7–8, detractores 0–6; NPS = % promotores − % detractores.","Siempre pregunta el porqué y compárate contigo mismo en el tiempo."]}]},{"id":"c-atencion-ventas-m4-l2","titulo":"Lección 2 — Tiempo de respuesta, conversión y ticket promedio","objetivo":"calcular tiempo de respuesta, satisfacción promedio, tasa de conversión y ticket promedio en una hoja de cálculo e interpretar los resultados.","bloques":[{"tipo":"texto","texto":"Además de la opinión del cliente, hay indicadores de <b>operación</b> y de <b>venta</b> que puedes llevar en una hoja sencilla. Los más útiles para empezar son cuatro."},{"tipo":"tabla","titulo":"Cuatro indicadores básicos","encabezados":["Indicador","Cómo se calcula","Qué te dice"],"filas":[["Tiempo de respuesta","Promedio de minutos entre que el cliente escribe o llama y le contestas.","Si el cliente espera demasiado; revisa también el caso más lento."],["Resolución en el primer contacto","Casos resueltos a la primera ÷ total de casos.","Si el cliente tiene que volver o llamar otra vez."],["Tasa de conversión","Ventas cerradas ÷ clientes atendidos.","De cada 10 personas que atiendes, cuántas compran."],["Ticket promedio","Importe vendido ÷ número de ventas.","Cuánto gasta en promedio cada cliente que compra."]]},{"tipo":"excel","rotulo":"Tablero de atención (10 casos de la semana)","datos":[["Folio","Canal","Minutos de respuesta","Satisfacción (1 a 5)","¿Resuelto a la primera?","","Indicador","Valor"],["T01","WhatsApp",4,5,"Sí","","Promedio de minutos",""],["T02","Teléfono",12,4,"Sí","","Respuesta más lenta",""],["T03","WhatsApp",35,2,"No","","Casos con más de 15 minutos",""],["T04","Mostrador",2,5,"Sí","","Promedio de minutos en WhatsApp",""],["T05","WhatsApp",8,4,"Sí","","Satisfacción promedio",""],["T06","Teléfono",20,3,"No","","% resueltos a la primera",""],["T07","WhatsApp",55,1,"No","","",""],["T08","Mostrador",5,4,"Sí","","",""],["T09","WhatsApp",6,5,"Sí","","",""],["T10","Teléfono",9,4,"Sí","","",""]],"retos":[{"celda":"H2","formula":"=PROMEDIO(C2:C11)","esperado":15.6,"requiere":"PROMEDIO(","texto":"<b>H2</b>: promedio de minutos de respuesta."},{"celda":"H3","formula":"=MAX(C2:C11)","esperado":55,"requiere":"MAX(","texto":"<b>H3</b>: ¿cuál fue la respuesta más lenta? Usa MAX."},{"celda":"H4","formula":"=CONTAR.SI(C2:C11,\">15\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>H4</b>: ¿cuántos casos tardaron más de 15 minutos?"},{"celda":"H5","formula":"=PROMEDIO.SI(B2:B11,\"WhatsApp\",C2:C11)","esperado":21.6,"requiere":"PROMEDIO.SI(","texto":"<b>H5</b>: promedio de minutos solo de WhatsApp.","pista":"=PROMEDIO.SI(rango del canal,\"WhatsApp\",rango de minutos)","explica":"WhatsApp promedia 21.6 minutos contra 15.6 general: ahí está el cuello de botella."},{"celda":"H6","formula":"=PROMEDIO(D2:D11)","esperado":3.7,"requiere":"PROMEDIO(","texto":"<b>H6</b>: satisfacción promedio."},{"celda":"H7","formula":"=CONTAR.SI(E2:E11,\"Sí\")/CONTARA(A2:A11)","esperado":0.7,"requiere":"CONTARA(","texto":"<b>H7</b>: porcentaje resuelto a la primera: cuenta los «Sí» y divide entre el número de folios (CONTARA).","explica":"70%. Fíjate: los tres casos no resueltos a la primera son también los más lentos y los peor calificados."}]},{"tipo":"excel","rotulo":"Conversión y ticket promedio (tienda de muebles)","datos":[["Día","Clientes atendidos","Ventas cerradas","Importe vendido","Conversión","Ticket promedio","¿Meta de 25%?"],["Lunes",40,10,8500,"","",""],["Martes",35,7,6300,"","",""],["Miércoles",50,15,13500,"","",""],["Jueves",45,9,9900,"","",""],["Viernes",60,18,14400,"","",""],["Semana",230,"",52600,"","",""]],"retos":[{"celda":"E2","formula":"=C2/B2","esperado":0.25,"texto":"<b>E2</b>: tasa de conversión del lunes: ventas cerradas entre clientes atendidos."},{"celda":"F2","formula":"=D2/C2","esperado":850,"texto":"<b>F2</b>: ticket promedio del lunes: importe entre número de ventas."},{"celda":"G5","formula":"=SI(C5/B5>=0.25,\"Sí\",\"No\")","esperado":"No","requiere":"SI(","texto":"<b>G5</b>: ¿el jueves alcanzó la meta de 25% de conversión? Responde «Sí» o «No» con SI.","pista":"=SI(C5/B5>=0.25,\"Sí\",\"No\")"},{"celda":"C7","formula":"=SUMA(C2:C6)","esperado":59,"requiere":"SUMA(","texto":"<b>C7</b>: total de ventas cerradas en la semana."},{"celda":"E7","formula":"=REDONDEAR(C7/B7,3)","esperado":0.257,"requiere":"REDONDEAR(","texto":"<b>E7</b>: conversión de la semana, redondeada a 3 decimales."},{"celda":"F7","formula":"=REDONDEAR(D7/C7,2)","esperado":891.53,"requiere":"REDONDEAR(","texto":"<b>F7</b>: ticket promedio de la semana, redondeado a 2 decimales.","explica":"Viernes tuvo más clientes y la mejor conversión (30%), pero el ticket más bajo (800). El jueves convirtió poco (20%): vale la pena revisar qué pasó ese día."}]},{"tipo":"practica","rotulo":"Interpreta","preguntas":[{"p":"Atendiste a 50 personas y cerraste 10 ventas. Tu conversión es…","ops":["10%","50%","20%"],"correcta":2,"explica":"10 ÷ 50 = 0.20."},{"p":"Vendiste 12,000 pesos en 15 ventas. Tu ticket promedio es…","ops":["180 pesos","800 pesos","1,200 pesos"],"correcta":1,"explica":"12,000 ÷ 15 = 800."},{"p":"Tu promedio de respuesta es bueno, pero un caso tardó 3 horas. Conviene…","ops":["Ignorarlo porque el promedio está bien","Revisar también el máximo, no solo el promedio"],"correcta":1,"explica":"Un promedio puede esconder casos muy malos."}]},{"tipo":"clave","items":["Conversión = ventas ÷ clientes atendidos; ticket promedio = importe ÷ ventas.","Mide el tiempo de respuesta con promedio y máximo, y por canal.","Los números señalan dónde mirar; la causa se busca platicando con el equipo y los clientes."]}]},{"id":"c-atencion-ventas-m4-l3","titulo":"Lección 3 — Tu plan personal de mejora","objetivo":"elaborar un plan personal de 30 días con una meta medible de servicio o ventas.","bloques":[{"tipo":"texto","texto":"Terminaste el curso con muchas ideas. El riesgo es querer aplicarlas todas mañana y no sostener ninguna. Mejor elige <b>una o dos</b>, ponles una meta medible y revísalas cada semana durante un mes. Los cambios pequeños y constantes son los que el cliente nota."},{"tipo":"pasos","rotulo":"Cómo armar tu plan en cinco pasos","pasos":["<b>Elige tu punto de partida:</b> el momento de verdad más débil, las quejas más repetidas o el indicador más bajo.","<b>Escoge una conducta concreta:</b> por ejemplo, «contestar todo WhatsApp en menos de 10 minutos» o «hacer dos preguntas abiertas antes de mostrar producto».","<b>Pon una meta medible:</b> un número y una fecha, como «subir mi conversión de 20% a 25% en 30 días».","<b>Decide cómo lo vas a medir:</b> una hoja sencilla, las encuestas de la tienda o los reportes del sistema.","<b>Revisa cada semana:</b> anota qué funcionó, qué no y qué ajustas."]},{"tipo":"plantilla","rotulo":"Plan personal de 30 días","texto":"PLAN PERSONAL DE MEJORA — [Tu nombre] — [Puesto] — Del [fecha] al [fecha]\n\n1. Lo que quiero mejorar (y por qué): \n2. Cómo estoy hoy (dato inicial): \n3. Meta medible a 30 días: \n4. Conductas concretas que voy a practicar:\n   a) \n   b) \n5. Frases o plantillas que voy a usar: \n6. Cómo lo voy a medir y dónde lo anoto: \n7. Revisión semanal:\n   Semana 1: \n   Semana 2: \n   Semana 3: \n   Semana 4: \n8. Resultado final y siguiente paso: "},{"tipo":"comparar","titulo":"Metas de mejora","malTitulo":"Meta vaga","mal":"«Voy a atender mejor a los clientes.»<br>«Voy a vender más.»","bienTitulo":"Meta medible","bien":"«En 30 días voy a subir mi NPS de 20 a 30 preguntando al final de cada atención si quedó resuelto.»<br>«Voy a subir mi ticket promedio de 650 a 720 pesos con una sugerencia de complemento por venta.»"},{"tipo":"practica","rotulo":"¿Es una buena meta?","preguntas":[{"p":"«Contestar todos los mensajes de WhatsApp en menos de 10 minutos durante mi turno, medido con los reportes de la semana.»","ops":["Sí: es concreta, medible y tiene cómo verificarse","No, es demasiado específica"],"correcta":0,"explica":"Tiene conducta, número y forma de medir."},{"p":"«Ser mejor vendedor.»","ops":["Sí, es una buena meta","No: no dice qué hacer ni cómo medirlo"],"correcta":1,"explica":"Conviértela en un número: conversión, ticket promedio o NPS."}]},{"tipo":"reflexion","rotulo":"Tu compromiso","pregunta":"Escribe tu meta de 30 días: qué vas a mejorar, cuál es tu dato de hoy, a cuánto quieres llegar y qué vas a hacer distinto desde mañana.","ayuda":"Hoy mi… está en… En 30 días quiero llegar a… Para lograrlo voy a…"},{"tipo":"clave","items":["Elige una o dos conductas, no diez.","Meta medible: número, fecha y forma de medir.","Revisa cada semana y ajusta; la constancia es lo que el cliente nota."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"La pregunta del NPS es…","ops":["«¿Te gustó el precio?»","«Del 1 al 5, ¿qué tan rápido te atendimos?»","«¿Volverías a comprar hoy?»","«Del 0 al 10, ¿qué tan probable es que nos recomiendes?»"],"correcta":3},{"p":"En el NPS, los detractores son quienes califican…","ops":["De 9 a 10","Solo con 0","De 0 a 6","De 7 a 8"],"correcta":2},{"p":"Con 50% de promotores, 30% de pasivos y 20% de detractores, el NPS es…","ops":["20","30","50","80"],"correcta":1},{"p":"La tasa de conversión se calcula…","ops":["Ventas cerradas ÷ clientes atendidos","Importe ÷ ventas","Clientes ÷ días","Quejas ÷ ventas"],"correcta":0},{"p":"Si vendiste 9,000 pesos en 12 ventas, tu ticket promedio es…","ops":["1,200 pesos","108 pesos","900 pesos","750 pesos"],"correcta":3},{"p":"Para promediar solo los minutos de respuesta de WhatsApp usas…","ops":["MAX","CONTARA","PROMEDIO.SI","SUMA"],"correcta":2},{"p":"Además del tiempo promedio de respuesta, conviene revisar…","ops":["El nombre del cliente","El caso más lento (máximo) y el promedio por canal","Solo el color de la hoja","Nada más"],"correcta":1},{"p":"Una meta de mejora bien planteada es…","ops":["«Subir mi conversión de 20% a 25% en 30 días»","«Vender más»","«Atender mejor»","«Echarle ganas»"],"correcta":0}]}}]});
window.CURSOS_MARA.push({"id":"d-liderazgo","nombre":"Diplomado en Liderazgo para Mandos Medios","color":"#B45309","nivel":"Diplomados","familia":"Recursos Humanos y empresa","periodoTipo":null,"periodoNum":null,"desc":"Para supervisores, jefes de turno y coordinadores que acaban de subir de puesto: cómo dar instrucciones claras, retroalimentar, delegar, medir a tu equipo en Excel, manejar conflictos y cumplir tu papel en la NOM-035. Práctico y con formatos listos; al terminar recibes una constancia de Instituto Mara.","horas":30,"precio":1690,"publicado":true,"proximamente":false,"modulos":[{"id":"d-liderazgo-m1","titulo":"Módulo 1 — De compañero a jefe","resumen":"Qué hace realmente un mando medio, la diferencia entre autoridad y liderazgo, los estilos de liderazgo, el modelo situacional de Hersey y Blanchard y los errores típicos del jefe nuevo. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-liderazgo-m1-l1","titulo":"Lección 1 — El rol del mando medio","objetivo":"describir qué se espera de un mando medio y por qué su trabajo cambia al dejar de ser «el mejor operativo».","bloques":[{"tipo":"destacado","texto":"<b>Antes de empezar, con claridad.</b> Este es un <b>diplomado libre de capacitación</b>: al terminarlo recibes una <b>constancia de Instituto Mara</b>. <b>No</b> es un título ni un documento oficial de la SEP, y <b>no</b> es una certificación de competencias de CONOCER. Su valor está en lo que vas a poder hacer con tu equipo desde el lunes."},{"tipo":"texto","texto":"Un <b>mando medio</b> es la persona que está entre la dirección y la operación: supervisor de línea, jefe de turno, coordinador de call center, gerente de piso, jefa de enfermeras de un servicio. Recibe metas desde arriba y tiene que convertirlas en trabajo diario de un equipo. Casi siempre llegas al puesto porque eras <b>muy bueno haciendo el trabajo</b>; el reto es que ahora tu trabajo es <b>lograr resultados a través de otros</b>."},{"tipo":"tabla","titulo":"Lo que cambia al subir de puesto","encabezados":["Antes (operativo)","Ahora (mando medio)"],"filas":[["Te medían por lo que tú producías","Te miden por lo que produce tu equipo"],["Resolvías los problemas con tus manos","Enseñas y organizas para que otros los resuelvan"],["Tu agenda la ponía tu jefe","Repartes tu tiempo entre equipo, jefe, otras áreas y pendientes"],["Opinabas sobre las decisiones","Tomas decisiones y respondes por ellas"],["Eras parte del grupo de amigos","Sigues siendo cercano, pero con otro papel"]]},{"tipo":"texto","texto":"Ejemplo: Rogelio era el mejor operador de inyección en una planta de autopartes en Silao. Lo ascendieron a supervisor del turno B. La primera semana se la pasó arreglando moldes él mismo «porque así es más rápido». Resultado: la línea funcionó, pero nadie aprendió, llegó tarde a la junta con producción y no revisó el ausentismo. Hacer el trabajo de tu gente se siente productivo, pero te quita el tiempo de hacer el tuyo."},{"tipo":"lista","items":["<b>Hacia abajo:</b> dar dirección, organizar, desarrollar y cuidar a tu equipo.","<b>Hacia arriba:</b> informar a tiempo, proponer soluciones y traducir las metas en planes realistas.","<b>Hacia los lados:</b> coordinarte con otras áreas (calidad, mantenimiento, almacén, RH).","<b>Contigo:</b> administrar tu tiempo, tus emociones y tu aprendizaje."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"A un mando medio se le mide principalmente por…","ops":["Los resultados de su equipo","Lo que produce con sus propias manos","Lo simpático que cae"],"correcta":0,"explica":"Tu aportación ahora es multiplicar el trabajo de otros."},{"p":"Rogelio arregla los moldes él mismo todos los días. El riesgo principal es…","ops":["Que la línea produzca más","Ninguno, es buen ejemplo","Que nadie aprenda y descuide su propio trabajo de supervisor"],"correcta":2,"explica":"Una vez está bien; como hábito, te vuelves el cuello de botella."}]},{"tipo":"relacionar","rotulo":"¿Hacia dónde va cada tarea?","pares":[["Explicar la meta del día al arranque del turno","Hacia abajo"],["Avisar a tu gerente que un pedido se va a retrasar","Hacia arriba"],["Acordar con mantenimiento el paro de una máquina","Hacia los lados"],["Bloquear media hora para planear la semana","Contigo"]]},{"tipo":"clave","items":["El mando medio logra resultados a través de su equipo.","Tu trabajo va en cuatro direcciones: equipo, jefe, otras áreas y tú.","Este diplomado da constancia de Instituto Mara, no documento SEP ni CONOCER."]}]},{"id":"d-liderazgo-m1-l2","titulo":"Lección 2 — Autoridad, liderazgo y estilos","objetivo":"distinguir la autoridad que da el puesto del liderazgo que se gana, y reconocer los estilos de liderazgo más comunes.","bloques":[{"tipo":"texto","texto":"El nombramiento te da <b>autoridad formal</b>: puedes asignar tareas, autorizar permisos, firmar reportes. Pero eso no garantiza que la gente te siga con ganas. El <b>liderazgo</b> es la capacidad de influir en otros para que trabajen hacia un objetivo común, y se gana con conducta: cumplir lo que prometes, ser justo, saber del trabajo y tratar con respeto."},{"tipo":"comparar","titulo":"Autoridad sola vs liderazgo","malTitulo":"Solo autoridad","mal":"«Aquí se hace así porque lo digo yo. Si no les gusta, ahí está la puerta.» La gente obedece mientras el jefe está presente y hace lo mínimo cuando se va.","bienTitulo":"Autoridad con liderazgo","bien":"«Necesitamos cerrar los 300 pedidos antes de las 6 porque sale el tráiler a Monterrey. Así lo vamos a repartir. ¿Qué ven que nos pueda atorar?» La gente entiende el porqué y ayuda a resolver."},{"tipo":"tabla","titulo":"Estilos de liderazgo comunes","encabezados":["Estilo","Cómo se ve","Cuándo sirve","Riesgo si abusas"],"filas":[["Autoritario o directivo","El jefe decide y ordena","Emergencias, seguridad, personal nuevo","Equipo pasivo y con miedo"],["Democrático o participativo","Consulta al equipo antes de decidir","Mejoras de proceso, cambios que afectan a todos","Lentitud cuando urge decidir"],["Delegativo o «laissez-faire»","Deja que el equipo decida","Gente experta y comprometida","Abandono: nadie sabe qué se espera"],["Coach o formador","Enseña, pregunta, acompaña","Desarrollar a alguien con potencial","Poco útil si hay prisa extrema"]],"nota":"Ningún estilo es bueno siempre. El buen jefe cambia de estilo según la situación y la persona."},{"tipo":"texto","texto":"Ejemplo: en una sucursal bancaria de Querétaro, la gerente Mariana usa estilo directivo cuando hay un simulacro de sismo («salgan por la puerta 2, ya»), participativo cuando reorganiza los horarios de caja y delegativo con su ejecutivo más experimentado, que ya maneja solo la cartera de pymes."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El liderazgo se diferencia de la autoridad en que…","ops":["Solo lo tienen los directores","Se gana con conducta, no con el nombramiento","Viene en el contrato"],"correcta":1,"explica":"La autoridad te la dan; el liderazgo te lo ganas."},{"p":"Hay una fuga de gas en el almacén. El estilo adecuado es…","ops":["Directivo","Delegativo","Participativo con votación"],"correcta":0,"explica":"En una emergencia no se consulta: se da una instrucción clara."},{"p":"Tu técnico con 15 años de experiencia propone cómo organizar el mantenimiento preventivo. Conviene…","ops":["Ordenarle paso a paso","Ignorarlo","Delegarle la organización con seguimiento"],"correcta":2}]},{"tipo":"tarjetas","rotulo":"Fuentes de influencia de un jefe","tarjetas":[{"frente":"Autoridad del puesto","reverso":"Viene del nombramiento. Sirve para lo formal, pero se desgasta si es lo único que usas."},{"frente":"Conocimiento","reverso":"La gente te sigue porque sabes resolver. Cuídalo: actualízate."},{"frente":"Ejemplo","reverso":"Si llegas a tiempo y usas el equipo de protección, puedes pedirlo."},{"frente":"Relación","reverso":"Confianza construida con trato justo y cumplir lo que dices."}]},{"tipo":"clave","items":["La autoridad te la da el puesto; el liderazgo te lo ganas con conducta.","Estilos: directivo, participativo, delegativo y coach.","Ninguno sirve siempre: se elige según la situación y la persona."]}]},{"id":"d-liderazgo-m1-l3","titulo":"Lección 3 — Liderazgo situacional (Hersey y Blanchard)","objetivo":"elegir cómo dirigir a cada persona según qué tan capaz y qué tan dispuesta está para una tarea concreta.","bloques":[{"tipo":"texto","texto":"El <b>modelo de liderazgo situacional</b> lo propusieron <b>Paul Hersey y Ken Blanchard</b> a finales de los años sesenta. Su idea central: <b>no hay un estilo único</b>; el estilo correcto depende de la <b>madurez o disposición</b> del colaborador <i>para esa tarea</i>, es decir, qué tan <b>capaz</b> (sabe hacerlo) y qué tan <b>dispuesto</b> (quiere y se siente seguro) está."},{"tipo":"texto","texto":"El jefe combina dos tipos de conducta: <b>conducta de tarea</b> (decir qué, cómo y cuándo; supervisar de cerca) y <b>conducta de relación</b> (escuchar, animar, explicar el porqué, involucrar). Según cuánto de cada una uses, salen cuatro estilos."},{"tipo":"tabla","titulo":"Los cuatro estilos del modelo","encabezados":["Estilo","Tarea / relación","Para quién","Ejemplo"],"filas":[["E1 Dirigir (ordenar)","Mucha tarea, poca relación","No sabe hacerlo y está inseguro o desmotivado","Cajero nuevo el primer día: le enseñas paso a paso el arqueo"],["E2 Persuadir (entrenar)","Mucha tarea, mucha relación","No sabe todavía, pero tiene ganas","Agente de call center con 3 semanas: le explicas y lo animas"],["E3 Participar (apoyar)","Poca tarea, mucha relación","Sabe hacerlo, pero duda o perdió motivación","Enfermera con experiencia insegura en un equipo nuevo: la escuchas y decides con ella"],["E4 Delegar","Poca tarea, poca relación","Sabe hacerlo y quiere hacerlo","Montacarguista experto: le das el objetivo y revisas al final"]],"nota":"La misma persona puede estar en distintos niveles según la tarea: un vendedor estrella puede ser principiante en el nuevo sistema de inventarios."},{"tipo":"relacionar","rotulo":"¿Qué estilo le toca?","pares":[["Practicante que nunca ha usado la báscula de recibo","Dirigir"],["Nuevo auxiliar entusiasta que aún comete errores","Persuadir"],["Operadora experta que anda desanimada tras un regaño injusto","Participar"],["Jefe de almacén con años de experiencia y buenos resultados","Delegar"]]},{"tipo":"practica","rotulo":"Caso: Karla, jefa de piso en un autoservicio de León","preguntas":[{"p":"Luis lleva 6 años en perecederos y siempre cumple. Karla le revisa cada caja y le dice cómo acomodar. ¿Qué pasa?","ops":["Debería regañarlo más","Lo sobredirige: le convendría delegar","Aplica bien el modelo"],"correcta":1,"explica":"Dirigir a alguien capaz y dispuesto lo desmotiva: siente que no confías en él."},{"p":"A Sofía, recién llegada, Karla le dice «tú ya sabes, acomoda la bodega». Sofía se equivoca todo el día. ¿Qué faltó?","ops":["Dirigir o persuadir: dar instrucciones claras y acompañar","Delegar más","Nada, así se aprende"],"correcta":0,"explica":"Delegar a quien no sabe es abandonarlo."},{"p":"Con el tiempo, Sofía aprende. Karla debería…","ops":["Seguir dirigiéndola igual siempre","Dejar de hablar con ella","Ir soltando control y pasar a apoyar y luego delegar"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa el modelo","items":[{"frase":"El estilo depende de qué tan capaz y qué tan ___ está la persona para la tarea.","resp":["dispuesta","dispuesto"]},{"frase":"Al experto comprometido le corresponde ___.","resp":["delegar"]},{"frase":"Al nuevo sin experiencia le corresponde ___.","resp":["dirigir","ordenar"]}]},{"tipo":"clave","items":["El estilo se elige por persona y por tarea, no por gusto del jefe.","Dirigir → persuadir → participar → delegar, conforme crece la capacidad y la disposición.","Sobredirigir desmotiva al experto; delegar al novato es abandonarlo."]}]},{"id":"d-liderazgo-m1-l4","titulo":"Lección 4 — Errores del jefe nuevo y cómo evitarlos","objetivo":"reconocer los errores más frecuentes del primer año como jefe y tener una alternativa práctica para cada uno.","bloques":[{"tipo":"texto","texto":"Casi todos los jefes nuevos cometen los mismos errores. No es falta de talento: es que nadie te enseñó el puesto. Conocerlos de antemano te ahorra meses de desgaste."},{"tipo":"tabla","titulo":"Errores frecuentes","encabezados":["Error","Por qué pasa","Qué hacer en su lugar"],"filas":[["Seguir haciendo el trabajo operativo","Es tu zona de confort y das resultados rápidos","Enseña una vez, delega y revisa"],["Querer caerle bien a todos","Miedo a perder a tus amigos","Sé cercano, pero aplica las mismas reglas a todos"],["Llegar a cambiarlo todo","Quieres demostrar que mereces el puesto","Primero escucha y entiende; cambia poco y bien"],["Favorecer a tus antiguos compañeros","Confianza y lealtad previa","Criterios claros y públicos para turnos, permisos y horas extra"],["No pedir ayuda a tu jefe","Crees que se verá como debilidad","Pide orientación con propuestas: «esto pienso hacer, ¿qué me recomiendas?»"],["Evitar las conversaciones difíciles","Incomodidad","Hablar pronto, en privado y con hechos (lo verás en el módulo 2)"]]},{"tipo":"comparar","titulo":"Tu primera junta con el equipo","malTitulo":"Así no","mal":"«A partir de hoy las cosas van a cambiar. Ya no soy su compañero, soy su jefe, y aquí se acabó el relajo.»","bienTitulo":"Así sí","bien":"«Muchos me conocen como compañero y eso no cambia el respeto que les tengo. Mi trabajo ahora es que tengamos lo necesario para cumplir y que nos vaya bien a todos. En las próximas dos semanas voy a platicar con cada uno para escuchar qué funciona y qué no.»"},{"tipo":"texto","texto":"Ejemplo: Daniela fue ascendida a coordinadora de un call center de cobranza en Guadalajara. Su mejor amiga, Paty, sigue como agente. Paty empezó a llegar tarde «porque Dani entiende». Daniela habló con ella en privado: «Te aprecio igual que siempre. Justo por eso te lo digo a ti primero: las reglas de puntualidad aplican para todos, incluyéndote. Si hay algo que te complica llegar, platiquémoslo»."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Tu antiguo compañero te pide el mejor turno «por los viejos tiempos». Lo correcto es…","ops":["Negárselo sin explicación","Aplicar el mismo criterio que a los demás y explicarlo","Dárselo para no perder la amistad"],"correcta":1,"explica":"La justicia visible es la base de tu credibilidad."},{"p":"En tu primera semana conviene…","ops":["Escuchar a cada persona y entender el trabajo antes de cambiar cosas","Cambiar todos los procesos","Encerrarte en la oficina"],"correcta":0},{"p":"Pedir ayuda a tu jefe es…","ops":["Señal de debilidad","Innecesario si eres bueno","Recomendable, llevando una propuesta"],"correcta":2}]},{"tipo":"ordenar","rotulo":"Ordena la frase","items":[{"frase":"Cercano con todos pero las mismas reglas para todos","es":"La regla de oro con tus excompañeros"}]},{"tipo":"reflexion","rotulo":"Tu error más probable","pregunta":"¿Cuál de estos errores crees que te costará más trabajo evitar y por qué? Escribe una acción concreta para esta semana.","ayuda":"El error que más me cuesta es… porque… Esta semana voy a…"},{"tipo":"clave","items":["Los errores del jefe nuevo son comunes y previsibles.","Primero escucha y entiende; cambia poco y bien.","Cercanía sí, favoritismo no: mismas reglas para todos."]}]}],"quiz":{"titulo":"Evaluación del módulo 1","preguntas":[{"p":"La principal diferencia entre un operativo y un mando medio es que el mando medio…","ops":["Trabaja más horas","Ya no tiene jefe","No necesita saber del trabajo","Logra resultados a través de su equipo"],"correcta":3},{"p":"La constancia de este diplomado la emite…","ops":["CONOCER","La STPS","Instituto Mara, como diplomado libre","La SEP"],"correcta":2},{"p":"El liderazgo, a diferencia de la autoridad formal…","ops":["No se puede aprender","Se gana con conducta y trato justo","Se obtiene con el nombramiento","Solo se usa en emergencias"],"correcta":1},{"p":"En una emergencia de seguridad, el estilo más adecuado es…","ops":["Directivo","Delegativo","Participativo con votación","Ninguno"],"correcta":0},{"p":"El modelo situacional fue propuesto por…","ops":["Peter Drucker","Amy Edmondson","Frederick Herzberg","Paul Hersey y Ken Blanchard"],"correcta":3},{"p":"Para una persona capaz y comprometida con la tarea, el modelo situacional recomienda…","ops":["Persuadir","Supervisar cada paso","Delegar","Dirigir"],"correcta":2},{"p":"Delegar una tarea compleja a alguien que nunca la ha hecho es…","ops":["Liderazgo participativo","Abandonarlo: primero hay que dirigir o entrenar","La mejor forma de motivarlo","Lo que pide el modelo"],"correcta":1},{"p":"Un error típico del jefe nuevo es…","ops":["Seguir haciendo el trabajo operativo en lugar de organizar y enseñar","Escuchar a su equipo","Pedir orientación a su jefe","Aplicar las mismas reglas a todos"],"correcta":0}]}},{"id":"d-liderazgo-m2","titulo":"Módulo 2 — Comunicar para que las cosas pasen","resumen":"Juntas cortas que sí sirven, instrucciones claras, escucha activa, retroalimentación con el modelo SBI, conversaciones difíciles y cómo comunicarte con tu propio jefe. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-liderazgo-m2-l1","titulo":"Lección 1 — Juntas cortas e instrucciones claras","objetivo":"dirigir una junta de arranque de 10 minutos y dar instrucciones que no se malinterpreten.","bloques":[{"tipo":"texto","texto":"La mayoría de los problemas en un turno no vienen de que la gente no quiera trabajar, sino de que <b>no entendió lo mismo</b> que tú. Dos herramientas resuelven buena parte de eso: la <b>junta corta de arranque</b> y la <b>instrucción clara</b>."},{"tipo":"pasos","rotulo":"Junta de arranque de turno (10 minutos, de pie)","pasos":["<b>Seguridad (1 min):</b> un riesgo del día o un recordatorio concreto.","<b>Resultados de ayer (2 min):</b> una o dos cifras: piezas, llamadas atendidas, tiempo de espera, faltantes.","<b>Meta y prioridades de hoy (3 min):</b> qué es lo más importante y quién hace qué.","<b>Problemas y apoyos (3 min):</b> qué nos puede atorar; lo que no se resuelve en un minuto se platica después con quien corresponda.","<b>Cierre (1 min):</b> repite la prioridad y reconoce algo que salió bien."]},{"tipo":"comparar","titulo":"Instrucción mala vs buena","malTitulo":"Mala","mal":"«Oigan, a ver si le echan ganas con lo del inventario, que está medio atrasado, ¿eh?»","bienTitulo":"Buena","bien":"«Pedro y Lupita: hoy terminan el conteo del pasillo 7, de abarrotes, antes de las 2 de la tarde. Usen la hoja de conteo nueva. Si encuentran diferencias de más de 5 piezas, me avisan por radio. Pedro, ¿me repites qué van a hacer?»"},{"tipo":"texto","texto":"Una instrucción clara responde: <b>quién</b>, <b>qué</b> exactamente, <b>para cuándo</b>, <b>con qué estándar</b> (cómo se ve bien hecho) y <b>qué hacer si hay un problema</b>. Y se cierra pidiendo que la persona la <b>repita con sus palabras</b>: no para humillarla, sino para comprobar que te explicaste bien."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"«Échenle ganas al inventario» es una mala instrucción porque…","ops":["Es grosera","No dice quién, qué, para cuándo ni con qué estándar","Es demasiado larga"],"correcta":1,"explica":"Suena amable, pero cada quien la entiende distinto."},{"p":"Pedir que te repitan la instrucción sirve para…","ops":["Verificar que te explicaste bien","Hacer quedar mal a la persona","Alargar la junta"],"correcta":0},{"p":"En la junta de arranque, un problema que requiere 20 minutos de discusión…","ops":["Se discute ahí con todos","Se ignora","Se platica después solo con los involucrados"],"correcta":2}]},{"tipo":"completar","rotulo":"Los elementos de una instrucción clara","items":[{"frase":"Quién, qué, para ___, con qué estándar y qué hacer si hay problema.","resp":["cuándo","cuando"]},{"frase":"Al final pide que la persona la ___ con sus palabras.","resp":["repita"]},{"frase":"La junta de arranque dura unos ___ minutos.","resp":["10","diez"]}]},{"tipo":"clave","items":["Junta de arranque: seguridad, resultados, meta, problemas y cierre en 10 minutos.","Instrucción clara: quién, qué, cuándo, estándar y qué hacer si hay un problema.","Pide que te la repitan: así compruebas que te explicaste bien."]}]},{"id":"d-liderazgo-m2-l2","titulo":"Lección 2 — Escucha activa y comunicación hacia arriba","objetivo":"escuchar para entender antes de responder, y presentar problemas a tu jefe con datos y propuestas.","bloques":[{"tipo":"texto","texto":"<b>Escuchar activamente</b> es poner atención completa para entender lo que la otra persona dice y siente, y demostrarle que la entendiste. No es quedarte callado esperando tu turno para contestar. Es una de las conductas que más confianza construye en un equipo."},{"tipo":"tabla","titulo":"Técnicas de escucha activa","encabezados":["Técnica","Ejemplo"],"filas":[["Atención completa","Guardas el celular, lo miras y dejas lo que estabas haciendo"],["Parafrasear","«Entonces, lo que me dices es que la báscula marca distinto desde el lunes…»"],["Preguntas abiertas","«¿Qué pasó exactamente?», «¿Qué has intentado?»"],["Reflejar la emoción","«Te veo frustrado con esto, y lo entiendo»"],["Resumir y acordar","«Quedamos en que reviso con mantenimiento y te aviso mañana a las 10»"]]},{"tipo":"practica","rotulo":"¿Escucha activa o no?","preguntas":[{"p":"Un cajero te cuenta un problema y tú contestas mensajes mientras dices «ajá, ajá».","ops":["No es escucha activa","Sí es escucha activa"],"correcta":0,"explica":"La atención dividida se nota y la persona deja de contarte cosas."},{"p":"Dices: «A ver si entendí: el cliente pidió cancelar y el sistema no te dejó, ¿correcto?»","ops":["No, es interrumpir","Sí, es parafrasear"],"correcta":1},{"p":"Antes de que termine, le dices «ya sé, ya sé, eso pasa siempre».","ops":["No es escucha activa","Sí, demuestra experiencia"],"correcta":0}]},{"tipo":"texto","texto":"<b>Comunicación hacia arriba.</b> Tu jefe tiene poco tiempo y muchos pendientes. Si llegas solo con quejas («todo está mal en el turno»), te volverás el que siempre se queja. Llega con <b>hechos, impacto y propuesta</b>. Y avisa de las malas noticias <b>temprano</b>: a nadie le gusta enterarse a las 5:55 de que el embarque de las 6 no sale."},{"tipo":"comparar","titulo":"Cómo le planteas un problema a tu jefe","malTitulo":"Así no","mal":"«Jefe, es que ya no se puede con el turno de noche, nadie quiere trabajar y la máquina 4 está de la fregada.»","bienTitulo":"Así sí","bien":"«Jefe, la máquina 4 tuvo 3 paros esta semana, 5 horas en total; perdimos unas 900 piezas. Mantenimiento dice que falta una refacción que tarda 10 días. Propongo pasar el modelo X a la máquina 6 mientras llega. Necesito su visto bueno para mover a dos operadores. ¿Lo autoriza?»"},{"tipo":"plantilla","rotulo":"Mensaje breve para tu jefe (hechos, impacto, propuesta)","texto":"Asunto: [Tema en pocas palabras]\n\nQué pasa: [hecho concreto con dato: cuánto, desde cuándo]\nImpacto: [en producción, clientes, costo, seguridad o personas]\nLo que ya hice: [acciones tomadas]\nPropuesta: [opción recomendada y, si hay, una alternativa]\nLo que necesito de usted: [decisión, recurso o apoyo] para [fecha u hora]","nota":"Úsalo por correo, WhatsApp de trabajo o como guion para una llamada de dos minutos."},{"tipo":"relacionar","rotulo":"Relaciona la frase con la técnica","pares":[["«¿Qué has intentado hasta ahora?»","Pregunta abierta"],["«O sea que el proveedor llegó dos horas tarde, ¿verdad?»","Parafrasear"],["«Se nota que esto te tiene preocupada»","Reflejar la emoción"],["«Propongo mover el modelo X a la máquina 6»","Propuesta para tu jefe"]]},{"tipo":"clave","items":["Escucha activa: atención completa, parafrasear, preguntar, reflejar y acordar.","Con tu jefe: hechos, impacto y propuesta, no solo quejas.","Las malas noticias se avisan temprano."]}]},{"id":"d-liderazgo-m2-l3","titulo":"Lección 3 — Retroalimentación con el modelo SBI","objetivo":"dar retroalimentación positiva y de mejora usando Situación, Comportamiento e Impacto.","bloques":[{"tipo":"texto","texto":"La retroalimentación es información sobre cómo alguien está haciendo su trabajo para que <b>repita lo que funciona y corrija lo que no</b>. El problema es que solemos darla vaga («buen trabajo», «ponte las pilas») o atacando a la persona («eres un desordenado»). El modelo <b>SBI</b> (Situación, Comportamiento, Impacto; en inglés <i>Situation-Behavior-Impact</i>), difundido por el <b>Center for Creative Leadership</b>, te ayuda a ser concreto y justo."},{"tipo":"tabla","titulo":"Las tres partes del SBI","encabezados":["Parte","Qué dices","Ejemplo"],"filas":[["Situación","Cuándo y dónde pasó","«Ayer en el cierre de caja de las 3…»"],["Comportamiento","Lo que la persona hizo o dijo, observable, sin juicios","«…entregaste el arqueo con un faltante de $400 sin reportarlo en la bitácora…»"],["Impacto","El efecto que tuvo en el equipo, el cliente o el resultado","«…y el turno de la tarde tuvo que rehacer el conteo; salimos 40 minutos tarde.»"]],"nota":"Después del impacto, pregunta y acuerden: «¿Qué pasó?» y «¿Qué vas a hacer la próxima vez?»."},{"tipo":"comparar","titulo":"Retroalimentación mala vs buena","malTitulo":"Mala","mal":"«Otra vez tú con tus descuidos. Es que no pones atención, así no se puede.»","bienTitulo":"Buena (SBI)","bien":"«Hoy en el arranque de las 7 (S), la línea 2 empezó sin la revisión de guardas de seguridad (C). Eso nos expone a un accidente y a una multa en una auditoría (I). ¿Qué pasó? ¿Cómo aseguramos que se haga todos los días?»"},{"tipo":"comparar","titulo":"También para reconocer","malTitulo":"Vago","mal":"«Buen trabajo, sigue así.»","bienTitulo":"Concreto (SBI)","bien":"«En la llamada de las 11 con el cliente que quería cancelar (S), lo escuchaste sin interrumpir y le ofreciste el plan de pagos (C). Se quedó con nosotros y además te dio calificación de 5 (I). Así es como queremos atender.»"},{"tipo":"ordenar","rotulo":"Ordena el modelo","items":[{"frase":"Situación comportamiento e impacto","es":"Las tres partes del SBI en orden"}]},{"tipo":"practica","rotulo":"¿Qué parte del SBI es?","preguntas":[{"p":"«…el martes en la junta con calidad…»","ops":["Impacto","Situación","Comportamiento"],"correcta":1},{"p":"«…interrumpiste tres veces a la ingeniera cuando explicaba…»","ops":["Comportamiento","Situación","Impacto"],"correcta":0,"explica":"Es observable: cualquiera que estuvo ahí lo vio igual."},{"p":"«Eres muy grosero» ¿es un comportamiento?","ops":["Sí, es un comportamiento","No, es un juicio sobre la persona"],"correcta":1,"explica":"Describe lo que hizo, no lo que crees que es."},{"p":"«…y la ingeniera ya no quiso compartir los datos del lote.»","ops":["Comportamiento","Impacto","Situación"],"correcta":1}]},{"tipo":"plantilla","rotulo":"Guion de retroalimentación SBI","texto":"RETROALIMENTACIÓN SBI\n\nPersona: [nombre]      Fecha: [__/__/____]      Tipo: [reconocimiento / mejora]\n\nSituación (cuándo y dónde): [...]\nComportamiento (lo que hizo o dijo, observable): [...]\nImpacto (efecto en el cliente, el equipo o el resultado): [...]\n\nPregunta abierta: ¿Cómo lo ves tú? / ¿Qué pasó?\nAcuerdo: [qué va a hacer, desde cuándo]\nSeguimiento: [fecha en que lo revisamos]","nota":"Da la retroalimentación de mejora en privado y pronto; el reconocimiento puede ser en público si a la persona no le incomoda."},{"tipo":"clave","items":["SBI: Situación, Comportamiento observable e Impacto.","Habla de conductas, no de la persona.","Úsalo también para reconocer, y cierra con pregunta y acuerdo."]}]},{"id":"d-liderazgo-m2-l4","titulo":"Lección 4 — Conversaciones difíciles","objetivo":"preparar y conducir una conversación difícil sin evitarla ni convertirla en pleito.","bloques":[{"tipo":"texto","texto":"Una conversación difícil es aquella en la que <b>hay mucho en juego, opiniones distintas y emociones fuertes</b>: hablar del olor corporal de alguien, de llegadas tarde repetidas, de una queja de un cliente, de negar un permiso o de un rumor que está dañando al equipo. Evitarlas no las desaparece: las hace crecer."},{"tipo":"pasos","rotulo":"Cómo prepararla y conducirla","pasos":["<b>Prepárate:</b> reúne hechos (fechas, datos, ejemplos), define qué resultado quieres y piensa cómo puede reaccionar la persona.","<b>Elige lugar y momento:</b> en privado, sin prisa y no en caliente. Nunca frente al equipo ni por grupo de WhatsApp.","<b>Ve al grano con respeto:</b> «Quiero platicar contigo de algo importante: tus llegadas tarde».","<b>Describe con SBI</b> y luego <b>escucha</b> su versión sin interrumpir.","<b>Maneja la emoción:</b> si se enoja o llora, da un momento. «Entiendo que es incómodo. ¿Seguimos o prefieres que lo retomemos en 15 minutos?»","<b>Acuerden</b> algo concreto y una fecha de seguimiento. Si aplica, deja nota por escrito según el procedimiento de tu empresa."]},{"tipo":"comparar","titulo":"Frases que complican vs frases que ayudan","malTitulo":"Complican","mal":"«Siempre llegas tarde.» «Todos se quejan de ti.» «Tú sabrás, pero te va a ir mal.»","bienTitulo":"Ayudan","bien":"«Esta quincena llegaste tarde 4 veces: lunes 3, miércoles 5…» «Recibí dos comentarios sobre…» «Quiero que te vaya bien aquí; por eso lo platico contigo.»"},{"tipo":"practica","rotulo":"Caso: Martín, jefe de turno en un hospital de Aguascalientes","preguntas":[{"p":"Varios camilleros comentan que Toño no se baña y hay quejas de pacientes. Martín debería…","ops":["Hablar con Toño en privado, con respeto y hechos","Hacer una broma en la junta para que capte","Pedirle a otro compañero que se lo diga"],"correcta":0,"explica":"Un tema personal se trata en privado y directamente."},{"p":"Toño se pone rojo y se queda callado. Martín…","ops":["Sigue hablando rápido para terminar","Se ríe para romper la tensión","Le da un momento y reconoce que es incómodo"],"correcta":2},{"p":"Toño comenta que se descompuso el calentador de su casa. Martín…","ops":["Lo reporta a RH de inmediato como falta","Escucha y busca con él una solución (por ejemplo, usar las regaderas del hospital si la política lo permite)","Le dice que no es su problema"],"correcta":1,"explica":"Escuchar descubre causas que no imaginabas."}]},{"tipo":"reflexion","rotulo":"Tu conversación pendiente","pregunta":"¿Qué conversación difícil llevas tiempo posponiendo? Escribe los hechos concretos (sin juicios) y la primera frase con la que la vas a abrir.","ayuda":"Hechos: … Primera frase: «Quiero platicar contigo de…»"},{"tipo":"clave","items":["Evitar una conversación difícil la hace crecer.","Prepárala con hechos, en privado y sin prisa; escucha su versión.","Termina con un acuerdo concreto y fecha de seguimiento."]}]}],"quiz":{"titulo":"Evaluación del módulo 2","preguntas":[{"p":"Una junta de arranque de turno efectiva dura aproximadamente…","ops":["Una hora","Lo que haga falta","Dos minutos sin agenda","10 minutos"],"correcta":3},{"p":"¿Cuál es una instrucción clara?","ops":["«Hagan lo que puedan»","«Ya saben qué hacer»","«Luis, termina el conteo del pasillo 7 antes de las 2 con la hoja nueva y avísame si hay diferencias»","«Échenle ganas al inventario»"],"correcta":2},{"p":"Parafrasear consiste en…","ops":["Terminar la frase del otro","Repetir con tus palabras lo que entendiste para confirmarlo","Cambiar de tema","Dar tu opinión de inmediato"],"correcta":1},{"p":"Al plantear un problema a tu jefe conviene llevar…","ops":["Hechos, impacto y una propuesta","Solo tu queja","Rumores del equipo","Nada, que él lo resuelva"],"correcta":0},{"p":"En el modelo SBI, la «B» (comportamiento) debe ser…","ops":["Una opinión sobre la personalidad","Un rumor","Una amenaza","Observable y sin juicios"],"correcta":3},{"p":"«Eres un irresponsable» es…","ops":["Un impacto","Una situación","Un juicio sobre la persona, no un comportamiento","Un buen ejemplo de SBI"],"correcta":2},{"p":"La retroalimentación de mejora se da preferentemente…","ops":["Meses después, en la evaluación anual","En privado y pronto","Frente a todo el equipo","Por el grupo de WhatsApp"],"correcta":1},{"p":"Una conversación difícil debe terminar con…","ops":["Un acuerdo concreto y fecha de seguimiento","Un regaño fuerte","Nada en particular","Una amenaza de despido"],"correcta":0}]}},{"id":"d-liderazgo-m3","titulo":"Módulo 3 — Organizar y medir el desempeño del equipo","resumen":"Objetivos SMART, delegación por niveles, matriz de Eisenhower, indicadores del equipo en Excel, juntas 1 a 1 y cómo atender el bajo desempeño con un plan de mejora. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-liderazgo-m3-l1","titulo":"Lección 1 — Objetivos SMART para tu equipo","objetivo":"convertir metas vagas en objetivos específicos, medibles y con fecha.","bloques":[{"tipo":"texto","texto":"«Mejorar la atención», «bajar la merma», «echarle más ganas»: así llegan muchas metas. Tu trabajo es convertirlas en algo que tu equipo pueda <b>entender, medir y lograr</b>. La herramienta más usada es el criterio <b>SMART</b>, que George T. Doran publicó en 1981. Hoy se usa sobre todo en esta versión:"},{"tipo":"tabla","titulo":"Qué significa SMART","encabezados":["Letra","Significado","Pregunta de control"],"filas":[["S","Específico","¿Queda claro qué se va a lograr y quién?"],["M","Medible","¿Con qué número sabremos si se logró?"],["A","Alcanzable","¿Es posible con la gente y los recursos que tenemos?"],["R","Relevante","¿Ayuda a la meta del área o de la empresa?"],["T","Con tiempo definido","¿Para cuándo?"]],"nota":"Hay variantes (por ejemplo, la «A» como «asignable»); lo importante es que el objetivo pase las cinco preguntas."},{"tipo":"comparar","titulo":"Objetivo vago vs objetivo SMART","malTitulo":"Vago","mal":"«Hay que bajar las filas en cajas.»","bienTitulo":"SMART","bien":"«Del 1 al 31 de octubre, en la sucursal Centro, reducir el tiempo promedio de espera en cajas de 12 a 8 minutos en horario de 12 a 3, abriendo una caja adicional y midiendo con el turnero.»"},{"tipo":"practica","rotulo":"¿Es SMART?","preguntas":[{"p":"«Mejorar la calidad este año.»","ops":["No: no es específico ni medible","Sí, es SMART"],"correcta":0,"explica":"¿Qué calidad? ¿Cuánto? ¿Cómo se mide?"},{"p":"«Bajar el rechazo de la línea 3 de 2.5% a 1.5% al cierre de diciembre.»","ops":["No, le falta todo","Sí: es específico, medible y con fecha"],"correcta":1},{"p":"«Atender 500 llamadas por hora por agente a partir de mañana.»","ops":["Falla en alcanzable","Es perfectamente SMART"],"correcta":0,"explica":"Un objetivo imposible desmotiva: nadie lo intenta en serio."}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"La «M» de SMART significa ___.","resp":["medible"]},{"frase":"La «T» pide un ___ definido.","resp":["tiempo","plazo"]},{"frase":"Un objetivo imposible falla en ser ___.","resp":["alcanzable"]}]},{"tipo":"reflexion","rotulo":"Convierte tu meta","pregunta":"Toma una meta vaga que te hayan dado y reescríbela como objetivo SMART para tu equipo.","ayuda":"Del ___ al ___, [equipo] va a lograr [resultado medible] pasando de ___ a ___, mediante…"},{"tipo":"clave","items":["SMART: específico, medible, alcanzable, relevante y con tiempo.","Sin número y sin fecha no hay objetivo, hay deseo.","Un objetivo imposible desmotiva tanto como uno vago."]}]},{"id":"d-liderazgo-m3-l2","titulo":"Lección 2 — Delegar por niveles y priorizar","objetivo":"delegar con el nivel de autonomía adecuado y ordenar tus pendientes con la matriz de Eisenhower.","bloques":[{"tipo":"texto","texto":"Delegar no es «aventar» trabajo. Es <b>encargar un resultado</b> a alguien, darle la autoridad y los recursos para lograrlo, y dar seguimiento. Tú sigues siendo responsable ante tu jefe. Un error común es delegar sin aclarar <b>cuánta libertad</b> tiene la persona para decidir."},{"tipo":"tabla","titulo":"Niveles de delegación","encabezados":["Nivel","Qué le dices","Ejemplo"],"filas":[["1. Investiga","«Averigua y me informas; yo decido»","Cotizar tres proveedores de guantes"],["2. Recomienda","«Investiga y dime qué recomiendas»","Proponer el rol de vacaciones del área"],["3. Decide y avísame antes","«Decide, pero avísame antes de actuar»","Reacomodar al personal cuando falta alguien"],["4. Actúa y avísame después","«Resuélvelo y me cuentas cómo quedó»","Atender quejas menores de clientes"],["5. Actúa","«Es tuyo; no necesitas avisarme»","Ordenar el acomodo del almacén de empaque"]],"nota":"Sube de nivel a la persona conforme demuestra capacidad (recuerda el liderazgo situacional del módulo 1)."},{"tipo":"pasos","rotulo":"Cómo delegar bien","pasos":["Elige la tarea y a la persona (capacidad y disposición).","Explica el <b>resultado esperado</b>, el porqué y la fecha.","Aclara el <b>nivel de delegación</b> y los recursos con que cuenta.","Acuerda <b>puntos de revisión</b> (no esperes al final para ver cómo va).","Reconoce el resultado y aprende de lo que salió mal, sin quitarle la tarea al primer error."]},{"tipo":"tabla","titulo":"Matriz de Eisenhower","encabezados":["","Urgente","No urgente"],"filas":[["Importante","<b>Hazlo ya:</b> máquina parada, cliente molesto, accidente","<b>Agéndalo:</b> capacitar, planear, juntas 1 a 1, mantenimiento preventivo"],["No importante","<b>Delégalo:</b> muchas llamadas, reportes de rutina, trámites","<b>Elimínalo:</b> chats sin fin, juntas sin objetivo"]],"nota":"Se atribuye al presidente Dwight D. Eisenhower y la popularizó Stephen Covey. El cuadrante que más descuidan los jefes nuevos es el de «importante no urgente»."},{"tipo":"relacionar","rotulo":"¿En qué cuadrante va?","pares":[["Se cayó el sistema de cobro en cajas a la hora pico","Hazlo ya"],["Diseñar la capacitación del nuevo auxiliar","Agéndalo"],["Capturar el reporte diario de asistencia","Delégalo"],["Ver memes en el grupo del turno","Elimínalo"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Delegas una tarea a Rosa y ella comete un error pequeño. Lo mejor es…","ops":["Revisar juntos qué pasó y dejar que siga con la tarea","Quitarle la tarea y hacerla tú","Regañarla frente a todos"],"correcta":0,"explica":"Si le quitas la tarea al primer error, nadie querrá asumir responsabilidades."},{"p":"Si dices «resuélvelo y me cuentas cómo quedó», estás en el nivel…","ops":["Investiga","Recomienda","Actúa y avísame después"],"correcta":2},{"p":"Las juntas 1 a 1 con tu equipo son…","ops":["Algo que se puede eliminar","Importantes no urgentes: hay que agendarlas","Urgentes no importantes"],"correcta":1}]},{"tipo":"clave","items":["Delegar es encargar un resultado con autoridad, recursos y seguimiento.","Aclara el nivel: investiga, recomienda, decide y avisa, actúa y avisa, actúa.","Eisenhower: hazlo, agéndalo, delégalo o elimínalo; protege lo importante no urgente."]}]},{"id":"d-liderazgo-m3-l3","titulo":"Lección 3 — Indicadores del equipo en Excel","objetivo":"calcular el cumplimiento de metas por persona, un semáforo, el promedio del equipo y el ausentismo.","bloques":[{"tipo":"texto","texto":"Lo que no se mide se discute con opiniones. Con unos cuantos <b>indicadores</b> puedes ver quién necesita apoyo, reconocer con justicia y hablar con tu jefe con datos. Para un equipo operativo, casi siempre bastan tres: <b>cumplimiento de meta</b>, <b>calidad</b> y <b>asistencia</b>. Aquí trabajarás con los de un turno de ensamble en una planta de Celaya."},{"tipo":"excel","rotulo":"Cumplimiento por operador y semáforo","datos":[["Operador","Meta (piezas)","Piezas buenas","% cumplimiento","Semáforo"],["Andrea",1200,1260,"",""],["Brenda",1200,1116,"",""],["Carlos",1200,1008,"",""],["Diego",1000,1000,"",""],["Elena",1000,870,"",""],["Fernando",1000,1050,"",""]],"retos":[{"celda":"D2","formula":"=C2/B2","esperado":1.05,"texto":"<b>D2</b>: calcula el % de cumplimiento de Andrea: piezas buenas entre meta.","pista":"=C2/B2. En Excel puedes darle formato de porcentaje: 1.05 es 105%."},{"celda":"D3","formula":"=C3/B3","esperado":0.93,"texto":"<b>D3</b>: cumplimiento de Brenda."},{"celda":"D4","formula":"=REDONDEAR(C4/B4,2)","esperado":0.84,"requiere":"REDONDEAR(","texto":"<b>D4</b>: cumplimiento de Carlos redondeado a 2 decimales con REDONDEAR."},{"celda":"E2","formula":"=SI(D2>=1,\"Verde\",SI(D2>=0.9,\"Amarillo\",\"Rojo\"))","esperado":"Verde","requiere":"SI(","texto":"<b>E2</b>: semáforo: 100% o más «Verde»; de 90% a menos de 100% «Amarillo»; menos de 90% «Rojo».","pista":"Dos SI anidados: =SI(D2>=1,\"Verde\",SI(D2>=0.9,\"Amarillo\",\"Rojo\"))"},{"celda":"E3","formula":"=SI(D3>=1,\"Verde\",SI(D3>=0.9,\"Amarillo\",\"Rojo\"))","esperado":"Amarillo","requiere":"SI(","texto":"<b>E3</b>: semáforo de Brenda."},{"celda":"E6","formula":"=SI(C6/B6>=1,\"Verde\",SI(C6/B6>=0.9,\"Amarillo\",\"Rojo\"))","esperado":"Rojo","requiere":"SI(","texto":"<b>E6</b>: semáforo de Elena. Como D6 está vacía, calcula el porcentaje dentro del SI (C6/B6).","explica":"Elena está en 87%: rojo. El semáforo no dice por qué; te dice con quién tienes que platicar primero."}]},{"tipo":"excel","rotulo":"Resumen del mes del equipo","datos":[["Persona","% cumplimiento","Faltas","Días programados","","Indicador","Valor"],["Andrea",1.05,0,24,"","Promedio del equipo",""],["Brenda",0.93,2,24,"","Personas que cumplen (100% o más)",""],["Carlos",0.84,3,24,"","Cumplimiento más bajo",""],["Diego",1,0,24,"","Total de faltas",""],["Elena",0.87,1,24,"","% de ausentismo",""],["Fernando",1.05,0,24,"","",""]],"retos":[{"celda":"G2","formula":"=PROMEDIO(B2:B7)","esperado":0.9566666666666667,"requiere":"PROMEDIO(","texto":"<b>G2</b>: promedio de cumplimiento del equipo."},{"celda":"G3","formula":"=CONTAR.SI(B2:B7,\">=1\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>G3</b>: ¿cuántas personas cumplieron (100% o más)?","pista":"El criterio va entre comillas: \">=1\"."},{"celda":"G4","formula":"=MIN(B2:B7)","esperado":0.84,"requiere":"MIN(","texto":"<b>G4</b>: el cumplimiento más bajo del equipo."},{"celda":"G5","formula":"=SUMA(C2:C7)","esperado":6,"requiere":"SUMA(","texto":"<b>G5</b>: total de faltas del mes."},{"celda":"G6","formula":"=REDONDEAR(G5/SUMA(D2:D7),3)","esperado":0.042,"requiere":"REDONDEAR(","texto":"<b>G6</b>: % de ausentismo = faltas entre días programados, redondeado a 3 decimales.","explica":"4.2% de ausentismo. Ojo: 5 de las 6 faltas son de Brenda, Carlos y Elena, justo quienes no llegaron a la meta. Vale la pena preguntar qué está pasando antes de sacar conclusiones."}]},{"tipo":"destacado","texto":"<b>El número abre la conversación, no la cierra.</b> Un promedio de 95.7% se ve bien, pero esconde a Carlos en 84%. Revisa siempre el promedio y también a cada persona, y usa los datos para preguntar («¿qué te está frenando?»), no para exhibir. No publiques los resultados individuales con nombre si tu empresa no lo autoriza."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Para contar cuántos cumplieron la meta usas…","ops":["CONTAR.SI","PROMEDIO","MIN"],"correcta":0,"explica":"CONTAR.SI cuenta las celdas que cumplen un criterio."},{"p":"Un promedio del equipo en verde significa que…","ops":["Nadie necesita apoyo","Ya no hay que medir","Puede haber personas en rojo: revisa también a cada una"],"correcta":2}]},{"tipo":"clave","items":["Tres indicadores básicos: cumplimiento, calidad y asistencia.","% cumplimiento = real / meta; el semáforo se arma con SI anidados.","PROMEDIO, CONTAR.SI y MIN resumen al equipo; el dato abre la conversación."]}]},{"id":"d-liderazgo-m3-l4","titulo":"Lección 4 — Juntas 1 a 1, bajo desempeño y plan de mejora","objetivo":"llevar juntas 1 a 1 útiles, diagnosticar el bajo desempeño y dar seguimiento a un plan de mejora.","bloques":[{"tipo":"texto","texto":"La <b>junta 1 a 1</b> es una plática breve y periódica (por ejemplo, 20 minutos cada dos semanas) entre tú y cada persona de tu equipo. Es <b>su</b> espacio: para hablar de avances, obstáculos, ideas y desarrollo. Cuando existe, los problemas se detectan temprano y el bajo desempeño rara vez te toma por sorpresa."},{"tipo":"plantilla","rotulo":"Agenda de junta 1 a 1","texto":"JUNTA 1 A 1\nColaborador: [nombre]      Fecha: [__/__/____]      Duración: 20 min\n\n1. ¿Cómo estás? (2 min)\n2. Lo que tú quieras platicar primero (5 min)\n3. Avance de objetivos e indicadores (5 min): [dato de cumplimiento, calidad, asistencia]\n4. Obstáculos: ¿qué te está frenando? ¿qué necesitas de mí? (5 min)\n5. Reconocimiento o retroalimentación SBI (2 min)\n6. Acuerdos (1 min):\n   - Colaborador se compromete a: [...]\n   - Yo me comprometo a: [...]\n   - Próxima 1 a 1: [fecha]","nota":"No la canceles a la primera urgencia: si la mueves, reprográmala ese mismo día."},{"tipo":"tabla","titulo":"¿Por qué alguien no rinde? Diagnostica antes de actuar","encabezados":["Pregunta","Si la respuesta es «no»…"],"filas":[["¿Sabe qué se espera de él o ella?","Aclara la meta y el estándar (objetivo SMART)"],["¿Sabe cómo hacerlo?","Capacita, acompaña, dirige (estilo E1 o E2)"],["¿Puede hacerlo? (herramientas, tiempo, salud, carga)","Resuelve recursos, cargas o canaliza a RH o al servicio médico"],["¿Quiere hacerlo?","Explora motivación, conflictos o problemas personales; aplica consecuencias si ya se aclaró todo lo anterior"]]},{"tipo":"practica","rotulo":"Diagnostica","preguntas":[{"p":"Juan tiene bajo cumplimiento desde que cambiaron el sistema de captura y nadie lo capacitó. El problema es de…","ops":["Nada, ya se acostumbrará","Saber cómo hacerlo: toca capacitar","Querer: toca sancionar"],"correcta":1,"explica":"Sancionar lo que en realidad es falta de capacitación es injusto y no resuelve nada."},{"p":"Ana sabe hacer el trabajo pero su montacargas falla a diario. El problema es de…","ops":["Poder: faltan recursos en buen estado","Querer","Saber"],"correcta":0}]},{"tipo":"texto","texto":"Si después de hablarlo el problema sigue, se usa un <b>plan de mejora</b>: un acuerdo por escrito con metas concretas, apoyos y fechas de revisión. Su objetivo real es que la persona mejore, no «armar el expediente». Trabájalo con <b>Recursos Humanos</b>: cualquier sanción o rescisión se decide con RH y conforme al reglamento interior y la Ley Federal del Trabajo, nunca por tu cuenta."},{"tipo":"plantilla","rotulo":"Plan de mejora del desempeño","texto":"PLAN DE MEJORA DEL DESEMPEÑO\nColaborador: [nombre]      Puesto: [...]      Jefe inmediato: [...]\nFecha de inicio: [...]      Duración: [4 a 8 semanas]      RH enterado: [nombre]\n\n1. Situación actual (hechos y datos): [ej. cumplimiento promedio 84% en septiembre; 9 errores de calidad por semana]\n2. Meta esperada (SMART): [ej. 95% o más de la meta semanal y 3 errores o menos por semana, a partir de la semana 4]\n3. Apoyos que da la empresa: [capacitación, acompañamiento, ajuste de herramientas]\n4. Compromisos del colaborador: [...]\n5. Revisiones: [fechas semanales, en junta 1 a 1]\n6. Qué pasa si se cumple / si no se cumple: [según políticas de la empresa y RH]\n\nFirmas: Colaborador ____  Jefe ____  RH ____"},{"tipo":"excel","rotulo":"Seguimiento del plan de mejora de Carlos","datos":[["Semana","Meta","Piezas buenas","Errores de calidad","¿Cumple semana?","","Indicador","Valor"],["1",1200,1010,9,"","","Promedio de piezas (6 semanas)",""],["2",1200,1080,7,"","","Promedio últimas 3 semanas",""],["3",1200,1150,4,"","","Semanas con 3 errores o menos",""],["4",1200,1210,3,"","","Estado en la semana 6",""],["5",1200,1230,2,"","","",""],["6",1200,1190,2,"","","",""]],"retos":[{"celda":"E2","formula":"=SI(Y(C2>=B2*0.95,D2<=3),\"Sí\",\"No\")","esperado":"No","requiere":"Y(","texto":"<b>E2</b>: la semana cumple si las piezas son al menos 95% de la meta <b>y</b> hay 3 errores o menos. Usa SI con Y.","pista":"=SI(Y(C2>=B2*0.95, D2<=3), \"Sí\", \"No\")"},{"celda":"E5","formula":"=SI(Y(C5>=B5*0.95,D5<=3),\"Sí\",\"No\")","esperado":"Sí","requiere":"Y(","texto":"<b>E5</b>: ¿cumple la semana 4?"},{"celda":"H2","formula":"=PROMEDIO(C2:C7)","esperado":1145,"requiere":"PROMEDIO(","texto":"<b>H2</b>: promedio de piezas buenas en las 6 semanas."},{"celda":"H3","formula":"=PROMEDIO(C5:C7)","esperado":1210,"requiere":"PROMEDIO(","texto":"<b>H3</b>: promedio solo de las semanas 4 a 6.","explica":"El promedio general (1145) esconde la mejora: en las últimas tres semanas Carlos ya está arriba de la meta."},{"celda":"H4","formula":"=CONTAR.SI(D2:D7,\"<=3\")","esperado":3,"requiere":"CONTAR.SI(","texto":"<b>H4</b>: ¿cuántas semanas tuvo 3 errores o menos?"},{"celda":"H5","formula":"=SI(O(D7>5,C7<B7*0.9),\"Alerta\",\"En camino\")","esperado":"En camino","requiere":"O(","texto":"<b>H5</b>: marca «Alerta» si en la semana 6 hubo más de 5 errores <b>o</b> menos de 90% de la meta; si no, «En camino». Usa SI con O."}]},{"tipo":"clave","items":["La 1 a 1 periódica detecta los problemas temprano.","Antes de actuar diagnostica: ¿sabe qué se espera?, ¿sabe?, ¿puede?, ¿quiere?","El plan de mejora busca que la persona mejore y se trabaja con RH; tú no despides por tu cuenta."]}]}],"quiz":{"titulo":"Evaluación del módulo 3","preguntas":[{"p":"¿Cuál es un objetivo SMART?","ops":["Mejorar la calidad","Echarle más ganas este año","Ser los mejores","Bajar el rechazo de la línea 3 de 2.5% a 1.5% al 31 de diciembre"],"correcta":3},{"p":"Decir «resuélvelo y me cuentas cómo quedó» corresponde al nivel de delegación…","ops":["Recomienda","Yo decido todo","Actúa y avísame después","Investiga y me informas"],"correcta":2},{"p":"En la matriz de Eisenhower, capacitar a tu equipo suele ser…","ops":["Siempre urgente","Importante y no urgente: se agenda","Urgente y no importante","Algo que se elimina"],"correcta":1},{"p":"Si la meta es 1,000 piezas y alguien hizo 870, su cumplimiento es…","ops":["87%","113%","13%","870%"],"correcta":0},{"p":"La fórmula =CONTAR.SI(B2:B7,\">=1\") sirve para…","ops":["Sumar las piezas","Sacar el promedio","Encontrar el mínimo","Contar cuántas personas llegaron al 100% o más"],"correcta":3},{"p":"El % de ausentismo se calcula como…","ops":["Faltas por 24","Personas entre faltas","Faltas entre días programados","Días programados entre faltas"],"correcta":2},{"p":"Antes de aplicar una consecuencia por bajo desempeño debes revisar…","ops":["Nada, basta el indicador","Si la persona sabe qué se espera, sabe hacerlo y puede hacerlo","Solo su actitud","Qué opinan sus compañeros"],"correcta":1},{"p":"Sobre un plan de mejora, lo correcto es…","ops":["Trabajarlo con RH; las sanciones o rescisiones no las decide el jefe por su cuenta","Usarlo para despedir de inmediato","Hacerlo de palabra, sin registro","Aplicarlo sin avisar a la persona"],"correcta":0}]}},{"id":"d-liderazgo-m4","titulo":"Módulo 4 — Liderar personas","resumen":"Motivación y reconocimiento, manejo de conflictos, seguridad psicológica, diversidad e inclusión, y tu papel como jefe en la NOM-035 y ante la Ley Federal del Trabajo. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-liderazgo-m4-l1","titulo":"Lección 1 — Motivación y reconocimiento","objetivo":"entender qué mueve a las personas en el trabajo y reconocer de forma concreta y frecuente.","bloques":[{"tipo":"texto","texto":"No puedes «inyectar» motivación, pero sí puedes crear condiciones para que aparezca o para que se apague. El psicólogo <b>Frederick Herzberg</b> (1959) propuso distinguir dos grupos de factores: los <b>higiénicos</b>, cuya falta genera insatisfacción (sueldo, condiciones, trato del jefe, políticas), y los <b>motivadores</b>, que generan satisfacción real (logro, reconocimiento, el trabajo en sí, responsabilidad, crecimiento)."},{"tipo":"tabla","titulo":"Lo que puedes mover como mando medio","encabezados":["Factor","Qué depende de ti"],"filas":[["Trato del jefe (higiénico)","Respeto, justicia, cumplir lo que prometes"],["Condiciones (higiénico)","Pedir a tiempo herramientas, equipo de protección, reparaciones"],["Logro (motivador)","Metas claras y alcanzables; que la gente vea su avance"],["Reconocimiento (motivador)","Decir concretamente qué se hizo bien, con frecuencia"],["Responsabilidad y crecimiento (motivadores)","Delegar, enseñar, proponer a alguien para una capacitación"]],"nota":"El sueldo lo decide la empresa, pero cómo tratas a tu gente lo decides tú todos los días."},{"tipo":"texto","texto":"<b>Daniel Pink</b>, en su libro <i>Drive</i> (2009), resume la motivación para trabajos que requieren pensar en tres elementos: <b>autonomía</b> (algo de control sobre cómo hago mi trabajo), <b>maestría</b> (sentir que mejoro) y <b>propósito</b> (saber para qué sirve lo que hago). Ejemplo: en un hospital, explicarle a la camillera que su puntualidad hace que el quirófano arranque a tiempo le da propósito a su trabajo."},{"tipo":"comparar","titulo":"Reconocimiento que no sirve vs el que sí","malTitulo":"No sirve","mal":"Un «gracias a todos» al final del mes, igual para quien se esforzó y para quien no.","bienTitulo":"Sí sirve","bien":"«Lupita, el sábado reacomodaste la bodega de lácteos y ya no tuvimos producto caducado en anaquel. Eso nos ahorró mermas y quejas. Gracias.» Concreto, oportuno y sincero."},{"tipo":"tarjetas","rotulo":"Formas de reconocer que no cuestan","tarjetas":[{"frente":"Un mensaje concreto","reverso":"Escríbelo el mismo día: qué hizo y qué impacto tuvo."},{"frente":"Frente al equipo","reverso":"En la junta de arranque, si a la persona no le incomoda."},{"frente":"Hacia arriba","reverso":"Menciona su nombre con tu jefe: «esto lo resolvió Juan»."},{"frente":"Confianza","reverso":"Encargarle algo retador también es una forma de reconocer."},{"frente":"Escuchar su idea","reverso":"Y si la aplicas, decir que fue suya."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Según Herzberg, un sueldo justo y buenas condiciones…","ops":["Son lo único que motiva","No importan","Evitan la insatisfacción, pero por sí solos no motivan"],"correcta":2,"explica":"Son necesarios pero no suficientes."},{"p":"Un buen reconocimiento es…","ops":["Solo con dinero","Concreto, oportuno y sincero","Genérico y anual"],"correcta":1},{"p":"Explicar para qué sirve un trabajo alimenta el…","ops":["Propósito","Salario","Horario"],"correcta":0}]},{"tipo":"clave","items":["Herzberg: factores higiénicos evitan insatisfacción; los motivadores generan compromiso.","Autonomía, maestría y propósito (Pink).","Reconoce concreto, pronto y sincero; no cuesta dinero."]}]},{"id":"d-liderazgo-m4-l2","titulo":"Lección 2 — Conflictos en el equipo","objetivo":"identificar el tipo de conflicto y elegir la forma de manejarlo.","bloques":[{"tipo":"texto","texto":"Donde hay personas hay conflictos: por turnos, por cargas de trabajo, por malentendidos, por formas distintas de trabajar. El conflicto no es malo en sí; lo dañino es <b>ignorarlo</b> o dejar que se vuelva personal. Tu papel es atenderlo pronto y con imparcialidad."},{"tipo":"tabla","titulo":"Cinco formas de manejar un conflicto (modelo de Thomas y Kilmann)","encabezados":["Forma","Qué es","Cuándo sirve"],"filas":[["Competir","Imponer tu posición","Emergencias, seguridad, reglas no negociables"],["Colaborar","Buscar juntos una solución que sirva a ambos","Temas importantes con tiempo para hablar"],["Transigir (ceder un poco cada uno)","Punto medio","Cuando hay que decidir pronto y ambas partes tienen razón en parte"],["Evitar","Posponer o no entrar","Temas menores o cuando hace falta enfriar los ánimos"],["Complacer","Ceder a lo que pide el otro","Cuando el tema importa más al otro que a ti"]]},{"tipo":"pasos","rotulo":"Mediar entre dos personas de tu equipo","pasos":["Habla primero con cada una <b>por separado</b> y escucha su versión sin tomar partido.","Reúnelas en privado. Pon reglas: hablar por turnos, sin insultos, de hechos.","Que cada una explique qué necesita (no solo qué le molesta).","Busquen opciones juntas; tú propones solo si se atoran.","Acuerden algo concreto y fecha para revisar.","Si hay acoso, amenazas o violencia, <b>no es un conflicto para mediar</b>: canaliza a RH según el protocolo de la empresa."]},{"tipo":"practica","rotulo":"Caso: call center en Monterrey","preguntas":[{"p":"Dos agentes discuten porque una siempre toma el descanso a la hora que la otra quiere. Lo mejor es…","ops":["Ignorarlo, ya se les pasará","Darle la razón a la que tenga más antigüedad","Escuchar a ambas y acordar un rol de descansos claro"],"correcta":2,"explica":"Un problema de reglas se resuelve con reglas claras."},{"p":"Sale un simulacro de evacuación y un agente dice que no va a salir porque está en llamada. Usas…","ops":["Evitar","Competir: la seguridad no se negocia","Colaborar con calma"],"correcta":1},{"p":"Una agente te dice que un compañero le manda mensajes con insinuaciones sexuales. Tú…","ops":["La escuchas, no la juzgas y canalizas a RH según el protocolo","Los sientas a los dos a mediar","Le dices que no le haga caso"],"correcta":0,"explica":"Eso no es un simple conflicto: puede ser acoso sexual y requiere el procedimiento formal."}]},{"tipo":"relacionar","rotulo":"Relaciona","pares":[["Buscar una solución que sirva a ambos","Colaborar"],["Cada uno cede un poco","Transigir"],["Imponer tu posición","Competir"],["Posponer para enfriar ánimos","Evitar"]]},{"tipo":"clave","items":["El conflicto se atiende pronto, en privado y con imparcialidad.","Cinco formas: competir, colaborar, transigir, evitar y complacer; se elige según el caso.","El acoso o la violencia no se median: se canalizan a RH."]}]},{"id":"d-liderazgo-m4-l3","titulo":"Lección 3 — Seguridad psicológica, diversidad e inclusión","objetivo":"crear un ambiente donde la gente se atreva a reportar errores y opinar, y tratar a todas las personas con igualdad.","bloques":[{"tipo":"texto","texto":"<b>Amy Edmondson</b>, profesora de Harvard, definió la <b>seguridad psicológica</b> (en un estudio de 1999) como la creencia compartida en un equipo de que es seguro asumir riesgos interpersonales: preguntar, admitir un error, dar una idea o decir «no estoy de acuerdo» sin miedo a ser humillado o castigado. No significa que todo se vale ni que no haya exigencia: significa que <b>se puede hablar</b>."},{"tipo":"texto","texto":"¿Por qué te importa? Porque si tu gente tiene miedo, <b>esconde los errores</b>. En una planta, el operador que no reporta que la guarda está floja; en un hospital, la enfermera que no pregunta si la dosis es correcta. Los problemas no desaparecen: te enteras tarde y más caros."},{"tipo":"comparar","titulo":"Cómo reaccionas ante un error reportado","malTitulo":"Destruye la seguridad","mal":"«¿Otra vez? ¿Pues en qué estabas pensando? Esto va a tu expediente.»","bienTitulo":"Construye seguridad","bien":"«Gracias por avisar a tiempo. Primero contengamos: separa el lote. Luego vemos qué falló en el proceso para que no se repita.»"},{"tipo":"lista","items":["Admite tus propios errores frente al equipo.","Pregunta «¿qué opinan?» y espera la respuesta, aunque haya silencio.","Agradece a quien trae malas noticias.","Separa el error honesto de la negligencia o la falta repetida.","Nunca te burles de una pregunta."]},{"tipo":"texto","texto":"<b>Diversidad e inclusión.</b> Tu equipo puede tener personas de distintas edades, orígenes, religiones, con alguna discapacidad, mujeres en puestos tradicionalmente masculinos, personas LGBT+, madres y padres con cuidados a su cargo. La <b>Ley Federal del Trabajo (art. 3)</b> prohíbe establecer condiciones que discriminen por origen étnico o nacional, género, edad, discapacidad, condición social, condiciones de salud, religión, opiniones, preferencias sexuales o estado civil, entre otros motivos. Y el art. 133 prohíbe, por ejemplo, exigir certificados de no embarazo."},{"tipo":"practica","rotulo":"¿Inclusión o discriminación?","preguntas":[{"p":"Asignar las horas extra solo a hombres «porque aguantan más».","ops":["Discriminación por género","Criterio válido"],"correcta":0,"explica":"Las horas extra se reparten con criterios de puesto y capacidad, no por sexo."},{"p":"Ajustar la estación de trabajo para un operador en silla de ruedas.","ops":["Trato preferente injusto","Inclusión"],"correcta":1},{"p":"Hacer chistes sobre la edad del compañero de 60 años en la junta.","ops":["Trato discriminatorio que el jefe debe frenar","Humor sin importancia"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu equipo hoy","pregunta":"¿En tu equipo la gente reporta errores y opina, o se queda callada? Escribe una señal que lo demuestre y una conducta tuya que vas a cambiar o reforzar.","ayuda":"Señal: … Conducta que voy a…"},{"tipo":"clave","items":["Seguridad psicológica: poder hablar sin miedo, con exigencia (Edmondson).","Si hay miedo, los errores se esconden y te llegan tarde.","La LFT prohíbe discriminar: el jefe frena tratos y chistes discriminatorios."]}]},{"id":"d-liderazgo-m4-l4","titulo":"Lección 4 — El jefe ante la NOM-035 y la ley","objetivo":"reconocer lo que la NOM-035 y la Ley Federal del Trabajo esperan de ti como jefe, y hasta dónde llega tu autoridad.","bloques":[{"tipo":"texto","texto":"La <b>NOM-035-STPS-2018</b> obliga a los centros de trabajo a identificar y prevenir los factores de riesgo psicosocial y la violencia laboral. No necesitas ser experto en la norma (para eso existe un diplomado aparte), pero sí debes saber algo: entre los factores de riesgo que la norma reconoce están el <b>liderazgo negativo y las relaciones negativas en el trabajo</b>, las <b>cargas de trabajo</b>, la <b>falta de control</b> sobre el trabajo, las <b>jornadas</b> y la <b>interferencia trabajo-familia</b>. Muchos de esos pasan por tus manos."},{"tipo":"tabla","titulo":"Tu papel como jefe","encabezados":["Qué hacer","Ejemplo"],"filas":[["Repartir cargas y horarios con criterio","No cargarle siempre las horas extra al mismo"],["Dar claridad y algo de control","Explicar funciones y dejar decidir cómo organizarse"],["Prevenir la violencia laboral","Frenar gritos, humillaciones, burlas y apodos ofensivos"],["Detectar y canalizar","Notar cambios (aislamiento, faltas, errores) y ofrecer apoyo o canalizar a RH o al servicio médico"],["Acontecimientos traumáticos severos","Tras un accidente grave o un asalto, avisar a RH para que la persona sea identificada y canalizada"],["Respetar el canal de quejas","Nunca tomar represalias contra quien se queja de buena fe"]],"nota":"No diagnostiques ni hagas de psicólogo: tu trabajo es notar, escuchar y canalizar."},{"tipo":"texto","texto":"<b>Lo que dice la Ley Federal del Trabajo.</b> El art. 3 Bis define el <b>hostigamiento</b> (ejercicio del poder en una relación de subordinación, con conductas verbales, físicas o ambas) y el <b>acoso sexual</b>. El art. 133 prohíbe a los patrones <i>y a sus representantes</i> realizar o tolerar hostigamiento o acoso sexual. Y el art. 11 considera <b>representantes del patrón</b> a quienes ejercen funciones de dirección o administración: lo que tú haces como jefe compromete a la empresa."},{"tipo":"destacado","texto":"<b>Tú no despides por tu cuenta.</b> Aunque tengas el enojo o la razón, una rescisión mal hecha (sin causa justificada ni aviso por escrito conforme a la ley) puede costarle a la empresa un juicio y una indemnización. Si hay una falta grave, documenta los hechos y lleva el caso a <b>Recursos Humanos</b> de inmediato. Frases como «estás despedido» o «si no firmas tu renuncia te va peor» no te corresponden y pueden ser ilegales."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un jefe de turno les grita y pone apodos humillantes a sus operadores «para que reaccionen». Según la NOM-035 eso es…","ops":["Un estilo de liderazgo válido","Asunto privado del jefe","Violencia laboral que debe prevenirse"],"correcta":2,"explica":"Además, al ser representante del patrón compromete a la empresa."},{"p":"Un cajero fue asaltado ayer en ventanilla. Tú…","ops":["Lo diagnosticas con estrés postraumático","Avisas a RH para identificarlo y canalizarlo a atención","Le dices que ya pasó y que siga trabajando"],"correcta":1,"explica":"Es un acontecimiento traumático severo según la NOM-035."},{"p":"Descubres que un operador llegó en estado de ebriedad. Lo correcto es…","ops":["Retirarlo de la operación por seguridad, documentar y llevar el caso a RH","Despedirlo tú en ese momento","Ignorarlo"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa","items":[{"frase":"El art. 11 de la LFT considera a los jefes ___ del patrón.","resp":["representantes","representante"]},{"frase":"Tras un accidente grave, el jefe detecta y ___ a la persona para que reciba atención.","resp":["canaliza"]},{"frase":"Ante una falta grave, el jefe documenta y lleva el caso a ___.","resp":["RH","Recursos Humanos","recursos humanos"]}]},{"tipo":"clave","items":["El liderazgo negativo es un factor de riesgo psicosocial en la NOM-035: tú puedes prevenirlo.","Nota, escucha y canaliza; no diagnostiques ni tomes represalias.","Como representante del patrón, no hostigas ni toleras acoso y no despides por tu cuenta: vas con RH."]}]}],"quiz":{"titulo":"Evaluación del módulo 4","preguntas":[{"p":"Según Herzberg, el reconocimiento y el logro son factores…","ops":["Higiénicos","Legales","Irrelevantes","Motivadores"],"correcta":3},{"p":"Un reconocimiento eficaz es…","ops":["Siempre en dinero","Igual para todos sin importar lo que hicieron","Concreto, oportuno y sincero","Genérico y una vez al año"],"correcta":2},{"p":"Buscar juntos una solución que sirva a ambas partes es…","ops":["Complacer","Colaborar","Competir","Evitar"],"correcta":1},{"p":"Si una trabajadora reporta insinuaciones sexuales de un compañero, el jefe…","ops":["Escucha y canaliza a RH según el protocolo","Los pone a mediar","Le pide que lo ignore","Lo comenta en la junta"],"correcta":0},{"p":"La seguridad psicológica, según Amy Edmondson, es…","ops":["Que no haya exigencia","Tener seguro de gastos médicos","No cometer errores","La creencia de que es seguro hablar, preguntar y admitir errores en el equipo"],"correcta":3},{"p":"Exigir certificado de no embarazo para contratar o ascender está…","ops":["Obligatorio","Permitido solo en planta","Prohibido por la LFT","Permitido si lo pide el jefe"],"correcta":2},{"p":"Entre los factores de riesgo psicosocial de la NOM-035 está…","ops":["El número de sucursales","El liderazgo negativo y las relaciones negativas en el trabajo","El color de las paredes","La marca del uniforme"],"correcta":1},{"p":"Ante una falta grave de un colaborador, el jefe debe…","ops":["Documentar los hechos y llevar el caso a RH","Despedirlo en ese momento","Pedirle que firme su renuncia","No hacer nada"],"correcta":0}]}},{"id":"d-liderazgo-m5","titulo":"Módulo 5 — Cambio, decisiones y crecimiento","resumen":"Cómo llevar a tu equipo a través de un cambio, tomar decisiones con método, cuidar tu propia energía, desarrollar a tu reemplazo y armar tu plan de liderazgo de 90 días. Cuatro lecciones y una evaluación.","lecciones":[{"id":"d-liderazgo-m5-l1","titulo":"Lección 1 — Liderar el cambio","objetivo":"explicar por qué la gente se resiste a los cambios y cómo acompañar a tu equipo en uno.","bloques":[{"tipo":"texto","texto":"Nuevo sistema de nómina, otra línea de producto, cambio de horarios, fusión de sucursales: como mando medio te toca <b>aterrizar</b> cambios que muchas veces no decidiste. La resistencia es normal: la gente teme perder algo (su puesto, su dominio del trabajo, su rutina, su grupo) y muchas veces no entiende el porqué."},{"tipo":"texto","texto":"<b>Kurt Lewin</b> describió el cambio en tres etapas: <b>descongelar</b> (hacer ver que lo actual ya no sirve), <b>cambiar</b> (aprender la nueva forma) y <b>recongelar</b> (volverla la nueva costumbre). <b>John Kotter</b>, en <i>Leading Change</i> (1996), propuso ocho pasos para las organizaciones; varios se aplican a tu escala: crear sentido de urgencia, comunicar la visión, quitar obstáculos y conseguir <b>victorias rápidas</b>."},{"tipo":"pasos","rotulo":"Aterrizar un cambio con tu equipo","pasos":["<b>Explica el porqué</b> con datos y sin tecnicismos. Si no sabes el porqué, pregúntale a tu jefe antes de anunciarlo.","<b>Di qué cambia y qué no</b>: reduce la incertidumbre.","<b>Escucha los miedos</b> y responde lo que sepas; lo que no sepas, dilo y averígualo.","<b>Capacita antes</b> de exigir, y acepta que al principio bajará el rendimiento.","<b>Busca aliados</b>: personas respetadas del equipo que prueben primero.","<b>Celebra las primeras victorias</b> y corrige rápido lo que no funcione."]},{"tipo":"comparar","titulo":"Anunciar un cambio","malTitulo":"Así no","mal":"«De arriba dicen que desde el lunes usamos terminales para surtir pedidos. No sé por qué, pero así es. Ni modo.»","bienTitulo":"Así sí","bien":"«Desde el lunes surtiremos con terminales portátiles. El año pasado tuvimos 4% de pedidos con errores y cada uno nos cuesta devoluciones. Con la terminal, el sistema te avisa si tomas el producto equivocado. Esta semana hay capacitación en cada turno y los primeros días voy a estar en piso para apoyar. ¿Qué dudas tienen?»"},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La razón más común de resistencia al cambio es…","ops":["Que la gente es floja","Que el jefe es nuevo","El miedo a perder algo y no entender el porqué"],"correcta":2,"explica":"Por eso explicar y escuchar reduce la resistencia."},{"p":"Si no sabes por qué se hace un cambio, antes de anunciarlo…","ops":["Dices «ni modo, así es»","Preguntas a tu jefe","Inventas una razón"],"correcta":1},{"p":"Las «victorias rápidas» sirven para…","ops":["Demostrar que el cambio funciona y ganar confianza","Terminar antes","Evitar capacitar"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Ordena las etapas de Lewin","items":[{"frase":"Descongelar cambiar y recongelar","es":"Las tres etapas del cambio"}]},{"tipo":"clave","items":["La resistencia al cambio es normal: miedo a perder y falta de porqué.","Lewin: descongelar, cambiar, recongelar; Kotter: urgencia, visión, obstáculos, victorias rápidas.","Explica, escucha, capacita antes de exigir y celebra los primeros logros."]}]},{"id":"d-liderazgo-m5-l2","titulo":"Lección 2 — Decidir bajo presión y cuidar tu energía","objetivo":"aplicar un método sencillo para decidir y reconocer las señales de estrés propio antes de que te rebasen.","bloques":[{"tipo":"texto","texto":"Un mando medio toma decenas de decisiones al día. La mayoría son rápidas y reversibles (a quién mover de estación). Algunas son difíciles de deshacer (cambiar un proveedor, proponer a alguien para un ascenso). La regla práctica: <b>decide rápido lo reversible y date más tiempo en lo que no tiene marcha atrás</b>."},{"tipo":"pasos","rotulo":"Método para decisiones importantes","pasos":["<b>Define el problema</b> en una frase. Pregunta «¿por qué?» varias veces (la técnica de los <b>5 porqués</b>, del sistema de producción de Toyota) para llegar a la causa.","<b>Reúne datos</b> suficientes, no todos los posibles.","<b>Genera al menos dos opciones</b>; consulta a quien conoce el tema.","<b>Compara</b> con criterios claros: seguridad, cliente, costo, tiempo, personas.","<b>Decide y comunica</b> el porqué.","<b>Revisa</b> el resultado y aprende."]},{"tipo":"tabla","titulo":"Los 5 porqués: la línea 2 paró","encabezados":["Pregunta","Respuesta"],"filas":[["¿Por qué paró la línea?","Se atoró la banda"],["¿Por qué se atoró?","El rodillo estaba desgastado"],["¿Por qué estaba desgastado?","No se cambió en el mantenimiento preventivo"],["¿Por qué no se cambió?","No había refacción en almacén"],["¿Por qué no había?","Nadie tiene asignado revisar el mínimo de refacciones críticas"]],"nota":"La solución real no es «cambiar el rodillo», es asignar quién revisa el inventario de refacciones críticas."},{"tipo":"texto","texto":"<b>Tu propio estrés.</b> Estás entre la presión de arriba y las necesidades de abajo. Señales de alerta: dormir mal por varias semanas, irritarte con todo, dolores de cabeza o de estómago frecuentes, no desconectarte nunca del celular del trabajo, dejar de hacer lo que antes disfrutabas. Un jefe agotado decide peor y trata peor a su gente."},{"tipo":"lista","items":["Pausas breves: respira lento unos minutos entre juntas.","Límites: acuerda con tu equipo qué es emergencia para llamarte fuera de horario.","Delega y usa la matriz de Eisenhower para soltar lo que no te toca.","Cuida sueño, comida y movimiento; no son lujo, son herramientas de trabajo.","Busca con quién hablar: un colega, tu jefe o un profesional."]},{"tipo":"destacado","texto":"Si el estrés te está rebasando, pide apoyo a tu servicio médico o a un profesional de la salud mental. Si tienes pensamientos de hacerte daño, llama a la <b>Línea de la Vida 800 911 2000</b> (24 horas, gratuita) o al <b>911</b> en una emergencia."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Decidir a quién mover de estación hoy es una decisión…","ops":["Irreversible: requiere semanas de análisis","Reversible: se decide rápido"],"correcta":1,"explica":"Si sale mal, mañana lo cambias."},{"p":"Los 5 porqués sirven para…","ops":["Alargar la junta","Llegar a la causa de fondo de un problema","Culpar a alguien"],"correcta":1},{"p":"Revisar mensajes del trabajo a las 2 de la mañana todos los días es…","ops":["Una señal de alerta de estrés","Señal de compromiso sano","Obligatorio para un jefe"],"correcta":0}]},{"tipo":"clave","items":["Rápido en lo reversible; con método en lo que no tiene marcha atrás.","Los 5 porqués llevan a la causa de fondo.","Cuida tu energía: un jefe agotado decide y trata peor; pide ayuda a tiempo."]}]},{"id":"d-liderazgo-m5-l3","titulo":"Lección 3 — Desarrollar a tu reemplazo","objetivo":"identificar a quién desarrollar y armar un plan para que pueda cubrirte y crecer.","bloques":[{"tipo":"texto","texto":"Parece contradictorio, pero <b>desarrollar a alguien que pueda hacer tu trabajo</b> es de lo mejor que puedes hacer por tu carrera. Si nadie puede cubrirte, no puedes tomar vacaciones tranquilo, ni capacitarte, ni ser promovido: tu jefe no puede moverte sin dejar un hueco."},{"tipo":"tabla","titulo":"Cómo aprende un adulto en el trabajo (regla práctica 70-20-10)","encabezados":["Proporción aproximada","Cómo","Ejemplo"],"filas":[["70%","Experiencia: retos reales en el trabajo","Que cubra la junta de arranque los viernes"],["20%","Otros: retroalimentación, mentoría, observar","Acompañarte a la junta con producción y comentar después"],["10%","Cursos y lecturas","Un curso de Excel o de seguridad industrial"]],"nota":"Los porcentajes son una guía, no una ley: la idea es que la mayor parte del desarrollo pasa haciendo, con acompañamiento."},{"tipo":"pasos","rotulo":"Plan para desarrollar a tu posible reemplazo","pasos":["Elige a alguien con <b>capacidad y ganas</b> (no solo al más antiguo) y pregúntale si le interesa.","Lista las tareas de tu puesto y marca cuáles ya domina y cuáles no.","Asígnale tareas graduales: primero te observa, luego lo hace contigo, luego solo con revisión, luego solo.","Da retroalimentación SBI después de cada tarea nueva.","Hazlo visible: dile a tu jefe quién te puede cubrir y en qué.","Revisa el avance cada mes en su junta 1 a 1."]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Desarrollar a tu reemplazo…","ops":["Pone en riesgo tu puesto siempre","Es tarea exclusiva de RH","Facilita que te puedan promover o que tomes vacaciones"],"correcta":2,"explica":"Un jefe sin respaldo es difícil de mover."},{"p":"Según la regla 70-20-10, la mayor parte del aprendizaje viene de…","ops":["Los libros","La experiencia en retos reales","Los cursos"],"correcta":1},{"p":"Para elegir a quién desarrollar el criterio principal es…","ops":["Capacidad y ganas","Antigüedad solamente","Amistad"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la secuencia","items":[{"frase":"Primero te observa, luego lo hace ___, luego solo con revisión.","resp":["contigo"]},{"frase":"El avance se revisa cada mes en la junta ___.","resp":["1 a 1","uno a uno"]}]},{"tipo":"clave","items":["Si nadie puede cubrirte, nadie puede promoverte.","70-20-10: la mayor parte del desarrollo pasa haciendo, con acompañamiento.","Delega en forma gradual y hazlo visible con tu jefe."]}]},{"id":"d-liderazgo-m5-l4","titulo":"Lección 4 — Tu plan de liderazgo de 90 días","objetivo":"armar un plan de 90 días para tu equipo integrando lo aprendido en el diplomado.","bloques":[{"tipo":"texto","texto":"Los primeros meses en un puesto de mando marcan cómo te verá tu equipo. <b>Michael Watkins</b>, en <i>The First 90 Days</i> (2003), plantea que en una transición conviene aprender rápido, conseguir algunas victorias tempranas y alinear expectativas con tu jefe. Aunque ya lleves tiempo como jefe, un plan de 90 días te sirve para reiniciar con intención."},{"tipo":"tabla","titulo":"Estructura sugerida","encabezados":["Periodo","Enfoque","Acciones"],"filas":[["Días 1 a 30","Escuchar y entender","1 a 1 con cada persona; revisar indicadores; acordar con tu jefe qué espera de ti"],["Días 31 a 60","Ordenar","Objetivos SMART del equipo; junta de arranque diaria; semáforo en Excel; delegar 2 tareas"],["Días 61 a 90","Consolidar y desarrollar","Primer cambio de mejora; reconocimiento sistemático; elegir y empezar a desarrollar a tu posible reemplazo"]]},{"tipo":"plantilla","rotulo":"Mi plan de liderazgo de 90 días","texto":"MI PLAN DE LIDERAZGO DE 90 DÍAS\nNombre: [...]      Puesto: [...]      Equipo: [número de personas]\nFecha de inicio: [...]      Revisión con mi jefe: [día 30, 60 y 90]\n\nLo que mi jefe espera de mí (en sus palabras): [...]\n\nDÍAS 1 A 30 — ESCUCHAR Y ENTENDER\n- Juntas 1 a 1 con: [nombres]\n- Indicadores que voy a revisar: [cumplimiento, calidad, asistencia...]\n- Lo que aprendí (llenar el día 30): [...]\n\nDÍAS 31 A 60 — ORDENAR\n- Objetivo SMART del equipo: [...]\n- Tareas que voy a delegar y a quién (nivel): [...]\n- Hábito nuevo: [junta de arranque, semáforo semanal...]\n\nDÍAS 61 A 90 — CONSOLIDAR Y DESARROLLAR\n- Victoria temprana que busco: [...]\n- Persona que voy a desarrollar y primeras tareas: [...]\n- Cómo voy a reconocer al equipo: [...]\n\nMi compromiso personal (estilo, comunicación, energía): [...]"},{"tipo":"relacionar","rotulo":"¿En qué etapa va cada acción?","pares":[["Tener una 1 a 1 con cada colaborador","Días 1 a 30"],["Definir el objetivo SMART del equipo","Días 31 a 60"],["Empezar a desarrollar a tu posible reemplazo","Días 61 a 90"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"En los primeros 30 días lo prioritario es…","ops":["Cambiar todos los procesos","Despedir a quien no rinde","Escuchar y entender al equipo y lo que espera tu jefe"],"correcta":2,"explica":"Cambiar sin entender genera resistencia y errores."},{"p":"Una «victoria temprana» es…","ops":["Ganar una discusión","Una mejora visible y alcanzable que da confianza al equipo","Un proyecto enorme a cinco años"],"correcta":1}]},{"tipo":"reflexion","rotulo":"Tu compromiso","pregunta":"Después de este diplomado, ¿cuál es la <b>única</b> conducta de liderazgo que vas a empezar a practicar el próximo lunes? Escribe cuándo, con quién y cómo sabrás que la estás cumpliendo.","ayuda":"A partir del lunes voy a… con… Sabré que lo cumplo porque…"},{"tipo":"clave","items":["Un plan de 90 días: escuchar y entender, ordenar, consolidar y desarrollar.","Alinea expectativas con tu jefe y busca victorias tempranas.","El liderazgo se construye con conductas pequeñas y constantes."]}]}],"quiz":{"titulo":"Evaluación del módulo 5","preguntas":[{"p":"La resistencia al cambio suele deberse a…","ops":["La pereza","La edad","El salario únicamente","El miedo a perder algo y no entender el porqué"],"correcta":3},{"p":"Las etapas del cambio según Kurt Lewin son…","ops":["Negar, aceptar, olvidar","Urgencia, visión, cultura","Descongelar, cambiar y recongelar","Planear, hacer, verificar"],"correcta":2},{"p":"Antes de exigir un nuevo procedimiento, el jefe debe…","ops":["Evitar hablar del tema","Capacitar al equipo","Sancionar a quien se equivoque","Esperar a que aprendan solos"],"correcta":1},{"p":"La técnica de los 5 porqués sirve para…","ops":["Encontrar la causa de fondo de un problema","Asignar culpables","Evaluar al personal","Calcular metas"],"correcta":0},{"p":"Una decisión reversible y de bajo impacto conviene tomarla…","ops":["Después de semanas de análisis","Nunca","Siempre por votación","Rápido"],"correcta":3},{"p":"Una señal de alerta de estrés propio es…","ops":["Delegar tareas","Hacer pausas breves","Dormir mal por semanas y no desconectarte del trabajo","Tomar vacaciones"],"correcta":2},{"p":"Desarrollar a tu reemplazo…","ops":["Está prohibido","Facilita que te promuevan o te puedan cubrir","Te pone en riesgo siempre","Solo le corresponde a RH"],"correcta":1},{"p":"En los primeros 30 días de un plan de liderazgo lo principal es…","ops":["Escuchar y entender","Cambiar todo","Despedir a alguien","Comprar equipo nuevo"],"correcta":0}]}}]});
